INSERT INTO `notification_templates` (`id`, `name`, `category`, `type`, `subject`, `body`, `is_active`, `created_at`, `updated_at`) VALUES (1, 'Exam Reminder Email', 'exam_reminder', 'email', 'Pengingat Ujian: {exam_name}', 'Halo {user_name},<br><br>Ujian {exam_name} akan dimulai dalam {hours_before} jam.<br><br>Jangan lupa untuk mempersiapkan diri Anda.<br><br>Salam,<br>Tim Ujian Sekolah Kedinasan', 1, '2026-05-14 03:05:58', '2026-05-14 03:05:58');
INSERT INTO `notification_templates` (`id`, `name`, `category`, `type`, `subject`, `body`, `is_active`, `created_at`, `updated_at`) VALUES (2, 'Exam Result Email', 'exam_result', 'email', 'Hasil Ujian: {exam_name}', 'Halo {user_name},<br><br>Hasil ujian Anda untuk {exam_name} telah tersedia.<br><br>Nilai: {score}<br>Status: {status}<br><br>Login ke dashboard untuk melihat detail lengkap.<br><br>Salam,<br>Tim Ujian Sekolah Kedinasan', 1, '2026-05-14 03:05:58', '2026-05-14 03:05:58');
