INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (1, 1, NULL, 13, NULL, NULL, NULL, 'Negara X adalah sebuah negara yang baru saja merdeka dan sedang berusaha membangun rasa nasionalisme di kalangan warganya. Proses ini dilakukan melalui implementasi berbagai program pemerintah dan penyebaran nilai-nilai patriotisme dalam pendidikan. Namun, beberapa tantangan tampaknya menjadi penghambat dalam upaya tersebut. Antara lain: Banyak warga Negara X yang memilih untuk bekerja di negara lain dan mengadopsi gaya hidup serta budaya negara tersebut. Sebagian masyarakat Negara X lebih tertarik pada barang-barang impor dibandingkan produk lokal. Penyiaran dan media di Negara X banyak didominasi oleh konten dari luar negeri. Konflik internal antara berbagai kelompok etnis dan agama yang berbeda. Pengetahuan dan apresiasi terhadap sejarah dan budaya lokal cukup tinggi di kalangan masyarakat berusia. Berdasarkan kasus di atas, mana faktor yang paling mungkin menjadi penghambat utama dalam membangun semangat nasionalisme di Negara X?', NULL, 'Globalisasi', NULL, 'Kesenjangan sosial', NULL, 'Pendidikan yang kurang efektif', NULL, 'Sumber daya manusia yang kurang', NULL, 'Kurangnya dukungan dari pemerintah', NULL, 'A', 'Globalisasi merupakan fenomena di mana dunia semakin terhubung dari segi teknologi, ekonomi, dan budaya. Dalam kasus Negara X, globalisasi memiliki pengaruh yang signifikan sebagai penghambat perkembangan nasionalisme. Hal ini dapat dilihat dari beberapa indikasi: 1) Migrasi tenaga kerja: Banyak warga Negara X yang memilih untuk bekerja di negara lain. Migrasi tenaga kerja ini cenderung membuat mereka mengadopsi gaya hidup serta budaya negara di mana mereka bekerja, yang dapat berpotensi mengurangi ikatan mereka dengan Negara X. 2) Dominasi barang dan layanan impor: Ketertarikan masyarakat Negara X terhadap barang-barang impor di atas produk lokal menunjukkan dampak globalisasi. 3) Dominasi konten media asing: Media memainkan peran penting dalam membentuk persepsi masyarakat. Melalui tiga indikasi ini, dapat disimpulkan bahwa globalisasi adalah faktor utama yang menghambat pembangunan semangat nasionalisme di Negara X.', NULL, 'Untuk soal TWK tentang nasionalisme, perhatikan konteks globalisasi dan dampaknya terhadap identitas nasional. Cari indikator-indikator yang menunjukkan pengaruh asing terhadap kehidupan lokal.', '2026-05-09 18:31:32', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 2);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (2, 1, NULL, 1, NULL, NULL, NULL, 'Pada masa penjajahan, beberapa pemuda Indonesia seperti Ernest Douwes Dekker, Soewardi Soerjaningrat dan Tjipto Mangunkusumo mendirikan organisasi yang bernama Indische Party. Organisasi ini dikenal sebagai organisasi pertama yang mencetuskan konsep merdeka, yaitu bebas dari penjajahan Belanda dan menjadi fondasi penting dalam paham nasionalisme Indonesia. Peran Indische Party dan konsep merdeka memiliki pengaruh yang signifikan dalam sejarah kemerdekaan Indonesia. Bagaimanakah dampak konsep merdeka dan paham nasionalisme yang ditetapkan oleh Indische Party dalam perjuangan bangsa Indonesia hingga hari ini?', NULL, 'Menginspirasi pembuatan Pancasila sebagai dasar negara', NULL, 'Mendorong pertumbuhan partai-partai politik di Indonesia', NULL, 'Mendorong terbentuknya kesadaran kolektif untuk merdeka', NULL, 'Mendorong penggunaan Bahasa Indonesia sebagai bahasa resmi', NULL, 'Menstimulasi pembentukan lembaga-lembaga pemerintahan setelah kemerdekaan', NULL, 'C', 'Konsep merdeka dan paham nasionalisme yang disuarakan oleh Indische Party dapat dianggap sebagai gerakan awal yang signifikan dalam mendorong terbentuknya kesadaran kolektif untuk merdeka di Indonesia. Kesadaran kolektif ini merujuk pada pemahaman bersama di antara penduduk Indonesia bahwa mereka menginginkan dan berhak atas kemerdekaan negara mereka sendiri, bebas dari penjajahan asing. Paham nasionalisme ini meletakkan dasar bagi perjuangan Indonesia untuk mendapatkan kemerdekaan. Ide-ide dari Indische Party, termasuk konsep merdeka dan nasionalisme, membantu menguatkan perlawanan terhadap penjajah dan membentuk pergerakan nasionalis yang lebih besar yang akhirnya sukses memenangkan kemerdekaan Indonesia.', NULL, 'Untuk soal sejarah pergerakan nasional, pahami konsep dasar dari setiap organisasi dan dampaknya terhadap kesadaran kolektif bangsa.', '2026-05-09 18:31:32', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 49);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (3, 1, NULL, 1, NULL, NULL, NULL, 'Pada 2021 silam, seorang aparat bernama Briptu Nikmal Idwan diduga melakukan pemerkosaan terhadap seorang remaja perempuan berusia 16 tahun di Mapolsek Jailolo Selatan, Halmahera Barat, Maluku Utara. Tindakan aparat ini jelas sekali bertentangan dengan....', NULL, 'UUD 1945 pasal 27 ayat 3', NULL, 'UUD 1945 pasal 30 ayat 3', NULL, 'UUD 1945 pasal 30 ayat 4', NULL, 'UU nomor 3 2002 pasal 9 ayat 1', NULL, 'UU nomor 3 2002 pasal 9 ayat 2', NULL, 'C', 'Bunyi masing-masing pasal: UUD 1945 pasal 27 ayat 3: Setiap warga negara berhak dan wajib ikut serta dalam pembelaan negara. UUD 1945 pasal 30 ayat 3: Tentara Nasional Indonesia terdiri atas Angkatan Darat, Angkatan Laut, dan Angkatan Udara sebagai alat negara yang bertugas mempertahankan, melindungi, dan memelihara keutuhan dan kedaulatan negara. UUD 1945 pasal 30 ayat 4: Kepolisian Negara Republik Indonesia sebagai alat negara yang menjaga keamanan dan ketertiban masyarakat bertugas melindungi, mengayomi, melayani masyarakat, serta menegakkan hukum. Tindakan pemerkosaan yang dilakukan oleh oknum aparat tersebut jelas melanggar UUD 1945 pasal 30 ayat 4. Polisi seharusnya melindungi dan mengayomi masyarakat, tetapi justru menjadi ancaman dan pelaku kriminal.', NULL, 'Untuk soal hukum/tata negara, hafalkan pasal-pasal penting dalam UUD 1945 terutama yang berkaitan dengan tugas dan fungsi lembaga negara.', '2026-05-09 18:31:32', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 50);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (4, 1, NULL, 1, NULL, NULL, NULL, 'Nama Pandawara Group seringkali menjadi perbincangan dan trending topik di sosial media berkat aksi-aksi heroiknya dalam membersihkan sampah. Beranggotakan lima orang pemuda, yaitu Ikhsan Destian, Gliang Rahma, Muhammad Rifqi, Rafly Pasya, dan Agung Permana, tak jarang Pandawara Group mengajak masyarakat dan netizen untuk turut serta turun ke lapangan membersihkan sampah. Aksi kelompok pemuda ini mencerminkan salah satu nilai bela negara, yaitu....', NULL, 'cinta tanah air', NULL, 'kesadaran berbangsa dan bernegara', NULL, 'rela berkorban', NULL, 'memiliki kemampuan bela negara', NULL, 'memiliki kemampuan awal bela negara', NULL, 'A', 'Dalam kasus tersebut, Pandawara Group berupaya menjaga dan melestarikan lingkungan hidup. Aksi mereka ini sesuai dengan salah satu indikator cinta tanah air. Indikatornya adalah sebagai berikut: Mencintai, menjaga dan melestarikan Lingkungan Hidup, Menghargai dan menggunakan karya anak bangsa, Menggunakan produk dalam negeri, Menjaga dan memahami seluruh ruang wilayah NKRI, Menjaga nama baik bangsa dan negara, Mengenal wilayah tanah air tanpa rasa fanatisme kedaerahan.', NULL, 'Untuk soal bela negara, pahami indikator-indikator dari setiap nilai bela negara seperti cinta tanah air, kesadaran berbangsa, dan rela berkorban.', '2026-05-09 18:31:32', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 47);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (5, 1, NULL, 1, NULL, NULL, NULL, 'Sikap di bawah ini yang berlandaskan nasionalisme yang berpengaruh pada kebijakan fiskal negara ialah....', NULL, 'Melakukan pembayaran pajak tepat pada waktu yang ditentukan', NULL, 'Melakukan suatu pekerjaan yang tidak bertentangan dengan hukum', NULL, 'Membeli produk-produk buatan dalam negeri', NULL, 'Menggunakan hak pilih pada pemilihan umum (pemilu)', NULL, 'Memiliki sikap toleransi tinggi terhadap orang/masyarakat yang berbeda keyakinan', NULL, 'A', 'Kebijakan fiskal adalah kebijakan yang dibuat oleh pemerintah untuk mengarahkan ekonomi suatu negara melalui pengeluaran (expenditure) dan pendapatan (income) dalam bentuk pajak oleh pemerintah. Jadi, membayar pajak tepat pada waktunya merupakan salah satu tindakan nasionalisme yang berpengaruh pada kebijakan fiskal negara.', NULL, 'Pahami definisi kebijakan fiskal (berkaitan dengan pajak dan pengeluaran negara) untuk membedakan dengan kebijakan moneter.', '2026-05-09 18:31:32', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 22);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (6, 2, NULL, 32, NULL, NULL, NULL, 'API : ... = ... : TERBASAHI', NULL, 'PANAS – CAIRAN', NULL, 'TERBAKAR – AIR', NULL, 'BERBAHAYA – GENANGAN', NULL, 'DIHINDARI – DIDEKATI', NULL, 'GAS – CAIR', NULL, 'B', 'Kata pertama kelompok kiri adalah API yang merupakan sebuah nomina atau kata benda, kata kedua di kelompok kanan adalah kata kerja. Berdasarkan hal tersebut, untuk mengisi bagian rumpang dibutuhkan kata benda dan kata kerja yang cocok sehingga TERBAKAR dan AIR dapat dipilih untuk melengkapi bagian rumpang. Hubungan: API menyebabkan terbakar, AIR mencegah terbakar/terbasahi.', NULL, 'Untuk soal analogi kata, identifikasi hubungan antar kata (sebab-akibat, sinonim, antonim, bagian-keseluruhan, dll) lalu cari pasangan dengan hubungan yang sama.', '2026-05-09 18:31:32', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 4);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (7, 2, NULL, 41, NULL, NULL, NULL, 'KULKAS : SATU PINTU : DUA PINTU = ...', NULL, 'APEL : SATU KERANJANG : DUA KERANJANG', NULL, 'ES KRIM : DINGIN : PANAS', NULL, 'RODA : BULAT : KOTAK', NULL, 'KASUR : RANJANG : ALAS TIDUR', NULL, 'MESIN CUCI : BUKAAN ATAS : BUKAAN DEPAN', NULL, 'E', 'Hubungan antara \"KULKAS\", \"SATU PINTU\", \"DUA PINTU\" adalah Kulkas memiliki jenis 1 pintu dan jenis 2 pintu. Hubungan ini sama seperti \"MESIN CUCI\", \"BUKAAN ATAS\", \"BUKAAN DEPAN\", mesin cuci memiliki jenis bukaan atas dan bukaan depan.', NULL, 'Untuk soal analogi tiga kata, identifikasi pola hubungan: objek memiliki variasi/jenis, lalu cari opsi dengan pola yang sama.', '2026-05-09 18:31:32', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 6);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (8, 2, NULL, 25, NULL, NULL, NULL, 'Hubungan yang terdapat pada kalimat ikan adalah ekor sama seperti hubungan pada kalimat....', NULL, 'Manusia adalah kaki.', NULL, 'Kucing adalah buntut.', NULL, 'Daun adalah helai.', NULL, 'Bunga adalah buah.', NULL, 'Rumah adalah hunian.', NULL, 'C', 'Hubungan yang terdapat dalam kalimat ikan adalah ekor yang paling mungkin adalah ikan menggunakan penggolongan ekor dalam perhitungannya. Kalimat yang memiliki hubungan yang sama yaitu Daun adalah helai karena daun menggunakan penggolongan helai dalam perhitungannya. Ini adalah hubungan bagian-keseluruhan dengan satuan hitung.', NULL, 'Perhatikan hubungan semantik antar kata. Dalam soal ini, hubungan adalah objek-bagian dengan satuan penghitungan.', '2026-05-09 18:31:32', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 72);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (9, 2, NULL, 25, NULL, NULL, NULL, 'Perhatikan pernyataan berikut! Setiap manusia di dunia pernah mengalami gigi rontok. Beberapa manusia di dunia adalah orang yang sangat tampan. Jadi,....', NULL, 'Beberapa manusia yang sangat tampan tidak pernah mengalami rontok gigi.', NULL, 'Beberapa manusia yang sangat tampan pernah mengalami rontok gigi.', NULL, 'Semua manusia yang sangat tampan tidak pernah mengalami rontok gigi.', NULL, 'Semua manusia yang sangat tampan pernah mengalami rontok gigi.', NULL, 'Semua manusia yang pernah mengalami rontok gigi adalah manusia yang sangat tampan.', NULL, 'B', 'Kesimpulan yang tepat berdasarkan kedua informasi adalah Beberapa manusia yang sangat tampan pernah mengalami rontok gigi. Kesimpulan ini ditarik berdasarkan pernyataan bahwa Setiap manusia di dunia pernah mengalami gigi rontok. Karena Beberapa manusia di dunia adalah orang yang sangat tampan, maka orang tersebut tetap pernah mengalami rontok gigi. Ini adalah silogisme dengan premis universal dan partikular.', NULL, 'Untuk soal silogisme, gunakan aturan logika: dari \"semua A adalah B\" dan \"beberapa A adalah C\" dapat disimpulkan \"beberapa C adalah B\".', '2026-05-09 18:31:32', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 73);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (10, 2, NULL, 25, NULL, NULL, NULL, 'Orang-orang yang rajin membaca buku pasti memiliki pengetahuan yang luas. Orang yang memiliki pengetahuan luas sering kali lebih kreatif dalam memecahkan masalah. Hal ini membuat seseorang sukses dalam kariernya. Kesimpulan yang dapat ditarik dari premis-premis di atas adalah....', NULL, 'Orang yang sukses dalam kariernya pasti rajin membaca buku.', NULL, 'Orang yang rajin membaca buku sukses dalam kariernya.', NULL, 'Orang yang kreatif dalam memecahkan masalah pasti memiliki pengetahuan luas.', NULL, 'Orang yang sukses dalam karier pasti sering kali lebih kreatif dalam memecahkan masalah.', NULL, 'Orang yang sukses dalam karier sering kali rajin membaca buku.', NULL, 'B', 'Premis pertama menyatakan bahwa orang yang rajin membaca buku (p) memiliki pengetahuan luas (q). Premis kedua menyatakan bahwa orang yang memiliki pengetahuan luas (q) lebih kreatif dalam memecahkan masalah (r). Premis ketiga menyatakan bahwa Hal ini (orang yang kreatif dalam memecahkan masalah) (r) membuat seseorang sukses dalam kariernya (s). P1: p → q, P2: q → r, P3: r → s. Dari P1, P2 dan P3 dapat kita ambil kesimpulan sehingga berlaku p → s, kesimpulan ini memiliki bentuk kalimat Orang yang rajin membaca buku sukses dalam kariernya.', NULL, 'Untuk silogisme berantai, gabungkan semua premis: jika A→B, B→C, C→D, maka A→D.', '2026-05-09 18:31:32', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 56);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (11, 2, NULL, 25, NULL, NULL, NULL, '65, 60, 45, 40, ..., 20, 10, 5', NULL, 5, NULL, 25, NULL, 30, NULL, 35, NULL, 40, NULL, 'B', 'Bilangan deret terbentuk dengan pola angka dimana angka setelahnya (sepasang) memiliki selisih 5 atau -5. Pola: 65-60=5, 60-45=15, 45-40=5, 40-?=15, ?-20=5, 20-10=10, 10-5=5. Pola selisih: 5, 15, 5, 15, 5, 10, 5. Untuk ? = 25, maka 40-25=15 dan 25-20=5. Pola konsisten.', NULL, 'Untuk deret angka, cari pola selisih antar angka. Perhatikan apakah ada pola berulang atau naik-turun.', '2026-05-09 18:31:32', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 4);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (12, 2, NULL, 26, NULL, NULL, NULL, 'Suap : Politik = .......... : ..........', NULL, 'Korupsi : nepotisme', NULL, 'Sontek : Ujian', NULL, 'Perampok : Polisi', NULL, 'Culas : Sifat', NULL, 'Joki : Ganti', NULL, 'B', 'Suap dilarang dalam Politik. Sontek dilarang dalam ujian. Hubungan: perbuatan negatif yang dilarang dalam konteks tertentu.', NULL, 'Identifikasi hubungan: X dilarang dalam Y. Cari pasangan dengan hubungan yang sama.', '2026-05-09 18:31:32', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 4);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (13, 2, NULL, 25, NULL, NULL, NULL, 'Asia : Jepang : Sapporo = ..... : ...... : .........', NULL, 'Asia : Baghdah : Khalifah', NULL, 'Eropa : London : Coloseum', NULL, 'Amerika : Amerika Serikat : Liberty', NULL, 'Kelimutu : Flores : Indonesia', NULL, 'Benua : Pulau : Berpenduduk', NULL, 'C', 'Salah satu Negara yang ada di benua ASIA adalah Jepang yang memiliki ikon wisata Sapporo. Salah satu Negara yang ada di benua Amerika adalah Amerika Serikat yang memiliki ikon wisata Liberty. Hubungan: Benua : Negara di benua tersebut : Ikon/kota terkenal.', NULL, 'Untuk analogi tiga kata, identifikasi hierarki: Benua → Negara → Ikon/Kota.', '2026-05-09 18:31:32', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 4);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (14, 3, NULL, 49, NULL, NULL, NULL, 'Saat Anda menghadapi situasi sulit di tempat kerja, apa yang akan Anda lakukan?', NULL, 'Mengeluh dan mencari kesalahan orang lain', NULL, 'Menghindar dan menunda penyelesaian masalah', NULL, 'Menganalisis masalah dan mencari solusi dengan tenang', NULL, 'Meminta bantuan tanpa mencoba menyelesaikan sendiri', NULL, 'Menyerah dan mencari pekerjaan lain', NULL, 'C', 'Jawaban C menunjukkan sikap tanggung jawab, kemampuan problem solving, dan ketenangan dalam menghadapi masalah. Ini adalah karakteristik yang diinginkan untuk pegawai negeri/sekolah kedinasan.', NULL, 'Untuk soal TKP, pilih jawaban yang menunjukkan sikap positif, tanggung jawab, jujur, dan profesional.', '2026-05-09 18:31:32', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 118);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (15, 3, NULL, 49, NULL, NULL, NULL, 'Rekan kerja Anda melakukan kesalahan yang tidak disengaja. Apa tindakan Anda?', NULL, 'Melaporkan ke atasan untuk mendapatkan keuntungan pribadi', NULL, 'Menertawakan dan mengumumkan kesalahan tersebut', NULL, 'Memberi tahu rekan tersebut dan menawarkan bantuan', NULL, 'Pura-pura tidak tahu dan membiarkan saja', NULL, 'Mencari-cari kesalahan lain dari rekan tersebut', NULL, 'C', 'Jawaban C menunjukkan sikap kepedulian, kerjasama, dan integritas. Memberi tahu dengan cara yang baik dan menawarkan bantuan adalah sikap yang profesional.', NULL, 'TKP mengukur karakteristik pribadi. Pilih jawaban yang menunjukkan sikap kolaboratif, empati, dan integritas tinggi.', '2026-05-09 18:31:32', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 116);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (16, 3, NULL, 49, NULL, NULL, NULL, 'Anda mendapatkan tugas baru yang menantang. Sikap Anda adalah....', NULL, 'Menolak tugas tersebut karena terlalu sulit', NULL, 'Menerima tapi tidak serius mengerjakannya', NULL, 'Menerima dengan antusias dan belajar untuk menyelesaikannya', NULL, 'Menunda mengerjakan sampai deadline dekat', NULL, 'Minta orang lain mengerjakan untuk Anda', NULL, 'C', 'Jawaban C menunjukkan sikap antusias, motivasi belajar, dan tanggung jawab. Ini adalah karakteristik yang dicari untuk pegawai kedinasan.', NULL, 'Pilih jawaban yang menunjukkan motivasi, antusiasme, dan kemauan untuk belajar dan berkembang.', '2026-05-09 18:31:32', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 114);
