INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (72, 1, NULL, 1, NULL, NULL, NULL, 'Seorang mahasiswa Pendidikan Teknik Elektro baru saja menyelesaikan studinya. Ia ditawarkan untuk melanjutkan studinya di Inggris dengan beasiswa. Meski demikian ia memilih Kembali ke kampungnya. Di kampung ia membuat pembangkit listrik sederhana dengan memanfaatkan aliran air sungai yang deras. Berkat pembangkit listrik tersebut, warga kampung sudah dapat menikmati ketersediaan listrik. Tindakan mahasiswa tersebut menunjukkan sikap...', NULL, 'Bela negara', NULL, 'Cinta tanah air', NULL, 'Patriotisme', NULL, 'Nasionalisme', NULL, 'Integritas', NULL, 'C', 'Patriotisme adalah cinta tanah air yang ditunjukkan dengan tindakan nyata. Mahasiswa tersebut memilih kembali ke kampung dan berkontribusi untuk masyarakatnya, bukan mengejar keuntungan pribadi di luar negeri.', NULL, 'Untuk soal TWK tentang sikap nasionalisme, cari jawaban yang menunjukkan tindakan nyata untuk kemajuan bangsa.', '2026-05-09 18:44:25', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 50);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (73, 1, NULL, 1, NULL, NULL, NULL, 'Hampir semua partai politik melakukan proses permohonan gugatan kepada KPU, adapun sengketa yang diajukan antara lain terkait masalah internal dan perselisihan kursi terakhir di DPR RI. Komisi Pemilihan Umum (KPU) RI berusaha mengumpulkan bukti-bukti dari KPU daerah untuk menghadapi gugatan sengketa PHPU Legislatif 2019, yang akan segera disidangkan Komisioner KPU Ilham Saputra mengatakan, bukti-bukti dari KPU Kabupaten/kota dan provinsi itu akan dijadikan bahan untuk memberikan keterangan dalam sidang sengketa Pileg 2019. Jika terjadi kasus tersebut maka yang memiliki kewenangan untuk memberikan putusan adalah...', NULL, 'Komisi Yudisial', NULL, 'Mahkamah Agung', NULL, 'Mahkamah Konstitusi', NULL, 'Kehakiman', NULL, 'Komisi Pemilihan Umum', NULL, 'C', 'Sengketa hasil pemilihan umum (PHPU) merupakan kewenangan Mahkamah Konstitusi berdasarkan UUD 1945 Pasal 24C ayat (1).', NULL, 'Hafalkan kewenangan lembaga negara dalam UUD 1945, terutama Mahkamah Konstitusi untuk sengketa pemilu.', '2026-05-09 18:44:25', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 39);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (74, 1, NULL, 1, NULL, NULL, NULL, 'Konflik antara Indonesia dengan Tiongkok kembali terjadi di Perairan Natuna yang berbatasan dengan Laut Cina Selatan. Sejumlah kapal penangkap ikan asal Tiongkok didampingi kapan Coast Guard negaranya, berkegiatan di perairan yang masih masuk dalam teritori ZonaEkonomi Eksklusif (ZEE) milik Indonesia. Hal tersebut juga merupakan sebuah ancaman bagi Indonesia. Ancaman terhadap satu pulau atau daerah pada hakikatnya ancaman seluruh bangsa dan negara. Hal ini ditegaskan dalam wawasan Nusantara dalam bidang...', NULL, 'Ideologi', NULL, 'Politik', NULL, 'Ekonomi', NULL, 'Sosial budaya', NULL, 'Hankam', NULL, 'E', 'Wawasan Nusantara dalam bidang Hankam menyatakan bahwa ancaman terhadap satu pulau atau daerah adalah ancaman terhadap seluruh bangsa dan negara.', NULL, 'Pahami konsep Wawasan Nusantara dan aspek-aspeknya (politik, ekonomi, sosial budaya, hankam).', '2026-05-09 18:44:25', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 39);
