INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (122, 3, NULL, 49, NULL, NULL, NULL, 'Anda adalah seorang karyawan apotek. Seorang pembeli ingin membeli obat-obatan tertentu yang harus menggunakan resep dokter karena bisa membahayakan kesehatan. Dia tidak mempunyai resep itu. Namun pembeli tersebut memaksa ingin membelinya dan dia memberikan sejumlah uang kepada Anda agar mau memberikan obat tersebut. Apa yang Anda lakukan?', NULL, 'Saya memberikan obat tersebut kepadanya, toh tak ada yang tahu', NULL, 'Saya ragu-ragu keputusan apa yang saya ambil', NULL, 'Saya berkonsultasi kepada rekan sejawat dulu', NULL, 'Saya menolaknya dengan mantap', NULL, 'Saya menerima uang tersebut dan memberikan obatnya', NULL, 'D', 'Jawaban D menunjukkan integritas, kejujuran, dan komitmen terhadap aturan.', NULL, 'Pilih jawaban yang menunjukkan integritas dan kepatuhan terhadap aturan.', '2026-05-09 18:44:25', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 119);
