INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (124, 3, NULL, 49, NULL, NULL, NULL, 'Saya telah mempersiapkan diri dengan baik sebelum melakukan presentasi di kantor besok pagi.', NULL, 'Saya yakin besok presentasi saya berjalan dengan baik, namun saya tetap mempersiapkan dengan maksimal.', NULL, 'Meski begitu saya cemas kalau-kalau ternyata besok presentasi saya kurang lancar', NULL, 'Saya pasrah jika ada kendala', NULL, 'Tak mungkin presentasi saya tidak lancar', NULL, 'Tapi Mungkin saja presentasi saya terganggu hal lain', NULL, 'A', 'Jawaban A menunjukkan kepercayaan diri, persiapan yang matang, dan sikap positif.', NULL, 'Pilih jawaban yang menunjukkan kepercayaan diri dan persiapan yang matang.', '2026-05-09 18:44:25', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 101);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (125, 3, NULL, 49, NULL, NULL, NULL, 'Rekan saya meminta saya memalsukan tanda tangan presensi. Sikap saya...', NULL, 'Menuruti permintaannya karena dia rekan yang baik', NULL, 'Menegurnya agar tidak melakukan kecurangan presensi', NULL, 'Melaporkannya pada atasan agar atasan menegurnya', NULL, 'Meminta rekan lain untuk memalsukan tanda tangannya', NULL, 'Menolak permintaannya dan membiarkan kolom presensinya kosong', NULL, 'B', 'Jawaban B menunjukkan integritas dan keberanian menegur rekan yang melakukan kecurangan.', NULL, 'Pilih jawaban yang menunjukkan integritas dan keberanian menegur kecurangan.', '2026-05-09 18:44:25', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 116);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (126, 3, NULL, 49, NULL, NULL, NULL, 'Ketika Anda mengalami kegagalan dalam meminta maaf atas kesalahan yang Anda lakukan, sikap Anda adalah...', NULL, 'berusaha meminta maaf lagi, sampai dimaafkan', NULL, 'bimbang apakah meminta maaf lagi itu perlu', NULL, 'tidak berani meminta maaf lagi', NULL, 'berusaha meminta maaf lagi berharap dimaafkan', NULL, 'meminta bantuan orang lain menjadi penengah', NULL, 'A', 'Jawaban A menunjukkan ketekunan, kemauan untuk memperbaiki kesalahan, dan tidak mudah menyerah.', NULL, 'Pilih jawaban yang menunjukkan ketekunan dan kemauan untuk memperbaiki kesalahan.', '2026-05-09 18:44:25', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 107);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (127, 3, NULL, 49, NULL, NULL, NULL, 'Staf Anda berniat untuk mengundurkan diri, padahal kinerjanya sangat baik. Sebagai atasan tindakan yang akan Anda lakukan adalah...', NULL, 'Mempertahankan karyawan tersebut agar tidak mengundurkan diri.', NULL, 'Menaikkan gaji dan tunjangan agar tidak jadi mengundurkan diri.', NULL, 'Mencoba untuk menanyakan alasan pengunduran dirinya, jika memungkinkan meminta karyawan tersebut untuk tetap bertahan di kantor.', NULL, 'Membiarkannya mengundurkan diri karena merupakan hak.', NULL, 'Memberikan fasilitas yang diinginkan oleh karyawan tersebut.', NULL, 'C', 'Jawaban C menunjukkan kepemimpinan yang baik, empati, dan kemauan mempertahankan karyawan berkinerja baik.', NULL, 'Pilih jawaban yang menunjukkan kepemimpinan yang baik dan empati terhadap karyawan.', '2026-05-09 18:44:25', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 144);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (128, 3, NULL, 49, NULL, NULL, NULL, 'Pada suatu malam ketika Anda sedang sibuk bekerja, anak Anda sedang belajar di kamarnya, dan istri Anda sedang memasak untuk hidangan malam keluarga. Tiba-tiba listrik di rumah Anda padam sehingga membuat anak dan istri Anda panik, yang akan Anda lakukan adalah...', NULL, 'berinisiatif mencari penerangan agar anak saya tetap bisa belajar dan istri saya juga bisa melanjutkan masak dengan tenang', NULL, 'mengkhawatirkan anak dan istri yang ketakutan karena gelap, dan mencari penerangan agar mereka tidak ketakutan', NULL, 'diam saja dan langsung tidur di kamar bila anak dan istri saya tetap tenang, namun bila mereka ketakutan saya akan segera mencari penerangan', NULL, 'tetap tenang dan menyuruh istri untuk menyalakan penerangan alternatif. Istri yang sedang berada di dapur tentu akan lebih dekat dengan penerangan alternatif', NULL, 'saya akan mencari penerangan bila tidak ada satupun yang berusaha mencari penerangan alternatif', NULL, 'A', 'Jawaban A menunjukkan kepemimpinan, inisiatif, dan kemampuan mengambil keputusan cepat dalam situasi darurat.', NULL, 'Pilih jawaban yang menunjukkan kepemimpinan, inisiatif, dan kemampuan mengambil keputusan cepat.', '2026-05-09 18:44:25', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 148);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (129, 3, NULL, 49, NULL, NULL, NULL, 'Bagi saya untuk meraih prestasi saya harus...', NULL, 'Bekerja keras', NULL, 'Jujur', NULL, 'Berani', NULL, 'Rajin', NULL, 'Pintar', NULL, 'A', 'Jawaban A menunjukkan etos kerja yang tinggi dan komitmen untuk meraih prestasi.', NULL, 'Pilih jawaban yang menunjukkan etos kerja tinggi dan komitmen.', '2026-05-09 18:44:25', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 143);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (130, 1, NULL, 1, NULL, NULL, NULL, 'Seorang mahasiswa Pendidikan Teknik Elektro baru saja menyelesaikan studinya. Ia ditawarkan untuk melanjutkan studinya di Inggris dengan beasiswa. Meski demikian ia memilih Kembali ke kampungnya. Di kampung ia membuat pembangkit listrik sederhana dengan memanfaatkan aliran air sungai yang deras. Berkat pembangkit listrik tersebut, warga kampung sudah dapat menikmati ketersediaan listrik. Tindakan mahasiswa tersebut menunjukkan sikap...', NULL, 'Bela negara', NULL, 'Cinta tanah air', NULL, 'Patriotisme', NULL, 'Nasionalisme', NULL, 'Integritas', NULL, 'C', 'Patriotisme adalah cinta tanah air yang ditunjukkan dengan tindakan nyata. Mahasiswa tersebut memilih kembali ke kampung dan berkontribusi untuk masyarakatnya, bukan mengejar keuntungan pribadi di luar negeri.', NULL, 'Untuk soal TWK tentang sikap nasionalisme, cari jawaban yang menunjukkan tindakan nyata untuk kemajuan bangsa.', '2026-05-09 18:45:43', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 50);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (131, 1, NULL, 1, NULL, NULL, NULL, 'Hampir semua partai politik melakukan proses permohonan gugatan kepada KPU, adapun sengketa yang diajukan antara lain terkait masalah internal dan perselisihan kursi terakhir di DPR RI. Komisi Pemilihan Umum (KPU) RI berusaha mengumpulkan bukti-bukti dari KPU daerah untuk menghadapi gugatan sengketa PHPU Legislatif 2019, yang akan segera disidangkan Komisioner KPU Ilham Saputra mengatakan, bukti-bukti dari KPU Kabupaten/kota dan provinsi itu akan dijadikan bahan untuk memberikan keterangan dalam sidang sengketa Pileg 2019. Jika terjadi kasus tersebut maka yang memiliki kewenangan untuk memberikan putusan adalah...', NULL, 'Komisi Yudisial', NULL, 'Mahkamah Agung', NULL, 'Mahkamah Konstitusi', NULL, 'Kehakiman', NULL, 'Komisi Pemilihan Umum', NULL, 'C', 'Sengketa hasil pemilihan umum (PHPU) merupakan kewenangan Mahkamah Konstitusi berdasarkan UUD 1945 Pasal 24C ayat (1).', NULL, 'Hafalkan kewenangan lembaga negara dalam UUD 1945, terutama Mahkamah Konstitusi untuk sengketa pemilu.', '2026-05-09 18:45:43', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 39);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (132, 1, NULL, 1, NULL, NULL, NULL, 'Konflik antara Indonesia dengan Tiongkok kembali terjadi di Perairan Natuna yang berbatasan dengan Laut Cina Selatan. Sejumlah kapal penangkap ikan asal Tiongkok didampingi kapan Coast Guard negaranya, berkegiatan di perairan yang masih masuk dalam teritori ZonaEkonomi Eksklusif (ZEE) milik Indonesia. Hal tersebut juga merupakan sebuah ancaman bagi Indonesia. Ancaman terhadap satu pulau atau daerah pada hakikatnya ancaman seluruh bangsa dan negara. Hal ini ditegaskan dalam wawasan Nusantara dalam bidang...', NULL, 'Ideologi', NULL, 'Politik', NULL, 'Ekonomi', NULL, 'Sosial budaya', NULL, 'Hankam', NULL, 'E', 'Wawasan Nusantara dalam bidang Hankam menyatakan bahwa ancaman terhadap satu pulau atau daerah adalah ancaman terhadap seluruh bangsa dan negara.', NULL, 'Pahami konsep Wawasan Nusantara dan aspek-aspeknya (politik, ekonomi, sosial budaya, hankam).', '2026-05-09 18:45:43', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 39);
