INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (259, 3, NULL, 49, NULL, NULL, NULL, 'Saya telah mempersiapkan diri dengan baik sebelum melakukan presentasi di kantor besok pagi.', NULL, 'Saya yakin besok presentasi saya berjalan dengan baik, namun saya tetap mempersiapkan dengan maksimal.', NULL, 'Meski begitu saya cemas kalau-kalau ternyata besok presentasi saya kurang lancar', NULL, 'Saya pasrah jika ada kendala', NULL, 'Tak mungkin presentasi saya tidak lancar', NULL, 'Tapi Mungkin saja presentasi saya terganggu hal lain', NULL, 'A', 'Jawaban A menunjukkan kepercayaan diri, persiapan yang matang, dan sikap positif.', NULL, 'Pilih jawaban yang menunjukkan kepercayaan diri dan persiapan yang matang.', '2026-05-09 18:46:52', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 101);
