INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (262, 3, NULL, 49, NULL, NULL, NULL, 'Staf Anda berniat untuk mengundurkan diri, padahal kinerjanya sangat baik. Sebagai atasan tindakan yang akan Anda lakukan adalah...', NULL, 'Mempertahankan karyawan tersebut agar tidak mengundurkan diri.', NULL, 'Menaikkan gaji dan tunjangan agar tidak jadi mengundurkan diri.', NULL, 'Mencoba untuk menanyakan alasan pengunduran dirinya, jika memungkinkan meminta karyawan tersebut untuk tetap bertahan di kantor.', NULL, 'Membiarkannya mengundurkan diri karena merupakan hak.', NULL, 'Memberikan fasilitas yang diinginkan oleh karyawan tersebut.', NULL, 'C', 'Jawaban C menunjukkan kepemimpinan yang baik, empati, dan kemauan mempertahankan karyawan berkinerja baik.', NULL, 'Pilih jawaban yang menunjukkan kepemimpinan yang baik dan empati terhadap karyawan.', '2026-05-09 18:46:52', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 144);
