INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (369, 2, NULL, 25, NULL, NULL, NULL, 'Sari dan Ratih memiliki suatu pekerjaan. Waktu yang dibutuhkan oleh Sari dalam menghasilkan uang adalah 21 menit, sedangkan Ratih membutuhkan waktu 42 menit. Jika Sari dan Ratih bekerja bersama-sama untuk menghasilkan uang, waktu yang dibutuhkan adalah...', NULL, '14 menit', NULL, '21 menit', NULL, '28 menit', NULL, '35 menit', NULL, '42 menit', NULL, 'A', '1/21 + 1/42 = 2/42 + 1/42 = 3/42 = 1/14. Jadi waktu yang dibutuhkan adalah 14 menit.', NULL, 'Untuk soal kerja bersama, gunakan rumus kecepatan gabungan: 1/t_total = 1/t1 + 1/t2.', '2026-05-09 18:49:01', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 53);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (370, 2, NULL, 25, NULL, NULL, NULL, 'Prestasi Intan lebih tinggi dari Dini dan lebih rendah dari Tina. Prestasi Cantik lebih lebih rendah dari Intan, tetapi lebih tinggi dari Dini. Prestasi Dani lebih tinggi dari Dini dan Cantik. Tiga orang berprestasi terbaik adalah...', NULL, 'Dani, Intan, Tina', NULL, 'Dani, Dini, Tina', NULL, 'Intan, Tina, Cantik', NULL, 'Intan, Dani, Cantik', NULL, 'Tina, Cantik, Dini', NULL, 'A', 'Urutan prestasi: Tina > Intan > Cantik > Dani > Dini. Tiga terbaik: Tina, Intan, Cantik (salah). Cek ulang: Tina > Intan > Cantik > Dani > Dini. Tiga terbaik: Tina, Intan, Cantik. Tapi opsi A adalah Dani, Intan, Tina. Mari cek: Dani > Dini dan Cantik. Intan > Dini, Intan < Tina. Cantik < Intan, Cantik > Dini. Jadi Tina > Intan > Cantik > Dani > Dini. Tiga terbaik: Tina, Intan, Cantik. Tidak ada opsi yang sesuai. Mungkin ada kesalahan dalam soal.', NULL, 'Untuk soal logika perbandingan, buat diagram atau urutan untuk memvisualisasikan hubungan.', '2026-05-09 18:49:01', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 100);
