INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (372, 3, NULL, 49, NULL, NULL, NULL, 'Ketika pemilihan kepala desa sedang berlangsung di tempat tinggal Anda. Nenek Anda yang mempunyai hak pilih dalam pemilihan kepala desa tetapi pada saat pencoblosan nenek dirawat di rumah sakit. Apa yang Anda lakukan...', NULL, 'Melaporkan keadaan nenek kepada panitia pemungutan suara', NULL, 'Melaporkan keadaan nenek kepada panitia pemungutan suara untuk menentukan langkah yang harus ditempuh', NULL, 'Melaporkan dan menginformasikan kondisi nenek kepada panitia pemungutan suara untuk diwakilkan Anda menggunakan hak pilihnya', NULL, 'Melaporkan keadaan nenek kepada panitia pemungutan suara untuk meminta tolong orang lain menggunakan hak pilihnya', NULL, 'Membiarkan hak suara nenek hangus', NULL, 'B', 'Jawaban B menunjukkan jejaring kerja, kerja sama, dan kolaborasi dengan panitia pemungutan suara. Hak pilih bersifat personal dan tidak bisa diwakili.', NULL, 'Pilih jawaban yang menunjukkan kerja sama dan solusi yang tepat terhadap masalah.', '2026-05-09 18:49:01', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 107);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (374, 3, NULL, 49, NULL, NULL, NULL, 'Anda ditunjuk sebagai ketua kegiatan. Atasanmu memberikan tugas untuk menyiapkan pentas seni acara ulang tahun perusahaanmu yang ke-21 dikarenakan tiap-tiap kantor cabang harus menampilkan pertunjukannya. Tindakan yang Anda lakukan...', NULL, 'Bekerja keras membentuk panitia persiapan pentas seni ulang tahun perusahaan', NULL, 'Menunjuk beberapa anggota untuk tampil pada pentas seni ulang tahun perusahaan', NULL, 'Mengumpulkan seluruh anggota untuk membahas bersama-sama persiapan pentas seni ulang tahun perusahaan', NULL, 'Melakukan voting untuk mengambil keputusan persiapan pentas seni ulang tahun perusahaan', NULL, 'Menyerahkan sepenuhnya kepada panitia yang ditunjuk', NULL, 'C', 'Jawaban C menunjukkan kepemimpinan demokratis, kerja sama, dan partisipasi semua anggota.', NULL, 'Pilih jawaban yang menunjukkan kepemimpinan demokratis dan kerja sama tim.', '2026-05-09 18:49:01', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 134);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (376, 1, NULL, 1, NULL, NULL, NULL, 'Ekonomi kerakyatan adalah sistem ekonomi yang berbasis pada kekuatan ekonomi rakyat... Pembangunan ekonomi kerakyatan memiliki peranan dalam menciptakan kemakmuran dan kesejahteraan rakyat. Hal tersebut sesuai dengan bunyi UUD 1945 pasal 33 ayat 1 yang berbunyi...', NULL, 'Cabang-cabang produksi yang penting bagi negara dan yang menguasai hajat hidup orang banyak dikuasai oleh negara', NULL, 'Perekonomian disusun sebagai usaha bersama berdasar atas asas kekeluargaan', NULL, 'Perekonomian nasional diselenggarakan berdasarkan atas demokrasi ekonomi dengan prinsip kebersamaan, efisiensi keadilan, keberlanjutan, wawasan lingkungan, kemandirian, serta dengan menjaga keseimbangan kemajuan dan kesatuan ekonomi nasional', NULL, 'Cabang-cabang produksi boleh dikuasai oleh perseorangan atau Negara', NULL, 'Bumi dan air dan kekayaan alam yang terkandung di dalamnya dikuasai oleh negara dan dipergunakan untuk sebesar-besarnya kemakmuran rakyat', NULL, 'B', 'Pasal 33 ayat 1 UUD 1945: \"Perekonomian disusun sebagai usaha bersama berdasar atas asas kekeluargaan.\" Ini sesuai dengan konsep ekonomi kerakyatan.', NULL, 'Hafalkan Pasal 33 UUD 1945 tentang perekonomian nasional.', '2026-05-09 18:49:01', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 45);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (377, 1, NULL, 1, NULL, NULL, NULL, 'Seorang pegawai negeri sipil diberikan tawaran oleh seorang rekan bisnis instansi untuk menerima paket liburan gratis sebagai bentuk ucapan terima kasih atas kelancaran proyek. Sikap yang harus diambil oleh pegawai tersebut adalah...', NULL, 'Menerimanya karena itu diberikan secara sukarela', NULL, 'Menolak dengan halus dan menjelaskan bahwa hal tersebut melanggar kode etik', NULL, 'Menerima namun melaporkannya kepada atasan setelah pulang liburan', NULL, 'Memberikan paket tersebut kepada rekan kerja lain yang membutuhkan', NULL, 'Menolak dan langsung memutus hubungan kerja sama dengan rekan tersebut', NULL, 'B', 'Integritas menuntut ASN untuk menolak gratifikasi dalam bentuk apa pun yang berhubungan dengan jabatan atau tugasnya. Menolak dengan sopan adalah cerminan profesionalisme.', NULL, 'Pilih jawaban yang menunjukkan integritas dan profesionalisme sebagai ASN.', '2026-05-09 18:49:01', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 50);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (378, 1, NULL, 1, NULL, NULL, NULL, 'Aksi gotong royong warga desa dalam membangun jembatan yang putus akibat banjir merupakan pengamalan Pancasila, khususnya sila ke...', NULL, 'Kesatu', NULL, 'Kedua', NULL, 'Ketiga', NULL, 'Keempat', NULL, 'Kelima', NULL, 'C', 'Gotong royong dan kerja sama untuk kepentingan umum merupakan wujud nyata dari Persatuan Indonesia (Sila ke-3).', NULL, 'Pahami pengamalan sila-sila Pancasila dalam kehidupan sehari-hari.', '2026-05-09 18:49:01', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 28);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (379, 2, NULL, 41, NULL, NULL, NULL, 'GURU : SEKOLAH = ... : ...', NULL, 'Penebang : Pohon', NULL, 'Musisi : Konser', NULL, 'Pengacara : Hakim', NULL, 'Petani : Ladang', NULL, 'Dokter : Pasien', NULL, 'D', 'Hubungan katanya adalah Profesi : Tempat Bekerja. Guru bekerja di Sekolah, Petani bekerja di Ladang.', NULL, 'Untuk analogi, identifikasi hubungan antara dua kata pertama lalu cari pasangan dengan hubungan yang sama.', '2026-05-09 18:49:01', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 6);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (380, 2, NULL, 25, NULL, NULL, NULL, 'Jika 5 orang pekerja dapat menyelesaikan sebuah bangunan dalam waktu 20 hari, maka berapa lama waktu yang dibutuhkan jika pekerja ditambah menjadi 10 orang?', NULL, '5 hari', NULL, '10 hari', NULL, '15 hari', NULL, '25 hari', NULL, '40 hari', NULL, 'B', 'Ini adalah perbandingan berbalik nilai. 5 x 20 = 10 x x, maka 100 = 10x, x = 10 hari.', NULL, 'Untuk soal kerja berbanding terbalik, gunakan rumus: pekerja1 x waktu1 = pekerja2 x waktu2.', '2026-05-09 18:49:01', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 56);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (381, 2, NULL, 25, NULL, NULL, NULL, 'Semua atlet harus menjaga pola makan. Sebagian warga desa adalah atlet. Kesimpulan yang tepat adalah...', NULL, 'Semua warga desa harus menjaga pola makan', NULL, 'Sebagian warga desa harus menjaga pola makan', NULL, 'Semua yang menjaga pola makan adalah atlet', NULL, 'Sebagian warga desa bukan merupakan atlet', NULL, 'Tidak ada warga desa yang menjaga pola makan', NULL, 'B', 'Karena \"sebagian\" warga desa adalah atlet, dan \"semua\" atlet wajib menjaga pola makan, maka kesimpulannya adalah sebagian warga desa (yang atlet tersebut) harus menjaga pola makan.', NULL, 'Untuk silogisme, perhatikan kata kuantifikasi (semua, sebagian, tidak ada) dan tarik kesimpulan yang logis.', '2026-05-09 18:49:01', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 81);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (382, 3, NULL, 49, NULL, NULL, NULL, 'Anda sedang melayani antrean pelanggan yang panjang di kantor, lalu tiba-tiba ada seorang lanjut usia yang meminta didahulukan karena merasa tidak kuat berdiri lama. Sikap Anda adalah...', NULL, 'Langsung melayaninya karena merasa kasihan', NULL, 'Memintanya untuk tetap mengantre agar adil bagi yang lain', NULL, 'Menyiapkan kursi prioritas dan memintanya menunggu sebentar sementara Anda mempercepat pelayanan', NULL, 'Meminta izin kepada antrean di depannya apakah mereka bersedia jika lansia tersebut didahulukan', NULL, 'Menyuruh rekan kerja lain untuk melayani lansia tersebut di meja yang berbeda', NULL, 'D', 'Dalam pelayanan publik, keadilan tetap diutamakan namun empati terhadap kelompok rentan juga diperlukan. Meminta izin kepada pengantre lain menunjukkan sikap komunikatif dan solutif.', NULL, 'Pilih jawaban yang menyeimbangkan keadilan dan empati dalam pelayanan publik.', '2026-05-09 18:49:01', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 110);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (383, 3, NULL, 49, NULL, NULL, NULL, 'Atasan Anda meminta Anda untuk menggunakan aplikasi perkantoran baru yang belum pernah Anda pelajari sebelumnya. Sikap Anda adalah...', NULL, 'Meminta atasan untuk tetap menggunakan cara lama yang lebih aman', NULL, 'Mencari tutorial di internet dan mempelajarinya secara mandiri agar bisa segera menggunakannya', NULL, 'Menunggu rekan kerja lain mempelajarinya terlebih dahulu baru kemudian bertanya', NULL, 'Mengeluh karena beban kerja bertambah dengan adanya sistem baru', NULL, 'Meminta perusahaan mengadakan pelatihan khusus sebelum mewajibkan penggunaannya', NULL, 'B', 'ASN harus adaptif terhadap teknologi. Inisiatif belajar mandiri menunjukkan kemauan untuk berkembang tanpa membebani organisasi secara berlebihan.', NULL, 'Pilih jawaban yang menunjukkan adaptabilitas dan inisiatif belajar mandiri.', '2026-05-09 18:49:01', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 112);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (386, 1, NULL, 1, NULL, NULL, NULL, 'Konflik antara Indonesia dengan Tiongkok kembali terjadi di Perairan Natuna yang berbatasan dengan Laut Cina Selatan. Sejumlah kapal penangkap ikan asal Tiongkok didampingi kapan Coast Guard negaranya, berkegiatan di perairan yang masih masuk dalam teritori ZonaEkonomi Eksklusif (ZEE) milik Indonesia. Hal tersebut juga merupakan sebuah ancaman bagi Indonesia. Ancaman terhadap satu pulau atau daerah pada hakikatnya ancaman seluruh bangsa dan negara. Hal ini ditegaskan dalam wawasan Nusantara dalam bidang...', NULL, 'Ideologi', NULL, 'Politik', NULL, 'Ekonomi', NULL, 'Sosial budaya', NULL, 'Hankam', NULL, 'E', 'Wawasan Nusantara dalam bidang Hankam menyatakan bahwa ancaman terhadap satu pulau atau daerah adalah ancaman terhadap seluruh bangsa dan negara.', NULL, 'Pahami konsep Wawasan Nusantara dan aspek-aspeknya (politik, ekonomi, sosial budaya, hankam).', '2026-05-09 18:50:40', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 39);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (387, 1, NULL, 25, NULL, NULL, NULL, 'Pancasila sebagai ideologi terbuka memiliki batas-batas berikut, kecuali', NULL, 'Mencegah berkembangnya paham dan ideologi liberal.', NULL, 'Penciptaan norma baru tidak perlu memiliki konsensus', NULL, 'Larangan terhadap ideologi Marxisme, Leninisme, dan Komunisme', NULL, 'Larangan terhadap pandangan ekstrim yang meresahkan masyarakat.', NULL, 'Menekankan pandangan stabilitas nasional yang sehat dan dinamis.', NULL, 'B', 'Pancasila sebagai ideologi terbuka dapat berkembang dan menyerap nilai baru, tetapi tetap harus melalui konsensus nasional. Penciptaan norma baru tanpa konsensus bertentangan dengan prinsip demokrasi.', NULL, 'Pahami konsep ideologi terbuka dan batas-batasnya dalam Pancasila.', '2026-05-09 18:50:40', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 4);
