INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (433, 3, NULL, 49, NULL, NULL, NULL, 'Anda sedang sibuk dengan pekerjaan Anda yang sudah hampir memasuki deadline, maka Anda akan...', NULL, 'Mengurangi aktivitas bersama keluarga Anda', NULL, 'Lembur setiap hari', NULL, 'Mengurangi interaksi dengan rekan-rekan kerja Anda', NULL, 'Biasa saja karena saya sudah menyicilnya terlebih dulu', NULL, 'Fokus pada penyelesaian tugas tanpa melupakan yang lainnya', NULL, 'E', 'Jawaban E menunjukkan kemampuan manajemen waktu, fokus, dan keseimbangan kehidupan.', NULL, 'Pilih jawaban yang menunjukkan kemampuan manajemen waktu dan keseimbangan kehidupan.', '2026-05-09 18:50:40', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 110);
