INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (465, 3, NULL, 49, NULL, NULL, NULL, 'Edi baru saja diterima bekerja di salah satu pabrik pengolahan kayu. Sebagai pegawai baru, tentu Edi belum terlalu mengenal jenis-jenis pekerjaan dan cara menyelesaikannya. Suatu malam, tiba-tiba Edi ditugaskan manajernya untuk menyelesaikan tugas seorang rekannya yang tiba-tiba memutuskan untuk keluar dan berhenti bekerja. Edi jelas kaget dan kesulitan dengan penugasan itu, tapi ia tidak punya pilihan lain selain menjalankan perintah atasan. Apalagi manajer tadi memang memberikan tugas tersebut karena kagum melihat track record Edi sebagai mahasiswa lulusan terbaik. Menurut Anda, apa yang harus dilakukan Edi?', NULL, 'Meminta orang lain mengerjakan asalkan bisa selesai tepat waktu', NULL, 'Segera berusaha memulai dan menyelesaikan sebisanya saja yang penting selesai', NULL, 'Tidak perlu buru-buru menyelesaikannya karena pekerjaan tersebut bukan merupakan tugas pokoknya', NULL, 'Segera berusaha memulai untuk menyelesaikan tugas itu dan berusaha menyelesaikannya sesempurna mungkin', NULL, 'Mempertanyakan dan menegosiasi manajernya karena merasa takut hasilnya tidak maksimal', NULL, 'D', 'Jawaban D menunjukkan profesionalisme dan semangat berprestasi. Melaksanakan tupoksi sebaik mungkin secara maksimal.', NULL, 'Pilih jawaban yang menunjukkan profesionalisme dan semangat berprestasi.', '2026-05-09 18:50:40', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 127);
