INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (467, 1, NULL, 1, NULL, NULL, NULL, '\"Sesudah tiga hari berturut-turut anggota-anggota Dokuritsu Zyunbi Tyoosakai mengeluarkan pendapat-pendapatnya, maka sekarang saya mendapat kehormatan dari Paduka Tuan Ketua yang mulia untuk mengemukakan pendapat saya...\" Dalam pidatonya di sidang BPUPKI Bung Karno telah menyampaikan prinsip dasar negara yakni...', NULL, 'Kebangsaan Indonesia; Internasionalisme atau perikemanusiaan; Mufakat atau demokrasi; Perdamaian abadi', NULL, 'Peri Kebangsaan, Peri Kemanusiaan, Peri keTuhanan, Peri Kerakyatan, dan Mufakat', NULL, 'Kebangsaan Indonesia; Internasionalisme atau perikemanusiaan; Mufakat atau demokrasi; Kesejahteraan sosial; Ketuhanan yang berkebudayaan', NULL, 'Peri Kebangsaan, Peri Kemanusiaan, Peri keTuhanan, Peri Kerakyatan, dan Kesejahteraan Rakyat', NULL, 'Ketuhanan YME, Peri Kemanusiaan, Kebangsaan, Kerakyatan, Keadilan Sosial', NULL, 'C', 'Pada tanggal 1 Juni 1945, Ir. Soekarno menyampaikan pidato di hadapan sidang BPUPKI dengan lima asas: Nasionalisme, Internasionalisme, Mufakat, Kesejahteraan sosial, dan Ketuhanan yang berkebudayaan.', NULL, 'Hafalkan pidato 1 Juni 1945 Ir. Soekarno tentang lima asas Pancasila.', '2026-05-09 18:50:40', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 40);
