INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (476, 1, NULL, 13, NULL, NULL, NULL, 'Secara umum, tujuan bela negara adalah untuk mewujudkan sikap dan perilaku yang mendukung sistem pertahanan negara. Salah satu nilai utama dalam bela negara adalah kesadaran berbangsa dan bernegara. Bagaimana kesadaran ini seharusnya diimplementasikan dalam kehidupan sehari-hari?', NULL, 'Aktif mengikuti kegiatan sosial di lingkungan sekitar untuk membangun koneksi yang kuat dengan kelompok tertentu', NULL, 'Menghormati perbedaan dan menjaga kerukunan antar suku, agama, ras, dan golongan di setiap kesempatan', NULL, 'Mengutamakan kepentingan nasional dalam setiap keputusan yang diambil, meskipun terkadang mengorbankan kepentingan individu atau kelompok', NULL, 'Menunjukkan semangat nasionalisme dengan mengikuti berbagai acara formal yang diselenggarakan oleh pemerintah dan organisasi', NULL, 'Mengkritisi kebijakan pemerintah yang dirasa tidak sesuai dengan kepentingan kelompol tertentu sebagai bentuk kepedulian terhadap bangsa', NULL, 'B', 'Kesadaran berbangsa dan bernegara diimplementasikan dengan menghormati perbedaan dan menjaga kerukunan antar suku, agama, ras, dan golongan.', NULL, 'Pilih jawaban yang menunjukkan sikap toleransi dan kerukunan dalam keberagaman.', '2026-05-09 18:50:40', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 2);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (477, 1, NULL, 1, NULL, NULL, NULL, 'Dalam konteks penerapan prinsip Bhinneka Tunggal Ika, berikut adalah pernyataan yang paling tepat mengenai masyarakat Indonesia dalam mengelola keberagaman...', NULL, 'Masyarakat Indonesia harus menghargai perbedaan suku, agama, dan budaya sebagai elemen yang memperkaya kehidupan sosial tanpa mengubah norma dan tradisi lokal', NULL, 'Masyarakat Indonesia harus menyamakan semua aspek kehidupan sosial dan budaya untuk mencapai persatuan yang homogen tanpa memandang perbedaan yang ada', NULL, 'Masyarakat Indonesia harus mengintegrasikan perbedaan suku, agama, dan budaya dalam satu identitas nasional sambil mempertahankan keberagaman sebagai nilai yang dibanggakan', NULL, 'Masyarakat Indonesia harus menciptakan kebijakan yang menyeimbangkan antara penghargaan terhadap perbedaan dan upaya untuk tuk menyamakan stand standar dalam kehidupan berbangsa dan bernegara', NULL, 'Masyarakat Indonesia harus memastikan bahwa semua kelompok memiliki hak dan kewajiban yang sama tanpa memandang latar belakang suku, agama, dan budaya, sehingga menghindari perbedaan yang dapat memecah belah persatuan', NULL, 'C', 'Bhinneka Tunggal Ika berarti berbeda-beda tetapi tetap satu jua. Masyarakat harus mengintegrasikan perbedaan dalam satu identitas nasional sambil mempertahankan keberagaman.', NULL, 'Pilih jawaban yang mencerminkan semangat Bhinneka Tunggal Ika - persatuan dalam keberagaman.', '2026-05-09 18:50:40', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 40);
