INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (576, 3, NULL, 49, NULL, NULL, NULL, 'Anda akan memberikan kontribusi terhadap pembangunan nusa dan bangsa Indonesia...', NULL, 'Apabila Anda berkarya sebagai PNS', NULL, 'Di manapun Anda berkarya, akan turut memberikan kontribusi terhadap pembangunan bangsa', NULL, 'Ketika Anda menjadi seorang birokrat tingkat atas', NULL, 'Ketika Anda menjabat anggota DPR', NULL, 'Di manapun Anda berkarya, akan turut memberikan kontribusi terhadap pembangunan bangsa dengan syarat didukung oleh pemerintah', NULL, 'B', 'Jawaban B menunjukkan sikap nasionalisme, tanggung jawab, dan kesediaan berkontribusi di mana pun.', NULL, 'Pilih jawaban yang menunjukkan nasionalisme dan tanggung jawab terhadap bangsa.', '2026-05-09 18:53:47', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 134);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (577, 3, NULL, 49, NULL, NULL, NULL, 'Atasan Anda tidak ada di kantor. Teman Anda mengajak untuk sedikit bersantai. Bagaimana dengan Anda?', NULL, 'Tetap di meja dan menyelesaikan pekerjaan', NULL, 'Mengikuti ajakannya dan bersantai', NULL, 'Ragu-ragu', NULL, 'Apabila memang tidak ada yang mengawasi, maka boleh saja bersantai', NULL, 'Memarahi teman dan menyuruh semuanya bekerja', NULL, 'A', 'Jawaban A menunjukkan integritas, disiplin, dan etos kerja yang tinggi.', NULL, 'Pilih jawaban yang menunjukkan integritas dan etos kerja tinggi.', '2026-05-09 18:53:47', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 112);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (589, 1, NULL, 1, NULL, NULL, NULL, '\"Sesudah tiga hari berturut-turut anggota-anggota Dokuritsu Zyunbi Tyoosakai mengeluarkan pendapat-pendapatnya, maka sekarang saya mendapat kehormatan dari Paduka Tuan Ketua yang mulia untuk mengemukakan pendapat saya...\" Dalam pidatonya di sidang BPUPKI Bung Karno telah menyampaikan prinsip dasar negara yakni...', NULL, 'Kebangsaan Indonesia; Internasionalisme atau perikemanusiaan; Mufakat atau demokrasi; Perdamaian abadi', NULL, 'Peri Kebangsaan, Peri Kemanusiaan, Peri keTuhanan, Peri Kerakyatan, dan Mufakat', NULL, 'Kebangsaan Indonesia; Internasionalisme atau perikemanusiaan; Mufakat atau demokrasi; Kesejahteraan sosial; Ketuhanan yang berkebudayaan', NULL, 'Peri Kebangsaan, Peri Kemanusiaan, Peri keTuhanan, Peri Kerakyatan, dan Kesejahteraan Rakyat', NULL, 'Ketuhanan YME, Peri Kemanusiaan, Kebangsaan, Kerakyatan, Keadilan Sosial', NULL, 'C', 'Pada tanggal 1 Juni 1945, Ir. Soekarno menyampaikan pidato di hadapan sidang BPUPKI dengan lima asas: Nasionalisme, Internasionalisme, Mufakat, Kesejahteraan sosial, dan Ketuhanan yang berkebudayaan.', NULL, 'Hafalkan pidato 1 Juni 1945 Ir. Soekarno tentang lima asas Pancasila.', '2026-05-09 18:53:47', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 40);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (592, 1, NULL, 1, NULL, NULL, NULL, 'Aksi gotong royong warga desa dalam membangun jembatan yang putus akibat banjir merupakan pengamalan Pancasila, khususnya sila ke...', NULL, 'Kesatu', NULL, 'Kedua', NULL, 'Ketiga', NULL, 'Keempat', NULL, 'Kelima', NULL, 'C', 'Gotong royong dan kerja sama untuk kepentingan umum merupakan wujud nyata dari Persatuan Indonesia (Sila ke-3).', NULL, 'Pahami pengamalan sila-sila Pancasila dalam kehidupan sehari-hari.', '2026-05-09 18:53:47', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 28);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (593, 2, NULL, 41, NULL, NULL, NULL, 'GURU : SEKOLAH = ... : ...', NULL, 'Penebang : Pohon', NULL, 'Musisi : Konser', NULL, 'Pengacara : Hakim', NULL, 'Petani : Ladang', NULL, 'Dokter : Pasien', NULL, 'D', 'Hubungan katanya adalah Profesi : Tempat Bekerja. Guru bekerja di Sekolah, Petani bekerja di Ladang.', NULL, 'Untuk analogi, identifikasi hubungan antara dua kata pertama lalu cari pasangan dengan hubungan yang sama.', '2026-05-09 18:53:47', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 6);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (595, 2, NULL, 25, NULL, NULL, NULL, 'Semua atlet harus menjaga pola makan. Sebagian warga desa adalah atlet. Kesimpulan yang tepat adalah...', NULL, 'Semua warga desa harus menjaga pola makan', NULL, 'Sebagian warga desa harus menjaga pola makan', NULL, 'Semua yang menjaga pola makan adalah atlet', NULL, 'Sebagian warga desa bukan merupakan atlet', NULL, 'Tidak ada warga desa yang menjaga pola makan', NULL, 'B', 'Karena \"sebagian\" warga desa adalah atlet, dan \"semua\" atlet wajib menjaga pola makan, maka kesimpulannya adalah sebagian warga desa (yang atlet tersebut) harus menjaga pola makan.', NULL, 'Untuk silogisme, perhatikan kata kuantifikasi (semua, sebagian, tidak ada) dan tarik kesimpulan yang logis.', '2026-05-09 18:53:47', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 81);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (597, 3, NULL, 49, NULL, NULL, NULL, 'Atasan Anda meminta Anda untuk menggunakan aplikasi perkantoran baru yang belum pernah Anda pelajari sebelumnya. Sikap Anda adalah...', NULL, 'Meminta atasan untuk tetap menggunakan cara lama yang lebih aman', NULL, 'Mencari tutorial di internet dan mempelajarinya secara mandiri agar bisa segera menggunakannya', NULL, 'Menunggu rekan kerja lain mempelajarinya terlebih dahulu baru kemudian bertanya', NULL, 'Mengeluh karena beban kerja bertambah dengan adanya sistem baru', NULL, 'Meminta perusahaan mengadakan pelatihan khusus sebelum mewajibkan penggunaannya', NULL, 'B', 'ASN harus adaptif terhadap teknologi. Inisiatif belajar mandiri menunjukkan kemauan untuk berkembang tanpa membebani organisasi secara berlebihan.', NULL, 'Pilih jawaban yang menunjukkan adaptabilitas dan inisiatif belajar mandiri.', '2026-05-09 18:53:47', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 112);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (598, 1, NULL, 13, NULL, NULL, NULL, 'Secara umum, tujuan bela negara adalah untuk mewujudkan sikap dan perilaku yang mendukung sistem pertahanan negara. Salah satu nilai utama dalam bela negara adalah kesadaran berbangsa dan bernegara. Bagaimana kesadaran ini seharusnya diimplementasikan dalam kehidupan sehari-hari?', NULL, 'Aktif mengikuti kegiatan sosial di lingkungan sekitar untuk membangun koneksi yang kuat dengan kelompok tertentu', NULL, 'Menghormati perbedaan dan menjaga kerukunan antar suku, agama, ras, dan golongan di setiap kesempatan', NULL, 'Mengutamakan kepentingan nasional dalam setiap keputusan yang diambil, meskipun terkadang mengorbankan kepentingan individu atau kelompok', NULL, 'Menunjukkan semangat nasionalisme dengan mengikuti berbagai acara formal yang diselenggarakan oleh pemerintah dan organisasi', NULL, 'Mengkritisi kebijakan pemerintah yang dirasa tidak sesuai dengan kepentingan kelompol tertentu sebagai bentuk kepedulian terhadap bangsa', NULL, 'B', 'Kesadaran berbangsa dan bernegara diimplementasikan dengan menghormati perbedaan dan menjaga kerukunan antar suku, agama, ras, dan golongan.', NULL, 'Pilih jawaban yang menunjukkan sikap toleransi dan kerukunan dalam keberagaman.', '2026-05-09 18:53:47', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 2);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (599, 1, NULL, 1, NULL, NULL, NULL, 'Dalam konteks penerapan prinsip Bhinneka Tunggal Ika, berikut adalah pernyataan yang paling tepat mengenai masyarakat Indonesia dalam mengelola keberagaman...', NULL, 'Masyarakat Indonesia harus menghargai perbedaan suku, agama, dan budaya sebagai elemen yang memperkaya kehidupan sosial tanpa mengubah norma dan tradisi lokal', NULL, 'Masyarakat Indonesia harus menyamakan semua aspek kehidupan sosial dan budaya untuk mencapai persatuan yang homogen tanpa memandang perbedaan yang ada', NULL, 'Masyarakat Indonesia harus mengintegrasikan perbedaan suku, agama, dan budaya dalam satu identitas nasional sambil mempertahankan keberagaman sebagai nilai yang dibanggakan', NULL, 'Masyarakat Indonesia harus menciptakan kebijakan yang menyeimbangkan antara penghargaan terhadap perbedaan dan upaya untuk tuk menyamakan stand standar dalam kehidupan berbangsa dan bernegara', NULL, 'Masyarakat Indonesia harus memastikan bahwa semua kelompok memiliki hak dan kewajiban yang sama tanpa memandang latar belakang suku, agama, dan budaya, sehingga menghindari perbedaan yang dapat memecah belah persatuan', NULL, 'C', 'Bhinneka Tunggal Ika berarti berbeda-beda tetapi tetap satu jua. Masyarakat harus mengintegrasikan perbedaan dalam satu identitas nasional sambil mempertahankan keberagaman.', NULL, 'Pilih jawaban yang mencerminkan semangat Bhinneka Tunggal Ika - persatuan dalam keberagaman.', '2026-05-09 18:53:47', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 40);
