INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (628, 3, NULL, 49, NULL, NULL, NULL, 'Anda adalah seorang kepala instansi yang cukup bergengsi. Suatu hari, ada teman akrab Anda datang dan meminta bantuan agar menerima anaknya bekerja tanpa melalui tes. Rekan karib Anda tersebut menjanjikan jaminan berupa sejumlah uang dan fasilitas. Apa yang akan Anda lakukan?', NULL, 'Menerima tawaran tanpa jaminan karena dia sahabat Anda', NULL, 'Basa-basi dulu, lalu menerimanya karena tidak enak pada teman', NULL, 'Menolaknya mentah-mentah', NULL, 'Menolaknya secara halus dan menganjurkan agar anak rekan Anda mengikuti seleksi seperti lainnya', NULL, 'Menerimanya dan menyuruhnya mengikuti tes seleksi sebagai formalitas', NULL, 'D', 'Menolak secara halus dan menganjurkan mengikuti seleksi menunjukkan integritas dan profesionalisme sebagai kepala instansi.', NULL, 'Pilih jawaban yang menunjukkan integritas dan kepatuhan terhadap prosedur.', '2026-05-09 18:53:47', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 119);
