INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (630, 3, NULL, 49, NULL, NULL, NULL, 'Ketika diterima sebagai PNS dan Anda tidak mempunyai uang, maka Anda akan...', NULL, 'Bekerja apapun untuk memperoleh uang', NULL, 'Mencari pinjaman ke teman sekantor', NULL, 'Mencari pinjaman dari atasan', NULL, 'Mengundurkan diri dari PNS', NULL, 'Melakukan tindakan korupsi', NULL, 'B', 'Mencari pinjaman ke teman sekantor menunjukkan solusi yang tepat tanpa melanggar integritas.', NULL, 'Pilih jawaban yang menunjukkan solusi tepat tanpa melanggar integritas.', '2026-05-09 18:53:47', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 107);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (631, 3, NULL, 49, NULL, NULL, NULL, 'Anda adalah seorang pegawai yang rajin. Namun, apa yang akan terjadi di masa depan tak ada yang tahu...', NULL, 'Anda tetap saja akan terkena pemutusan hubungan kerja (PHK) apabila ekonomi nasional lesu', NULL, 'Mustahil pegawai serajin Anda terkena PHK', NULL, 'Karakter Anda sebagai karyawan rajin dapat membantu kenaikan karier', NULL, 'Pemecatan banyak pegawai tidaklah terlalu berpengaruh terhadap citra perusahaan', NULL, 'Harusnya pegawai rajin tidak boleh terkena PHK', NULL, 'C', 'Karakter rajin dapat membantu kenaikan karier karena kinerja yang baik dihargai.', NULL, 'Pilih jawaban yang menunjukkan hubungan antara karakter rajin dan karier.', '2026-05-09 18:53:47', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 119);
