INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (670, 3, NULL, 49, NULL, NULL, NULL, 'Apakah Anda selalu merasa mempunyai talenta dan kesempatan yang sama dengan orang lain?', NULL, 'Anda merasa mempunyai lebih dari orang lain', NULL, 'Talenta orang berbeda, tetapi kesempatan setiap orang untuk menjadi yang terbaik adalah sama', NULL, 'Anda merasa sama dengan orang yang lain', NULL, 'Anda merasa orang lain banyak yang lebih baik', NULL, 'Anda merasa tidak mempunyai kemampuan apapun', NULL, 'B', 'Talenta berbeda tetapi kesempatan sama menunjukkan sikap adil dan optimis.', NULL, 'Pilih jawaban yang menunjukkan sikap adil dan optimis.', '2026-05-09 18:53:47', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 138);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (671, 3, NULL, 49, NULL, NULL, NULL, 'Apakah Anda selalu membandingkan diri Anda dengan rekan kerja yang lain?', NULL, 'Ya, sebagai motivasi untuk menjadi lebih baik', NULL, 'Ya, Anda tidak boleh kalah karena Anda selalu menjadi yang nomor satu', NULL, 'Sering seperti itu', NULL, 'Terkadang saja dan hanya beberapa hal', NULL, 'Tidak pernah, Anda tidak peduli dengan bagaimana orang lain', NULL, 'A', 'Membandingkan sebagai motivasi untuk menjadi lebih baik menunjukkan sikap kompetitif yang sehat.', NULL, 'Pilih jawaban yang menunjukkan sikap kompetitif yang sehat.', '2026-05-09 18:53:47', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 138);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (672, 3, NULL, 49, NULL, NULL, NULL, 'Anda sering mengingatkan bawahan untuk tidak melakukan kesalahan pekerjaan di kantor...', NULL, 'Anda pun tidak boleh melakukan kesalahan itu', NULL, 'Karena Anda atasannya, peraturan tidak berlaku bagi diri-sendiri', NULL, 'Anda sesekali melakukan kesalahan', NULL, 'Peraturan khusus untuk pegawai setingkat', NULL, 'Lebih baik Anda tidak melakukan kesalahan itu', NULL, 'A', 'Anda pun tidak boleh melakukan kesalahan menunjukkan keteladanan sebagai atasan.', NULL, 'Pilih jawaban yang menunjukkan keteladanan.', '2026-05-09 18:53:47', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 106);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (673, 3, NULL, 49, NULL, NULL, NULL, 'Draf laporan yang dibuat oleh tim kerja Anda ditolak atasan karena dianggap kurang layak. Sikap Anda...', NULL, 'Segera melakukan perbaikan draf laporan dan mengajukan kembali', NULL, 'Menyalahkan rekan sejawat yang sama-sama mengerjakannya', NULL, 'Menerima penolakan, tetapi tidak melakukan tindak lanjut', NULL, 'Berusaha mencari alasan seperti sedikitnya waktu untuk mengerjakannya', NULL, 'Tidak menerima penolakan dan berusaha memperbaiki seadanya', NULL, 'A', 'Segera melakukan perbaikan menunjukkan sikap responsif dan bertanggung jawab.', NULL, 'Pilih jawaban yang menunjukkan sikap responsif dan bertanggung jawab.', '2026-05-09 18:53:47', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 121);
