INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (675, 3, NULL, 49, NULL, NULL, NULL, 'Apakah Anda menunjukkan inisiatif dan berusaha untuk mengejar prestasi?', NULL, 'Anda selalu menunjukkan inisiatif dalam bekerja', NULL, 'Terkadang bila Anda terpikirkan ide akan berinisiatif melakukan sesuatu', NULL, 'Tergantung perubahan suasana hati dan kondisi pribadi', NULL, 'Anda jarang menunjukkan inisiatif, tetapi pernah melakukannya', NULL, 'Anda tidak pernah berinisiatif, tetapi melakukan tugas yang ada sebaik mungkin', NULL, 'A', 'Selalu menunjukkan inisiatif menunjukkan sikap proaktif dan berprestasi.', NULL, 'Pilih jawaban yang menunjukkan sikap proaktif dan berprestasi.', '2026-05-09 18:53:47', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 138);
