INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (677, 3, NULL, 49, NULL, NULL, NULL, 'Anda senang bila membantu klien yang...', NULL, 'Cepat mengertinya', NULL, 'Tidak sungkan untuk bertanya', NULL, 'Mengikuti saran-saran Anda', NULL, 'Kritis dan suka bertanya', NULL, 'Biasa-biasa saja', NULL, 'D', 'Klien yang kritis dan suka bertanya menunjukkan klien yang ingin belajar dan berkembang.', NULL, 'Pilih jawaban yang menunjukkan kepuasan membantu klien yang ingin belajar.', '2026-05-09 18:53:47', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 7);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (679, 1, NULL, 1, NULL, NULL, NULL, 'Hampir semua partai politik melakukan proses permohonan gugatan kepada KPU, adapun sengketa yang diajukan antara lain terkait masalah internal dan perselisihan kursi terakhir di DPR RI. Komisi Pemilihan Umum (KPU) RI berusaha mengumpulkan bukti-bukti dari KPU daerah untuk menghadapi gugatan sengketa PHPU Legislatif 2019, yang akan segera disidangkan Komisioner KPU Ilham Saputra mengatakan, bukti-bukti dari KPU Kabupaten/kota dan provinsi itu akan dijadikan bahan untuk memberikan keterangan dalam sidang sengketa Pileg 2019. Jika terjadi kasus tersebut maka yang memiliki kewenangan untuk memberikan putusan adalah...', NULL, 'Komisi Yudisial', NULL, 'Mahkamah Agung', NULL, 'Mahkamah Konstitusi', NULL, 'Kehakiman', NULL, 'Komisi Pemilihan Umum', NULL, 'C', 'Sengketa hasil pemilihan umum (PHPU) merupakan kewenangan Mahkamah Konstitusi berdasarkan UUD 1945 Pasal 24C ayat (1).', NULL, 'Hafalkan kewenangan lembaga negara dalam UUD 1945, terutama Mahkamah Konstitusi untuk sengketa pemilu.', '2026-05-09 18:57:31', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 39);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (681, 1, NULL, 25, NULL, NULL, NULL, 'Pancasila sebagai ideologi terbuka memiliki batas-batas berikut, kecuali', NULL, 'Mencegah berkembangnya paham dan ideologi liberal.', NULL, 'Penciptaan norma baru tidak perlu memiliki konsensus', NULL, 'Larangan terhadap ideologi Marxisme, Leninisme, dan Komunisme', NULL, 'Larangan terhadap pandangan ekstrim yang meresahkan masyarakat.', NULL, 'Menekankan pandangan stabilitas nasional yang sehat dan dinamis.', NULL, 'B', 'Pancasila sebagai ideologi terbuka dapat berkembang dan menyerap nilai baru, tetapi tetap harus melalui konsensus nasional. Penciptaan norma baru tanpa konsensus bertentangan dengan prinsip demokrasi.', NULL, 'Pahami konsep ideologi terbuka dan batas-batasnya dalam Pancasila.', '2026-05-09 18:57:31', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 4);
