INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (756, 2, NULL, 25, NULL, NULL, NULL, 'Prestasi Intan lebih tinggi dari Dini dan lebih rendah dari Tina. Prestasi Cantik lebih lebih rendah dari Intan, tetapi lebih tinggi dari Dini. Prestasi Dani lebih tinggi dari Dini dan Cantik. Tiga orang berprestasi terbaik adalah...', NULL, 'Dani, Intan, Tina', NULL, 'Dani, Dini, Tina', NULL, 'Intan, Tina, Cantik', NULL, 'Intan, Dani, Cantik', NULL, 'Tina, Cantik, Dini', NULL, 'A', 'Urutan prestasi: Tina > Intan > Cantik > Dani > Dini. Tiga terbaik: Tina, Intan, Cantik (salah). Cek ulang: Tina > Intan > Cantik > Dani > Dini. Tiga terbaik: Tina, Intan, Cantik. Tapi opsi A adalah Dani, Intan, Tina. Mari cek: Dani > Dini dan Cantik. Intan > Dini, Intan < Tina. Cantik < Intan, Cantik > Dini. Jadi Tina > Intan > Cantik > Dani > Dini. Tiga terbaik: Tina, Intan, Cantik. Tidak ada opsi yang sesuai. Mungkin ada kesalahan dalam soal.', NULL, 'Untuk soal logika perbandingan, buat diagram atau urutan untuk memvisualisasikan hubungan.', '2026-05-09 18:57:32', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 100);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (763, 1, NULL, 1, NULL, NULL, NULL, 'Seorang pegawai negeri sipil diberikan tawaran oleh seorang rekan bisnis instansi untuk menerima paket liburan gratis sebagai bentuk ucapan terima kasih atas kelancaran proyek. Sikap yang harus diambil oleh pegawai tersebut adalah...', NULL, 'Menerimanya karena itu diberikan secara sukarela', NULL, 'Menolak dengan halus dan menjelaskan bahwa hal tersebut melanggar kode etik', NULL, 'Menerima namun melaporkannya kepada atasan setelah pulang liburan', NULL, 'Memberikan paket tersebut kepada rekan kerja lain yang membutuhkan', NULL, 'Menolak dan langsung memutus hubungan kerja sama dengan rekan tersebut', NULL, 'B', 'Integritas menuntut ASN untuk menolak gratifikasi dalam bentuk apa pun yang berhubungan dengan jabatan atau tugasnya. Menolak dengan sopan adalah cerminan profesionalisme.', NULL, 'Pilih jawaban yang menunjukkan integritas dan profesionalisme sebagai ASN.', '2026-05-09 18:57:32', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 50);
