an.', NULL, 'Pilih jawaban yang mencerminkan semangat Bhinneka Tunggal Ika - persatuan dalam keberagaman.', '2026-05-09 18:59:35', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 40);
