INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (1060, 1, NULL, 3, NULL, NULL, NULL, 'Indonesia memiliki beragam suku bangsa. Bagaimana sikap yang sebaiknya diambil untuk membangun persatuan?', NULL, 'Mempertahankan kebudayaan masing-masing suku secara eksklusif', NULL, 'Mengutamakan suku tertentu sebagai suku yang paling unggul', NULL, 'Menghargai dan merayakan keberagaman suku bangsa', NULL, 'Memisahkan diri dari suku lain', NULL, 'Disiplin kerja', NULL, 'C', 'Menghargai dan merayakan keberagaman suku bangsa membangun persatuan Indonesia.', NULL, 'Pilih jawaban yang menunjukkan sikap toleransi dan penghargaan terhadap keberagaman.', '2026-05-09 18:59:36', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 1);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (1090, 2, NULL, 25, NULL, NULL, NULL, 'Dayana memiliki permen sebanyak 3 kali banyaknya permen yang dimiliki Estefania. Permen Estefania lebih sedikit 6 buah dari Catriona. Catriona memiliki 2 permen lebih banyak dari Dayana. Perbandingan banyak permen yang dimiliki ketiganya adalah...', NULL, '3 : 6 : 2', NULL, '6 : 2 : 4', NULL, '4 : 3 : 1', NULL, '3 : 1 : 4', NULL, '1 : 2 : 4', NULL, 'C', 'Misalkan Permen Dayana = D, Permen Estefania = E, Permen Catriona = C. D = 3E, E = C - 6, C = D + 2. Substitusi: C = 3E + 2, E = (3E + 2) - 6, E = 3E - 4, 2E = 4, E = 2. Maka D = 6, C = 8. Perbandingan C : D : E = 8 : 6 : 2 = 4 : 3 : 1.', NULL, 'Untuk soal perbandingan, misalkan variabel dan buat persamaan, lalu selesaikan sistem persamaan.', '2026-05-09 18:59:36', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 53);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (1091, 2, NULL, 25, NULL, NULL, NULL, 'Pernyataan: \"jika laba tinggi maka karyawan sejahtera\" mempunyai kontraposisi yaitu...', NULL, 'Jika laba tinggi maka karyawan tidak sejahtera', NULL, 'Jika laba rendah maka karyawan tidak sejahtera', NULL, 'Jika laba rendah maka karyawan sejahtera', NULL, 'Jika karyawan sejahtera maka laba tinggi', NULL, 'Jika karyawan tidak sejahtera maka laba tidak tinggi', NULL, 'E', 'Kontraposisi dari p → q adalah ~q → ~p. Jadi kontraposisi \"jika laba tinggi maka karyawan sejahtera\" adalah \"Jika karyawan tidak sejahtera maka laba tidak tinggi\".', NULL, 'Hafalkan rumus kontraposisi: p → q, kontraposisinya adalah ~q → ~p.', '2026-05-09 18:59:36', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 59);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (1092, 2, NULL, 25, NULL, NULL, NULL, 'MEI : JULI = .... = ....', NULL, 'Januari : Desember', NULL, 'Januari : November', NULL, 'Juli : Oktober', NULL, 'Maret : Mei', NULL, 'Agustus : September', NULL, 'D', 'Kuncinya adalah urutan bulan. Dua bulan setelah Mei adalah Juli. Dua bulan setelah Maret adalah Mei.', NULL, 'Untuk soal analogi waktu, perhatikan pola atau jarak waktu antara dua hal yang diberikan.', '2026-05-09 18:59:36', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 4);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (1093, 3, NULL, 49, NULL, NULL, NULL, 'Rekan kerja baru saya sering sekali izin sakit ketika bekerja sehingga saya jarang bertemu dengannya. Suatu hari pimpinan saya memberikan amanat kepada saya untuk menagih tugas yang dibebankan kepada rekan kerja saya karena dia sudah cukup lama tidak hadir di kantor. Sikap saya adalah...', NULL, 'Menolak karena saya tidak berwenang untuk menagih', NULL, 'Menerima perintah pimpinan karena pekerjaan tersebut penting bagi perusahaan', NULL, 'Menerima karena pimpinan saya memberikan uang tambahan', NULL, 'Menerima jika saya mendapatkan promosi kerja', NULL, 'Tidak peduli dengan keadaan kantor, yang saya tahu saya hanya bekerja', NULL, 'B', 'Jawaban B memiliki skor tertinggi (5) yang menunjukkan kemampuan menyesuaikan diri dengan tugas baru dan berorientasi pada kemajuan perusahaan.', NULL, 'Pilih jawaban dengan skor tertinggi yang menunjukkan orientasi pada kemajuan perusahaan.', '2026-05-09 18:59:36', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 116);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (1094, 3, NULL, 49, NULL, NULL, NULL, 'Jika saya gagal dalam sebuah hubungan, saya...', NULL, 'Menyerah dan sangat putus asa', NULL, 'Tidak akan memulai hubungan dalam waktu yang lama', NULL, 'Sadar bahwa mungkin ini yang terbaik untuk saya', NULL, 'Mengintrospeksi diri saya, adakah kekurangan dan kesalahan yang saya lakukan', NULL, 'Sadar bahwa menjalin hubungan itu hanya membuang-buang uang', NULL, 'D', 'Jawaban D memiliki skor tertinggi (5) yang menunjukkan kemauan bangkit dan belajar dari keterpurukan.', NULL, 'Pilih jawaban dengan skor tertinggi yang menunjukkan kemauan belajar dari kegagalan.', '2026-05-09 18:59:36', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 101);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (1095, 3, NULL, 49, NULL, NULL, NULL, 'Persaingan antar kelompok di dalam kantor sangatlah ketat dan kelompok saya mengalami kekalahan saat mengajukan kerja sama dengan perusahaan asing. Sikap saya adalah...', NULL, 'Saya marah-marah terhadap rekan kerja yang lain dan mencari tahu siapa penyebab kekalahan ini', NULL, 'Saya mengevaluasi kinerja bersama-sama dengan kelompok dan menjadikannya pelajaran di masa mendatang', NULL, 'Ini adalah kejadian yang sangat memalukan bagi saya, kelompok saya tidak pernah kalah', NULL, 'Memberikan ucapan selamat kepada pemenang dan saya yakin lain waktu kelompok saya yang akan menang', NULL, 'Saya sudah menduga hasilnya, kelompok kami memang sulit untuk bekerja sama', NULL, 'B', 'Jawaban B memiliki skor tertinggi (5) yang menunjukkan sikap tetap positif dan mencari solusi bersama demi perkembangan di masa mendatang.', NULL, 'Pilih jawaban dengan skor tertinggi yang menunjukkan sikap positif dan solutif.', '2026-05-09 18:59:36', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 105);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (1096, 1, NULL, 1, NULL, NULL, NULL, 'Untuk menjalankan kehidupan bermasyarakat, Indonesia berpedoman pada hukum karena hukum merupakan aturan yang tertulis maupun tidak tertulis yang dapat mengatur masyarakat dan dikenai sanksi jika melanggarnya. Untuk menerapkan suatu sistem hukum diperlukan sumber hukum yang merupakan asal terjadinya hukum. Jadi sebelum adanya hukum, perlu adanya sumber hukum terlebih dahulu. Sumber hukum dapat dibedakan menjadi dua yakni sumber hukum formil dan materil. Manakah di bawah ini yang bukan merupakan sumber hukum formil?', NULL, 'Undang – Undang', NULL, 'Traktat', NULL, 'Yuridipensi', NULL, 'Sosial budaya', NULL, 'Doktrin', NULL, 'D', 'Sumber hukum formil meliputi Undang-Undang, Adat-istiadat, Traktat, Yurisprudensi, dan Doktrin. Sosial budaya bukan sumber hukum formil.', NULL, 'Hafalkan sumber hukum formil: UU, Adat-istiadat, Traktat, Yurisprudensi, Doktrin.', '2026-05-09 18:59:36', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 1);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (1097, 1, NULL, 1, NULL, NULL, NULL, 'Peristiwa nahas ini terjadi saat Sumarijem yang baru berusia 18 tahun tengah menanti bus di pinggir jalan. Tiba-tiba ia diseret oleh sekelompok pria dan dibius. Selanjutnya ia dibawa ke sebuah rumah di Klaten dan diperkosa secara bergilir hingga tak sadarkan diri. Saat melapor pada polisi, bukannya dibantu Sum malah ditangkap atas tuduhan membuat laporan palsu. Ia mendapat masalah besar karena kasus ini melibatkan anak-anak pejabat sebagai tersangka. Bahkan Jenderal Pur Hoegeng yang merupakan mantan Kapolri yang berusaha mengungkap kasus ini malah dipensiunkan. Banyak orang menduga pensiunnya Hoegeng adalah agar kasus ini segera ditutup. Kasus tersebut merupakan pelanggaran dari Undang-Undang Hak Asasi Manusia yakni...', NULL, 'UU No. 40 Tahun 1999', NULL, 'UU No. 38 Tahun 2000', NULL, 'UU No. 39 Tahun 1999', NULL, 'UU No. 37 Tahun 1998', NULL, 'UU No. 36 Tahun 1997', NULL, 'C', 'UU No. 39 Tahun 1999 Pasal 1 mendefinisikan Hak Asasi Manusia sebagai seperangkat hak yang melekat pada hakikat dan keberadaan manusia sebagai makhluk Tuhan Yang Maha Esa.', NULL, 'Hafalkan UU No. 39 Tahun 1999 tentang Hak Asasi Manusia.', '2026-05-09 18:59:36', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 27);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (1098, 1, NULL, 5, NULL, NULL, NULL, 'Alberto Gonzales tinggal di Indonesia sudah lebih dari 5 tahun dan menikah dengan seorang wanita Indonesia dan dikaruniai 3 orang anak. Karena ia telah jatuh cinta dengan Indonesia sehingga ingin mengganti kewarganegaraannya menjadi warga negara Indonesia. Landasan hukum yang digunakan Gonzales untuk mengganti kewarganegaraanya tertuang dalam Undang-Undang Hak Asasi Manusia yakni pada pasal...', NULL, '26 Ayat 1', NULL, '27 Ayat 1', NULL, '28 Ayat 2', NULL, '29 Ayat 3', NULL, '30 Ayat 4', NULL, 'A', 'Pasal 26 Ayat 1 dan 2 UUD 1945 menyatakan: (1) Yang menjadi warga negara ialah orang-orang bangsa Indonesia asli dan orang-orang bangsa lain yang disahkan dengan undang-undang sebagai warga negara.', NULL, 'Hafalkan Pasal 26 UUD 1945 tentang kewarganegaraan.', '2026-05-09 18:59:36', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 1);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (1102, 1, NULL, 25, NULL, NULL, NULL, 'Pancasila sebagai ideologi terbuka memiliki batas-batas berikut, kecuali', NULL, 'Mencegah berkembangnya paham dan ideologi liberal.', NULL, 'Penciptaan norma baru tidak perlu memiliki konsensus', NULL, 'Larangan terhadap ideologi Marxisme, Leninisme, dan Komunisme', NULL, 'Larangan terhadap pandangan ekstrim yang meresahkan masyarakat.', NULL, 'Menekankan pandangan stabilitas nasional yang sehat dan dinamis.', NULL, 'B', 'Pancasila sebagai ideologi terbuka dapat berkembang dan menyerap nilai baru, tetapi tetap harus melalui konsensus nasional. Penciptaan norma baru tanpa konsensus bertentangan dengan prinsip demokrasi.', NULL, 'Pahami konsep ideologi terbuka dan batas-batasnya dalam Pancasila.', '2026-05-09 19:01:38', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 4);
