INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (1138, 2, NULL, 25, NULL, NULL, NULL, '1, 5, 11, 19, 29, ..., 55', NULL, '39 dan 69', NULL, '41 dan 71', NULL, '35 dan 65', NULL, '39 dan 65', NULL, '40 dan 71', NULL, 'B', 'Pola: +4, +6, +8, +10, +12, +16. 29+12=41, 41+16=57 (bukan 55). Cek ulang: 1+4=5, 5+6=11, 11+8=19, 19+10=29, 29+12=41, 41+14=55. Pola: selisih bertambah 2. 41+14=55.', NULL, 'Untuk deret angka, perhatikan apakah selisih antar angka mengikuti pola tertentu.', '2026-05-09 19:01:38', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 4);
