INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (1309, 3, NULL, 49, NULL, NULL, NULL, 'Jika saya gagal dalam sebuah hubungan, saya...', NULL, 'Menyerah dan sangat putus asa', NULL, 'Tidak akan memulai hubungan dalam waktu yang lama', NULL, 'Sadar bahwa mungkin ini yang terbaik untuk saya', NULL, 'Mengintrospeksi diri saya, adakah kekurangan dan kesalahan yang saya lakukan', NULL, 'Sadar bahwa menjalin hubungan itu hanya membuang-buang uang', NULL, 'D', 'Jawaban D memiliki skor tertinggi (5) yang menunjukkan kemauan bangkit dan belajar dari keterpurukan.', NULL, 'Pilih jawaban dengan skor tertinggi yang menunjukkan kemauan belajar dari kegagalan.', '2026-05-09 19:01:39', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 101);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (1313, 1, NULL, 5, NULL, NULL, NULL, 'Alberto Gonzales tinggal di Indonesia sudah lebih dari 5 tahun dan menikah dengan seorang wanita Indonesia dan dikaruniai 3 orang anak. Karena ia telah jatuh cinta dengan Indonesia sehingga ingin mengganti kewarganegaraannya menjadi warga negara Indonesia. Landasan hukum yang digunakan Gonzales untuk mengganti kewarganegaraanya tertuang dalam Undang-Undang Hak Asasi Manusia yakni pada pasal...', NULL, '26 Ayat 1', NULL, '27 Ayat 1', NULL, '28 Ayat 2', NULL, '29 Ayat 3', NULL, '30 Ayat 4', NULL, 'A', 'Pasal 26 Ayat 1 dan 2 UUD 1945 menyatakan: (1) Yang menjadi warga negara ialah orang-orang bangsa Indonesia asli dan orang-orang bangsa lain yang disahkan dengan undang-undang sebagai warga negara.', NULL, 'Hafalkan Pasal 26 UUD 1945 tentang kewarganegaraan.', '2026-05-09 19:01:39', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 1);
