INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (1315, 1, NULL, 26, NULL, NULL, NULL, 'Sila keempat Pancasila dilambangkan dengan kepala banteng yang mencerminkan kebiasaan bermusyawarah. Implementasi nilai dari sila tersebut adalah...', NULL, 'Tidak memaksakan suatu agama kepada orang lain', NULL, 'Bergaul dengan siapa saja', NULL, 'Menjunjung tinggi toleransi dalam beragama', NULL, 'Memiliki rasa empati dan peduli terhadap sesama', NULL, 'Tidak memaksakan kehendak kepada orang lain', NULL, 'E', 'Sila keempat Pancasila menekankan nilai musyawarah dan kebijaksanaan dalam pengambilan keputusan. Sikap yang mencerminkan nilai tersebut adalah tidak memaksakan kehendak kepada orang lain.', NULL, 'Pilih jawaban yang menunjukkan nilai musyawarah dan tidak memaksakan kehendak.', '2026-05-09 19:01:39', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 4);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (1316, 1, NULL, 1, NULL, NULL, NULL, 'UUD 1945 telah mengalami beberapa kali amandemen. Tujuan utama dilakukannya amandemen UUD 1945 adalah...', NULL, 'Untuk menyesuaikan konstitusi dengan perkembangan zaman dan tuntutan masyarakat', NULL, 'Memberikan hak yang lebih luas kepada partai politik', NULL, 'Membentuk lembaga pemerintahan baru untuk pelayanan publik', NULL, 'Membatasi kekuasaan MPR dan DPR', NULL, 'Memisahkan kekuasaan eksekutif dan yudikatif', NULL, 'A', 'Amandemen UUD 1945 dilakukan untuk menyesuaikan konstitusi dengan perkembangan zaman serta tuntutan masyarakat, termasuk memperkuat sistem demokrasi dan perlindungan hak asasi manusia.', NULL, 'Pilih jawaban yang menekankan penyesuaian dengan perkembangan zaman.', '2026-05-09 19:01:39', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 30);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (1317, 1, NULL, 7, NULL, NULL, NULL, 'Indonesia telah mengalami beberapa kali perubahan konstitusi sejak kemerdekaan. Urutan perubahan konstitusi yang benar adalah...', NULL, 'UUD 1945, UUDS, Konstitusi RIS, UUD 1945 amandemen', NULL, 'UUD 1945, Konstitusi RIS, UUDS, UUD 1945 amandemen', NULL, 'Konstitusi RIS, UUDS, UUD 1945 amandemen, UUD 1945', NULL, 'Konstitusi RIS, UUD 1945, UUDS, UUD 1945 amandemen', NULL, 'UUDS, UUD 1945, Konstitusi RIS, UUD 1945 amandemen', NULL, 'B', 'Urutan perubahan konstitusi di Indonesia dimulai dari UUD 1945 (1945–1949), kemudian Konstitusi RIS (1949–1950), dilanjutkan UUDS 1950 (1950–1959), dan kembali ke UUD 1945 yang kemudian mengalami amandemen pada periode 1999–2002.', NULL, 'Hafalkan urutan perubahan konstitusi Indonesia: UUD 1945 → Konstitusi RIS → UUDS → UUD 1945 amandemen.', '2026-05-09 19:01:39', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 1);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (1318, 1, NULL, 52, NULL, NULL, NULL, 'Bhinneka Tunggal Ika merupakan semboyan bangsa Indonesia yang mencerminkan persatuan dalam keberagaman. Sikap yang tidak sesuai dengan nilai tersebut adalah...', NULL, 'Adanya kasus tindak pidana korupsi oleh pejabat', NULL, 'Mengabaikan tetangga yang membutuhkan bantuan', NULL, 'Perilaku perundungan terhadap sesama', NULL, 'Kasus pembunuhan berencana', NULL, 'Kasus pelecehan seksual terhadap anak', NULL, 'C', 'Bhinneka Tunggal Ika mencerminkan persatuan dalam keberagaman. Perundungan tidak sesuai karena merusak persatuan dan tidak menghargai perbedaan.', NULL, 'Pilih jawaban yang bertentangan dengan nilai persatuan dalam keberagaman.', '2026-05-09 19:01:39', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 7);
