INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (1574, 3, NULL, 49, NULL, NULL, NULL, 'Anda bekerja dalam sebuah tim proyek yang memiliki deadline ketat. Salah satu anggota tim mengalami kesulitan menyelesaikan tugasnya. Sikap Anda adalah...', NULL, 'Membiarkannya karena itu tanggung jawabnya', NULL, 'Menyalahkannya karena tidak mampu bekerja', NULL, 'Membantu sesuai kemampuan agar pekerjaan tim tetap selesai tepat waktu', NULL, 'Melaporkan ke atasan agar diganti', NULL, 'Mengambil alih seluruh pekerjaannya', NULL, 'C', 'Sikap kerja sama tim dan saling membantu sesuai kemampuan penting untuk memastikan tujuan bersama tercapai.', NULL, 'Pilih jawaban yang menunjukkan kerja sama tim dan saling membantu.', '2026-05-09 19:03:26', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 111);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (1575, 3, NULL, 49, NULL, NULL, NULL, 'Anda bekerja pada perusahaan penerbangan yang cukup besar. Perusahaan Anda berencana untuk membentuk anak perusahaan sehingga melakukan rekrutmen calon pegawai yang akan mengurus anak perusahaan tersebut. Kebetulan hari ini adalah proses penentuan calon karyawan yang akan diterima, namun dewan pimpinan berhalangan hadir sehingga beliau mengamanahkan Anda menjadi salah satu dewan yang menentukan siapa saja karyawan yang akan diterima. Hal apa yang akan Anda lakukan?', NULL, 'Saya akan meminta rekan yang menurut saya dia memiliki kompetensi dalam menyeleksi karyawan yang sesuai dengan kriteria perusahaan', NULL, 'Saya akan menambahkan ujian tulis dan wawancara secara singkat sehingga saya dapat lebih mengetahui kemampuan mereka', NULL, 'Saya akan menggunakan cara seleksi sebelumnya agar tidak terjadi kesalahan prosedur', NULL, 'Saya akan memberikan ujian tulis dan wawancara secara mendalam agar mengetahui calon pelamar yang sesuai dengan klasifikasi yang dibutuhkan perusahaan', NULL, 'Saya akan mengadakan seleksi tertulis dan wawancara dan hasil dari tes tulis dan wawancara akan saya sampaikan ke pimpinan agar mereka dapat memutuskan sesuai dengan laporan yang saya kirim', NULL, 'D', 'Jawaban D memiliki skor tertinggi (5) yang menunjukkan kemampuan bekerja secara mandiri dan tuntas dengan indikator tanggung jawab dan inisiatif.', NULL, 'Pilih jawaban dengan skor tertinggi yang menunjukkan tanggung jawab dan inisiatif.', '2026-05-09 19:03:26', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 111);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (1576, 3, NULL, 49, NULL, NULL, NULL, 'Anda mendapatkan informasi penting yang dapat meningkatkan efisiensi kerja di instansi tempat Anda bekerja. Tetapi informasi tersebut diberikan secara rahasia oleh rekan kerja Anda. Bagaimana sikap Anda dalam situasi tersebut?', NULL, 'Saya akan memanfaatkan informasi tersebut untuk keuntungan pribadi tanpa memberitahu siapapun', NULL, 'Saya akan menyimpan informasi tersebut untuk diri sendiri tanpa menggunakannya', NULL, 'Saya akan membagikan informasi tersebut kepada atasan saya tanpa menyebutkan nama rekan kerja saya', NULL, 'Saya akan memberitahu rekan kerja saya untuk memberitahu atasan langsung tanpa melibatkan diri saya', NULL, 'Saya akan langsung memberitahu atasan saya dengan menyebutkan nama rekan kerja saya sebagai sumber informasi', NULL, 'C', 'Jawaban C memiliki skor tertinggi (5) yang menunjukkan kepatuhan pada prinsip kerahasiaan, kejujuran dan kepentingan organisasi di atas kepentingan pribadi.', NULL, 'Pilih jawaban dengan skor tertinggi yang menunjukkan kejujuran dan kepentingan organisasi.', '2026-05-09 19:03:26', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 104);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (1577, 3, NULL, 49, NULL, NULL, NULL, 'Anda mendapatkan tugas untuk mengelola anggaran di departemen tempat Anda bekerja. Saat melakukan pengeluaran, Anda menemukan bahwa ada kesalahan dalam pembukuan dan terdapat dana yang tidak sesuai dengan rencana anggaran. Bagaimana sikap Anda dalam situasi tersebut?', NULL, 'Saya akan memanfaatkan dana tersebut untuk keperluan pribadi', NULL, 'Saya akan melaporkan kesalahan tersebut kepada atasan saya dan meminta petunjuk', NULL, 'Saya akan mencoba menutupi kesalahan tersebut dan tidak melaporkannya', NULL, 'Saya akan membiarkan dana tersebut tersimpan di akun pribadi dan tidak melaporkannya', NULL, 'Saya akan segera melaporkan kesalahan tersebut kepada atasan saya dan mengusulkan solusi yang tepat', NULL, 'E', 'Jawaban E memiliki skor tertinggi (5) yang menunjukkan integritas, kejujuran dan keinginan untuk memperbaiki kesalahan demi kepentingan organisasi.', NULL, 'Pilih jawaban dengan skor tertinggi yang menunjukkan integritas dan kejujuran.', '2026-05-09 19:03:26', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 114);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (1578, 3, NULL, 49, NULL, NULL, NULL, 'Anda bekerja di instansi pelayanan publik dan seringkali dihadapkan pada situasi di mana Anda harus menangani keluhan atau kekecewaan dari masyarakat. Bagaimana sikap Anda dalam menghadapi situasi tersebut?', NULL, 'Saya akan mengabaikan keluhan masyarakat dan tidak menggubrisnya', NULL, 'Saya akan merasa tersinggung dan menanggapi dengan nada yang kasar', NULL, 'Saya akan mendengarkan dengan empati dan berusaha mencari solusi yang memuaskan masyarakat', NULL, 'Saya akan mengalihkan perhatian dan menghindari tanggung jawab tersebut', NULL, 'Saya akan menyalahkan masyarakat atas masalah yang mereka hadapi', NULL, 'C', 'Jawaban C memiliki skor tertinggi (5) yang menunjukkan kemampuan dalam mengelola konflik, kepedulian terhadap kebutuhan masyarakat, dan komunikasi yang baik.', NULL, 'Pilih jawaban dengan skor tertinggi yang menunjukkan kemampuan mengelola konflik dan kepedulian.', '2026-05-09 19:03:26', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 111);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (1579, 2, NULL, 25, NULL, NULL, NULL, 'FLUKTUASI = ....', NULL, 'Bangkrut', NULL, 'Gejolak', NULL, 'Skeptis', NULL, 'Mayor', NULL, 'Pilih-pilih', NULL, 'B', 'Fluktuasi = Gejolak. Bangkrut = Pailit. Skeptis = Ragu-ragu. Mayor = Besar. Pilih-pilih = Elektif.', NULL, 'Untuk soal sinonim, hafalkan kata-kata yang sering muncul dalam tes CPNS.', '2026-05-09 19:03:26', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 4);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (1580, 2, NULL, 25, NULL, NULL, NULL, 'PULPEN : MENULIS = PISAU : ....', NULL, 'Mengiris', NULL, 'Tajam', NULL, 'Alat masak', NULL, 'Mengasah', NULL, 'Dapur', NULL, 'A', 'Pulpen digunakan untuk menulis. Sama halnya dengan pisau yang digunakan untuk mengiris.', NULL, 'Untuk soal analogi fungsi, cari hubungan penggunaan antara dua hal yang diberikan.', '2026-05-09 19:03:26', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 4);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (1581, 2, NULL, 25, NULL, NULL, NULL, 'Rudi dan Ahmad menjadi peserta asuransi kesehatan dengan besaran premi yang sama. Rudi menerima gaji sebesar Rp 3.000.000 per bulan dan gaji tersebut dipotong 5% untuk premi asuransi. Berapa besar gaji Ahmad per bulan jika gajinya harus dipotong 3% untuk membayar premi?', NULL, 'Rp 4.000.000', NULL, 'Rp 5.000.000', NULL, 'Rp 6.000.000', NULL, 'Rp 7.000.000', NULL, 'Rp 8.000.000', NULL, 'B', 'Gaji Rudi = y, Gaji Ahmad = z. Besarnya premi asuransi = 5% x y = 5% x 3.000.000 = 150.000. Besarnya premi asuransi = 3% x z. 150.000 = 3% x z. 150.000 / 3% = z. 150.000 / (3/100) = z. 150.000 x 100 / 3 = z. 5.000.000 = z.', NULL, 'Untuk soal cerita persentase, buat persamaan dan selesaikan dengan teliti.', '2026-05-09 19:03:26', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 85);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (1582, 2, NULL, 25, NULL, NULL, NULL, 'Semua karyawan di perusahaan A mendapat Tunjangan Hari Raya. Sebagian karyawan mendapat bingkisan hari raya. Maka, ....', NULL, 'semua karyawan Perusahaan A mendapat Tunjangan Hari Raya dan bingkisan Hari Raya', NULL, 'karyawan Perusahaan A yang mendapat Tunjangan Hari Raya selalu mendapat bingkisan Hari Raya', NULL, 'sebagian karyawan Perusahaan A mendapat Tunjangan Hari Raya dan bingkisan Hari Raya', NULL, 'karyawan Perusahaan A yang mendapat gaji, tidak mendapat bingkisan Hari Raya', NULL, 'karyawan Perusahaan A tidak mendapat Tunjangan Hari Raya dan bingkisan Hari Raya', NULL, 'C', 'Semua karyawan → Tunjangan Hari Raya. Sebagian karyawan → bingkisan Hari Raya. Jadi, sebagian karyawan mendapat Tunjungan Hari Raya dan bingkisan Hari Raya.', NULL, 'Untuk soal logika, perhatikan hubungan \"semua\" dan \"sebagian\" antar himpunan.', '2026-05-09 19:03:26', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 94);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (1583, 2, NULL, 25, NULL, NULL, NULL, '2 2 5 6 8 18 .... ....', NULL, '8 dan 18', NULL, '9 dan 10', NULL, '36 dan 72', NULL, '11 dan 54', NULL, '18 dan 36', NULL, 'D', 'Bilangan pertama berpola ditambah tiga (+3) dengan bilangan ke tiga, lima, tujuh, dst. Bilangan kedua berpola dikalikan tiga (x3) dengan bilangan ke empat, enam, delapan, dst. 8 + 3 = 11, 18 x 3 = 54.', NULL, 'Untuk soal deret berselang-seling, pisahkan deret ganjil dan genap untuk mencari pola masing-masing.', '2026-05-09 19:03:26', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 4);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (1584, 1, NULL, 25, NULL, NULL, NULL, 'Pancasila adalah dasar falsafah negara Indonesia, sehingga dapat diambil kesimpulan bahwa Pancasila merupakan dasar falsafah dan ideologi negara yang diharapkan menjadi pandangan hidup bangsa Indonesia sebagai dasar pemersatu, lambang persatuan dan kesatuan serta sebagai pertahanan bangsa dan negara Indonesia. Definisi tersebut adalah pengertian Pancasila yang dikemukakan oleh ....', NULL, 'Ir. Soekarno', NULL, 'Drs. Moh. Hatta', NULL, 'Muhammad Yamin', NULL, 'Notonegoro', NULL, 'Ahmad Subarjo', NULL, 'D', 'Notonegoro mendefinisikan Pancasila sebagai dasar falsafah negara Indonesia, sehingga dapat diambil kesimpulan bahwa Pancasila merupakan dasar falsafah dan ideologi negara yang diharapkan menjadi pandangan hidup bangsa Indonesia.', NULL, 'Hafalkan definisi Pancasila menurut para ahli, terutama Notonegoro.', '2026-05-09 19:03:26', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 4);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (1585, 1, NULL, 13, NULL, NULL, NULL, 'Suatu Negara memerlukan pedoman dalam menjalankan roda pemerintahan dan juga dalam menjalankan kehidupan sehari-hari. Jika pedoman ini tidak ada maka suatu Negara akan kesulitan dalam melangsungkan kehidupan bernegara. Fungsi tersebut merupakan definisi dari?', NULL, 'UUD', NULL, 'Konstitusi Negara', NULL, 'Presiden dan Wakil Presiden', NULL, 'Falsafah Negara', NULL, 'Dasar Negara', NULL, 'A', 'UUD merupakan suatu perangkat peraturan yang menentukan kekuasaan dan tanggung jawab dari alat Negara.', NULL, 'Hafalkan definisi UUD sebagai pedoman dalam menjalankan roda pemerintahan.', '2026-05-09 19:03:26', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 2);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (1586, 1, NULL, 1, NULL, NULL, NULL, 'Penunjukan Nadiem Makarim sebagai Mendikbud RI dalam Kabinet Indonesia Maju mengejutkan banyak pihak. Betapa tidak, pengusaha sukses ini belum pernah mengelola pendidikan, baik di tingkat dasar, menengah, maupun pendidikan tinggi, dan kini harus menahkodai sebuah kementerian yang sangat strategis dan sarat beban persoalan. Dalam sebuah kesempatan, videonya kemudian viral, Nadiem memberikan paparan sangat menarik mengenai pengembangan SDM RI menuju ekonomi digital. Di mata beliau, setidaknya terdapat empat hal penting yang wajib masuk kurikulum pendidikan. Pertama, bahasa Inggris dan ini wajib sejak SD agar anak memiliki kemampuan berkomunikasi secara internasional. Ke depan, kecenderungan belajar mandiri dari sumber-sumber belajar di luar sekolah dan PT semakin menguat. Kedua, pemrograman dan koding komputer, untuk mengenalkan secara lebih dini bahasa pemrograman dan penalaran, serta mengembangkan spesialisasi dan keterampilan yang dapat diterapkan secara langsung. Ketiga, mentorship dan coaching, universitas kelas dunia membutuhkan staf pengajar kelas dunia. Keempat, statistik dan psikologi, agar gaya berpikir yang timbul berdasarkan data. Kepemimpinan karena kepiawaian pengelolaan SDM. Skala dan informasi sebagai landasan kebijakan. Penulis sependapat sepenuhnya, tapi di mana pendidikan karakter? Manakah pernyataan di bawah ini yang sesuai untuk melanjutkan teks artikel di atas?', NULL, 'Pentingnya pendidikan karakter di era global saat ini', NULL, 'Perlunya pendidikan yang disesuaikan dengan kebutuhan industri saat ini', NULL, 'Pendidikan yang baik harus selalu dikaitkan dengan norma sopan santun di masyarakat', NULL, 'Pendidikan yang berbasis teknologi harus digunakan secara bertahap', NULL, 'Perlunya dunia pendidikan menerapkan nilai karakter pancasila', NULL, 'A', 'Sebab di akhir paragraf penulis memberikan pertanyaan mengenai pendidikan karakter tentunya penulis ingin mengulas mengenai pentingnya pendidikan karakter.', NULL, 'Untuk soal pemahaman wacana, perhatikan konteks dan pertanyaan di akhir paragraf.', '2026-05-09 19:03:26', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 1);
