INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (1847, 2, NULL, 25, NULL, NULL, NULL, 'Berapa tiga suku pertama suatu barisan yang rumus suku ke-n nya Un = 3n² - 2?', NULL, '1,5,10', NULL, '1,10,25', NULL, '1,15,20', NULL, '1,20,25', NULL, '1, 15, 25', NULL, 'B', 'U1 = 3(1)² - 2 = 1, U2 = 3(2)² - 2 = 10, U3 = 3(3)² - 2 = 25.', NULL, 'Untuk soal rumus barisan, substitusi n = 1, 2, 3 untuk mencari suku pertama.', '2026-05-09 19:08:08', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 88);
