INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (2152, 1, NULL, 1, NULL, NULL, NULL, 'Tindakan bullying saat ini menjadi momok yang menakutkan bagi generasi muda. Bahkan bullying bisa dilakukan dimana saja karena arus perkembangan teknologi informasi dan komunikasi yang begitu cepat. Penyebab utama kasus cyber bullying pada era milennial saat ini ditinjau dari pendekatan pilar kebangsaan disebabkan oleh...', NULL, 'Kurangnya kesadaran terhadap hukum', NULL, 'Lemahnya pendidikan dasar', NULL, 'Minimnya pengawasan yang dilakukan oleh sekolah', NULL, 'Kurangnya bimbingan konseling pada peserta didik', NULL, 'Lunturnya pemahaman terhadap nilai-nilai Pancasila', NULL, 'E', 'Lunturnya pemahaman terhadap nilai-nilai Pancasila menjadi penyebab utama cyber bullying karena Pancasila sebagai dasar moral bangsa.', NULL, 'Pilih jawaban yang berkaitan dengan nilai-nilai Pancasila sebagai pilar kebangsaan.', '2026-05-09 19:10:39', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 47);
