INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (2159, 2, NULL, 25, NULL, NULL, NULL, 'Kucing-kucing itu bertengger di atas dahan-dahan pohon. Kalimat yang menyerupai kalimat tersebut adalah...', NULL, 'Mereka berdua saling berpegangan tangan', NULL, 'Karya seni itu bertemakan nasionalisme', NULL, 'Anak-anak sedang bermain di lapangan', NULL, 'Ibu membeli sayur di pasar', NULL, 'Adik membelikan kucingnya makanan kucing', NULL, 'C', 'Keduanya memiliki struktur subjek + verba + lokasi.', NULL, 'Untuk soal analogi kalimat, perhatikan struktur kalimat.', '2026-05-09 19:10:39', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 78);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (2160, 2, NULL, 25, NULL, NULL, NULL, 'K, 5, 14, 22, 29, 35, 40, 44, 47, 49, 50. Berapakah nilai K?', NULL, -5, NULL, -3, NULL, 3, NULL, -2, NULL, 1, NULL, 'A', 'Pola: +5, +9, +8, +7, +6, +5, +4, +3, +2, +1. K + 5 = 5, maka K = 0. 0 - 5 = -5.', NULL, 'Untuk soal deret, cari pola penambahan yang menurun.', '2026-05-09 19:10:39', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 54);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (2161, 2, NULL, 25, NULL, NULL, NULL, 'Dalam pembagian tugas kuliah ada lima orang yang berdiskusi dengan memakai kostum yang berbeda-beda. Dodi memakai kemeja, Aldi dan Bintang memakai kaos lengan pendek, sisanya memakai kaos lengan Panjang. Pipit dan Hari memakai sepatu, Aldi memakai sepatu sendal, sisanya memakai sendal. Dodi dan Aldi tidak berkacamata sedangkan yang lain memakai kacamata. Siapakah mahasiswa yang berkacamata, memakai kaos lengan pendek dan bersendal?', NULL, 'Aldi', NULL, 'Bintang', NULL, 'Pipit', NULL, 'Hari', NULL, 'Dodi', NULL, 'B', 'Bintang memakai kaos lengan pendek (bersama Aldi), bersendal (selain Pipit dan Hari), dan berkacamata (selain Dodi dan Aldi).', NULL, 'Untuk soal logika, buat tabel eliminasi untuk memudahkan.', '2026-05-09 19:10:39', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 56);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (2162, 2, NULL, 25, NULL, NULL, NULL, 'Andi membuat sebuah gapura memerlukan waktu 12 hari sedangkan Eko membuat gapura yang sama memerlukan waktu 6 hari. Disamping itu Eca dapat membuat gapura yang sama dalam waktu 4 hari. X: Waktu yang dibutuhkan ketika Andi, Eko dan Eca membuat gapura bersama-sama. Y: Waktu yang dibutuhkan ketika Andi dan Eko membuat gapura bersama-sama dimana Andi meningkatkan kecepatannya sebesar 100 persen.', NULL, 'X = Y', NULL, 'XY = 3Y- 2', NULL, '4Y = 3X', NULL, 'Y = 1,5 X', NULL, 'X2– Y2 = -4', NULL, 'D', 'Kecepatan Andi = 1/12, Eko = 1/6, Eca = 1/4. X = 1/(1/12+1/6+1/4) = 1/2 hari. Andi kecepatan baru = 2/12 = 1/6. Y = 1/(1/6+1/6) = 3 hari. Y = 1.5 X.', NULL, 'Untuk soal kerja bersama, gunakan rumus 1/(1/A + 1/B + 1/C).', '2026-05-09 19:10:39', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 71);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (2163, 3, NULL, 49, NULL, NULL, NULL, 'Anda seorang mahasiswa yang mendapatkan tugas materi dalam kelompok dan dijadwalkan untuk presentasi besok dan anda ditunjuk sebagai ketua kelompok. Dalam kelompok anda terdiri dari 4 (empat) orang termasuk anda. Ketika dalam proses penyusunan materi, anda sudah mengetahui kemampuan akademis rekan-rekan satu tim anda sehingga anda tahu mana orang yang mampu membantu menyusun materi dengan baik dan yang tidak, bahkan anda mengetahui mana yang pasif (hanya mengandalkan rekannya yang lain) dan mana yang tidak. Bagaimana sikap anda?', NULL, 'Membagi tugas penyusunan materi sesuai dengan kemampuan akademis masing-masing anggota', NULL, 'Membagi tugas penyusunan materi sama rata kepada seluruh anggota tanpa memandang kemampuan mereka sama sekali', NULL, 'Membagi tugas penyusunan materi hanya kepada anggota yang pandai saja dan mengabaikan anggota yang lainnya', NULL, 'Membagi tugas penyusunan materi hanya kepada anggota yang pandai saja dan yang tidak pandai diberi tugas yang lain (mencetak materi/print, menjilid makalah)', NULL, 'Membagi tugas penyusunan materi sama rata kepada seluruh anggota tanpa memandang kemampuan mereka sama sekali dan memberikan hukuman kepada anggota yang tidak mau menjalankan pembagian tugas tersebut dengan mengeluarkan dari keanggotaan', NULL, 'A', 'Jawaban A menunjukkan kepemimpinan yang adil dengan membagi tugas sesuai kemampuan.', NULL, 'Pilih jawaban yang menunjukkan kepemimpinan yang adil dan efektif.', '2026-05-09 19:10:39', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 119);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (2165, 3, NULL, 49, NULL, NULL, NULL, 'Pimpinan kantor pusat merancang aplikasi untuk berkoordinasi secara terbatas dengan kepala kantor cabang di seluruh Indonesia untuk membahas masalah penting perusahaan. Pimpinan meminta kepala kantor cabang untuk mempersiapkan aplikasinya. Bagaimana sikap Mila sebagai kepala kantor cabang tentang hal tersebut?', NULL, 'Menyiapkan aplikasinya dan memberikan kata sandi kepada staf agar bisa mengikuti pertemuan saat Mila berhalangan hadir', NULL, 'Menghentikan penggunaan aplikasi jika identitas pribadi disalahgunakan untuk menurunkan citra kantor cabang', NULL, 'Mendorong pimpinan membuat POS tentang bagaimana penggunaan aplikasi yang aman, baik bagi pribadi maupun organisasi', NULL, 'Menghentikan pemanfaatan aplikasi ketika pertemuan daring nanti disusupi oleh orang lain yang tidak berkepentingan', NULL, 'Mengingatkan kepala kantor cabang lain untuk berhati-hati mengakses aplikasi yang memuat data pribadi', NULL, 'C', 'Jawaban C menunjukkan sikap proaktif dalam memastikan keamanan aplikasi.', NULL, 'Pilih jawaban yang menunjukkan sikap proaktif dan bertanggung jawab.', '2026-05-09 19:10:39', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 105);
