INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (2167, 3, NULL, 49, NULL, NULL, NULL, 'Suatu hari Anda ditugasi oleh pimpinan untuk menjadi ketua dalam sebuah acara yang melibatkan semua peserta dari berbagai usia. Tindakan yang tepat dilakukan agar acara berjalan dengan lancar adalah...', NULL, 'Mengajak semua rekan kerja Anda untuk berdiskusi tentang acara apa yang akan dilakukan pada hari H agar berjalan dengan lancar', NULL, 'Memberikan ide Anda sendiri mengenai acara milenial yang kekinian dan semua peserta harus ikut serta', NULL, 'Menanyakan satu per satu ide kepada seluruh pegawai acara apa yang cocok untuk semua generasi', NULL, 'Menanyakan kepada atasan langsung tentang ide acara yang cocok untuk berbagai usia', NULL, 'Menggunakan ide Anda sendiri mengenai konsep acara yang dapat merangkul semua peserta dari berbagai usia', NULL, 'A', 'Jawaban A menunjukkan sikap demokratis dan kolaboratif dalam perencanaan.', NULL, 'Pilih jawaban yang menunjukkan sikap demokratis dan kolaboratif.', '2026-05-09 19:10:39', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 129);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (2168, 3, NULL, 49, NULL, NULL, NULL, 'Anda sedang mengerjakan tugas mata kuliah di perpustakaan dan meminjam komputer di sana. Saat sedang mengetik, tiba-tiba komputer tersebut mati. Yang akan anda lakukan adalah...', NULL, 'Browsing di internet tentang cara memperbaiki komputer yang tiba-tiba mati lalu mencobanya', NULL, 'Segera melapor kepada petugas perpustakaan tentang kerusakan dan meminta bantuan untuk mendapatkan kembali tugas yang sedang diketik', NULL, 'Menelpon teman anak IT dan meminta bantuannya untuk memperbaiki komputer perpustakaan', NULL, 'Segera pindah ke komputer sebelah yang kosong lalu mengetik semua tugas dari awal', NULL, 'Mengecek apakah ada kabel yang tercabut lalu mencoba me-restart komputer untuk menyelamatkan tugas', NULL, 'E', 'Jawaban E menunjukkan sikap tenang dan mencoba solusi praktis terlebih dahulu.', NULL, 'Pilih jawaban yang menunjukkan sikap tenang dan praktis.', '2026-05-09 19:10:39', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 110);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (2169, 3, NULL, 49, NULL, NULL, NULL, 'Saya merupakan salah satu junior di sebuah perusahaan terkemuka. Pada era sekarang ini, perusahaan mengharuskan merubah sistem kerja menggunakan IT mulai dari pengiriman surat, komunikasi dengan pihak lain untuk bekerjasama dan aktivitas lainnya yang dapat dijalankan dengan IT. Saya mendapati bahwa senior di tempat saya masih tetap menggunakan non IT, padahal perusahaan telah memberikan instruksi untuk penggunaan IT dalam aktivitas perusahaan, Apa yang akan anda lakukan...', NULL, 'Memberikan penjelasan kepada senior tersebut bahwa perusahaan mengharuskan penggunaan IT dalam aktivitas perusahaan', NULL, 'Memberikan penjelasan kepada senior tersebut dan mengajarkannya tentang IT', NULL, 'Membantu senior dalam bekerja yang mengharuskan penggunaan IT jika tidak sibuk', NULL, 'Biarkan saja sampai senior tersebut merasa bahwa IT diperlukan', NULL, 'Karena IT diperlukan, seharusnya senior mawas diri', NULL, 'C', 'Jawaban C menunjukkan sikap membantu dan adaptif terhadap perubahan teknologi.', NULL, 'Pilih jawaban yang menunjukkan sikap membantu dan adaptif.', '2026-05-09 19:10:39', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 101);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (2170, 3, NULL, 49, NULL, NULL, NULL, 'Anda menemukan data evaluasi pelanggan yang menyarankan agar kantor Anda memiliki akun media sosial sehingga mudah berkomunikasi dengan pelanggan. Pada sisi lain, beberapa staf menolak saran tersebut karena akan menambah pekerjaan mereka. Bagaimana tindakan Anda?', NULL, 'Saya merasa tidak semua saran pelanggan perlu diwujudkan; apabila kantor akan membuat akun media sosial, pengelolanya dapat diserahkan kepada staf yang ahli', NULL, 'Saya menilai penting untuk mempelajari pembuatan dan pengelolaan akun media sosial sehingga dapat mengoptimalkan pekerjaan tim marketing dan layanan pelanggan', NULL, 'Saya merasa sistem layanan pelanggan sebelumnya sudah cukup memfasilitasi kebutuhan pelanggan; pengelolaan media sosial dapat membebani pekerjaan yang sudah ada', NULL, 'Saya memandang bahwa evaluasi efektivitas sistem layanan pelanggan itu penting agar dapat memberikan solusi terbaik dalam melayani pelanggan', NULL, 'Saya merasa terdorong untuk mempelajari cara pembuatan dan pengelolaan akun media sosial sehingga dapat memberikan hasil optimal dalam melayani pelanggan', NULL, 'E', 'Jawaban E menunjukkan sikap inovatif dan berorientasi pada pelayanan pelanggan.', NULL, 'Pilih jawaban yang menunjukkan sikap inovatif dan berorientasi pelayanan.', '2026-05-09 19:10:39', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 105);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (2171, 3, NULL, 49, NULL, NULL, NULL, 'Deni adalah kepala unit termuda di tempat kerjanya. Sejumlah karyawan di unit kerja Deni berusia jauh lebih tua darinya dengan pengalaman kerja puluhan tahun. Namun, cara kerja mereka cenderung tradisional dan kurang inovatif. Apa tindakan Deni?', NULL, 'Menggunakan cara komunikasi yang sesuai dengan karyawan', NULL, 'Melanjutkan pola kerja yang sudah biasa dilakukan di unit kerja yang ia pimpin', NULL, 'Menunjukkan ketidaksetujuan pada cara kerja tradisional yang kurang efektif', NULL, 'Menghargai kemampuan dan pengalaman setiap karyawan di unit kerjanya', NULL, 'Mendorong keterlibatan dan kerja sama semua karyawan untuk mencapai target', NULL, 'E', 'Jawaban E menunjukkan kepemimpinan yang inklusif dan berorientasi hasil.', NULL, 'Pilih jawaban yang menunjukkan kepemimpinan yang inklusif dan berorientasi hasil.', '2026-05-09 19:10:39', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 132);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (2172, 3, NULL, 49, NULL, NULL, NULL, 'Karena kekurangan sumber daya manusia di sebuah kantor cabang perusahaan tempat anda bekerja, Atasan anda memutuskan hendak memindahkan anda ke cabang yang sama sekali tidak pernah anda kunjungi di sebuah pulau terpencil, padahal anda adalah karyawan yang sudah lama mengabdi dan berprestasi dan anda cukup dekat dengan atasan, sikap anda adalah....', NULL, 'Menolak dengan halus dan mengusulkan yang lain saja, Karena anda merupakan karyawan lama yang seharusnya tetap bekerja di kantor pusat', NULL, 'Berdiskusi dengan atasan anda terkait proses pemindahan anda ke kantor cabang yang baru tersebut', NULL, 'Bersedia dipindah tanpa membantah sedikit pun perintah dari atasan dan kebijakan perusahaan', NULL, 'Menerima tapi berusaha mengusulkan karyawan yang lain saja karena anda merasa senior dan disegani di kantor', NULL, 'Berangkat mengikuti keputusan perusahaan tentang pemindahan anda ke kantor cabang baru tersebut', NULL, 'B', 'Jawaban B menunjukkan sikap komunikatif dan profesional dalam menghadapi keputusan perusahaan.', NULL, 'Pilih jawaban yang menunjukkan sikap komunikatif dan profesional.', '2026-05-09 19:10:39', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 105);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (2175, 1, NULL, 1, NULL, NULL, NULL, 'Konflik antara Indonesia dengan Tiongkok kembali terjadi di Perairan Natuna yang berbatasan dengan Laut Cina Selatan. Sejumlah kapal penangkap ikan asal Tiongkok didampingi kapan Coast Guard negaranya, berkegiatan di perairan yang masih masuk dalam teritori ZonaEkonomi Eksklusif (ZEE) milik Indonesia. Hal tersebut juga merupakan sebuah ancaman bagi Indonesia. Ancaman terhadap satu pulau atau daerah pada hakikatnya ancaman seluruh bangsa dan negara. Hal ini ditegaskan dalam wawasan Nusantara dalam bidang...', NULL, 'Ideologi', NULL, 'Politik', NULL, 'Ekonomi', NULL, 'Sosial budaya', NULL, 'Hankam', NULL, 'E', 'Wawasan Nusantara dalam bidang Hankam menyatakan bahwa ancaman terhadap satu pulau atau daerah adalah ancaman terhadap seluruh bangsa dan negara.', NULL, 'Pahami konsep Wawasan Nusantara dan aspek-aspeknya (politik, ekonomi, sosial budaya, hankam).', '2026-05-09 19:15:35', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 39);
