INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (2837, 2, NULL, 25, NULL, NULL, NULL, 'Irfan, Zidny, Hery, Rama, dan Kemal bersahabat sejak kecil meskipun mereka berbeda usia. Rama lebih muda dari Hery dan Irfan, sementara Zidny lebih tua dari Kemal. Irfan lebih muda 1 tahun dari Hery dan lebih tua 2 tahun dari Kemal. Bila Rama paling muda di antara teman-temannya sementara usia Kemal 13 tahun, maka berapakah kemungkinan umur Zidny?', NULL, 10, NULL, 11, NULL, 12, NULL, 13, NULL, 14, NULL, 'E', 'Kemal 13 tahun. Irfan lebih tua 2 tahun dari Kemal = 15 tahun. Irfan lebih muda 1 tahun dari Hery = Hery 16 tahun. Zidny lebih tua dari Kemal, jadi Zidny > 13. Rama paling muda. Kemungkinan Zidny 14 tahun.', NULL, 'Untuk soal logika usia, buat tabel hubungan usia.', '2026-05-09 19:20:24', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 51);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (2838, 2, NULL, 25, NULL, NULL, NULL, 'Jelajahi Mars dengan Simulator Baru Keluaran NASA. Meskipun masih diperlukan bertahun-tahun lamanya hingga manusia dapat menginjakkan kaki di planet Mars, bukan berarti tidak mungkin bagi manusia sekarang ini untuk menjalankan tur keliling Mars. NASA telah mengeluarkan simulator 3D baru yang dapat memungkinkan para penggunanya menjelajahi Mars. Simulator ini memberikan pengalaman tur virtual bagi orang-orang yang berkeinginan untuk melakukan perjalanan mengelilingi Mars. Dikutip dari situs Quartz, fitur terbaru ciptaan NASA ini mengizinkan para penggunanya untuk mengatur gerak navigasi kendaraan Mars Curiosity yang dimiliki agen luar angkasa Amerika Serikat ini ke seluruh penjuru Mars. Dengan mengatur gerak Mars Curiosity, para pengguna fitur terbaru NASA dapat mengeksplorasi planet merah sesuai yang mereka inginkan melalui komputer pribadi mereka. Kata \"fitur\" pada bacaan di atas adalah....', NULL, 'Kemampuan/ciri khusus pada suatu gawai', NULL, 'alat yang memiliki berbagai fungsi', NULL, 'Sistem', NULL, 'Perangkat alat', NULL, 'Perangkat sistem', NULL, 'A', 'Fitur berarti kemampuan atau ciri khusus pada suatu gawai atau aplikasi.', NULL, 'Untuk soal menentukan makna kata, perhatikan konteks kalimat.', '2026-05-09 19:20:24', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 82);
