INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (2840, 2, NULL, 25, NULL, NULL, NULL, 'TIMUR : SELATAN : TENGGARA : ...', NULL, 'barat : utara : barat daya', NULL, 'selatan : barat : barat daya', NULL, 'pasti : tidak mungkin : mungkin', NULL, 'jelas : pasti : tidak mungkin', NULL, 'timur : barat : utara', NULL, 'A', 'Timur, Selatan, Tenggara adalah arah mata angin berurutan searah jarum jam. Berikutnya adalah Barat, Utara, Barat Daya.', NULL, 'Untuk soal deret arah, perhatikan pola arah mata angin.', '2026-05-09 19:20:24', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 4);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (2841, 2, NULL, 25, NULL, NULL, NULL, 'Jumlah 5 suku pertama suatu deret aritmatika adalah 20. Jika masing-masing suku dikurangi dengan suku ke-3 maka hasil kali U1, U2, U4 dan U5 adalah 324. Jumlah 8 suku pertama deret tersebut adalah ...', NULL, '-64 atau 88', NULL, '-56 atau 138', NULL, '-52 atau 116', NULL, '-44 atau 124', NULL, '-4 atau 68', NULL, 'C', 'Misal suku ke-3 = a, maka U1 = a-2d, U2 = a-d, U4 = a+d, U5 = a+2d. (a-2d)(a-d)(a+d)(a+2d) = (a²-4d²)(a²-d²) = 324. Jumlah 5 suku = 5a = 20, maka a = 4. Substitusi a = 4: (16-4d²)(16-d²) = 324. Solusi d = ±3 atau d = ±√7. Jumlah 8 suku = 8a + 28d = 32 + 28d. Untuk d = 3: 32 + 84 = 116. Untuk d = -3: 32 - 84 = -52.', NULL, 'Untuk soal deret aritmatika, gunakan rumus suku ke-n dan jumlah suku.', '2026-05-09 19:20:24', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 63);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (2842, 2, NULL, 34, NULL, NULL, NULL, 'PRIBADI : KELOMPOK : MASYARAKAT :...', NULL, 'saya : kita : mereka', NULL, 'huruf : kata : roman', NULL, 'jarang : sering : selalu', NULL, 'padi : karung : lumbung', NULL, 'makan : minum : perbuatan', NULL, 'A', 'Pribadi, Kelompok, Masyarakat adalah tingkatan sosial dari individu ke kolektif. Saya, Kita, Mereka adalah tingkatan pronomina dari individu ke kolektif.', NULL, 'Untuk soal analogi, cari hubungan tingkatan.', '2026-05-09 19:20:24', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 5);
