INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (2882, 3, NULL, 49, NULL, NULL, NULL, 'Pimpinan kantor menggelar rapat kerja membahas penyusunan rencana kerja untuk tahun anggaran depan. Setiap pegawai diharapkan mempersiapkan usulan untuk kegiatan tahun depan. Respons saya...', NULL, 'Tidak peduli', NULL, 'Tidak berminat sama sekali untuk mengajukan suatu ide kegiatan', NULL, 'Akan mengajukan suatu ide kegiatan jika diminta oleh pimpinan', NULL, 'Mungkin berminat untuk mengajukan suatu ide kegiatan yang akan dilaksanakan. Namun tergantung situasi dan kondisi', NULL, 'Ragu-ragu untuk mengajukan suatu ide kegiatan karena akan kecewa jika tidak diterima', NULL, 'C', 'Sikap yang baik adalah mengajukan ide jika diminta pimpinan.', NULL, 'Pilih jawaban yang menunjukkan respons positif terhadap permintaan pimpinan.', '2026-05-09 19:20:24', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 105);
