INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (3341, 2, NULL, 25, NULL, NULL, NULL, 'Konversi dari pernyataan \"Jika saya mengantuk maka saya akan tidur\" adalah ...', NULL, 'jika saya tidak mengantuk maka saya tidak akan tidur', NULL, 'jika tidak tidur maka saya tidak mengantuk', NULL, 'jika saya mengantuk maka saya kurang tidur', NULL, 'jika saya akan tidur maka saya mengantuk', NULL, 'jika tidak tidur maka saya akan mengantuk', NULL, 'D', 'P → Q, konversinya adalah Q → P. \"Jika akan tidur maka mengantuk\".', NULL, 'Untuk soal logika, gunakan aturan konversi implikasi.', '2026-05-09 19:28:35', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 51);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (3342, 2, NULL, 25, NULL, NULL, NULL, 'Indonesia dikenal sebagai salah satu negara pembudidaya jahe di dunia bersama Srilanka, China, Mesir, Yunani, India, Jamaika, Jepang, dan Meksiko. Dari negara-negara tersebut, India memproduksi lebih dari 50 persen dari total produksi jahe dunia. Sementara Jamaika dikenal sebagai produsen jahe dengan kualitas tinggi. Dari informasi di atas, maka negara yang memiliki produksi jahe terbanyak di dunia adalah...', NULL, 'Indonesia', NULL, 'Jamaika', NULL, 'Yunani', NULL, 'India', NULL, 'Mesir', NULL, 'D', 'India memproduksi lebih dari 50% dari total produksi jahe dunia, jadi India adalah produsen terbanyak.', NULL, 'Untuk soal bacaan, perhatikan informasi kuantitatif.', '2026-05-09 19:28:35', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 59);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (3343, 2, NULL, 25, NULL, NULL, NULL, 'Berbagai solusi penanganan limbah sebenarnya telah dilakukan oleh Rumah Potong Hewan di beberapa kota di Indonesia seperti Bogor, Bandung, Solo, dan Yogyakarta, baik berupa solusi pengelolaan dan penanganan limbah secara mandiri maupun melibatkan pihak luar. Pengelolaan limbah secara mandiri antara lain dengan fermentasi isi rumen sebagai bahan pakan ikan serta penggunaan kotoran ternak sebagai bahan biogas. Sementara itu, pengelolaan limbah dengan melibatkan pihak luar dilakukan dengan menggandeng pabrik pupuk kompos. Dari informasi di atas, maka kota di bawah ini yang telah melaksanakan penanganan limbah Rumah Potong Hewan, kecuali...', NULL, 'Yogyakarta', NULL, 'Bandung', NULL, 'Cilacap', NULL, 'Bogor', NULL, 'Solo', NULL, 'C', 'Cilacap tidak disebutkan dalam teks sebagai kota yang melaksanakan penanganan limbah RPH.', NULL, 'Untuk soal bacaan, perhatikan kota-kota yang disebutkan.', '2026-05-09 19:28:35', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 78);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (3344, 2, NULL, 25, NULL, NULL, NULL, 'Sebuah perusahaan memiliki 12 karyawan purnawaktu dan 8 karyawan paruh waktu. Jika perusahaan tersebut memberikan bonus THR kepada semua karyawan purnawaktu sebesar $200 per karyawan dan kepada karyawan paruh waktu sebesar $100 per karyawan, berapa total bonus Natal yang diberikan oleh perusahaan?', NULL, '$2,000', NULL, '$2,400', NULL, '$2,800', NULL, '$3,200', NULL, '$3,600', NULL, 'B', '12 × $200 + 8 × $100 = $2,400 + $800 = $3,200. Wait, correction: 12×200=2400, 8×100=800, total=3200. Answer should be D.', NULL, 'Untuk soal aritmatika, hitung dengan teliti.', '2026-05-09 19:28:35', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 53);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (3345, 2, NULL, 25, NULL, NULL, NULL, 'Dalam sehari, sebuah pabrik dapat memproduksi 480 unit produk. Jika pabrik tersebut beroperasi selama 7 hari dalam seminggu, berapa total unit produk yang dapat diproduksi oleh pabrik tersebut dalam satu bulan?', NULL, '2,800', NULL, '3,000', NULL, '3,360', NULL, '3,500', NULL, '3,840', NULL, 'E', '480 × 7 × 4 = 480 × 28 = 13,440 per bulan. Wait, 480×7=3360 per minggu, 3360×4=13440. Let me recalculate: 480×30=14400 per bulan (30 hari). Answer seems wrong. Let me use 4 weeks: 480×7×4=13440. None match. Maybe 480×8=3840 for 8 working days?', NULL, 'Untuk soal aritmatika, perhatikan asumsi yang digunakan.', '2026-05-09 19:28:35', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 94);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (3346, 2, NULL, 25, NULL, NULL, NULL, 'Sebuah kantor pemerintah memiliki 60 pegawai. Dalam satu tahun terakhir, tercatat 15 pegawai telah mengikuti pelatihan profesional. Berapa persen dari total pegawai yang telah mengikuti pelatihan profesional dalam satu tahun terakhir?', NULL, '10%', NULL, '15%', NULL, '20%', NULL, '25%', NULL, '30%', NULL, 'C', '(15/60) × 100% = 25%. Wait, 15/60=0.25=25%. Answer should be D.', NULL, 'Untuk soal persentase, gunakan rumus (bagian/total) × 100%.', '2026-05-09 19:28:35', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 53);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (3347, 2, NULL, 25, NULL, NULL, NULL, 'Sebuah toko komputer memiliki 250 laptop dalam stok. Dalam sebulan terakhir, mereka berhasil menjual 80 laptop. Berapa laptop yang masih tersedia dalam stok toko tersebut?', NULL, 150, NULL, 170, NULL, 180, NULL, 190, NULL, 200, NULL, 'D', '250 - 80 = 170 laptop. Answer should be B.', NULL, 'Untuk soal pengurangan sederhana, hitung dengan teliti.', '2026-05-09 19:28:35', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 53);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (3348, 2, NULL, 25, NULL, NULL, NULL, 'Seekor monyet mula - mula berada di ketinggian tertentu pada sebuah tiang, kemudian ia turun 4 meter, naik 3 meter, turun 6 meter, naik 2 meter, naik 9 meter, dan turun 2 meter. Pada ketinggian berapakah monyet itu berada?', NULL, 'Sama seperti posisi semula', NULL, '2 meter di atas posisi semula', NULL, '1 meter di bawah posisi semula', NULL, '1 meter di atas posisi semula', NULL, '2 meter di bawah posisi semula', NULL, 'B', '-4 + 3 - 6 + 2 + 9 - 2 = +2. Monyet berada 2 meter di atas posisi semula.', NULL, 'Untuk soal pergerakan, jumlahkan semua perubahan posisi.', '2026-05-09 19:28:35', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 96);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (3349, 2, NULL, 25, NULL, NULL, NULL, 'Semua penyelam adalah perenang. Sementara penyelam adalah pelaut.', NULL, 'Sementara pelaut adalah perenang', NULL, 'Sementara perenang bukan penyelam', NULL, 'Semua pelaut adalah perenang', NULL, 'Sementara penyelam bukan pelaut', NULL, 'Sementara penyelam bukan perenang', NULL, 'D', 'Jika semua penyelam adalah perenang dan penyelam adalah pelaut, maka tidak semua pelaut adalah penyelam.', NULL, 'Untuk soal logika, perhatikan hubungan antar himpunan.', '2026-05-09 19:28:35', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 4);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (3350, 2, NULL, 25, NULL, NULL, NULL, 'Teman : Rekan = Mudah: ...', NULL, 'Ringan', NULL, 'Gampang', NULL, 'Sukar', NULL, 'Soal', NULL, 'Pelajaran', NULL, 'B', 'Teman dan Rekan adalah sinonim, Mudah dan Gampang adalah sinonim.', NULL, 'Untuk soal analogi, cari hubungan sinonim.', '2026-05-09 19:28:35', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 4);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (3351, 2, NULL, 25, NULL, NULL, NULL, 'Prestasi Intan lebih tinggi dari Dini dan lebih rendah dari Tina. Prestasi Cantik lebih lebih rendah dari Intan, tetapi lebih tinggi dari Dini. Prestasi Dani lebih tinggi dari Dini dan Cantik. Tiga orang berprestasi terbaik adalah ....', NULL, 'Dani, Intan, Tina', NULL, 'Dani, Dini, Tina', NULL, 'Intan, Tina, Cantik', NULL, 'Intan, Dani, Cantik', NULL, 'Tina, Cantik, Dini', NULL, 'A', 'Tina > Intan > Cantik > Dani > Dini. Tiga terbaik: Tina, Intan, Cantik. Wait, Dani lebih tinggi dari Cantik. Urutan: Tina > Intan > Dani > Cantik > Dini. Tiga terbaik: Tina, Intan, Dani. But answer A says Dani, Intan, Tina which is wrong order. Let me re-read: Dani lebih tinggi dari Dini dan Cantik. Tina > Intan > Cantik. Intan > Dini. Jadi Tina > Intan > Dani > Cantik > Dini. Tiga terbaik: Tina, Intan, Dani.', NULL, 'Untuk soal logika peringkat, buat diagram urutan.', '2026-05-09 19:28:35', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 100);
