INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (3713, 2, NULL, 25, NULL, NULL, NULL, 'Sebuah proyek pembangunan terdiri atas beberapa jenis proyek kecil, yakni proyek P, Q, R, S, T, dan U. Proyek kecil ini berkaitan satu dengan yang lain sehingga tiap-tiap jenis pekerjaan diatur sebagai berikut: Proyek Q tidak boleh dikerjakan bersamaan dengan proyek S. Proyek P boleh dikerjakan bersama dengan proyek T. Proyek Q hanya boleh dikerjakan bersama dengan proyek R. Proyek T dikerjakan jika proyek U dikerjakan. Jika pekerja sudah mengerjakan proyek T, maka ....', NULL, 'Pekerja tidak mengerjakan proyek S', NULL, 'Pekerja tentu akan mengerjakan proyek P', NULL, 'Pekerja hanya akan mengerjakan proyek R', NULL, 'Pekerja juga mengerjakan proyek U', NULL, 'Pekerja tidak mengerjakan proyek R', NULL, 'D', 'Jika T dikerjakan, maka U harus dikerjakan (karena T dikerjakan jika U dikerjakan).', NULL, 'Untuk soal logika, buat tabel hubungan antar proyek.', '2026-05-09 19:31:03', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 69);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (3726, 2, NULL, 25, NULL, NULL, NULL, 'Jika saya pekerja maka saya mendapat gaji. Kalimat berikut yang ekuivalen dengan pernyataan diatas adalah?', NULL, 'Saya bukan pekerja atau saya mendapat gaji', NULL, 'Saya bukan pekerja dan saya mendapat gaji', NULL, 'Saya bukan pekerja atau saya tidak mendapatkan gaji', NULL, 'Saya bukan pekerja dan saya tidak mendapatkan gaji', NULL, 'Saya pekerja dan saya tidak mendapat gaji', NULL, 'A', 'P → Q ekuivalen dengan ¬P ∨ Q. \"Jika saya pekerja maka saya mendapat gaji\" ekuivalen dengan \"Saya bukan pekerja atau saya mendapat gaji\".', NULL, 'Untuk soal logika, gunakan aturan ekuivalensi implikasi.', '2026-05-09 19:31:03', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 51);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (3746, 2, NULL, 25, NULL, NULL, NULL, 'Andi membuat sebuah gapura memerlukan waktu 12 hari sedangkan Eko membuat gapura yang sama memerlukan waktu 6 hari. Disamping itu Eca dapat membuat gapura yang sama dalam waktu 4 hari. X: Waktu yang dibutuhkan ketika Andi, Eko dan Eca membuat gapura bersama-sama. Y: Waktu yang dibutuhkan ketika Andi dan Eko membuat gapura bersama-sama dimana Andi meningkatkan kecepatannya sebesar 100 persen.', NULL, 'X = Y', NULL, 'XY = 3Y- 2', NULL, '4Y = 3X', NULL, 'Y = 1,5 X', NULL, 'X2– Y2 = -4', NULL, 'D', 'Kecepatan Andi = 1/12, Eko = 1/6, Eca = 1/4. X = 1/(1/12+1/6+1/4) = 1/2 hari. Andi kecepatan baru = 2/12 = 1/6. Y = 1/(1/6+1/6) = 3 hari. Y = 1.5 X.', NULL, 'Untuk soal kerja bersama, gunakan rumus 1/(1/A + 1/B + 1/C).', '2026-05-09 19:31:03', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 71);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (3763, 3, NULL, 49, NULL, NULL, NULL, 'Saya mengikuti rapat RT untuk menentukan konsep acara hari kemerdekaan, namun rapat berlangsung lama karena peserta rapat tidak ada yang mengajukan konsep', NULL, 'Rapat ini benar-benar membuang waktu saja', NULL, 'Saya mengajukan konsep yang saya punya sebagai pancingan saja.', NULL, 'Mereka saja tidak menyiapkan konsep, mengapa harus saya yang bicara.', NULL, 'Saya mengajukan konsep yang saya punya dan meminta saran dari para peserta.', NULL, 'Saya mengusulkan konsep yang sama dengan tahun lalu.', NULL, 'D', 'Sikap yang baik adalah mengajukan konsep dan meminta saran.', NULL, 'Pilih jawaban yang menunjukkan inisiatif dan kerjasama.', '2026-05-09 19:31:03', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 101);
