INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (3783, 1, NULL, 1, NULL, NULL, NULL, 'Setiap siswa peserta kesenian adalah peserta bela diri atau renang. Tidak ada peserta bela diri atau renang yang bukan peserta melukis. Inda bukan peserta melukis.', NULL, 'Inda adalah bukan peserta bela diri maupun kesenian.', NULL, 'Inda adalah peserta melukis dan bukan peserta kesenian.', NULL, 'Inda adalah bukan peserta kesenian, tetapi peserta renang.', NULL, 'Inda adalah peserta renang dan bukan peserta melukis.', NULL, 'Inda adalah bukan peserta kesenian tetapi peserta bela diri.', NULL, 'A', 'Inda bukan peserta melukis, maka Inda bukan peserta bela diri maupun kesenian.', NULL, 'Untuk soal logika, buat diagram Venn untuk memvisualisasikan.', '2026-05-09 19:31:03', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 17);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (3835, 2, NULL, 25, NULL, NULL, NULL, 'Jika 20 ekor kambing mampu menghabiskan rumput sebanyak 4 lapangan selama 8 hari, maka 16 ekor kambing mampu menghabiskan rumput sebanyak 8 lapangan selama hari.', NULL, 8, NULL, 12, NULL, 14, NULL, 16, NULL, 20, NULL, 'E', '20 kambing, 4 lapangan, 8 hari. 16 kambing, 8 lapangan, x hari. (20/16) × (8/4) × 8 = 20 hari.', NULL, 'Untuk soal perbandingan, gunakan rumus proporsi.', '2026-05-09 19:31:03', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 94);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (3947, 1, NULL, 1, NULL, NULL, NULL, 'UUD 1945 yang disahkan oleh Panitia Persiapan Kemerdekaan Indonesia (PPKI) pada 18 Agustus 1945 terdiri atas...', NULL, 'Pembukaan, landasan teori, dan kesimpulan', NULL, 'Pembukaan, batang tubuh, dan penjelasan', NULL, 'Landasan teori, batang tubuh, dan penjelasan', NULL, 'Landasan teori, penjelasan, dan kesimpulan', NULL, 'Pembukaan, batang tubuh, dan penutup', NULL, 'B', 'UUD 1945 terdiri dari Pembukaan, Batang Tubuh, dan Penjelasan.', NULL, 'Hafalkan struktur UUD 1945.', '2026-05-09 19:33:26', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 30);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (3952, 2, NULL, 25, NULL, NULL, NULL, 'Arkeologi : purbakala = meteorologi : ...', NULL, 'Langit', NULL, 'Tata surya', NULL, 'Atmosfer', NULL, 'Meteor', NULL, 'Benda langit', NULL, 'C', 'Arkeologi mempelajari purbakala, meteorologi mempelajari atmosfer. Hubungan: Ilmu : Objek kajiannya.', NULL, 'Untuk analogi ilmu, identifikasi hubungan ilmu dengan objek kajiannya.', '2026-05-09 19:33:26', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 4);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (3968, 1, NULL, 3, NULL, NULL, NULL, '\"Sesudah tiga hari berturut-turut anggota-anggota Dokuritsu Zyunbi Tyoosakai mengeluarkan pendapat-pendapatnya, maka sekarang saya mendapat kehormatan dari Paduka Tuan Ketua yang mulia untuk mengemukakan pendapat saya. Saya akan menepati permintaan Paduka Tuan Ketua yang mulia. Apakah permintaan Paduka Tuan Ketua yang mulia? Paduka Tuan Ketua yang mulia minta kepada sidang Dokuritsu Zyunbi Tyoosakai untuk mengemukakan dasar Indonesia Merdeka. Dasar inilah nanti akan saya kemukakan di dalam pidato saya ini,\" begitu kata Bung Karno mengawali pidatonya seperti dikutip dari http://www.academia.edu, Rabu (1/6/2016). Dalam pidatonya di sidang BPUPKI Bung Karno telah menyampaikan prinsip dasar negara yakni...', NULL, 'Kebangsaan Indonesia; Internasionalisme atau perikemanusiaan; Mufakat atau demokrasi; Perdamaian abadi', NULL, 'Peri Kebangsaan, Peri Kemanusiaan, Peri keTuhanan, Peri Kerakyatan, dan Mufakat', NULL, 'Kebangsaan Indonesia; Internasionalisme atau perikemanusiaan; Mufakat atau demokrasi; Kesejahteraan sosial; Ketuhanan yang berkebudayaan', NULL, 'Peri Kebangsaan, Peri Kemanusiaan, Peri keTuhanan, Peri Kerakyatan, dan Kesejahteraan Rakyat', NULL, 'Ketuhanan YME, Peri Kemanusiaan, Kebangsaan, Kerakyatan, Keadilan Sosial', NULL, 'C', 'Pada tanggal 1 Juni 1945, Ir.Soekarno menyampaikan pidatonya dihadapan sidang BPUPKI. Dalam pidato tersebut diajukan oleh Ir.Soekarno secara lisan usulan lima asas sebagai dasar Negara Indonesia yang akan dibentuk,yang terdiri dari: 1) Nasionalisme atau Kebangsaan Indonesia; 2) Internasionalisme atau Perikemanusiaan; 3) Mufakat atau Demokrasi; 4) Kesejahteraan sosial; dan 5) Ketuhanan yang berkebudayaan. Lima asas di atas oleh Ir.Soekarno diusulkan agar diberi nama \"Pancasila\".', NULL, 'Hafalkan pidato 1 Juni 1945 Soekarno tentang Pancasila.', '2026-05-09 19:33:26', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 1);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (3969, 1, NULL, 1, NULL, NULL, NULL, 'Ekonomi kerakyatan adalah sistem ekonomi yang berbasis pada kekuatan ekonomi rakyat. Dimana ekonomi rakyat sendiri adalah sebagai kegiatan ekonomi atau usaha yang dilakukan oleh rakyat kebanyakan (popular) yang dengan secara swadaya mengelola sumberdaya ekonomi apa saja yang dapat diusahakan dan dikuasainya, yang selanjutnya disebut sebagai Usaha Kecil dan Menengah (UKM) terutama meliputi sektor pertanian, peternakan, kerajinan, makanan, dsb, yang ditujukan terutama untuk memenuhi kebutuhan dasarnya dan keluarganya tanpa harus mengorbankan kepentingan masyarakat lainnya. Pembangunan ekonomi kerakyatan memiliki peranan dalam menciptakan kemakmuran dan kesejahteraan rakyat. Hal tersebut sesuai dengan bunyi UUD 1945 pasal 33 ayat 1 yang berbunyi...', NULL, 'Cabang-cabang produksi yang penting bagi negara dan yang menguasai hajat hidup orang banyak dikuasai oleh negara', NULL, 'Perekonomian disusun sebagai usaha bersama berdasar atas asas kekeluargaan', NULL, 'Perekonomian nasional diselenggarakan berdasarkan atas demokrasi ekonomi dengan prinsip kebersamaan, efisiensi keadilan, keberlanjutan, wawasan lingkungan, kemandirian, serta dengan menjaga keseimbangan kemajuan dan kesatuan ekonomi nasional', NULL, 'Cabang-cabang produksi boleh dikuasai oleh perseorangan atau Negara', NULL, 'Bumi dan air dan kekayaan alam yang terkandung di dalamnya dikuasai oleh negara dan dipergunakan untuk sebesar-besarnya kemakmuran rakyat', NULL, 'B', 'Kemakmuran rakyat merupakan tujuan utama dari pembangunan ekonomi kerakyatan. Hal tersebut sesuai dengan bunyi UUD 1945 pasal 33 ayat 1 yang berbunyi: Perekonomian disusun sebagai usaha bersama berdasar atas asas kekeluargaan.', NULL, 'Hafalkan Pasal 33 UUD 1945 tentang ekonomi kerakyatan.', '2026-05-09 19:33:26', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 45);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (3970, 1, NULL, 1, NULL, NULL, NULL, 'Perundingan antara Indonesia dan Belanda yang dilakukan pada tanggal 10 November 1945. Dalam perundingan ini, Indonesia diwakili oleh Perdana menteri Sutan Syahrir, sedangkan Belanda diwakili oleh Prof. Schermerhorn. Perundingan ini adalah...', NULL, 'Renville', NULL, 'Linggarjati', NULL, 'Roem Royen', NULL, 'Giyanti', NULL, 'Bongaya', NULL, 'B', 'Perundingan Linggarjati dilakukan pada tanggal 10 November 1946 di Linggarjati. Dalam perundingan ini, Indonesia diwakili oleh Perdana menteri Sutan Syahrir, sedangkan Belanda diwakili oleh Prof. Schermerhorn.', NULL, 'Hafalkan perundingan-perundingan Indonesia-Belanda beserta tanggalnya.', '2026-05-09 19:33:26', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 39);
