INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (4247, 3, NULL, 49, NULL, NULL, NULL, 'Bulan ini anda menerima berbagai macam keluhan dari pelanggan anda terkait pelayanan dari perusahaan terhadap mereka. Sebagai perusahaan yang memberikan layanan anda sudah sepatutnya mengerti akan kebutuhan pelanggan agar mereka tetap menggunakan jasa perusahaan anda, ketika ada seorang pelanggan yang datang menyampaikan keluhannya, yang anda lakukan?', NULL, 'Meminta pelanggan tersebut untuk menyampaikan keluhannya', NULL, 'Menanyakan keluhan pelanggan tersebut dan menjadikan bagian dari solusi', NULL, 'Mendengarkan setiap keluhan yang masuk kepada anda dengan seksama', NULL, 'Mengatasi keluhan yang masuk dengan tetap tenang dan fokus', NULL, 'Mencoba mengerti keluhan pelanggan terhadap perusahaan', NULL, 'B', 'Jawaban B menunjukkan sikap responsif dan solutif terhadap keluhan pelanggan.', NULL, 'Pilih jawaban yang menunjukkan sikap responsif dan solutif.', '2026-05-09 19:33:27', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 123);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (4256, 3, NULL, 49, NULL, NULL, NULL, 'Saya sedang menghadapi ujian akhir, namun saya tidak bisa hadir dalam ujian tersebut karena sakit dan dosen saya tidak menawarkan untuk mengikuti ujian susulan.', NULL, 'Cuek saja toh dosennya tidak menawarkan ujian susulan.', NULL, 'Saya menghadap dosen saya untuk meminta ujian susulan.', NULL, 'Saya menyadari bahwa jika saya tidak mengikuti ujian mungkin saya tidak akan lulus.', NULL, 'Seharusnya dosen tahu bahwa saya sedang sakit sehingga tidak dapat mengikuti ujian.', NULL, 'Saya mungkin akan mengikuti ujian susulan kalau diadakan.', NULL, 'B', 'Sikap yang baik adalah menghadap dosen untuk meminta ujian susulan.', NULL, 'Pilih jawaban yang menunjukkan inisiatif dan tanggung jawab.', '2026-05-09 19:33:27', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 101);
