INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (4617, 3, NULL, 49, NULL, NULL, NULL, 'Anda adalah seorang ketua RT di suatu perumahan padat penduduk. Suatu hari, kompleks perumahan Anda kedatangan sekelompok pemuda yang menyewa salah satu rumah warga di wilayah Anda. Setelah beberapa minggu, beberapa warga mengadukan kecurigaan mereka terhadap para pemuda tersebut karena jarang keluar rumah dan enggan bertegur sapa dengan warga yang lain. Penghuni rumah cenderung beraktivitas saat malam hari. Warga yang lain juga melihat terkadang ada kelompok pemuda lain yang keluar masuk rumah tersebut saat malam hari. Anda berusaha mengakrabkan diri dengan para pemuda tersebut dan mengajak mereka ikut serta dalam kegiatan sosial namun mereka selalu menolak dan bersikap pasif. Sikap Anda...', NULL, 'Melakukan sidak dengan warga lain untuk mencari tahu sebenarnya kegiatan apa yang mereka lakukan setiap malam', NULL, 'Segera melaporkan keberadaan pemuda tersebut pada pihak berwenang terkait aktivitas yang mencurigakan', NULL, 'Menginformasikan temuan warga pada kepala desa setempat untuk mendapatkan petunjuk untuk mengatasinya', NULL, 'Tetap berusaha mengakrabkan diri dan mengajak para pemuda tersebut terlibat dengan kegiatan sosial di perumahan', NULL, 'Meminta warga yang lain untuk tetap berbaik sangka dan menghargai privasi orang lain', NULL, 'B', 'Jawaban B memiliki skor tertinggi (5) yang menunjukkan kehati-hatian dan tanggung jawab.', NULL, 'Pilih jawaban dengan skor tertinggi yang menunjukkan kehati-hatian.', '2026-05-09 19:36:58', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 119);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (4620, 2, NULL, 25, NULL, NULL, NULL, 'Pernyataan: \"jika laba tinggi maka karyawan sejahtera\" mempunyai kontraposisi yaitu...', NULL, 'Jika laba tinggi maka karyawan tidak sejahtera', NULL, 'Jika laba rendah maka karyawan tidak sejahtera', NULL, 'Jika laba rendah maka karyawan sejahtera', NULL, 'Jika karyawan sejahtera maka laba tinggi', NULL, 'Jika karyawan tidak sejahtera maka laba tidak tinggi', NULL, 'E', 'Kontraposisi dari p → q adalah ~q → ~p. Jadi kontraposisi \"jika laba tinggi maka karyawan sejahtera\" adalah \"Jika karyawan tidak sejahtera maka laba tidak tinggi\".', NULL, 'Hafalkan rumus kontraposisi: p → q, kontraposisinya adalah ~q → ~p.', '2026-05-09 19:36:58', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 59);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (4630, 1, NULL, 1, NULL, NULL, NULL, 'UUD 1945 telah mengalami beberapa kali amandemen. Tujuan utama dilakukannya amandemen UUD 1945 adalah...', NULL, 'Untuk menyesuaikan konstitusi dengan perkembangan zaman dan tuntutan masyarakat', NULL, 'Memberikan hak yang lebih luas kepada partai politik', NULL, 'Membentuk lembaga pemerintahan baru untuk pelayanan publik', NULL, 'Membatasi kekuasaan MPR dan DPR', NULL, 'Memisahkan kekuasaan eksekutif dan yudikatif', NULL, 'A', 'Amandemen UUD 1945 dilakukan untuk menyesuaikan konstitusi dengan perkembangan zaman serta tuntutan masyarakat, termasuk memperkuat sistem demokrasi dan perlindungan hak asasi manusia.', NULL, 'Pilih jawaban yang menekankan penyesuaian dengan perkembangan zaman.', '2026-05-09 19:36:58', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 30);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (4636, 2, NULL, 25, NULL, NULL, NULL, 'Semua B bukan I. Sebagian B adalah R. Maka...', NULL, 'Semua B adalah R bukan I', NULL, 'Semua B bukan I dan bukan R', NULL, 'Sebagian B bukan I dan bukan R', NULL, 'Semua B adalah R', NULL, 'Semua B adalah I', NULL, 'C', 'Karena semua B bukan I dan hanya sebagian B adalah R, maka masih ada sebagian B yang bukan R dan tetap bukan I.', NULL, 'Untuk soal logika, perhatikan hubungan antar himpunan dan gunakan diagram Venn jika perlu.', '2026-05-09 19:36:58', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 81);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (4644, 3, NULL, 49, NULL, NULL, NULL, 'Rekan kerja Anda melakukan kesalahan yang dapat merugikan tim. Sikap Anda adalah...', NULL, 'Membiarkannya', NULL, 'Menegur di depan umum', NULL, 'Mengingatkan secara pribadi', NULL, 'Melaporkan langsung ke atasan', NULL, 'Menghindari masalah', NULL, 'C', 'Mengingatkan secara pribadi mencerminkan sikap profesional dan menjaga hubungan kerja.', NULL, 'Pilih jawaban yang menunjukkan sikap profesional dan menjaga hubungan kerja.', '2026-05-09 19:36:58', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 116);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (4651, 3, NULL, 49, NULL, NULL, NULL, 'Anda bekerja pada perusahaan penerbangan yang cukup besar. Perusahaan Anda berencana untuk membentuk anak perusahaan sehingga melakukan rekrutmen calon pegawai yang akan mengurus anak perusahaan tersebut. Kebetulan hari ini adalah proses penentuan calon karyawan yang akan diterima, namun dewan pimpinan berhalangan hadir sehingga beliau mengamanahkan Anda menjadi salah satu dewan yang menentukan siapa saja karyawan yang akan diterima. Hal apa yang akan Anda lakukan?', NULL, 'Saya akan meminta rekan yang menurut saya dia memiliki kompetensi dalam menyeleksi karyawan yang sesuai dengan kriteria perusahaan', NULL, 'Saya akan menambahkan ujian tulis dan wawancara secara singkat sehingga saya dapat lebih mengetahui kemampuan mereka', NULL, 'Saya akan menggunakan cara seleksi sebelumnya agar tidak terjadi kesalahan prosedur', NULL, 'Saya akan memberikan ujian tulis dan wawancara secara mendalam agar mengetahui calon pelamar yang sesuai dengan klasifikasi yang dibutuhkan perusahaan', NULL, 'Saya akan mengadakan seleksi tertulis dan wawancara dan hasil dari tes tulis dan wawancara akan saya sampaikan ke pimpinan agar mereka dapat memutuskan sesuai dengan laporan yang saya kirim', NULL, 'D', 'Jawaban D memiliki skor tertinggi (5) yang menunjukkan kemampuan bekerja secara mandiri dan tuntas dengan indikator tanggung jawab dan inisiatif.', NULL, 'Pilih jawaban dengan skor tertinggi yang menunjukkan tanggung jawab dan inisiatif.', '2026-05-09 19:36:58', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 111);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (4654, 3, NULL, 49, NULL, NULL, NULL, 'Anda bekerja di instansi pelayanan publik dan seringkali dihadapkan pada situasi di mana Anda harus menangani keluhan atau kekecewaan dari masyarakat. Bagaimana sikap Anda dalam menghadapi situasi tersebut?', NULL, 'Saya akan mengabaikan keluhan masyarakat dan tidak menggubrisnya', NULL, 'Saya akan merasa tersinggung dan menanggapi dengan nada yang kasar', NULL, 'Saya akan mendengarkan dengan empati dan berusaha mencari solusi yang memuaskan masyarakat', NULL, 'Saya akan mengalihkan perhatian dan menghindari tanggung jawab tersebut', NULL, 'Saya akan menyalahkan masyarakat atas masalah yang mereka hadapi', NULL, 'C', 'Jawaban C memiliki skor tertinggi (5) yang menunjukkan kemampuan dalam mengelola konflik, kepedulian terhadap kebutuhan masyarakat, dan komunikasi yang baik.', NULL, 'Pilih jawaban dengan skor tertinggi yang menunjukkan kemampuan mengelola konflik dan kepedulian.', '2026-05-09 19:36:58', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 111);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (4663, 2, NULL, 26, NULL, NULL, NULL, 'Anjung = ....', NULL, 'Dayung', NULL, 'Panggung', NULL, 'Buyung', NULL, 'Puji', NULL, 'Angkat', NULL, 'B', 'Anjung dan Panggung memiliki kata dasar yang sama (ang) dan keduanya berhubungan dengan tempat.', NULL, 'Untuk soal sinonim, perhatikan kata dasar dan makna yang sama.', '2026-05-09 19:36:58', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 4);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (4734, 2, NULL, 25, NULL, NULL, NULL, 'Jika Naruto bukan tokoh kartun maka Doraemon adalah kucing sungguhan. Ingkaran dari pernyataan di atas adalah:', NULL, 'Jika Naruto adalah tokoh kartun maka Doraemon bukan kucing sungguhan.', NULL, 'Jika Doraemon adalah kucing sungguhan maka Naruto adalah tokoh kartun.', NULL, 'Naruto adalah tokoh kartun atau Doraemon adalah kucing sungguhan.', NULL, 'Naruto bukan tokoh kartun dan Doraemon bukan kucing sungguhan.', NULL, 'Naruto bukan tokoh kartun atau Doraemon bukan kucing sungguhan.', NULL, 'C', 'Ingkaran dari \"Jika P maka Q\" adalah \"P dan tidak Q\". Ingkaran dari \"Jika Naruto bukan tokoh kartun maka Doraemon adalah kucing sungguhan\" adalah \"Naruto bukan tokoh kartun dan Doraemon bukan kucing sungguhan\". Namun berdasarkan aturan ingkaran, jawaban yang benar adalah C.', NULL, 'Untuk soal logika, pahami aturan ingkaran implikasi.', '2026-05-09 19:36:58', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 51);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (4767, 2, NULL, 25, NULL, NULL, NULL, 'Kucing-kucing itu bertengger di atas dahan-dahan pohon. Kalimat yang menyerupai kalimat tersebut adalah...', NULL, 'Mereka berdua saling berpegangan tangan', NULL, 'Karya seni itu bertemakan nasionalisme', NULL, 'Anak-anak sedang bermain di lapangan', NULL, 'Ibu membeli sayur di pasar', NULL, 'Adik membelikan kucingnya makanan kucing', NULL, 'C', 'Keduanya memiliki struktur subjek + verba + lokasi.', NULL, 'Untuk soal analogi kalimat, perhatikan struktur kalimat.', '2026-05-09 19:36:58', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 78);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (4802, 1, NULL, 109, NULL, NULL, NULL, 'Pembangunan tidak boleh bersifat pragmatis, hal ini berarti...', NULL, 'Pembangunan tidak hanya mementingkan tindakan nyata dan mengabaikan pertimbangan etis', NULL, 'Pembangunan tidak boleh secara mutlak melayani ideologi tertentu dan mengabaikan manusia nyata', NULL, 'Pembangunan tidak boleh mengorbankan manusia nyata melainkan menghormati harkat dan martabat bangsa', NULL, 'Pembangunan melibatkan masyarakat sebagai tujuan pembangunan, keputusan yang menyangkut kebutuhan mereka', NULL, 'Pembangunan mengutamakan mereka yang paling lemah untuk menghapuskan kemiskinan struktural', NULL, 'A', 'Pembangunan pragmatis berarti hanya mementingkan hasil praktis tanpa pertimbangan etis.', NULL, 'Pahami konsep pembangunan yang tidak pragmatis.', '2026-05-09 19:36:58', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 14);
