INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (5273, 2, NULL, 25, NULL, NULL, NULL, 'Sebuah proyek pembangunan terdiri atas beberapa jenis proyek kecil, yakni proyek P, Q, R, S, T, dan U. Proyek kecil ini berkaitan satu dengan yang lain sehingga tiap-tiap jenis pekerjaan diatur sebagai berikut: Proyek Q tidak boleh dikerjakan bersamaan dengan proyek S. Proyek P boleh dikerjakan bersama dengan proyek T. Proyek Q hanya boleh dikerjakan bersama dengan proyek R. Proyek T dikerjakan jika proyek U dikerjakan. Jika pekerja sudah mengerjakan proyek T, maka ....', NULL, 'Pekerja tidak mengerjakan proyek S', NULL, 'Pekerja tentu akan mengerjakan proyek P', NULL, 'Pekerja hanya akan mengerjakan proyek R', NULL, 'Pekerja juga mengerjakan proyek U', NULL, 'Pekerja tidak mengerjakan proyek R', NULL, 'D', 'Jika T dikerjakan, maka U harus dikerjakan (karena T dikerjakan jika U dikerjakan).', NULL, 'Untuk soal logika, buat tabel hubungan antar proyek.', '2026-05-09 19:42:51', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 69);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (5277, 2, NULL, 25, NULL, NULL, NULL, 'Jika M = T maka M tidak sama dengan C. Bila B = M, maka?', NULL, 'Bila B = M maka B = T', NULL, 'Bila B = C maka B tidak sama dengan T', NULL, 'Bila B = C maka B tidak sama dengan T', NULL, 'Bila B = C maka B = M = T', NULL, 'M = C= B tidak sama dengan T', NULL, 'B', 'Jika M = T dan M ≠ C, maka T ≠ C. Jika B = M, maka B = T dan B ≠ C. Jadi jika B = C, maka B tidak sama dengan T.', NULL, 'Untuk soal logika, gunakan aturan implikasi.', '2026-05-09 19:42:51', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 51);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (5281, 2, NULL, 25, NULL, NULL, NULL, 'Jelajahi Mars dengan Simulator Baru Keluaran NASA. Meskipun masih diperlukan bertahun-tahun lamanya hingga manusia dapat menginjakkan kaki di planet Mars, bukan berarti tidak mungkin bagi manusia sekarang ini untuk menjalankan tur keliling Mars. NASA telah mengeluarkan simulator 3D baru yang dapat memungkinkan para penggunanya menjelajahi Mars. Simulator ini memberikan pengalaman tur virtual bagi orang-orang yang berkeinginan untuk melakukan perjalanan mengelilingi Mars. Dikutip dari situs Quartz, fitur terbaru ciptaan NASA ini mengizinkan para penggunanya untuk mengatur gerak navigasi kendaraan Mars Curiosity yang dimiliki agen luar angkasa Amerika Serikat ini ke seluruh penjuru Mars. Dengan mengatur gerak Mars Curiosity, para pengguna fitur terbaru NASA dapat mengeksplorasi planet merah sesuai yang mereka inginkan melalui komputer pribadi mereka. Kata \"fitur\" pada bacaan di atas adalah....', NULL, 'Kemampuan/ciri khusus pada suatu gawai', NULL, 'alat yang memiliki berbagai fungsi', NULL, 'Sistem', NULL, 'Perangkat alat', NULL, 'Perangkat sistem', NULL, 'A', 'Fitur berarti kemampuan atau ciri khusus pada suatu gawai atau aplikasi.', NULL, 'Untuk soal menentukan makna kata, perhatikan konteks kalimat.', '2026-05-09 19:42:51', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 82);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (5286, 2, NULL, 25, NULL, NULL, NULL, 'Jika saya pekerja maka saya mendapat gaji. Kalimat berikut yang ekuivalen dengan pernyataan diatas adalah?', NULL, 'Saya bukan pekerja atau saya mendapat gaji', NULL, 'Saya bukan pekerja dan saya mendapat gaji', NULL, 'Saya bukan pekerja atau saya tidak mendapatkan gaji', NULL, 'Saya bukan pekerja dan saya tidak mendapatkan gaji', NULL, 'Saya pekerja dan saya tidak mendapat gaji', NULL, 'A', 'P → Q ekuivalen dengan ¬P ∨ Q. \"Jika saya pekerja maka saya mendapat gaji\" ekuivalen dengan \"Saya bukan pekerja atau saya mendapat gaji\".', NULL, 'Untuk soal logika, gunakan aturan ekuivalensi implikasi.', '2026-05-09 19:42:51', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 51);
