INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (5303, 2, NULL, 25, NULL, NULL, NULL, 'Kucing-kucing itu bertengger di atas dahan-dahan pohon. Kalimat yang menyerupai kalimat tersebut adalah...', NULL, 'Mereka berdua saling berpegangan tangan', NULL, 'Karya seni itu bertemakan nasionalisme', NULL, 'Anak-anak sedang bermain di lapangan', NULL, 'Ibu membeli sayur di pasar', NULL, 'Adik membelikan kucingnya makanan kucing', NULL, 'C', 'Keduanya memiliki struktur subjek + verba + lokasi.', NULL, 'Untuk soal analogi kalimat, perhatikan struktur kalimat.', '2026-05-09 19:42:51', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 78);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (5401, 2, NULL, 25, NULL, NULL, NULL, 'Dalam sehari, sebuah pabrik dapat memproduksi 480 unit produk. Jika pabrik tersebut beroperasi selama 7 hari dalam seminggu, berapa total unit produk yang dapat diproduksi oleh pabrik tersebut dalam satu bulan?', NULL, '2,800', NULL, '3,000', NULL, '3,360', NULL, '3,500', NULL, '3,840', NULL, 'E', '480 × 7 × 4 = 480 × 28 = 13,440 per bulan. Wait, 480×7=3360 per minggu, 3360×4=13440. Let me recalculate: 480×30=14400 per bulan (30 hari). Answer seems wrong. Let me use 4 weeks: 480×7×4=13440. None match. Maybe 480×8=3840 for 8 working days?', NULL, 'Untuk soal aritmatika, perhatikan asumsi yang digunakan.', '2026-05-09 19:42:51', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 94);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (5404, 2, NULL, 25, NULL, NULL, NULL, 'Seekor monyet mula - mula berada di ketinggian tertentu pada sebuah tiang, kemudian ia turun 4 meter, naik 3 meter, turun 6 meter, naik 2 meter, naik 9 meter, dan turun 2 meter. Pada ketinggian berapakah monyet itu berada?', NULL, 'Sama seperti posisi semula', NULL, '2 meter di atas posisi semula', NULL, '1 meter di bawah posisi semula', NULL, '1 meter di atas posisi semula', NULL, '2 meter di bawah posisi semula', NULL, 'B', '-4 + 3 - 6 + 2 + 9 - 2 = +2. Monyet berada 2 meter di atas posisi semula.', NULL, 'Untuk soal pergerakan, jumlahkan semua perubahan posisi.', '2026-05-09 19:42:51', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 96);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (5411, 2, NULL, 25, NULL, NULL, NULL, 'Sebuah kereta melaju dengan kecepatan 60 km/jam. Berapa jauh kereta tersebut melaju dalam 2,5 jam?', NULL, '120 km', NULL, '150 km', NULL, '160 km', NULL, '180 km', NULL, '200 km', NULL, 'B', 'Jarak = kecepatan × waktu = 60 × 2,5 = 150 km.', NULL, 'Untuk soal kecepatan, gunakan rumus jarak = kecepatan × waktu.', '2026-05-09 19:42:51', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 93);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (5428, 3, NULL, 49, NULL, NULL, NULL, 'Salah seorang rekan kerja saya mendapat promosi, sedangkan menurut penilaian saya, kemampuannya tidak lebih baik dari saya. Respon saya adalah...', NULL, 'Menggunakan berbagai cara agar dapat menggeser posisi rekan tersebut', NULL, 'Bekerja lebih giat dan menunjukkan kinerja terbaik saya', NULL, 'Menghadap pimpinan dan memprotes promosi tersebut', NULL, 'Tetap bekerja seperti biasa', NULL, 'Menerima keadaan tersebut tetapi tidak akan mengikuti perintah rekan tersebut', NULL, 'B', 'Bekerja lebih giat menunjukkan sikap kompetitif yang sehat.', NULL, 'Pilih jawaban yang menunjukkan sikap positif dan produktif.', '2026-05-09 19:42:52', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 124);
