INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (5512, 2, NULL, 25, NULL, NULL, NULL, 'Di antara bilangan-bilangan berikut, yang habis dibagi oleh 6 dan 7 adalah...', NULL, 252, NULL, 352, NULL, 452, NULL, 512, NULL, 622, NULL, 'A', 'KPK dari 6 dan 7 adalah 42. 252 ÷ 42 = 6. Jadi 252 habis dibagi oleh 6 dan 7.', NULL, 'Untuk soal kelipatan, cari KPK terlebih dahulu.', '2026-05-09 19:42:52', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 73);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (5513, 2, NULL, 25, NULL, NULL, NULL, 'Pintu air di suatu daerah mempunyai 927 cabang saluran yang disalurkan ke rumah-rumah tangga. Dalam satu minggu digunakan 88.065 liter air. Berapa literkah rata-rata air yang digunakan masing-masing rumah tangga dalam satu minggu?', NULL, 90, NULL, 95, NULL, 100, NULL, 105, NULL, 110, NULL, 'B', 'Rata-rata penggunaan air = volume air / banyak cabang = 88.065 / 927 = 95.', NULL, 'Untuk soal rata-rata, gunakan rumus total/n.', '2026-05-09 19:42:52', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 88);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (5514, 2, NULL, 25, NULL, NULL, NULL, 'Jika sudut suatu segitiga adalah x, 2x, dan 3x derajat, dan y = 30 derajat. Maka.....', NULL, 'x > y', NULL, 'x < y', NULL, 'x = y', NULL, 'x dan y tidak bisa ditentukan', NULL, '2x < y', NULL, 'C', 'Jumlah sudut dalam segitiga adalah 180 derajat. x + 2x + 3x = 180, 6x = 180, x = 30. Maka x = y = 30.', NULL, 'Untuk soal geometri, gunakan rumus jumlah sudut segitiga.', '2026-05-09 19:42:52', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 74);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (5515, 2, NULL, 25, NULL, NULL, NULL, 'Jika a + 2 < x + p < b + 2 dan b < y + p < c dengan a < b < c, maka....', NULL, 'x < y', NULL, 'x > y', NULL, 'x = y', NULL, '3x - y = 0', NULL, 'hubungan x dan y tidak dapat ditentukan', NULL, 'E', 'Terdapat empat variabel bebas yaitu a, b, p, dan c yang dapat merubah batas x dan y, sehingga hubungan x dan y tidak dapat ditentukan.', NULL, 'Untuk soal ketidaksamaan, periksa apakah hubungan dapat ditentukan.', '2026-05-09 19:42:52', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 51);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (5516, 2, NULL, 25, NULL, NULL, NULL, 'Setiap kota yang memiliki pusat hiburan mempunyai ciri rawan kejahatan. Ini karena pusat hiburan menyebabkan adanya keramaian yang menarik para penjahat, sementara semua penjahat adalah pelaku kriminal. Kesimpulan yang salah adalah....', NULL, 'Semua penjahat adalah kriminal', NULL, 'Semua pusat hiburan menarik penjahat', NULL, 'Semua kota banyak penjahat', NULL, 'Penjahat tertarik adanya keramaian', NULL, 'Pusat hiburan menyebabkan rawan kejahatan', NULL, 'C', 'Kesimpulan yang salah adalah semua kota banyak penjahat, karena tidak semua kota memiliki pusat hiburan.', NULL, 'Untuk soal logika, periksa kesimpulan yang tidak mengikuti premis.', '2026-05-09 19:42:52', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 53);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (5517, 2, NULL, 25, NULL, NULL, NULL, 'Semua lawak membuat tawa. Sebagian tontonan adalah lawak.', NULL, 'Semua tontonan adalah lawak', NULL, 'Semua tontonan membuat tawa', NULL, 'Sebagian tontonan membuat tawa', NULL, 'Semua yang membuat tawa adalah lawak', NULL, 'Semua yang membuat tawa adalah tontonan', NULL, 'C', 'Karena semua lawak membuat tawa dan sebagian tontonan adalah lawak, maka sebagian tontonan membuat tawa.', NULL, 'Untuk soal logika silogisme, ikuti rantai kesimpulan.', '2026-05-09 19:42:52', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 81);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (5518, 2, NULL, 39, NULL, NULL, NULL, 'Rahman berbadan tegap. Semua prajurit berbadan tegap.', NULL, 'Rahman adalah seorang prajurit', NULL, 'Seorang yang berbadan tegap pastilah seorang prajurit', NULL, 'Rahman berbadan tegap karena ia seorang prajurit', NULL, 'Rahman belum tentu seorang prajurit', NULL, 'Tidak dapat ditarik kesimpulan', NULL, 'D', 'Rahman berbadan tegap dan semua prajurit berbadan tegap, tetapi tidak berarti semua yang berbadan tegap adalah prajurit. Rahman belum tentu seorang prajurit.', NULL, 'Untuk soal logika, hindari kesalahan fallacy.', '2026-05-09 19:42:52', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 5);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (5519, 3, NULL, 49, NULL, NULL, NULL, 'Jika saya diterima menjadi PNS dan saya tak mempunyai uang maka saya...', NULL, 'Mengundurkan diri sesegera mungkin', NULL, 'Mencari bantuan atasan', NULL, 'Melakukan kerja apapun asal bisa mendapat uang', NULL, 'Mencari pinjaman ke teman lainnya', NULL, 'Mencari sumbangan dari suatu lembaga', NULL, 'C', 'Melakukan kerja apapun asal bisa mendapat uang menunjukkan semangat kerja keras dan tanggung jawab.', NULL, 'Pilih jawaban yang menunjukkan semangat kerja keras.', '2026-05-09 19:42:52', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 101);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (5520, 3, NULL, 49, NULL, NULL, NULL, 'Saya berhasil mengatasi tantangan karena ...', NULL, 'Nasib baik selalu ada di tangan saya', NULL, 'Saya berani mencoba dengan segala risikonya', NULL, 'Selalu berada di zona nyaman saya', NULL, 'Selalu mendapat bantuan dari teman dan lingkungan saya', NULL, 'Saya tidak pernah berputus asa', NULL, 'E', 'Tidak pernah berputus asa menunjukkan ketekunan dan semangat pantang menyerah.', NULL, 'Pilih jawaban yang menunjukkan ketekunan dan semangat.', '2026-05-09 19:42:52', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 101);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (5521, 3, NULL, 49, NULL, NULL, NULL, 'Jika Anda diminta mengerjakan tugas yang tidak sesuai dengan bidang pekerjaan Anda oleh atasan, apa yang akan Anda lakukan?', NULL, 'Tetap menerima tugas tersebut karena perintah atasan', NULL, 'Menolak secara baik-baik karena tidak sesuai dengan jobdesk saya', NULL, 'Menolak dengan tegas agar atasan tidak semena-mena di masa mendatang', NULL, 'Tetap menerima tugas tersebut agar disukai atasan', NULL, 'Meminta rekan lain mengerjakan tugas tersebut', NULL, 'B', 'Menolak secara baik-baik karena tidak sesuai dengan jobdesk menunjukkan profesionalisme dan komunikasi yang baik.', NULL, 'Pilih jawaban yang menunjukkan profesionalisme.', '2026-05-09 19:42:52', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 114);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (5522, 3, NULL, 49, NULL, NULL, NULL, 'Saat dalam perjalanan menuju kantor, motor Anda tiba-tiba bannya bocor, padahal pagi itu Anda harus memimpin rapat divisi. Di dekat Anda ada pangkalan becak. Bagaimana sikap Anda?', NULL, 'Marah pada keadaan', NULL, 'Segera memilih untuk naik becak ke kantor', NULL, 'Menelepon teman sekerja untuk menjemput', NULL, 'Menelepon atasan dan meminta untuk membatalkan rapat', NULL, 'Menunggu bus atau kendaraan lain yang mungkin akan segera lewat', NULL, 'B', 'Segera memilih untuk naik becak ke kantor menunjukkan sikap solutif dan bertanggung jawab.', NULL, 'Pilih jawaban yang menunjukkan sikap solutif.', '2026-05-09 19:42:52', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 118);
