INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (5603, 3, NULL, 49, NULL, NULL, NULL, 'Atasan Anda tidak ada di kantor. Teman Anda mengajak untuk sedikit bersantai. Bagaimana dengan Anda?', NULL, 'Tetap di meja dan menyelesaikan pekerjaan', NULL, 'Mengikuti ajakannya dan bersantai', NULL, 'Ragu-ragu', NULL, 'Apabila memang tidak ada yang mengawasi, maka boleh saja bersantai', NULL, 'Memarahi teman dan menyuruh semuanya bekerja', NULL, 'A', 'Jawaban A menunjukkan integritas, disiplin, dan etos kerja yang tinggi.', NULL, 'Pilih jawaban yang menunjukkan integritas dan etos kerja tinggi.', '2026-05-09 19:50:33', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 112);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (5604, 3, NULL, 49, NULL, NULL, NULL, 'Apabila menjadi pemimpin, maka menurut Anda, apakah mengakui kesalahan itu dibutuhkan?', NULL, 'Sangat dibutuhkan', NULL, 'Dibutuhkan bila memang bersalah', NULL, 'Terkadang dibutuhkan, tergantung situasi, diri, dan tim', NULL, 'Tidak terlalu dibutuhkan karena kesalahan harus segera diselesaikan', NULL, 'Tidak dibutuhkan karena pemimpin harus bertindak benar', NULL, 'A', 'Jawaban A menunjukkan kejujuran, integritas, dan kemauan mengakui kesalahan sebagai pemimpin.', NULL, 'Pilih jawaban yang menunjukkan kejujuran dan integritas sebagai pemimpin.', '2026-05-09 19:50:33', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 142);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (5609, 2, NULL, 25, NULL, NULL, NULL, 'Sari dan Ratih memiliki suatu pekerjaan. Waktu yang dibutuhkan oleh Sari dalam menghasilkan uang adalah 21 menit, sedangkan Ratih membutuhkan waktu 42 menit. Jika Sari dan Ratih bekerja bersama-sama untuk menghasilkan uang, waktu yang dibutuhkan adalah...', NULL, '14 menit', NULL, '21 menit', NULL, '28 menit', NULL, '35 menit', NULL, '42 menit', NULL, 'A', '1/21 + 1/42 = 2/42 + 1/42 = 3/42 = 1/14. Jadi waktu yang dibutuhkan adalah 14 menit.', NULL, 'Untuk soal kerja bersama, gunakan rumus 1/t1 + 1/t2 = 1/t_total.', '2026-05-09 19:50:33', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 53);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (5610, 2, NULL, 25, NULL, NULL, NULL, 'Prestasi Intan lebih tinggi dari Dini dan lebih rendah dari Tina. Prestasi Cantik lebih lebih rendah dari Intan, tetapi lebih tinggi dari Dini. Prestasi Dani lebih tinggi dari Dini dan Cantik. Tiga orang berprestasi terbaik adalah...', NULL, 'Dani, Intan, Tina', NULL, 'Dani, Dini, Tina', NULL, 'Intan, Tina, Cantik', NULL, 'Intan, Dani, Cantik', NULL, 'Tina, Cantik, Dini', NULL, 'A', 'Tina > Intan > Cantik > Dani > Dini. Tiga terbaik: Tina, Intan, Cantik. Wait, Dani lebih tinggi dari Cantik. Urutan: Tina > Intan > Dani > Cantik > Dini. Tiga terbaik: Tina, Intan, Dani.', NULL, 'Untuk soal logika peringkat, buat diagram urutan.', '2026-05-09 19:50:33', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 100);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (5613, 3, NULL, 49, NULL, NULL, NULL, 'Edi baru saja diterima bekerja di salah satu pabrik pengolahan kayu. Sebagai pegawai baru, tentu Edi belum terlalu mengenal jenis-jenis pekerjaan dan cara menyelesaikannya. Suatu malam, tiba-tiba Edi ditugaskan manajernya untuk menyelesaikan tugas seorang rekannya yang tiba-tiba memutuskan untuk keluar dan berhenti bekerja. Edi jelas kaget dan kesulitan dengan penugasan itu, tapi ia tidak punya pilihan lain selain menjalankan perintah atasan. Apalagi manajer tadi memang memberikan tugas tersebut karena kagum melihat track record Edi sebagai mahasiswa lulusan terbaik. Menurut Anda, apa yang harus dilakukan Edi?', NULL, 'Meminta orang lain mengerjakan asalkan bisa selesai tepat waktu.', NULL, 'Segera berusaha memulai dan menyelesaikan sebisanya saja yang penting selesai.', NULL, 'Tidak perlu buru-buru menyelesaikannya karena pekerjaan tersebut bukan merupakan tugas pokoknya.', NULL, 'Segera berusaha memulai untuk menyelesaikan tugas itu dan berusaha menyelesaikannya sesempurna mungkin.', NULL, 'Mempertanyakan dan menegosiasi manajernya karena merasa takut hasilnya tidak maksimal.', NULL, 'D', 'Berdasarkan ketentuan diatas maka seseorang dituntut untuk melaksanakan tanggung jawab kerja berdasarkan tugas dan fungsinya sekaligus berupaya untuk memberikan yang terbaik dalam setiap tugas yang diberikan.', NULL, 'Pilih jawaban yang menunjukkan profesionalisme dan semangat berprestasi.', '2026-05-09 19:50:33', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 127);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (5618, 1, NULL, 1, NULL, NULL, NULL, 'Seorang pegawai negeri sipil diberikan tawaran oleh seorang rekan bisnis instansi untuk menerima paket liburan gratis sebagai bentuk ucapan terima kasih atas kelancaran proyek. Sikap yang harus diambil oleh pegawai tersebut adalah...', NULL, 'Menerimanya karena itu diberikan secara sukarela', NULL, 'Menolak dengan halus dan menjelaskan bahwa hal tersebut melanggar kode etik', NULL, 'Menerima namun melaporkannya kepada atasan setelah pulang liburan', NULL, 'Memberikan paket tersebut kepada rekan kerja lain yang membutuhkan', NULL, 'Menolak dan langsung memutus hubungan kerja sama dengan rekan tersebut', NULL, 'B', 'Integritas menuntut ASN untuk menolak gratifikasi dalam bentuk apa pun yang berhubungan dengan jabatan atau tugasnya. Menolak dengan sopan adalah cerminan profesionalisme.', NULL, 'Pilih jawaban yang menunjukkan integritas dan profesionalisme sebagai ASN.', '2026-05-09 19:50:33', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 50);
