INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (6066, 3, NULL, 49, NULL, NULL, NULL, 'Edi baru saja diterima bekerja di salah satu pabrik pengolahan kayu. Sebagai pegawai baru, tentu Edi belum terlalu mengenal jenis-jenis pekerjaan dan cara menyelesaikannya. Suatu malam, tiba-tiba Edi ditugaskan manajernya untuk menyelesaikan tugas seorang rekannya yang tiba-tiba memutuskan untuk keluar dan berhenti bekerja. Edi jelas kaget dan kesulitan dengan penugasan itu, tapi ia tidak punya pilihan lain selain menjalankan perintah atasan. Apalagi manajer tadi memang memberikan tugas tersebut karena kagum melihat track record Edi sebagai mahasiswa lulusan terbaik. Menurut Anda, apa yang harus dilakukan Edi?', NULL, 'Meminta orang lain mengerjakan asalkan bisa selesai tepat waktu.', NULL, 'Segera berusaha memulai dan menyelesaikan sebisanya saja yang penting selesai.', NULL, 'Tidak perlu buru-buru menyelesaikannya karena pekerjaan tersebut bukan merupakan tugas pokoknya.', NULL, 'Segera berusaha memulai untuk menyelesaikan tugas itu dan berusaha menyelesaikannya sesempurna mungkin.', NULL, 'Mempertanyakan dan menegosiasi manajernya karena merasa takut hasilnya tidak maksimal.', NULL, 'D', 'Berdasarkan ketentuan diatas maka seseorang dituntut untuk melaksanakan tanggung jawab kerja berdasarkan tugas dan fungsinya sekaligus berupaya untuk memberikan yang terbaik dalam setiap tugas yang diberikan.', NULL, 'Pilih jawaban yang menunjukkan profesionalisme dan semangat berprestasi.', '2026-05-09 19:50:33', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 127);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (6069, 1, NULL, 1, NULL, NULL, NULL, 'Mengembangkan sikap bahwa bangsa Indonesia merupakan bagian dari seluruh umat manusia merupakan perwujudan sila ke-...', NULL, 1, NULL, 2, NULL, 3, NULL, 4, NULL, 5, NULL, 'B', 'Mengembangkan sikap bahwa bangsa Indonesia merupakan bagian dari seluruh umat manusia merupakan perwujudan sila ke-2 (Kemanusiaan yang Adil dan Beradab).', NULL, 'Pahami pengamalan setiap sila Pancasila.', '2026-05-09 19:50:33', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 22);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (6073, 1, NULL, 1, NULL, NULL, NULL, 'Dalam sistem checks and balances di Indonesia, pihak MPR memiliki wewenang untuk...', NULL, 'Memberi pertimbangan dalam memberi amnesti dan abolisi', NULL, 'Mengawasi pemerintah atau eksekutif sesuai hak pengawasan', NULL, 'Menyetujui atau menolak menyetujui perjanjian Internasional', NULL, 'Memberi pertimbangan dalam pengangkatan dan penerimaan duta asing', NULL, 'Memberhentikan Presiden dan Wakil Presiden atas usul DPR', NULL, 'E', 'Dalam sistem checks and balances di Indonesia, pihak MPR memiliki wewenang untuk memberhentikan Presiden dan Wakil Presiden atas usul DPR.', NULL, 'Pahami sistem checks and balances lembaga negara Indonesia.', '2026-05-09 19:50:33', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 1);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (6116, 1, NULL, 13, NULL, NULL, NULL, 'Negara X adalah sebuah negara yang baru saja merdeka dan sedang berusaha membangun rasa nasionalisme di kalangan warganya. Proses ini dilakukan melalui implementasi berbagai program pemerintah dan penyebaran nilai-nilai patriotisme dalam pendidikan. Namun, beberapa tantangan tampaknya menjadi penghambat dalam upaya tersebut. Antara lain: - Banyak warga Negara X yang memilih untuk bekerja di negara lain dan mengadopsi gaya hidup serta budaya negara tersebut. - Sebagian masyarakat Negara X lebih tertarik pada barang-barang impor dibandingkan produk lokal. - Penyiaran dan media di Negara X banyak didominasi oleh konten dari luar negeri. - Konflik internal antara berbagai kelompok etnis dan agama yang berbeda. - Pengetahuan dan apresiasi terhadap sejarah dan budaya lokal cukup tinggi di kalangan masyarakat berusia. Berdasarkan kasus di atas, mana faktor yang paling mungkin menjadi penghambat utama dalam membangun semangat nasionalisme di Negara X?', NULL, 'Globalisasi', NULL, 'Kesenjangan sosial', NULL, 'Pendidikan yang kurang efektif', NULL, 'Sumber daya manusia yang kurang', NULL, 'Kurangnya dukungan dari pemerintah', NULL, 'A', 'Globalisasi merupakan fenomena di mana dunia semakin terhubung dari segi teknologi, ekonomi, dan budaya. Dalam kasus Negara X, globalisasi memiliki pengaruh yang signifikan sebagai penghambat perkembangan nasionalisme. Hal ini dapat dilihat dari migrasi tenaga kerja, dominasi barang impor, dan dominasi konten media asing.', NULL, 'Pahami pengaruh globalisasi terhadap nasionalisme.', '2026-05-09 19:50:33', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 2);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (6118, 1, NULL, 1, NULL, NULL, NULL, 'Pada 2021 silam, seorang aparat bernama Briptu Nikmal Idwan diduga melakukan pemerkosaan terhadap seorang remaja perempuan berusia 16 tahun di Mapolsek Jailolo Selatan, Halmahera Barat, Maluku Utara. Tindakan aparat ini jelas sekali bertentangan dengan ....', NULL, 'UUD 1945 pasal 27 ayat 3', NULL, 'UUD 1945 pasal 30 ayat 3', NULL, 'UUD 1945 pasal 30 ayat 4', NULL, 'UU nomor 3 2002 pasal 9 ayat 1', NULL, 'UU nomor 3 2002 pasal 9 ayat 2', NULL, 'C', 'Tindakan pemerkosaan yang dilakukan oleh oknum aparat tersebut jelas melanggar UUD 1945 pasal 30 ayat 4. Polisi seharusnya melindungi dan mengayomi masyarakat, tetapi justru menjadi ancaman dan pelaku kriminal.', NULL, 'Hafalkan pasal-pasal UUD 1945 terkait tugas kepolisian.', '2026-05-09 19:50:33', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 50);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (6119, 1, NULL, 1, NULL, NULL, NULL, 'Nama Pandawara Group seringkali menjadi perbincangan dan trending topik di sosial media berkat aksi-aksi heroiknya dalam membersihkan sampah. Beranggotakan lima orang pemuda, yaitu Ikhsan Destian, Gliang Rahma, Muhammad Rifqi, Rafly Pasya, dan Agung Permana, tak jarang Pandawara Group mengajak masyarakat dan netizen untuk turut serta turun ke lapangan membersihkan sampah. Aksi kelompok pemuda ini mencerminkan salah satu nilai bela negara, yaitu ....', NULL, 'cinta tanah air', NULL, 'kesadaran berbangsa dan bernegara', NULL, 'rela berkorban', NULL, 'memiliki kemampuan bela negara', NULL, 'memiliki kemampuan awal bela negara', NULL, 'A', 'Dalam kasus tersebut, Pandawara Group berupaya menjaga dan melestarikan lingkungan hidup. Aksi mereka ini sesuai dengan salah satu indikator cinta tanah air, yaitu mencintai, menjaga dan melestarikan Lingkungan Hidup.', NULL, 'Pahami indikator-indikator cinta tanah air.', '2026-05-09 19:50:33', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 47);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (6120, 1, NULL, 1, NULL, NULL, NULL, 'Unjuk rasa atau demonstrasi merupakan salah satu bentuk penyampaian pendapat di muka umum dan hal ini dijamin oleh undang-undang. Sayangnya, tak jarang aksi demonstrasi disertai tindakan anarkis dari oknum-oknum tak bertanggung jawab ingin melakukan persekusi, pengrusakan dan penjarahan di kantor pemerintahan dan sarana publik. Tindakan para oknum ini jelas bertentangan dengan Pancasila sila ke ....', NULL, 1, NULL, 2, NULL, 3, NULL, 4, NULL, 5, NULL, 'D', 'Tindakan yang dilakukan oleh oknum-oknum yang terlibat dalam demonstrasi anarkis, seperti melakukan persekusi, pengrusakan, dan penjarahan di kantor pemerintahan dan sarana publik, jelas bertentangan dengan Sila ke-4 Pancasila.', NULL, 'Pahami makna setiap sila Pancasila.', '2026-05-09 19:50:33', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 21);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (6121, 1, NULL, 1, NULL, NULL, NULL, 'Desa yang dipimpin oleh Pak Dimas terancam banjir akibat musim penghujan yang akan segera tiba dan dikhawatirkan akan menyebabkan sungai di sekitar desa meluap. Untuk mengatasi masalah ini, Pak Dimas mengusulkan pembangunan tanggul baru atau memperkuat drainase. Melalui pemungutan suara yang diadakan di desa tersebut, mayoritas warga memilih bangun tanggul baru. Perilaku Pak Dimas dan seluruh warga desa merupakan cerminan dari ....', NULL, 'UUD 1945 Pasal 2 ayat 1', NULL, 'pembukaan UUD 1945 alinea ke 1', NULL, 'pembukaan UUD 1945 alinea ke 4', NULL, 'Pancasila sila ke-2', NULL, 'Pancasila sila ke-3', NULL, 'C', 'Dalam kasus tersebut, Pak Dimas bersama warga desa menggunakan pemungutan suara untuk memilih solusi terbaik menghadapi ancaman banjir, mencerminkan prinsip demokratis. Pemungutan suara adalah wujud kedaulatan rakyat, sebagaimana yang dinyatakan dalam pembukaan UUD 1945 alinea ke-4.', NULL, 'Pahami prinsip kedaulatan rakyat dalam UUD 1945.', '2026-05-09 19:50:33', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 28);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (6122, 1, NULL, 10, NULL, NULL, NULL, 'Dalam rapat BPUPKI yang membahas rancangan undang-undang dasar, permasalahan bentuk negara menjadi salah satu pembahasan yang diperbedatkan secara serius. Usulan bentuk negara yang muncul pada waktu itu, yaitu negara kesatuan dan negara federal. Namun kemudian disepakati bentuk Negara Indonesia ialah negara kesatuan, sebagaimana tertera dalam Pasal 1 ayat (1) Undang-Undang Dasar 1945. Mengapa negara kesatuan lebih cocok sebagai bentuk negara Indonesia?', NULL, 'Indonesia sangat heterogen dan bentuk negara kesatuan bisa merangkul seluruh perbedaan tersebut sekaligus memastikan pengambilan kebijakan yang adil untuk setiap daerah, serta memperkecil risiko perpecahan karena otonomi yang berlebihan.', NULL, 'Indonesia terdiri dari puluhan ribu pulau yang terbentang dari Sabang-Merauke dimana setiap pulaunya memiliki karakteristik tersendiri sehingga setiap wilayah perlu memiliki pemerintahan dan otonominya sendiri.', NULL, 'Indonesia merupakan negara yang sangat heterogen dengan beragam suku, budaya, dan agama sehingga diperlukan adanya kekuasaan tunggal yang tidak dapat diganggu gugat.', NULL, 'Indonesia harus bisa menyeimbangkan kepentingan nasional dan lokal, serta memberikan otonomi yang lebih besar bagi daerah.', NULL, 'Indonesia pada masa itu baru merdeka dan para founding fathers ingin mencegah lahirnya kelas borjuis dari penjajahan dan kelas proletar dari pihak terjajah.', NULL, 'A', 'Negara kesatuan adalah negara berdaulat yang diselenggarakan sebagai satu kesatuan tunggal, di mana pemerintah pusat adalah yang tertinggi dan satuan-satuan subnasionalnya hanya menjalankan kekuasaan-kekuasaan yang dipilih dan diberikan untuk untuk didelegasikan. Indonesia lebih cocok menggunakan bentuk negara kesatuan karena wilayah Indonesia yang sangat luas dan masyarakatnya sangat heterogen.', NULL, 'Pahami alasan Indonesia memilih bentuk negara kesatuan.', '2026-05-09 19:50:33', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 2);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (6125, 2, NULL, 25, NULL, NULL, NULL, 'Hubungan yang terdapat pada kalimat ikan adalah ekor sama seperti hubungan pada kalimat …', NULL, 'Manusia adalah kaki.', NULL, 'Kucing adalah buntut.', NULL, 'Daun adalah helai.', NULL, 'Bunga adalah buah.', NULL, 'Rumah adalah hunian.', NULL, 'C', 'Hubungan yang terdapat dalam kalimat ikan adalah ekor yang paling mungkin adalah ikan menggunakan penggolongan ekor dalam perhitungannya. Kalimat yang memiliki hubungan yang sama yaitu Daun adalah helai karena daun menggunakan penggolongan helai dalam perhitungannya.', NULL, 'Untuk soal analogi, cari hubungan penggolongan.', '2026-05-09 19:50:33', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 72);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (6126, 2, NULL, 25, NULL, NULL, NULL, 'Perhatikan pernyataan berikut! - Setiap manusia di dunia pernah mengalami gigi rontok. - Beberapa manusia di dunia adalah orang yang sangat tampan. Jadi, …', NULL, 'Beberapa manusia yang sangat tampan tidak pernah mengalami rontok gigi.', NULL, 'Beberapa manusia yang sangat tampan pernah mengalami rontok gigi.', NULL, 'Semua manusia yang sangat tampan tidak pernah mengalami rontok gigi.', NULL, 'Semua manusia yang sangat tampan pernah mengalami rontok gigi.', NULL, 'Semua manusia yang pernah mengalami rontok gigi adalah manusia yang sangat tampan.', NULL, 'B', 'Kesimpulan yang tepat berdasarkan kedua informasi adalah Beberapa manusia yang sangat tampan pernah mengalami rontok gigi. Kesimpulan ini ditarik berdasarkan pernyataan bahwa Setiap manusia di dunia pernah mengalami gigi rontok. Karena Beberapa manusia di dunia adalah orang yang sangat tampan, maka orang tersebut tetap pernah mengalami rontok gigi.', NULL, 'Untuk soal logika silogisme, ikuti rantai kesimpulan.', '2026-05-09 19:50:33', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 73);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (6127, 2, NULL, 25, NULL, NULL, NULL, 'Orang-orang yang rajin membaca buku pasti memiliki pengetahuan yang luas. Orang yang memiliki pengetahuan luas sering kali lebih kreatif dalam memecahkan masalah. Hal ini membuat seseorang sukses dalam kariernya. Kesimpulan yang dapat ditarik dari premis-premis di atas adalah …', NULL, 'Orang yang sukses dalam kariernya pasti rajin membaca buku.', NULL, 'Orang yang rajin membaca buku sukses dalam kariernya.', NULL, 'Orang yang kreatif dalam memecahkan masalah pasti memiliki pengetahuan luas.', NULL, 'Orang yang sukses dalam karier pasti sering kali lebih kreatif dalam memecahkan masalah.', NULL, 'Orang yang sukses dalam karier sering kali rajin membaca buku.', NULL, 'B', 'Premis pertama menyatakan bahwa orang yang rajin membaca buku (p) memiliki pengetahuan luas (q). Premis kedua menyatakan bahwa orang yang memiliki pengetahuan luas (q) lebih kreatif dalam memecahkan masalah (r). Premis ketiga menyatakan bahwa Hal ini (orang yang kreatif dalam memecahkan masalah) (r) membuat seseorang sukses dalam kariernya (s). Dari P1, P2 dan P3 dapat kita ambil kesimpulan sehingga berlaku p ⇒ s, kesimpulan ini memiliki bentuk kalimat Orang yang rajin membaca buku sukses dalam kariernya.', NULL, 'Untuk soal logika silogisme, ikuti rantai kesimpulan.', '2026-05-09 19:50:33', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 56);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (6128, 2, NULL, 25, NULL, NULL, NULL, 'Sebagian orang kaya tidak menyumbangkan hartanya untuk amal. Semua orang kaya memiliki aset yang besar. Berdasarkan informasi tersebut, manakah simpulan di bawah ini yang benar?', NULL, 'Sebagian orang kaya yang menyumbang tidak memiliki aset yang besar.', NULL, 'Sebagian orang kaya yang tidak menyumbang memiliki aset yang besar.', NULL, 'Semua orang kaya yang tidak menyumbang tidak memiliki aset yang besar.', NULL, 'Sebagian orang yang memiliki aset besar tidak menyumbangkan hartanya.', NULL, 'Semua orang kaya menyumbang untuk amal.', NULL, 'D', 'Fakta 1: Sebagian orang kaya tidak menyumbangkan hartanya untuk amal. Fakta 2: Semua orang kaya memiliki aset yang besar. Jadi, di semua orang kaya yang memiliki aset besar, beberapa di antaranya tidak menyumbangkan hartanya untuk amal. Kesimpulan: Sebagian orang yang memiliki aset besar tidak menyumbangkan hartanya.', NULL, 'Untuk soal logika silogisme, ikuti rantai kesimpulan.', '2026-05-09 19:50:33', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 81);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (6129, 2, NULL, 41, NULL, NULL, NULL, 'Dalam sebuah perlombaan lari, Dani mencapai garis finis segera setelah Anton. Budi menyelesaikan perlombaan di antara Anton dan Raka. Raka sendiri mencapai garis finis setelah Fikri yang merupakan juara lomba lari tersebut. Urutan masuk finis kelima pelari tersebut adalah ….', NULL, 'Budi – Anton – Fikri – Raka – Dani', NULL, 'Fikri – Budi – Dani – Raka – Anton', NULL, 'Fikri – Raka – Budi – Anton – Dani', NULL, 'Fikri – Dani – Raka – Budi – Anton', NULL, 'Raka – Budi – Fikri – Dani – Anton', NULL, 'C', 'Fikri disebut sebagai juara, artinya ia finis pertama. Raka finis setelah Fikri, sehingga Raka berada di urutan kedua. Budi menyelesaikan lomba di antara Anton dan Raka. Jadi, Budi berada di posisi ketiga atau keempat. Anton finis sebelum Dani, sehingga Anton di depan Dani. Dani finis setelah Anton, menjadikan Dani di urutan terakhir. Jadi, urutan yang benar adalah: 1. Fikri, 2. Raka, 3. Budi, 4. Anton, 5. Dani.', NULL, 'Untuk soal logika, susun urutan berdasarkan informasi yang diberikan.', '2026-05-09 19:50:33', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 6);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (6130, 2, NULL, 25, NULL, NULL, NULL, 'Nilai adalah … (akar 3 dari 2 + akar 3 dari 4)', NULL, 2, NULL, 3, NULL, 4, NULL, 5, NULL, 6, NULL, 'A', 'Ingat bahwa jika ada bentuk akar pada penyebut, maka penyelesaiannya menggunakan konsep perkalian dengan sekawan. (akar 3 dari 2 + akar 3 dari 4) x (akar 3 dari 4 - akar 3 dari 2 + akar 3 dari 4) / (akar 3 dari 4 - akar 3 dari 2 + akar 3 dari 4) = (4 - 2 + 2 akar 3 dari 8) / 2 = (2 + 2 akar 3 dari 8) / 2 = 1 + akar 3 dari 8. Namun ini bukan jawaban yang benar. Perhitungan yang benar adalah: akar 3 dari 2 + akar 3 dari 4 = akar 3 dari 2 (1 + akar 3 dari 2). Nilai dari 1 + akar 3 dari 2 adalah 2. Jadi hasilnya adalah 2 akar 3 dari 2.', NULL, 'Untuk soal hitung, gunakan konsep perkalian sekawan.', '2026-05-09 19:50:33', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 54);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (6131, 2, NULL, 25, NULL, NULL, NULL, 'A, Z, C, X, E, V, …, …', NULL, 'F, T', NULL, 'F, U', NULL, 'G, S', NULL, 'G, T', NULL, 'G, U', NULL, 'D', 'Perhatikan pola berikut! A (huruf ke-1), Z (huruf ke-26), C (huruf ke-3), X (huruf ke-24), E (huruf ke-5), V (huruf ke-22). Pola yang terjadi adalah huruf ganjil naik 2 (A, C, E, G) dan huruf genap turun 2 (Z, X, V, T). Dengan demikian, dua huruf berikutnya adalah G dan T.', NULL, 'Untuk soal deret huruf, cari pola kenaikan/penurunan posisi huruf.', '2026-05-09 19:50:33', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 4);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (6132, 2, NULL, 25, NULL, NULL, NULL, 'Jika 5 < x < 7 dan 6 < y < 8 dengan x dan y merupakan bilangan real, maka hubungan antara x dan y yang paling tepat adalah ….', NULL, 'x > y', NULL, 'x = y', NULL, 'x < y', NULL, 'x + 1 = y', NULL, 'hubungan antara x dan y tidak dapat ditentukan', NULL, 'E', 'Perhatikan bahwa karena 5 < x < 7 dan 6 < y < 8 dengan x dan y merupakan bilangan real, maka ada beberapa kemungkinan: Jika x = 6 dan y = 7, maka x < y. Jika x = 6.5 dan y = 6.5, maka x = y. Jika x = 6.5 dan y = 6.1, maka x > y. Jika x = 5.5 dan y = 6.5, maka x + 1 = y. Karena ada beberapa kemungkinan tersebut, maka hubungan antara x dan y tidak dapat ditentukan.', NULL, 'Untuk soal ketidaksamaan, periksa apakah hubungan dapat ditentukan.', '2026-05-09 19:50:33', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 51);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (6133, 2, NULL, 25, NULL, NULL, NULL, 'Sebuah tim konstruksi sedang membangun dinding pagar sepanjang 500 meter. Jika pekerjaan tersebut dilakukan oleh 5 pekerja, mereka dapat menyelesaikannya dalam waktu 12 jam tanpa istirahat. Agar pekerjaan tersebut dapat selesai dalam waktu 7 jam, dengan 1 jam waktu istirahat di tengah, maka jumlah pekerja yang dibutuhkan adalah …', NULL, '6 pekerja', NULL, '8 pekerja', NULL, '10 pekerja', NULL, '12 pekerja', NULL, '15 pekerja', NULL, 'C', 'Soal tersebut menggunakan prinsip perbandingan terbalik. Makin banyak orang yang mengerjakan pekerjaan tersebut, maka makin sedikit waktu yang dibutuhkan. Diketahui 5 orang dapat menyelesaikan pekerjaan tersebut dalam waktu 12 jam tanpa istirahat. Pada soal diketahui waktu yang diinginkan untuk menyelesaikan pekerjaan tersebut adalah 7 jam dengan termasuk di dalamnya waktu 1 jam untuk istirahat. Artinya, waktu untuk bekerja hanya 7 jam dikurangi 1 jam waktu istirahat, yaitu 6 jam. Berdasarkan hasil perhitungan, diperoleh bahwa pekerjaan tersebut dapat selesai dalam waktu 6 jam jika dikerjakan oleh 10 orang.', NULL, 'Untuk soal perbandingan terbalik, gunakan rumus pekerja x waktu = konstan.', '2026-05-09 19:50:33', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 96);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (6134, 2, NULL, 25, NULL, NULL, NULL, 'Perhatikan gambar berikut! (soal figural dengan pola garis) Gambar yang tepat untuk melengkapi pola di atas adalah …', NULL, 'Gambar dengan 2 garis', NULL, 'Gambar dengan 3 garis', NULL, 'Gambar dengan 4 garis', NULL, 'Gambar dengan 5 garis', NULL, 'Gambar dengan 6 garis', NULL, 'D', 'Perhatikan gambar berikut! Gambar \"?\" dapat diperoleh dengan menjumlahkan jumlah garis pada 2 gambar dalam satu kolom yang sama dengannya, yaitu 2 + 2. Sehingga, gambar yang tepat akan memiliki 4 buah garis atau sisi.', NULL, 'Untuk soal figural, cari pola penjumlahan elemen visual.', '2026-05-09 19:50:33', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 73);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (6135, 2, NULL, 25, NULL, NULL, NULL, 'Gambar berikut yang memiliki pola berbeda dengan yang lainnya adalah … (soal figural dengan pola berbeda)', NULL, 'Gambar A', NULL, 'Gambar B', NULL, 'Gambar C', NULL, 'Gambar D', NULL, 'Gambar E', NULL, 'B', 'Perhatikan pola pada setiap gambar. Gambar yang memiliki pola berbeda adalah gambar B karena memiliki karakteristik yang berbeda dari gambar-gambar lainnya.', NULL, 'Untuk soal figural, cari pola yang berbeda dari yang lain.', '2026-05-09 19:50:33', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 73);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (6136, 3, NULL, 49, NULL, NULL, NULL, 'Anda adalah seorang kepala seksi di sebuah dinas pelayanan publik yang baru saja diberi tanggung jawab untuk menangani keluhan masyarakat mengenai lambatnya proses perizinan usaha. Setelah mengadakan diskusi dengan pegawai, Anda mendapat bahwa sebagian besar dari mereka merasa kurang termotivasi akibat minimnya sumber daya yang tersedia serta kurangnya apresiasi dari pimpinan atas kinerja mereka. Langkah pertama apa yang sebaiknya Anda ambil untuk mulai mengatasi situasi ini?', NULL, 'Mengajukan permintaan ke pimpinan untuk menambah sumber daya dan menyusun kebijakan yang meningkatkan apresiasi bagi pegawai yang bekerja keras', NULL, 'Mengadakan pertemuan dengan pegawai untuk mendiskusikan masalah mereka dan mencari solusi yang dapat diterapkan segera', NULL, 'Mengidentifikasi kebutuhan tambahan sumber daya dan menyarankan kepada pimpinan agar dilakukan peningkatan fasilitas pelayanan', NULL, 'Melakukan evaluasi kinerja pegawai secara menyeluruh untuk memahami akar permasalahan, lalu merumuskan langkah perubahan sistem', NULL, 'Mendorong pimpinan untuk memberikan insentif kepada pegawai dan memperbaiki sistem kerja agar kinerja lebih efektif dan terorganisir', NULL, 'E', 'Pilihan jawaban E adalah poin dengan skor tertinggi (5) karena melakukan langkah strategis yang menyeluruh, yaitu mendorong pimpinan untuk memberikan insentif kepada pegawai sekaligus memperbaiki sistem kerja. Langkah ini tidak hanya meningkatkan motivasi pegawai, tetapi juga memperbaiki efektivitas layanan secara keseluruhan.', NULL, 'Pilih jawaban yang menunjukkan solusi menyeluruh dan strategis.', '2026-05-09 19:50:33', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 119);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (6137, 3, NULL, 49, NULL, NULL, NULL, 'Di sebuah puskesmas, masyarakat diberikan kesempatan untuk mengikuti pemeriksaan kesehatan gratis. Namun, sejumlah warga datang mendekati akhir waktu pemeriksaan, dan terlihat bahwa petugas yang bertugas menunjukkan ekspresi kurang bersahabat. Dalam situasi ini, apa langkah terbaik yang seharusnya diambil oleh petugas untuk meningkatkan interaksi dan pelayanan kepada masyarakat?', NULL, 'Menghentikan seluruh proses pemeriksaan dan menjelaskan kepada masyarakat bahwa mereka harus mengikuti jadwal yang sudah ditentukan agar semua orang memahami pentingnya disiplin', NULL, 'Menyampaikan secara langsung kepada masyarakat yang terlambat tentang kebijakan waktu pemeriksaan sambil meminta mereka untuk bersabar dan menunggu', NULL, 'Meminta maaf atas ketidaknyamanan yang terjadi dan berusaha untuk menyelesaikan pemeriksaan bagi mereka yang telah hadir', NULL, 'Menyarankan kepada masyarakat untuk mengikuti pemeriksaan pada waktu yang akan datang sambil menekankan pentingnya mematuhi jadwal untuk kelancaran pelayanan', NULL, 'Menyampaikan bahwa pemeriksaan akan dilanjutkan, namun prosedur yang ada harus mematuhi protokol tertentu dan tidak bisa diubah sehingga mereka harus mengerti bahwa ada batasan dalam layanan ini', NULL, 'C', 'Pilihan jawaban yang mendapatkan skor tertinggi adalah opsi C karena mencerminkan empati dan responsivitas terhadap masyarakat dengan meminta maaf atas ketidaknyamanan yang terjadi, serta menyatakan kesediaan untuk menyelesaikan pemeriksaan meskipun terlambat.', NULL, 'Pilih jawaban yang menunjukkan empati dan responsivitas.', '2026-05-09 19:50:33', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 147);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (6138, 3, NULL, 49, NULL, NULL, NULL, 'Diana baru diangkat sebagai manajer setelah perusahaan mengalami restrukturisasi besar-besaran. Proses ini mengakibatkan beberapa karyawan kehilangan posisi mereka, sementara yang lain merasa khawatir tentang perubahan tanggung jawab. Kini, tim Diana merasa cemas dan kurang termotivasi, sehingga dia ingin membangun kembali kepercayaan dan semangat kerja mereka. Langkah pertama yang seharusnya diambil oleh Diana adalah …', NULL, 'Mengadakan pertemuan untuk menjelaskan manfaat restrukturisasi dan memberikan kesempatan bagi tim untuk mengajukan pertanyaan terkait perubahan tersebut.', NULL, 'Menyusun agenda pertemuan yang berfokus pada penjelasan manfaat restrukturisasi dan menyediakan waktu untuk masukan dari anggota tim.', NULL, 'Memperkenalkan program dukungan untuk membantu karyawan beradaptasi dengan perubahan sambil memberikan ruang bagi mereka untuk berbagi pengalaman.', NULL, 'Mendorong tim terlibat dalam proyek baru yang dapat meningkatkan semangat kerja sambil secara bertahap membahas perubahan yang sedang berlangsung.', NULL, 'Menyampaikan rencana perubahan yang telah disusun dan menjadwalkan sesi lanjutan untuk mendiskusikan pertanyaan serta saran dari tim.', NULL, 'A', 'Opsi A memiliki skor tertinggi karena mencerminkan prinsip penting dalam jejaring kerja, yaitu komunikasi terbuka dan partisipatif. Dengan mengadakan pertemuan untuk menjelaskan manfaat restrukturisasi dan memberikan kesempatan kepada tim untuk mengajukan pertanyaan, Diana menunjukkan bahwa dia menghargai suara dan kontribusi setiap individu.', NULL, 'Pilih jawaban yang menunjukkan komunikasi terbuka dan partisipatif.', '2026-05-09 19:50:33', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 115);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (6139, 3, NULL, 49, NULL, NULL, NULL, 'Anda mengetahui bahwa seorang rekan kerja Anda sering mengikuti diskusi politik di luar kantor. Diskusi itu cukup terkenal dan kontroversial sebab diikuti orang-orang yang tidak pro terhadap idealisme Pancasila yang berlaku di Indonesia saat ini. Mereka yang terlibat di dalamnya pun berencana untuk menyebarluaskan paham mereka kepada orang-orang lain. Namun, selama mengikuti diskusi ini, rekan kerja Anda tidak pernah mengajak atau membujuk Anda untuk mengikutinya. Apakah tindakan yang Anda akan lakukan terhadap teman Anda tersebut?', NULL, 'Mengikuti rekan kerja Anda itu untuk melihat dan memahami hal yang dibahas dalam diskusi tersebut', NULL, 'Mengabaikan hal yang dilakukan teman Anda selama tidak berpengaruh ke kinerja dan hubungan pribadi Anda', NULL, 'Mengajak teman Anda untuk berdiskusi tentang alasannya mengikuti diskusi tersebut dan mencoba menghentikannya', NULL, 'Mengingatkan teman Anda agar tidak mengikuti diskusi itu lagi dan melaporkannya pada aparat jika diskusi itu sudah mengarah ke tindakan radikal', NULL, 'Memberikan peringatan pada teman Anda, tetapi jika ia memilih untuk melanjutkan kegiatannya, Anda akan membiarkannya demi menghormati keputusannya', NULL, 'D', 'Skor tertinggi ada pada pilihan D sebab tindakan ini menunjukkan sikap yang tegas dalam menghadapi potensi radikalisme yang ada di sekitar Anda. Anda berupaya mengajak teman Anda untuk menjauhi diskusi yang berbau radikal tersebut dan memutuskan untuk melaporkan hal ini pada pihak yang berwajib jika diskusi ini sudah mengarah ke perbuatan radikal.', NULL, 'Pilih jawaban yang menunjukkan sikap tegas terhadap radikalisme.', '2026-05-09 19:50:33', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 119);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (6140, 3, NULL, 49, NULL, NULL, NULL, 'Anda mendapatkan sebuah berita hoaks tentang kebijakan baru mengenai instansi yang Anda pimpin. Informasi hoaks ini beredar luas di media sosial dan membuat kebingungan bawahan Anda. Mengingat situasi tersebut, apa langkah yang akan Anda ambil?', NULL, 'Membantah berita hoaks tersebut secara individual kepada rekan-rekan kerja Anda tanpa melakukan klarifikasi resmi.', NULL, 'Melaporkan berita hoaks tersebut kepada pimpinan tertinggi dan menunggu instruksi selanjutnya.', NULL, 'Setelah melakukan klarifikasi resmi, Anda berinisiatif untuk membuat sistem atau prosedur tetap lainnya yang dapat mempercepat proses klarifikasi berita di masa mendatang dan menyampaikan strategi ini ke pimpinan lembaga.', NULL, 'Anda mengumpulkan informasi valid untuk membantu berita hoaks tersebut dan meneruskannya kepada seluruh anggota instansi.', NULL, 'Segera melakukan klarifikasi resmi melalui saluran komunikasi internal dan menekankan kepada bawahan mengenai pentingnya digital literacy dan cara mendeteksi hoaks.', NULL, 'C', 'Pilihan ini adalah pendekatan yang paling proaktif dan berdampak. Tidak hanya berurusan dengan berita hoaks saat ini, strategi ini juga mencoba mencegah atau setidaknya mempercepat penanganan hoaks di masa mendatang. Dengan sistem ini, instansi Anda akan lebih siap untuk menangani hoaks dan misinformasi.', NULL, 'Pilih jawaban yang menunjukkan pendekatan proaktif dan berdampak.', '2026-05-09 19:50:33', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 115);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (6141, 3, NULL, 49, NULL, NULL, NULL, 'Anda adalah seorang android developer dan bekerja sebagai ASN di departemen teknologi informasi suatu instansi pemerintah. Aplikasi instansi yang baru dirilis mendapatkan banyak feedback negatif dan rating rendah di Google Play Store. Mengingat situasi di atas, apa langkah terbaik yang akan Anda lakukan?', NULL, 'Menganalisis feedback, membuat rencana perbaikan, dan mengusulkannya pada atasan.', NULL, 'Menganggap feedback tersebut tidak signifikan dan melanjutkan pekerjaan rutin Anda.', NULL, 'Melaporkan feedback kepada atasan dan memberikan usulan perbaikan dasar.', NULL, 'Menganalisis feedback, berkoordinasi dengan tim untuk membuat rencana tindakan, dan meningkatkan aplikasi.', NULL, 'Mengumpulkan dan merangkum feedback untuk diulas dalam pertemuan tim selanjutnya.', NULL, 'D', 'Opsi ini adalah pendekatan yang paling efektif. Menganalisis feedback, berkoordinasi dengan tim, dan melakukan tindakan konkret adalah pendekatan yang sangat baik dalam menyelesaikan masalah dan meningkatkan aplikasi.', NULL, 'Pilih jawaban yang menunjukkan pendekatan paling efektif.', '2026-05-09 19:50:33', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 119);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (6142, 3, NULL, 49, NULL, NULL, NULL, 'Anda adalah seorang pegawai di sebuah dinas yang sedang menangani beberapa proyek penting. Dalam satu hari, Anda dihadapkan pada empat tugas mendesak: (1) mengirim laporan penting ke atasan; (2) mengikuti rapat mendadak dengan klien utama; (3) menyiapkan presentasi untuk acara besar; dan (4) menanggapi keluhan dari masyarakat. Semua tugas memiliki tenggat waktu yang sama. Apa yang sebaiknya Anda lakukan terlebih dahulu?', NULL, 'Mengirim laporan ke atasan karena atasan adalah prioritas utama dalam organisasi', NULL, 'Mengikuti rapat mendadak dengan klien utama karena hasil rapat ini berpengaruh langsung pada kelangsungan proyek besar', NULL, 'Menyiapkan presentasi untuk acara besar karena acara tersebut dihadiri oleh banyak pejabat penting', NULL, 'Menanggapi keluhan masyarakat karena sebagai pegawai negeri, Anda harus fokus pada pelayanan publik', NULL, 'Menghubungi atasan untuk meminta panduan terkait tugas mana yang harus diprioritaskan', NULL, 'B', 'Prioritas diberikan kepada rapat mendadak dengan klien utama (Pilihan B) karena hasil rapat tersebut dapat berpengaruh langsung pada kelangsungan proyek besar yang sedang berjalan. Hubungan dengan klien utama adalah salah satu faktor krusial dalam proyek besar dan jika tidak ditangani dengan cepat dapat menimbulkan risiko terhadap kelangsungan proyek itu sendiri.', NULL, 'Pilih jawaban yang menunjukkan prioritas berdasarkan urgensi dan dampak.', '2026-05-09 19:50:33', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 119);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (6143, 3, NULL, 49, NULL, NULL, NULL, 'Anda bertugas di daerah dengan beragam latar belakang etnis dan agama. Terdapat konflik antara dua kelompok masyarakat yang melaksanakan perayaan budaya yang berbeda pada waktu yang sama. Anda sebagai ASN diharapkan untuk memfasilitasi dialog antara kedua kelompok. Apa yang akan Anda lakukan?', NULL, 'Mengabaikan konflik tersebut karena merasa bukan urusan Anda.', NULL, 'Mencoba mendamaikan dengan mendengarkan keluhan masing-masing.', NULL, 'Mengusulkan salah satu kelompok untuk mengubah tanggal perayaan agar tidak bentrok.', NULL, 'Memanggil pihak atasan untuk menangani masalah ini agar tidak membebani Anda.', NULL, 'Menyusun rencana acara yang melibatkan kedua kelompok untuk merayakan bersama.', NULL, 'B', 'Sikap ini menunjukkan keterampilan komunikasi dan mediasi yang baik. Mendengarkan dengan empati adalah langkah awal untuk menyelesaikan konflik dan membangun kepercayaan antara kelompok.', NULL, 'Pilih jawaban yang menunjukkan keterampilan komunikasi dan mediasi yang baik.', '2026-05-09 19:50:33', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 122);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (6144, 1, NULL, 26, NULL, NULL, NULL, 'Pancasila berisi seperangkat nilai yang merupakan satu kesatuan yang utuh dan bulat. Nilai-nilai yang terkandung dalam Pancasila, kecuali...', NULL, 'Ketuhanan', NULL, 'Persatuan', NULL, 'Sosial', NULL, 'Kerakyatan', NULL, 'Kemanusiaan', NULL, 'C', 'Nilai-nilai yang terkandung dalam Pancasila adalah Ketuhanan, Persatuan, Kerakyatan, Kemanusiaan, dan Keadilan Sosial. Sosial bukanlah nilai yang terkandung dalam Pancasila.', NULL, 'Pahami nilai-nilai yang terkandung dalam Pancasila.', '2026-05-09 19:50:33', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 4);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (6145, 1, NULL, 25, NULL, NULL, NULL, 'Kedudukan Pancasila sebagai ideologi bangsa tercantum dalam ketetapan MPR nomor...', NULL, 'Ketetapan MPR No.XIV/MPR/1998', NULL, 'Ketetapan MPR No.XV/MPR/1998', NULL, 'Ketetapan MPR No.XVI/MPR/1998', NULL, 'Ketetapan MPR No.XVII/MPR/1998', NULL, 'Ketetapan MPR No.XVIII/MPR/1998', NULL, 'E', 'Kedudukan Pancasila sebagai ideologi bangsa tercantum dalam ketetapan MPR No.XVIII/MPR/1998.', NULL, 'Hafalkan nomor ketetapan MPR terkait Pancasila.', '2026-05-09 19:50:33', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 4);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (6146, 1, NULL, 13, NULL, NULL, NULL, 'Di bawah ini adalah sumber hukum formil dari dari hukum tata negara Indonesia, kecuali...', NULL, 'Pancasila', NULL, 'Perundang-undangan', NULL, 'Yurisprudensi', NULL, 'Kebiasaan', NULL, 'Doktrin', NULL, 'D', 'Sumber hukum formil dari hukum tata negara Indonesia adalah Pancasila, Perundang-undangan, Yurisprudensi, dan Doktrin. Kebiasaan bukan sumber hukum formil.', NULL, 'Pahami sumber hukum formil Indonesia.', '2026-05-09 19:50:33', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 2);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (6147, 1, NULL, 17, NULL, NULL, NULL, 'Presiden dalam rangka menjalankan undang-undang mempunyai kewenangan untuk menetapkan Peraturan Pemerintah. Peraturan Pemerintah adalah peraturan untuk menjalankan undang-undang dengan sebagaimana mestinya. Kewenangan menetapkan Peraturan Pemerintah adalah sebagian kewenangan pengaturan dari Presiden. Peraturan Pemerintah berfungsi untuk menjalankan undang-undang maka Peraturan Pemerintah harus dibentuk setelah ada undang-undang yang mengatur materi tersebut. Kekuasaan Presiden ini disebut...', NULL, 'Eksekutive power', NULL, 'Power and responsibility', NULL, 'Pouvoir réglementaire', NULL, 'Noodverordening Recht', NULL, 'Legislative power', NULL, 'C', 'Kekuasaan Presiden untuk menetapkan Peraturan Pemerintah disebut Pouvoir réglementaire.', NULL, 'Pahami istilah hukum tata negara.', '2026-05-09 19:50:33', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 3);
