INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (6151, 1, NULL, 1, NULL, NULL, NULL, 'Di antara kalimat-kalimat berikut, manakah yang merupakan kalimat yang baku?', NULL, 'Mereka jebak pencuri itu hingga akhirnya tertangkap.', NULL, 'Siti sudah lama menunggu adikmu di tempat ini.', NULL, 'Ia teriak-teriak hingga suaranya serak.', NULL, 'Ia berjalan cepat agar tidak terlambat masuk sekolah.', NULL, 'Dua anak lelaki itu berantem di pinggir kali.', NULL, 'D', 'Kalimat baku adalah \"Ia berjalan cepat agar tidak terlambat masuk sekolah.\" Kalimat lain menggunakan kata tidak baku.', NULL, 'Pilih kalimat yang menggunakan kata baku.', '2026-05-09 19:50:33', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 39);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (6152, 1, NULL, 50, NULL, NULL, NULL, 'Bhinneka Tunggal Ika adalah moto atau semboyan bangsa Indonesia yang tertulis pada lambang negara Indonesia, Garuda Pancasila. Frasa ini berasal dari bahasa Jawa Kuno yang artinya adalah \"Berbeda-beda tetapi tetap satu\". Diterjemahkan per kata, kata bhinneka berarti \"beraneka ragam\". Kata neka dalam bahasa Sanskerta berarti \"macam\" dan menjadi pembentuk kata \"aneka\" dalam Bahasa Indonesia. Kata tunggal berarti \"satu\". Kata ika berarti \"itu\". Secara harfiah Bhinneka Tunggal Ika diterjemahkan \"Beraneka Satu Itu\", yang bermakna meskipun beraneka ragam tetapi pada hakikatnya bangsa Indonesia tetap adalah satu kesatuan. Semboyan ini digunakan untuk menggambarkan persatuan dan kesatuan Bangsa dan Negara Kesatuan Republik Indonesia yang terdiri atas beraneka ragam budaya, bahasa daerah, ras, suku bangsa, agama dan kepercayaan. Pengamalan Bhinneka Tunggal Ika harus kita terapkan dalam ...', NULL, 'Kehidupan bermasyarakat dan bernegara', NULL, 'Kehidupan antar masyarakat sesama suku', NULL, 'Kehidupan dengan rekan sejawat', NULL, 'Hubungan antar rekan kerja', NULL, 'Hubungan dengan negara lain', NULL, 'A', 'Pengamalan Bhinneka Tunggal Ika harus kita terapkan dalam kehidupan bermasyarakat dan bernegara.', NULL, 'Pahami makna Bhinneka Tunggal Ika.', '2026-05-09 19:50:33', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 7);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (6153, 1, NULL, 1, NULL, NULL, NULL, 'Kekerasan dalam rumah tangga (disingkat KDRT) adalah tindakan yang dilakukan di dalam rumah tangga baik oleh suami, istri, maupun anak yang berdampak buruk terhadap keutuhan fisik, psikis, dan keharmonisan hubungan sesuai yang termaktub dalam pasal 1 UU Nomor 23 tahun 2004 tentang Penghapusan Kekerasan dalam Rumah Tangga (UU PKDRT). Kekerasan dalam rumah tangga adalah penyimpangan sila ke...', NULL, 1, NULL, 2, NULL, 3, NULL, 4, NULL, 5, NULL, 'B', 'Kekerasan dalam rumah tangga adalah penyimpangan sila ke-2 (Kemanusiaan yang Adil dan Beradab).', NULL, 'Pahami sila Pancasila yang terkait dengan KDRT.', '2026-05-09 19:50:33', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 26);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (6154, 1, NULL, 1, NULL, NULL, NULL, 'Integrasi nasional seharusnya dimulai dari pejabat negara sehingga bisa memberikan contoh bagi warga negara. Salah satu tindakan pejabat negara yang tidak mendukung integritas negara adalah praktik korupsi. Komisi Pemberantasan Korupsi (KPK) merupakan lembaga negara yang dibentuk untuk menyelidiki kasus kejahatan luar biasa korupsi, kolusi, dan nepotisme(KKN). Berbagai kasus korupsi mencuat ke permukaan. KPK berhasil mengungkap dan menangkap pelakunya. Akan tetapi, kasus korupsi masih marak terjadi. Upaya paling tepat yang dapat dilakukan masyarakat untuk menghentikan praktik kejahatan luar biasa tersebut adalah ....', NULL, 'Menjatuhkan sanksi berat terhadap terdakwa kasus korupsi', NULL, 'Menegakkan hukum setegak-tegaknya tanpa pandang bulu', NULL, 'Melakukan sosialisasi terkait tindak pidana korupsi dan dampaknya', NULL, 'Mengembangkan sikap sadar hukum dalam kehidupan mulai dari lingkungan terkecil', NULL, 'Membuat peraturan perundang-undangan tanpa memberi celah untuk berkembangnya praktik korupsi.', NULL, 'B', 'Upaya paling tepat yang dapat dilakukan masyarakat untuk menghentikan praktik korupsi adalah menegakkan hukum setegak-tegaknya tanpa pandang bulu.', NULL, 'Pilih jawaban yang menunjukkan penegakan hukum yang tegas.', '2026-05-09 19:50:33', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 25);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (6155, 1, NULL, 1, NULL, NULL, NULL, 'Krisis moneter pernah terjadi di Indonesia pada tahun 1997. Krisis itu memukul perekonomian dan usaha di Indonesia. Diambil dari buku Monetary Policy Strategy (2007) karya Frederic S Mishkin, krisis moneter adalah krisis yang berhubungan dengan keuangan suatu negara. Krisis Moneter yang dialami Indonesia sejak tahun 1997-1998, ditandai dengan melemahnya nilai tukar rupiah yang sangat drastis. Disebabkan oleh?', NULL, 'Kurs Dollar', NULL, 'Fundamental yang lemah', NULL, 'Faktor internal dan eksternal', NULL, 'Gejolak Politik', NULL, 'Defisit transaksi berjalan Indonesia cenderung membesar dari tahun ke tahun', NULL, 'C', 'Krisis Moneter yang dialami Indonesia sejak tahun 1997-1998 disebabkan oleh faktor internal dan eksternal.', NULL, 'Pahami penyebab krisis moneter Indonesia 1997-1998.', '2026-05-09 19:50:33', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 27);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (6156, 1, NULL, 1, NULL, NULL, NULL, 'Peristiwa Bandung Lautan Api adalah peristiwa kebakaran besar yang terjadi di kota Bandung, provinsi Jawa Barat, Indonesia pada 23 Maret 1946. Dalam waktu tujuh jam, sekitar 200.000 penduduk Bandung membakar rumah mereka, meninggalkan kota menuju pegunungan di daerah selatan Bandung. Hal ini dilakukan untuk mencegah tentara Sekutu dan tentara NICA Belanda untuk dapat menggunakan kota Bandung sebagai markas strategis militer dalam Perang Kemerdekaan Indonesia. Peristiwa yang tidak menjadi Latar belakang terjadinya Bandung Lautan Api adalah.....', NULL, 'Tuntutan pada masyarakat Bandung dari Brigade MacDonald untuk menyerahkan semua senjata dari hasil melucuti senjata tentara Jepang pada pihak sekutu.', NULL, 'Ultimatum dari sekutu dengan perintah untuk mengosongkan kota Bandung Utara selambat lambatnya tanggal 29 November 1945.', NULL, 'Tentara sekutu membagi kota Bandung menjadi dua yakni utara dan selatan', NULL, 'Rencana untuk membangun ulang markas sekutu di kota Bandung.', NULL, 'Terjadinya kesenjangan Ekonomi pada Warga Bandung pada masa itu', NULL, 'E', 'Peristiwa yang tidak menjadi latar belakang terjadinya Bandung Lautan Api adalah terjadinya kesenjangan Ekonomi pada Warga Bandung pada masa itu.', NULL, 'Pahami latar belakang peristiwa Bandung Lautan Api.', '2026-05-09 19:50:33', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 27);
