INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (6180, 2, NULL, 25, NULL, NULL, NULL, 'Rumah Durga berjarak 1,5 km dari sekolahnya. Jika kecepatan ia berjalan rata-rata 4,5 km/jam. Berapa jam yang diperlukan untuk berjalan pulang-pergi selama 6 hari?', NULL, '4 jam', NULL, '24 jam', NULL, '6 jam', NULL, '1/3 jam', NULL, '4,5 jam', NULL, 'A', 'Jarak pulang-pergi = 1,5 km x 2 = 3 km. Waktu per hari = 3 km / 4,5 km/jam = 2/3 jam. Waktu 6 hari = 2/3 jam x 6 = 4 jam.', NULL, 'Untuk soal cerita, hitung jarak total dan waktu per hari.', '2026-05-09 19:50:34', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 93);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (6181, 2, NULL, 25, NULL, NULL, NULL, 'Sebuah mobil bergerak dengan kecepatan 160 km/jam. Berapakah jauh perpindahan mobil dalam 15 menit?', NULL, '30 km', NULL, '22 km', NULL, '40 km', NULL, '21 km', NULL, '55 km', NULL, 'C', '15 menit = 0,25 jam. Jarak = 160 km/jam x 0,25 jam = 40 km.', NULL, 'Untuk soal kecepatan, konversi waktu ke jam dulu.', '2026-05-09 19:50:34', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 93);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (6182, 2, NULL, 25, NULL, NULL, NULL, 'Seorang penjual mengantar pesanan sebanyak 9 mangkuk sayur ke sebuah toko. Si penjual hanya bisa membawa 2 mangkuk setiap kali pengiriman. Berapa kali si penjual harus mengantarkan seluruh pesanannya?', NULL, '3 kali', NULL, '4 kali', NULL, '5 kali', NULL, '6 kali', NULL, '7 kali', NULL, 'C', '9 mangkuk / 2 mangkuk per kali = 4,5 kali. Karena tidak bisa setengah kali, maka dibulatkan menjadi 5 kali.', NULL, 'Untuk soal pembagian, perhatikan pembulatan ke atas.', '2026-05-09 19:50:34', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 88);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (6185, 2, NULL, 25, NULL, NULL, NULL, 'Lingkaran dari kalimat \"Sekarang hujan atau tidak hujan\" adalah ...', NULL, 'Besok hujan atau tidak hujan', NULL, 'Besok hujan deras', NULL, 'Sekarang cerah', NULL, 'Besok dan sekarang tidak hujan', NULL, 'Sekarang hujan dan tidak hujan', NULL, 'E', 'Lingkaran dari kalimat \"Sekarang hujan atau tidak hujan\" adalah \"Sekarang hujan dan tidak hujan\" yang berarti kontradiksi.', NULL, 'Untuk soal logika, cari kontradiksi dari premis.', '2026-05-09 19:50:34', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 57);
