INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (6192, 2, NULL, 25, NULL, NULL, NULL, 'Semua ban terbuat dari karet. Semua karet bersifat elastis. Sebagian karet berwarna hitam.', NULL, 'Semua ban elastis dan berwarna hitam.', NULL, 'Semua ban berwarna hitam.', NULL, 'Semua ban elastis berwarna hitam.', NULL, 'Sebagian ban berwarna hitam terbuat dari karet.', NULL, 'Semua ban elastis dan terbuat dari karet.', NULL, 'E', 'Dari premis: Semua ban terbuat dari karet dan Semua karet bersifat elastis, dapat disimpulkan Semua ban elastis dan terbuat dari karet.', NULL, 'Untuk soal logika silogisme, ikuti premis yang diberikan.', '2026-05-09 19:50:34', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 81);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (6193, 2, NULL, 25, NULL, NULL, NULL, 'Invers dari pernyataan: \"Jika harga minyak naik maka harga nasi padang naik\" adalah ...', NULL, 'Jika harga minyak tidak naik maka harga nasi padang naik.', NULL, 'Jika harga nasi padang naik maka harga minyak naik', NULL, 'Jika harga minyak tidak naik maka harga nasi padang tidak naik.', NULL, 'Jika harga nasi padang tidak naik maka harga minyak tidak naik.', NULL, 'Jika harga nasi padang tidak naik maka harga minyak tidak naik.', NULL, 'C', 'Invers dari \"Jika P maka Q\" adalah \"Jika tidak P maka tidak Q\". Jadi invers dari \"Jika harga minyak naik maka harga nasi padang naik\" adalah \"Jika harga minyak tidak naik maka harga nasi padang tidak naik\".', NULL, 'Untuk soal logika, ingat invers dari \"Jika P maka Q\" adalah \"Jika tidak P maka tidak Q\".', '2026-05-09 19:50:34', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 51);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (6194, 2, NULL, 25, NULL, NULL, NULL, 'Hubungan nilai a dan b yang tepat adalah: 2a + 5 - 2b = 3 3b - 12 = 12', NULL, 'a + b = 1', NULL, '2a = b', NULL, 'a > b', NULL, 'a = b - 1', NULL, 'a = b', NULL, 'D', 'Dari 3b - 12 = 12, maka 3b = 24, b = 8. Substitusi ke 2a + 5 - 2(8) = 3, maka 2a + 5 - 16 = 3, 2a - 11 = 3, 2a = 14, a = 7. Jadi a = b - 1 (7 = 8 - 1).', NULL, 'Untuk soal persamaan, selesaikan satu persamaan dulu lalu substitusi ke persamaan lain.', '2026-05-09 19:50:34', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 54);
