INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (6208, 3, NULL, 49, NULL, NULL, NULL, 'Dalam setiap pekerjaan pasti memiliki job description masing-masing, dan saya telah melakukan sesuai dengan job description tersebut.', NULL, 'Ditengah-tengah kesibukan pekerjaan, saya tetap mau membantu teman menyelesaikan pekerjaannya yang tertunda', NULL, 'Saya akan membantu kawan saya yang lain jika diminta.', NULL, 'Saya mau mempelajari hal lain di luar deskripsi jabatan saya.', NULL, 'Saya hanya akan melakukan pekerjaan di luar deskripsi jabatan jika diminta oleh atasan.', NULL, 'Enggan berkontribusi lebih dari apa yang telah dikerjakan saat ini.', NULL, 'A', 'Pilihan jawaban A adalah yang paling tepat karena menunjukkan kerjasama dan inisiatif.', NULL, 'Pilih jawaban yang menunjukkan kerjasama dan inisiatif.', '2026-05-09 19:50:34', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 109);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (6209, 3, NULL, 49, NULL, NULL, NULL, 'Kenan adalah seorang karyawan yang rajin. Namun apa yang akan terjadi pada masa mendatang tak ada yang tahu.', NULL, 'Kenan tetap saja akan terkena PHK jika ekonomi nasional lesu', NULL, 'Mustahil karyawan serajin Kenan kena PHK', NULL, 'Karakter Kenan sebagai karyawan rajin dapat membantu kenaikan karirnya kelak', NULL, 'Pemecatan banyak karyawan tidaklah terlalu berpengaruh terhadap citra perusahaan', NULL, 'Harusnya karyawan rajin tak boleh kena PHK', NULL, 'C', 'Pilihan jawaban C adalah yang paling tepat karena karakter rajin dapat membantu kenaikan karir.', NULL, 'Pilih jawaban yang logis dan positif.', '2026-05-09 19:50:34', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 119);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (6210, 3, NULL, 49, NULL, NULL, NULL, 'Setelah mematangkan rencana, . . .', NULL, 'Saya masih khawatir apakah rencana tersebut bisa berhasil', NULL, 'Berhasil tidaknya tak lepas dari pihak lain juga', NULL, 'Manusia berusaha sebaik-baiknya dan Tuhan yang menentukan', NULL, 'Bagaimanapun caranya rencana harus berhasil', NULL, 'Saya minta pendapat orang lain terlebih dulu, sebab pendapat banyak orang lebih baik daripada pendapat satu orang', NULL, 'C', 'Pilihan jawaban C adalah yang paling tepat karena menunjukkan sikap tawakal dan berusaha semaksimal mungkin.', NULL, 'Pilih jawaban yang menunjukkan sikap tawakal dan berusaha.', '2026-05-09 19:50:34', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 7);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (6211, 3, NULL, 49, NULL, NULL, NULL, 'Jika suatu rencana kerja terlihat rumit, maka . . .', NULL, 'Saya berani mencoba setelah mempertimbangkan risikonya', NULL, 'Saya khawatir jika mencobanya dan gagal', NULL, 'Yang penting saya coba dulu', NULL, 'Saya minta pendapat istri. Yang penting saya coba dulu', NULL, 'Saya tak mau repot-repot mencobanya', NULL, 'A', 'Pilihan jawaban A adalah yang paling tepat karena menunjukkan keberanian dan pertimbangan risiko.', NULL, 'Pilih jawaban yang menunjukkan keberanian dan pertimbangan risiko.', '2026-05-09 19:50:34', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 104);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (6214, 3, NULL, 49, NULL, NULL, NULL, 'Kerja keras dan cermat merupakan wujud upaya untuk menjadi pribadi yang bermanfaat. Berkaitan dengan hal itu saya senang . . .', NULL, 'Pekerjaan yang menantang.', NULL, 'Pekerjaan yang rutin.', NULL, 'Pekerjaan yang menumbuhkan kreativitas baru.', NULL, 'Bekerja dengan standar yang tinggi.', NULL, 'Bekerja tanpa mengenal lelah dan pamrih.', NULL, 'C', 'Pilihan jawaban C adalah yang paling tepat karena menunjukkan kreativitas.', NULL, 'Pilih jawaban yang menunjukkan kreativitas.', '2026-05-09 19:50:34', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 104);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (6215, 3, NULL, 49, NULL, NULL, NULL, 'Saya memiliki buku favorit dan buku tersebut dihilangkan oleh teman dekat saya.', NULL, 'Saya marah pada teman saya', NULL, 'Saya memintanya untuk mengganti buku tersebut karena buku itu favorit saya.', NULL, 'Saya sangat menyukai buku tersebut, namun buku itu sudah hilang.', NULL, 'Saya memusuhinya dan melarangnya meminjam buku saya lagi', NULL, 'Saya memintanya untuk mengganti dan mengatakan padanya untuk lebih berhati-hati jika dia meminjam buku saya lagi.', NULL, 'E', 'Pilihan jawaban E adalah yang paling tepat karena menunjukkan sikap tegas namun tetap mempertahankan hubungan.', NULL, 'Pilih jawaban yang menunjukkan sikap tegas namun tetap mempertahankan hubungan.', '2026-05-09 19:50:34', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 101);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (6216, 3, NULL, 49, NULL, NULL, NULL, 'Sudah sejak lama saya berusaha untuk memperbaiki kelemahan diri, tetapi belum juga tampak hasilnya. Pada akhirnya saya:', NULL, 'Dengan terpaksa menerimanya', NULL, 'Menerimanya dengan sedikit kekecewaan', NULL, 'Menerimanya dengan lapang dada', NULL, 'Membenci diri sendiri', NULL, 'Meratapi diri sendiri', NULL, 'C', 'Pilihan jawaban C adalah yang paling tepat karena menunjukkan sikap lapang dada.', NULL, 'Pilih jawaban yang menunjukkan sikap lapang dada.', '2026-05-09 19:50:34', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 101);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (6217, 3, NULL, 49, NULL, NULL, NULL, 'Untuk mencapai tujuan kelompok yang telah ditetapkan, saya:', NULL, 'Tidak mempermasalahkan apakah orang lain mau bekerja dengan baik atau tidak', NULL, 'Mendorong orang lain untuk bekerja dengan baik jika situasi memungkinkan', NULL, 'Mendorong orang lain bekerja dengan baik jika diperlukan', NULL, 'Menstimulasi orang lain untuk mau bekerja dengan baik', NULL, 'Mengajak orang lain bersama-sama untuk bekerja dengan baik', NULL, 'D', 'Pilihan jawaban D adalah yang paling tepat karena menunjukkan kemampuan memimpin dan memotivasi.', NULL, 'Pilih jawaban yang menunjukkan kemampuan memimpin dan memotivasi.', '2026-05-09 19:50:34', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 101);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (6218, 3, NULL, 49, NULL, NULL, NULL, 'Ketika teman kantor sedang membicarakan satu teman yang bermasalah, saya akan:', NULL, 'Membicarakan dengan teman dekat kemungkinan terbaik', NULL, 'Mengajak teman-teman mempertimbangkan suatu tindakan tertentu', NULL, 'Meyakinkan teman-teman akan keperluannya dilakukan suatu tindakan', NULL, 'Mengajukan usulan alternatif tindakan yang tepat', NULL, 'Menyetujui saja apa yang menjadi keputusan', NULL, 'D', 'Pilihan jawaban D adalah yang paling tepat karena menunjukkan kemampuan memberikan solusi.', NULL, 'Pilih jawaban yang menunjukkan kemampuan memberikan solusi.', '2026-05-09 19:50:34', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 107);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (6219, 3, NULL, 49, NULL, NULL, NULL, 'Ketika sedang mengerjakan tugas bersama yang harus selesai pada hari itu, seorang teman akan meninggalkan terlebih dahulu, maka saya:', NULL, 'Memaksa untuk tetap tinggal', NULL, 'Membujuknya untuk menyelesaikan tugas', NULL, 'Mempersilakan pergi', NULL, 'Meminta pertimbangan teman yang lain', NULL, 'Memintanya untuk mempertimbangkan', NULL, 'E', 'Pilihan jawaban E adalah yang paling tepat karena menunjukkan diplomasi.', NULL, 'Pilih jawaban yang menunjukkan diplomasi.', '2026-05-09 19:50:34', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 107);
