INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (6232, 3, NULL, 49, NULL, NULL, NULL, 'Draft laporan yang dibuat tim kerja saya ditolak oleh atasan karena dianggap kurang layak. Sikap saya adalah....', NULL, 'Introspeksi diri', NULL, 'Segera melakukan perbaikan atas draft laporan dan mengajukan kembali', NULL, 'Menerima penolakan tetapi tidak melakukan tindak lanjut', NULL, 'Menerima penolakan dan berusaha memperbaiki', NULL, 'Meminta pertanggungjawaban team saya yang lain akan hal ini', NULL, 'B', 'Pilihan jawaban B adalah yang paling tepat karena segera melakukan perbaikan menunjukkan responsivitas.', NULL, 'Pilih jawaban yang menunjukkan responsivitas.', '2026-05-09 19:50:34', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 121);
