INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (6495, 2, NULL, 25, NULL, NULL, NULL, 'Rudi dan Ahmad menjadi peserta asuransi kesehatan dengan besaran premi yang sama. Rudi menerima gaji sebesar Rp 3.000.000 per bulan dan gaji tersebut dipotong 5% untuk premi asuransi. Berapa besar gaji Ahmad per bulan jika gajinya harus dipotong 3% untuk membayar premi?', NULL, 'Rp 4.000.000', NULL, 'Rp 5.000.000', NULL, 'Rp 6.000.000', NULL, 'Rp 7.000.000', NULL, 'Rp 8.000.000', NULL, 'B', 'Gaji Rudi = y, Gaji Ahmad = z. Besarnya premi asuransi = 5% x y = 5% x 3.000.000 = 150.000. Besarnya premi asuransi = 3% x z. 150.000 = 3% x z. 150.000 / 3% = z. 150.000 / (3/100) = z. 150.000 x 100 / 3 = z. 5.000.000 = z.', NULL, 'Untuk soal cerita persentase, buat persamaan dan selesaikan dengan teliti.', '2026-05-09 19:53:57', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 85);
