INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (7603, 1, NULL, 65, NULL, NULL, NULL, 'Kebersihan lingkungan adalah tanggung jawab kita bersama. Kita harus memulainya dari bagian terkecil dari kebersihan lingkungan, yaitu diri kita sendiri. Kita dapat memulainya dari hal - hal sederhana, seperti tidak membuang sampah sembarangan, dan senantiasa menjaga kebersihan diri. Setelah berhasil dari diri kita, kita dapat melanjutkan upaya kita kepada lingkungan terdekat, seperti keluarga, dan tetangga. Dengan terciptanya kesadaran bersama, kebersihan lingkungan bukan merupakan tanggung jawab yang berat. Ide pokok dari bacaan di atas adalah ...', NULL, 'Kebersihan diri lebih utama dari kebersihan lingkungan', NULL, 'Kebersihan lingkungan adalah tanggung jawab bersama', NULL, 'Kesadaran bersama penting untuk keberhasilan kebersihan lingkungan', NULL, 'Kebersihan lingkungan bukan tanggung jawab yang berat', NULL, 'Kebersihan lingkungan adalah tanggung jawab pribadi', NULL, 'B', 'Ide pokok dari bacaan di atas adalah kebersihan lingkungan adalah tanggung jawab bersama.', NULL, 'Cari ide pokok dari bacaan.', '2026-05-09 19:58:13', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 9);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (7604, 1, NULL, 65, NULL, NULL, NULL, 'Kebersihan lingkungan adalah tanggung jawab kita bersama. Kita harus memulainya dari bagian terkecil dari kebersihan lingkungan, yaitu diri kita sendiri. Kita dapat memulainya dari hal - hal sederhana, seperti tidak membuang sampah sembarangan, dan senantiasa menjaga kebersihan diri. Setelah berhasil dari diri kita, kita dapat melanjutkan upaya kita kepada lingkungan terdekat, seperti keluarga, dan tetangga. Dengan terciptanya kesadaran bersama, kebersihan lingkungan bukan merupakan tanggung jawab yang berat. Berdasarkan isinya, bacaan di atas termasuk jenis karangan ...', NULL, 'Narasi', NULL, 'Deskripsi', NULL, 'Eksposisi', NULL, 'Persuasi', NULL, 'Analisis', NULL, 'C', 'Berdasarkan isinya, bacaan di atas termasuk jenis karangan Eksposisi karena menjelaskan tentang kebersihan lingkungan.', NULL, 'Pahami jenis-jenis karangan.', '2026-05-09 19:58:13', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 9);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (7679, 3, NULL, 49, NULL, NULL, NULL, 'Menurut saya, orang yang kehilangan kesempatan mengembangkan usahanya lebih disebabkan karena mereka...', NULL, 'Bertahan pada cara yang telah berjalan', NULL, 'Menunggu bantuan pihak lain', NULL, 'Pikiran bercabang pada usaha lain', NULL, 'Menunda ketika melihat risikonya', NULL, 'Mundur begitu melihat risikonya', NULL, 'A', 'Pilihan jawaban A adalah yang paling tepat karena bertahan pada cara yang telah berjalan menunjukkan ketidakmampuan beradaptasi.', NULL, 'Pilih jawaban yang logis.', '2026-05-09 19:58:14', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 128);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (7700, 1, NULL, 1, NULL, NULL, NULL, 'Salah satu contoh nilai persatuan Indonesia adalah bahwa semangat kebangsaan diarahkan pada pelindungan segenap bangsa dan seluruh tumpah darah Indonesia yang senasib sepenanggungan dalam bingkai NKRI. Bukti bahwa nilai tersebut digali dari budaya bangsa Indonesia adalah...', NULL, 'Perjuangan kemerdekaan dilakukan oleh semua rakyat Indonesia', NULL, 'Sikap patriotisme dan nasionalisme sudah tumbuh sejak penjajahan', NULL, 'Semangat rela berkorban untuk kemerdekaan bangsa Indonesia', NULL, 'Kerelaan bergabung menjadi bangsa Indonesia yang merdeka', NULL, 'Kuatnya rasa persatuan dalam memperjuangkan kemerdekaan Indonesia', NULL, 'E', 'Pilihan E adalah yang paling tepat. Pernyataan ini dengan jelas menunjukkan persatuan sebagai nilai yang digali dari budaya bangsa Indonesia, di mana seluruh rakyat Indonesia bersatu padu dalam memperjuangkan kemerdekaan. Kuatnya rasa persatuan yang muncul di tengah keberagaman suku, agama, dan budaya menunjukkan bahwa nilai ini berakar kuat dalam budaya dan sejarah bangsa Indonesia.', NULL, 'Pilih jawaban yang menunjukkan nilai persatuan sebagai hasil dari budaya bangsa Indonesia.', '2026-05-09 19:58:14', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 21);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (7701, 1, NULL, 50, NULL, NULL, NULL, 'Peristiwa pada 28 Oktober 1928 merupakan tonggak penting dalam sejarah lahirnya bangsa Indonesia. Para pemuda dari berbagai suku dan daerah berkumpul untuk mengikrarkan sumpah yang dikenal dengan Sumpah Pemuda. Bercermin dari peristiwa sejarah tersebut, yang tidak termasuk ke dalam nilai nasionalisme yang dapat digali dan diamalkan oleh generasi penerus bangsa adalah...', NULL, 'Kepedulian generasi muda terhadap nasib bangsa', NULL, 'Keberanian melawan kolonialisme', NULL, 'Mengorbankan semangat kesukuan dan kedaerahan dalam berjuang', NULL, 'Menunjukan eksistensi generasi muda Indonesia saat itu kepada pihak kolonial', NULL, 'Semangat kebersamaan untuk berjuang', NULL, 'D', 'Pilihan D adalah yang paling tepat. Pilihan ini tidak sejalan dengan nilai nasionalisme seperti yang tercermin dalam Sumpah Pemuda, yang lebih mengutamakan persatuan, pengorbanan, dan kepedulian terhadap nasib bangsa secara kolektif.', NULL, 'Pilih jawaban yang tidak mencerminkan nilai nasionalisme yang sejalan dengan semangat Sumpah Pemuda.', '2026-05-09 19:58:14', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 7);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (7702, 1, NULL, 81, NULL, NULL, NULL, 'Pada suatu hari di tempat ibadah diadakan kegiatan ceramah yang mendatangkan pembicara tokoh agama. Pembicara menyampaikan pro dan kontra ideologi Pancasila apabila ditinjau dari ajaran agama. Berdasarkan cerita tersebut, respon manakah yang paling tepat yang sesuai dengan konsep kebhinekaan untuk menghadapi tindakan di atas?', NULL, 'Meminta penyelenggara mengentikan acara karena membahayakan eksistensi NKRI berdasarkan Pancasila', NULL, 'Melaporkan ke pihak yang berwajib karena telah menyebarluaskan informasi yang tidak benar terkait dengan Pancasila', NULL, 'Setelah kegiatan keagamaan selesai, menemui pembicara untuk berdiskusi tentang Pancasila sebagai Ideologi negara', NULL, 'Meminta pemerintah untuk menerbitkan para penceramah keagamaan agar memiliki pemahaman tentang ideologi Pancasila', NULL, 'Mengingatkan pembicara bahwa Pancasila sebagai ideologi dan dasar negara untuk menjaga persatuan dan kesatuan bangsa', NULL, 'C', 'Pilihan C adalah yang paling tepat. Respon ini sangat tepat karena menunjukkan sikap terbuka untuk berdialog. Dengan berdiskusi, kita bisa memahami perspektif yang berbeda dan sekaligus mengklarifikasi pandangan mengenai Pancasila. Tindakan ini sejalan dengan konsep kebhinekaan yang menghargai perbedaan dan mempromosikan saling pengertian.', NULL, 'Pilih jawaban yang menunjukkan sikap dialogis dan terbuka sesuai dengan konsep kebhinekaan.', '2026-05-09 19:58:14', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 11);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (7703, 1, NULL, 42, NULL, NULL, NULL, 'Pemanfaatan media sosial sebagai wahana untuk berbagi informasi bagi anggota yang beragam merupakan hal yang tak terbantahkan pada era kemajuan teknologi informasi dan komunikasi saat ini. Dalam konteks ini, sikap yang paling tepat adalah...', NULL, 'Lebih teliti dan berhati-hati dalam menyebarluaskan berita atau informasi kepada orang lain', NULL, 'Menoleransi tindakan anggota yang sering menyinggung isu SARA', NULL, 'Mengembangkan sikap saling curiga di antara sesama anggota media sosial', NULL, 'Berprasangka buruk terhadap sesama anggota media sosial tersebut', NULL, 'Menoleransi tindakan anggota lain yang tidak sesuai dengan aturan', NULL, 'A', 'Pilihan A adalah yang paling tepat. Dalam menggunakan media sosial, bersikap teliti dan berhati-hati penting untuk mencegah penyebaran berita palsu atau hoaks, serta menjaga agar informasi yang dibagikan tidak menyinggung atau merugikan pihak lain. Sikap ini mencerminkan tanggung jawab dalam memanfaatkan teknologi dengan bijak.', NULL, 'Pilih jawaban yang menunjukkan tanggung jawab dalam menggunakan media sosial.', '2026-05-09 19:58:14', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 6);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (7704, 1, NULL, 1, NULL, NULL, NULL, 'UUD NRI 1945 mengandung ketentuan yang memberikan kebebasan dalam menjalankan ibadah sesuai dengan agama dan kepercayaan masing-masing. Contoh perilaku yang mencerminkannya adalah...', NULL, 'Mempelajari ajaran agama masing-masing dengan baik agar tidak timbul kesalahan dalam mempelajarinya', NULL, 'Berpedoman pada ajaran agama masing-masing sebagai sikap hidup agar tidak menimbulkan dosa', NULL, 'Menghormati dan memberikan kesempatan bagi orang lain melaksanakan ibadahnya', NULL, 'Menjunjung tinggi ajaran agama masing-masing karena karena ajaran tersebut paling benar dibandingkan dengan yang lain', NULL, 'Memprotes pendirian tempat ibadah agama lain karena dianggap tidak banyak pengikutnya', NULL, 'C', 'Pilihan C adalah yang paling tepat. Menghormati dan memberikan kesempatan kepada orang lain untuk menjalankan ibadahnya menunjukkan sikap toleransi dan penghormatan terhadap kebebasan beragama, sesuai dengan semangat UUD NRI 1945. Sikap ini mendukung terciptanya lingkungan yang harmonis dan damai di tengah masyarakat yang beragam.', NULL, 'Pilih jawaban yang mencerminkan sikap toleransi dan penghormatan terhadap kebebasan beragama.', '2026-05-09 19:58:14', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 30);
