INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (8045, 2, NULL, 25, NULL, NULL, NULL, 'Enam buah data terdiri dari bilangan positif yang memiliki modus 4, median 5 dan rataan 5, maka bilangan terbesar dari data tersebut adalah ...', NULL, 8, NULL, 7, NULL, 6, NULL, 5, NULL, 4, NULL, 'C', 'Dengan modus 4, median 5, dan rataan 5, data bisa 2,4,4,5,6,6 atau 4,4,5,5,6,6. Bilangan terbesar adalah 6.', NULL, 'Untuk soal statistika, gunakan konsep modus, median, dan rataan.', '2026-05-09 20:00:30', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 53);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (8071, 3, NULL, 49, NULL, NULL, NULL, 'Anda menemukan data evaluasi pelanggan yang menyarankan agar kantor Anda memiliki akun media sosial sehingga mudah berkomunikasi dengan pelanggan. Pada sisi lain, beberapa staf menolak saran tersebut karena akan menambah pekerjaan mereka. Bagaimana tindakan Anda?', NULL, 'Saya merasa tidak semua saran pelanggan perlu diwujudkan; apabila kantor akan membuat akun media sosial, pengelolanya dapat diserahkan kepada staf yang ahli', NULL, 'Saya menilai penting untuk mempelajari pembuatan dan pengelolaan akun media sosial sehingga dapat mengoptimalkan pekerjaan tim marketing dan layanan pelanggan', NULL, 'Saya merasa sistem layanan pelanggan sebelumnya sudah cukup memfasilitasi kebutuhan pelanggan; pengelolaan media sosial dapat membebani pekerjaan yang sudah ada', NULL, 'Saya memandang bahwa evaluasi efektivitas sistem layanan pelanggan itu penting agar dapat memberikan solusi terbaik dalam melayani pelanggan', NULL, 'Saya merasa terdorong untuk mempelajari cara pembuatan dan pengelolaan akun media sosial sehingga dapat memberikan hasil optimal dalam melayani pelanggan', NULL, 'E', 'Jawaban E menunjukkan sikap inovatif dan berorientasi pada pelayanan pelanggan.', NULL, 'Pilih jawaban yang menunjukkan sikap inovatif dan berorientasi pelayanan.', '2026-05-09 20:00:30', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 105);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (8263, 2, NULL, 25, NULL, NULL, NULL, 'ES : DINGIN = GULA : .....', NULL, 'Bubuk', NULL, 'Kristal', NULL, 'Tebu', NULL, 'Manis', NULL, 'Aren', NULL, 'D', 'Es dingin, gula manis. Hubungan analogi: objek dan sifatnya.', NULL, 'Untuk soal analogi, cari hubungan objek dan sifat.', '2026-05-09 20:00:31', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 4);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (8333, 1, NULL, 65, NULL, NULL, NULL, 'Kebersihan lingkungan adalah tanggung jawab kita bersama. Kita harus memulainya dari bagian terkecil dari kebersihan lingkungan, yaitu diri kita sendiri. Kita dapat memulainya dari hal - hal sederhana, seperti tidak membuang sampah sembarangan, dan senantiasa menjaga kebersihan diri. Setelah berhasil dari diri kita, kita dapat melanjutkan upaya kita kepada lingkungan terdekat, seperti keluarga, dan tetangga. Dengan terciptanya kesadaran bersama, kebersihan lingkungan bukan merupakan tanggung jawab yang berat. Ide pokok dari bacaan di atas adalah ...', NULL, 'Kebersihan diri lebih utama dari kebersihan lingkungan', NULL, 'Kebersihan lingkungan adalah tanggung jawab bersama', NULL, 'Kesadaran bersama penting untuk keberhasilan kebersihan lingkungan', NULL, 'Kebersihan lingkungan bukan tanggung jawab yang berat', NULL, 'Kebersihan lingkungan adalah tanggung jawab pribadi', NULL, 'B', 'Ide pokok dari bacaan di atas adalah kebersihan lingkungan adalah tanggung jawab bersama.', NULL, 'Cari ide pokok dari bacaan.', '2026-05-09 20:00:31', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 9);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (8334, 1, NULL, 65, NULL, NULL, NULL, 'Kebersihan lingkungan adalah tanggung jawab kita bersama. Kita harus memulainya dari bagian terkecil dari kebersihan lingkungan, yaitu diri kita sendiri. Kita dapat memulainya dari hal - hal sederhana, seperti tidak membuang sampah sembarangan, dan senantiasa menjaga kebersihan diri. Setelah berhasil dari diri kita, kita dapat melanjutkan upaya kita kepada lingkungan terdekat, seperti keluarga, dan tetangga. Dengan terciptanya kesadaran bersama, kebersihan lingkungan bukan merupakan tanggung jawab yang berat. Berdasarkan isinya, bacaan di atas termasuk jenis karangan ...', NULL, 'Narasi', NULL, 'Deskripsi', NULL, 'Eksposisi', NULL, 'Persuasi', NULL, 'Analisis', NULL, 'C', 'Berdasarkan isinya, bacaan di atas termasuk jenis karangan Eksposisi karena menjelaskan tentang kebersihan lingkungan.', NULL, 'Pahami jenis-jenis karangan.', '2026-05-09 20:00:31', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 9);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (8433, 1, NULL, 42, NULL, NULL, NULL, 'Pemanfaatan media sosial sebagai wahana untuk berbagi informasi bagi anggota yang beragam merupakan hal yang tak terbantahkan pada era kemajuan teknologi informasi dan komunikasi saat ini. Dalam konteks ini, sikap yang paling tepat adalah...', NULL, 'Lebih teliti dan berhati-hati dalam menyebarluaskan berita atau informasi kepada orang lain', NULL, 'Menoleransi tindakan anggota yang sering menyinggung isu SARA', NULL, 'Mengembangkan sikap saling curiga di antara sesama anggota media sosial', NULL, 'Berprasangka buruk terhadap sesama anggota media sosial tersebut', NULL, 'Menoleransi tindakan anggota lain yang tidak sesuai dengan aturan', NULL, 'A', 'Pilihan A adalah yang paling tepat. Dalam menggunakan media sosial, bersikap teliti dan berhati-hati penting untuk mencegah penyebaran berita palsu atau hoaks, serta menjaga agar informasi yang dibagikan tidak menyinggung atau merugikan pihak lain. Sikap ini mencerminkan tanggung jawab dalam memanfaatkan teknologi dengan bijak.', NULL, 'Pilih jawaban yang menunjukkan tanggung jawab dalam menggunakan media sosial.', '2026-05-09 20:00:31', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 6);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (8435, 1, NULL, 106, NULL, NULL, NULL, 'Thailand dan Kamboja terlibat konflik perebutan kuil kuno Preah Vihear karena sama-sama mengklaim berada di bawah wilayahnya. Konflik tersebut tidak baik bagi masa depan ASEAN. Apa peran Indonesia dalam penyelesaian konflik di atas?', NULL, 'Mengirimkan bantuan TNI untuk menjaga keamanan di wilayah yang menjadi konflik', NULL, 'Melaporkan ke mahkamah internasional untuk melakukan penyeledikan atas konflik antara Thailand dan Kamboja', NULL, 'Sebagai mediator yang berperan mempertemukan, memfasilitasi, dan memberikan rekomendasi bagi kedua negara untuk menyelesaikan konflik', NULL, 'Mengusulkan agar sementara waktu kedua negara meninggalkan daerah konflik untuk menghindari terjadinya konflik bersenjata sampai ada putusan PBB', NULL, 'Mengusulkan pembentukan forum lintas negara untuk melakukan penyelidikan dan pemeriksaan konflik perbatasan Thailand dan Kamboja', NULL, 'C', 'Pilihan C adalah yang paling tepat. Indonesia telah sering memainkan peran sebagai mediator dalam konflik regional, termasuk dalam konflik antara Thailand dan Kamboja. Sebagai mediator, Indonesia bisa mempertemukan kedua belah pihak, memfasilitasi dialog, dan memberikan rekomendasi untuk mencapai kesepakatan damai. Hal ini sesuai dengan prinsip ASEAN yang menekankan penyelesaian konflik melalui cara damai.', NULL, 'Pilih jawaban yang menunjukkan peran Indonesia sebagai mediator dalam penyelesaian konflik regional.', '2026-05-09 20:00:31', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 14);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (8436, 1, NULL, 89, NULL, NULL, NULL, 'Perhatikan nilai-nilai Pancasila di bawah ini! 1. Mengembangkan rasa cinta kepada tanah air dan bangsa, 2. Bangsa Indonesia merasa dirinya sebagai bagian dari seluruh umat manusia, 3. Tidak menggunakan hak milik untuk hal-hal yang bersifat pemborosan dan gaya hidup mewah, 4. Tidak menggunakan hak milik untuk yang bertentangan dengan atau merugikan kepentingan umum, 5. Memelihara ketertiban dunia yang berdasarkan kemerdekaan, perdamaian abadi, dan keadilan sosial. Pernyataan di atas yang menunjukan perwujudan sikap nasionalisme adalah nomor...', NULL, '1 dan 3', NULL, '2 dan 4', NULL, '3 dan 5', NULL, '1 dan 5', NULL, '3 dan 4', NULL, 'D', 'Pilihan D adalah yang paling tepat. Pernyataan 1 mengandung unsur cinta kepada tanah air dan bangsa, yang merupakan inti dari nasionalisme. Pernyataan 5 juga relevan dalam konteks nasionalisme karena menunjukkan peran Indonesia dalam memelihara perdamaian dan keadilan di dunia, yang sejalan dengan komitmen negara untuk berperan dalam tatanan global sebagai bagian dari sikap nasionalisme yang luas.', NULL, 'Pilih jawaban yang mencerminkan sikap nasionalisme berdasarkan nilai-nilai Pancasila.', '2026-05-09 20:00:31', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 12);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (8437, 1, NULL, 1, NULL, NULL, NULL, 'Di bawah ini adalah salah satu contoh perilaku sebagai perwujudan sikap nasionalisme warga negara dalam UUD Negara RI tahun 1945...', NULL, 'Membantu pihak kepolisian untuk menangkap dan menghakimi pencuri yang tertangkap', NULL, 'Menjadi distributor hasil pertanian untuk pedagang dalam rangka meningkatkan kesejahteraan', NULL, 'Mencoba bertahan hidup di ibu kota dengan mengamen di bus kota dan perempatan jalan', NULL, 'Mengembangkan dan mempromosikan budaya daerah sehingga daerah itu dikenal di kancah nasional dan internasional', NULL, 'Ikut aktif menjadi anggota kelompok seni budaya yang telah dirintis oleh keluarga karena hal itu menjadi sumber kehidupan satu-satunya', NULL, 'D', 'Pilihan D adalah yang tepat. Mengembangkan dan mempromosikan budaya daerah mencerminkan rasa cinta terhadap budaya nasional, dan upaya agar budaya Indonesia dikenal luas. Perilaku ini menunjukkan sikap nasionalisme dengan menjaga dan memajukan kekayaan budaya Indonesia, yang sejalan dengan nilai-nilai dalam UUD 1945.', NULL, 'Pilih jawaban yang mencerminkan sikap nasionalisme melalui pelestarian dan promosi budaya.', '2026-05-09 20:00:31', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 21);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (8438, 1, NULL, 1, NULL, NULL, NULL, 'Kongres Pemuda Indonesia pada tahun 1928 menghasilkan kesepakatan persatuan, satu tanah air, bangsa, dan bahasa. Manifestasi persatuan merupakan refleksi dari...', NULL, 'Persatuan yang dibangun pemuda adalah untuk menghadapi tantangan global', NULL, 'Kesadaran dan loyalitas tertinggi diletakkan kepada bangsa dan negara', NULL, 'Kelompok-kelompok sosial di wilayah nusantara harus dikendalikan', NULL, 'Prinsip menekan individu untuk membangun kebersamaan', NULL, 'Mereka dilahirkan di tanah air sama dan bersatu', NULL, 'B', 'Pilihan B adalah yang paling tepat. Kesepakatan yang dihasilkan dalam Kongres Pemuda menunjukkan bahwa para pemuda memiliki kesadaran dan loyalitas yang tinggi kepada bangsa Indonesia. Mereka bersatu di bawah satu identitas nasional dan mengutamakan kepentingan bangsa di atas kepentingan suku, agama, atau daerah. Ini adalah manifestasi nyata dari semangat persatuan dan nasionalisme.', NULL, 'Pilih jawaban yang mencerminkan kesadaran dan loyalitas tertinggi kepada bangsa dan negara.', '2026-05-09 20:00:31', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 1);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (8439, 1, NULL, 89, NULL, NULL, NULL, 'Berikut ini adalah nilai-nilai Pancasila: 1. Keadilan, 2. Persatuan, 3. Tidak diskriminatif, 4. Kesatuan, 5. Kerja sama. Manakah nilai-nilai yang merupakan penerapan sila ketiga Pancasila?', NULL, '1, 2, dan 3', NULL, '2, 3, dan 4', NULL, '2, 3, dan 5', NULL, '1, 4, dan 5', NULL, '3, 4, dan 5', NULL, 'B', 'Pilihan B adalah yang paling tepat. Persatuan (2), Tidak diskriminatif (3), dan Kesatuan (4) semuanya sejalan dengan sila ketiga, yang menekankan pentingnya persatuan dan kesatuan bangsa dalam keberagaman, serta semangat gotong royong dan saling menghargai.', NULL, 'Pilih jawaban yang mencerminkan nilai-nilai sila ketiga Pancasila (Persatuan Indonesia).', '2026-05-09 20:00:31', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 12);
