INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (8929, 3, NULL, 49, NULL, NULL, NULL, 'Jika Anda mendapatkan suatu pekerjaan yang bayarannya sangat besar, maka Anda akan ...', NULL, 'Bertanggung jawab dalam melakukan pekerjaan Anda', NULL, 'Lebih bersemangat', NULL, 'Takut', NULL, 'Merasa terharu', NULL, 'Biasa saja', NULL, 'A', 'Bertanggung jawab menunjukkan profesionalisme regardless of gaji.', NULL, 'Pilih jawaban yang menunjukkan integritas.', '2026-05-09 20:03:12', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 109);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (9068, 1, NULL, 65, NULL, NULL, NULL, 'Kebersihan lingkungan adalah tanggung jawab kita bersama. Kita harus memulainya dari bagian terkecil dari kebersihan lingkungan, yaitu diri kita sendiri. Kita dapat memulainya dari hal - hal sederhana, seperti tidak membuang sampah sembarangan, dan senantiasa menjaga kebersihan diri. Setelah berhasil dari diri kita, kita dapat melanjutkan upaya kita kepada lingkungan terdekat, seperti keluarga, dan tetangga. Dengan terciptanya kesadaran bersama, kebersihan lingkungan bukan merupakan tanggung jawab yang berat. Ide pokok dari bacaan di atas adalah ...', NULL, 'Kebersihan diri lebih utama dari kebersihan lingkungan', NULL, 'Kebersihan lingkungan adalah tanggung jawab bersama', NULL, 'Kesadaran bersama penting untuk keberhasilan kebersihan lingkungan', NULL, 'Kebersihan lingkungan bukan tanggung jawab yang berat', NULL, 'Kebersihan lingkungan adalah tanggung jawab pribadi', NULL, 'B', 'Ide pokok dari bacaan di atas adalah kebersihan lingkungan adalah tanggung jawab bersama.', NULL, 'Cari ide pokok dari bacaan.', '2026-05-09 20:03:13', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 9);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (9069, 1, NULL, 65, NULL, NULL, NULL, 'Kebersihan lingkungan adalah tanggung jawab kita bersama. Kita harus memulainya dari bagian terkecil dari kebersihan lingkungan, yaitu diri kita sendiri. Kita dapat memulainya dari hal - hal sederhana, seperti tidak membuang sampah sembarangan, dan senantiasa menjaga kebersihan diri. Setelah berhasil dari diri kita, kita dapat melanjutkan upaya kita kepada lingkungan terdekat, seperti keluarga, dan tetangga. Dengan terciptanya kesadaran bersama, kebersihan lingkungan bukan merupakan tanggung jawab yang berat. Berdasarkan isinya, bacaan di atas termasuk jenis karangan ...', NULL, 'Narasi', NULL, 'Deskripsi', NULL, 'Eksposisi', NULL, 'Persuasi', NULL, 'Analisis', NULL, 'C', 'Berdasarkan isinya, bacaan di atas termasuk jenis karangan Eksposisi karena menjelaskan tentang kebersihan lingkungan.', NULL, 'Pahami jenis-jenis karangan.', '2026-05-09 20:03:13', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 9);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (9118, 3, NULL, 49, NULL, NULL, NULL, 'Setelah mematangkan rencana, . . .', NULL, 'Saya masih khawatir apakah rencana tersebut bisa berhasil', NULL, 'Berhasil tidaknya tak lepas dari pihak lain juga', NULL, 'Manusia berusaha sebaik-baiknya dan Tuhan yang menentukan', NULL, 'Bagaimanapun caranya rencana harus berhasil', NULL, 'Saya minta pendapat orang lain terlebih dulu, sebab pendapat banyak orang lebih baik daripada pendapat satu orang', NULL, 'C', 'Pilihan jawaban C adalah yang paling tepat karena menunjukkan sikap tawakal dan berusaha semaksimal mungkin.', NULL, 'Pilih jawaban yang menunjukkan sikap tawakal dan berusaha.', '2026-05-09 20:03:13', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 7);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (9175, 1, NULL, 81, NULL, NULL, NULL, 'Sumbangan pemikiran dari para tokoh di dalam proses perumusan dan penetapan UUD NKRI 1945 pada sidang BPUPKI dan PPKI merupakan semangat para tokoh untuk...', NULL, 'Memajukan kebudayaan nasional Indonesia di tengah peradaban dunia dengan menjamin kebebasan masyarakat dalam memlihara nilai-nilai budaya', NULL, 'Menjamin perwujudan persatuan kesatuan segenap aspek kehidupan nasional, baik aspek alamiah maupun aspek sosial untuk kepentingan rakyat', NULL, 'Bahu-membahu untuk merumuskan sebuah dasar negara yang kuat walaupun berbeda prinsip tetapi tetap satu tujuan, yaitu kepentingan bersama', NULL, 'Penerapan atau implementasi wawasan nusantara dalam kehidupan politik akan menciptakan iklim penyelenggara negara yang sehat dan dinamis', NULL, 'Mencegah perbedaan yang lebih besar dan mencari titik temu di antara perbedaan-perbedaan tersebut agar menghasilkan kesepakatan', NULL, 'C', 'Pilihan C adalah yang paling tepat. Para tokoh di BPUPKI dan PPKI memiliki beragam pandangan, namun mereka tetap bekerja sama demi merumuskan dasar negara yang kuat untuk kepentingan seluruh rakyat Indonesia. Perbedaan prinsip tidak menjadi penghalang; sebaliknya, mereka mencari titik temu dan menyatukan pandangan demi mewujudkan tujuan bersama.', NULL, 'Pilih jawaban yang mencerminkan semangat kerja sama dan kebersamaan dalam merumuskan dasar negara.', '2026-05-09 20:03:13', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 11);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (9176, 1, NULL, 1, NULL, NULL, NULL, 'Di bawah ini merupakan contoh sikap integritas yang ditunjukkan R.A Kartini sebagai tokoh pergerakan nasional Indonesia yang berjuang...', NULL, 'Dengan kegigihan melalui bidang kesehatan dan pendidikan', NULL, 'Pantang menyerah untuk memajukan kaum wanita', NULL, 'Tanpa letih untuk gemar membaca setiap saat', NULL, 'Mencetuskan kata mutiara habis gelap terbitlah terang', NULL, 'Berkomitmen dalam memajukan bidang sosial dan ekonomi', NULL, 'B', 'Pilihan B adalah yang paling tepat. R.A. Kartini berjuang tanpa kenal lelah untuk memajukan kaum wanita di Indonesia. Beliau terus memperjuangkan hak perempuan untuk mendapatkan pendidikan dan berperan aktif dalam kehidupan sosial. Sikap pantang menyerahnya mencerminkan integritas yang tinggi.', NULL, 'Pilih jawaban yang mencerminkan sikap integritas R.A. Kartini dalam memajukan kaum wanita.', '2026-05-09 20:03:13', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 22);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (9177, 1, NULL, 1, NULL, NULL, NULL, 'Mohammad Yamin merupakan salah satu tokoh yang berperan penting dalam peristiwa Sumpah Pemuda 1928. Setelah peristiwa itu, semangat persatuan dan kesatuan pemuda Indonesia kembali menggelora untuk melakukan perlawanan terhadap pemerintah kolonial Belanda. Perilaku berintegritas yang dicontohkan Mohammad Yamin sebagai tokoh pergerakan nasional menunjukkan bahwa...', NULL, 'Kemerdekaan hanya bisa dicapai jika para pemuda dapat menggalang persatuan dan kesatuan', NULL, 'Tanpa Sumpah Pemuda 1928 kemerdekaan Indonesia mustahil dapat tercapai dengan baik', NULL, 'Persatuan dan kesatuan pemuda menjadi kekuatan bagi tercapainya kemerdekaan Indonesia', NULL, 'Kekuatan para pemuda menjadi ujung tombak satu-satunya melawan penjajahan Belanda', NULL, 'Terlaksananya Sumpah Pemuda 1928 merupakan bukti utama prestasi Mohammad Yamin', NULL, 'C', 'Pilihan C adalah yang paling tepat. Semangat persatuan yang dicetuskan melalui Sumpah Pemuda menunjukkan bahwa pemuda dari berbagai suku dan agama dapat bersatu dalam satu tujuan nasional. Semangat ini terus berlanjut dalam perjuangan melawan kolonialisme, dan Mohammad Yamin dengan integritasnya mendukung gagasan bahwa persatuan adalah kekuatan utama yang memperkuat perjuangan menuju kemerdekaan.', NULL, 'Pilih jawaban yang menekankan persatuan dan kesatuan pemuda sebagai kekuatan kemerdekaan.', '2026-05-09 20:03:13', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 21);
