INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (9918, 1, NULL, 89, NULL, NULL, NULL, 'Berikut ini adalah nilai-nilai Pancasila: 1. Toleransi, 2. Kerja sama, 3. Musyawarah, 4. Patuh, 5. Disiplin. Manakah nilai-nilai yang sesuai dengan sila keempat Pancasila?', NULL, '1, 2, dan 3', NULL, '1, 2, dan 4', NULL, '2, 3, dan 4', NULL, '2, 3, dan 5', NULL, '3, 4, dan 5', NULL, 'C', 'Pilihan C adalah yang paling tepat. Kerja sama, Musyawarah, dan Patuh (Patuh di sini dimaknai sebagai patuh pada hasil musyawarah) adalah nilai-nilai yang sesuai dengan sila keempat Pancasila \"Kerakyatan yang dipimpin oleh hikmat kebijaksanaan dalam permusyawaratan/perwakilan\".', NULL, 'Pilih jawaban yang mencerminkan nilai-nilai sila keempat Pancasila.', '2026-05-09 20:06:28', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 12);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (9919, 1, NULL, 52, NULL, NULL, NULL, 'Bangsa Indonesia memiliki karateristik kebersamaan budaya, etnis, agama, adat istiadat, dan bahasa yang tersebar dari Sabang sampai Merauke. Perilaku yang sesuai dengan upaya menjaga kebhinekaan dalam bingkai persatuan dan kesatuan untuk menghadapi karateristik tersebut adalah...', NULL, 'Menggunakan bahasa dari daerah masing-masing', NULL, 'Bangga menggunakan pakaian-pakaian adat dari daerahnya', NULL, 'Menghormati adat istiadat budaya masyarakat di daerah', NULL, 'Menghindari kerja sama dengan orang lain yang berbeda etnis', NULL, 'Bersikap sopan terhadap orang lain yang berasal dari daerah yang sama', NULL, 'C', 'Pilihan C adalah yang paling tepat. Menghormati adat istiadat budaya lain menunjukkan sikap toleransi dan saling menghargai, yang sangat penting dalam menjaga kebhinekaan. Sikap ini mendorong persatuan dan kesatuan, karena menunjukkan penghargaan terhadap keragaman budaya di Indonesia.', NULL, 'Pilih jawaban yang mencerminkan sikap menghormati kebhinekaan dan persatuan.', '2026-05-09 20:06:28', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 7);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (9920, 1, NULL, 1, NULL, NULL, NULL, 'Sidang pertama PPKI pada tanggal 18 agustus 1945 menghasilkan beberapa putusan, yaitu mengesahkan UUD 1945, memilih presiden dan wakil presiden, serta menetapkan Komite Nasional Indonesia Pusat. Peristiwa tersebut menunjukan nilai nasionalisme, yakni...', NULL, 'Patriotisme semangat perjuangan', NULL, 'Rela berkorban demi bangsa dan negara', NULL, 'Mengutamakan kepentingan bangsa dan negara', NULL, 'Toleransi antar suku bangsa, agama, dan daerah', NULL, 'Kemandirian sebagai suatu negara', NULL, 'C', 'Pilihan C adalah yang paling tepat. Sidang PPKI menunjukkan bahwa para pemimpin bangsa mengutamakan kepentingan Indonesia dengan membentuk pemerintahan, menyusun konstitusi, dan memilih pemimpin yang sah untuk menjaga kedaulatan negara. Tindakan ini mencerminkan sikap nasionalisme yang menempatkan kepentingan bangsa dan negara di atas kepentingan pribadi atau golongan.', NULL, 'Pilih jawaban yang mencerminkan nilai nasionalisme mengutamakan kepentingan bangsa dan negara.', '2026-05-09 20:06:28', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 35);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (9921, 1, NULL, 110, NULL, NULL, NULL, 'Adanya kasus pemaksaan suatu ajaran agama terhadap orang lain sangat tidak dibenarkan. Selain bertentangan dengan nilai-nilai Pancasila sehingga diperlukan rasa saling menghormati terhadap agama keyakinan orang lain. Berikut yang menjadi alasan diperlukannya sikap saling menghormati antarpemeluk agama adalah...', NULL, 'Dapat menyamakan agama yang berbeda', NULL, 'Menghilangkan segala perbedaan yang ada', NULL, 'Mempererat hubungan antarwarga', NULL, 'Memperkuat persatuan dan menghindari konflik', NULL, 'Menghindari konflik dan menyatukan agama', NULL, 'D', 'Pilihan D adalah yang paling tepat. Dengan saling menghormati keyakinan orang lain, persatuan dalam masyarakat yang majemuk bisa terjaga, dan potensi konflik karena perbedaan agama dapat diminimalisir. Sikap ini sesuai dengan prinsip Pancasila dan membantu menciptakan lingkungan yang damai.', NULL, 'Pilih jawaban yang menekankan pentingnya saling menghormati untuk memperkuat persatuan dan menghindari konflik.', '2026-05-09 20:06:28', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 14);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (9922, 1, NULL, 73, NULL, NULL, NULL, 'Dalam kehidupan masyarakat yang diwarnai keanekaragaman, konflik yang terjadi karena persoalan pribadi kadang-kadang sengaja dibawa untuk membangun persepsi seolah-olah terjadi yang bernuansa SARA. Oleh karena itu, sikap apakah yang perlu dimiliki setiap warga negara?', NULL, 'Menanggapi setiap konflik dengan pengamatan yang lebih cermat', NULL, 'Memberikan respons dengan cepat atas terjadinya setiap konflik', NULL, 'Mencari penjelasan dari media massa atas konflik yang terjadi', NULL, 'Menyerahkan penyelesaian setiap konflik pada penegak hukum', NULL, 'Membiarkan terjadinya konflik sebagai bagian dari dinamika sosial', NULL, 'A', 'Pilihan A adalah yang paling tepat. Menanggapi konflik dengan cermat memungkinkan seseorang untuk menganalisis situasi secara objektif dan tidak terburu-buru membuat asumsi yang dapat memperkeruh suasana. Sikap ini penting agar kita tidak terjebak dalam persepsi yang salah atau mendukung pandangan yang bernuansa SARA.', NULL, 'Pilih jawaban yang menunjukkan sikap cermat dan objektif dalam menyikapi konflik.', '2026-05-09 20:06:28', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 10);
