INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (10667, 1, NULL, 1, NULL, NULL, NULL, 'Sikap fanatik yang berlebihan dalam beragama dapat mengancam kerukunan dalam masyarakat. Fanatik yang berlebihan akan menganggap pemeluk agama lain sebagai musuh. Sikap tersebut tidak sesuai dengan Pancasila karena...', NULL, 'Mengarah pada ekslusifisme agama', NULL, 'Rendahnya rasa hormat pada keagamaan', NULL, 'Fanatisme yang buta bisa berdampak buruk', NULL, 'Tidak mencerminkan ketakwaan kepada Tuhan', NULL, 'Kerukunan beragama harus dijaga', NULL, 'A', 'Pilihan A adalah yang paling tepat. Fanatisme berlebihan dalam beragama dapat mengarah pada eksklusivisme, di mana seseorang hanya menghargai keyakinan agamanya sendiri dan mengabaikan, bahkan memusuhi, agama lain. Sikap eksklusif ini tidak sejalan dengan Pancasila yang menekankan toleransi dan kebebasan beragama.', NULL, 'Pilih jawaban yang menunjukkan bahaya eksklusivisme agama terhadap nilai Pancasila.', '2026-05-09 20:09:25', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 22);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (10668, 1, NULL, 77, NULL, NULL, NULL, 'Meskipun berbeda etnis dan agama, masyarakat sukses mengadakan festival budaya tingkat desa dan mendapatkan respon positif dari warga dan pengunjung pada umumnya. Kegiatan tersebut merefleksikan bahwa...', NULL, 'Keberagaman menjadi penghambat untuk memupuk kebersamaan', NULL, 'Sikap saling mempercayai (mutual trust) dapat mendorong persatuan', NULL, 'Perbedaan bukanlah penghalang untuk memupuk persatuan dalam masyarakat', NULL, 'Kerja sama yang terjalin dengan perbedaan hanya bersifat temporal', NULL, 'Persatuan dalam keberagaman merupakan hal yang sulit untuk diwujudkan', NULL, 'C', 'Pilihan C adalah yang paling tepat. Peristiwa yang digambarkan menunjukkan bahwa perbedaan etnis dan agama tidak menjadi penghalang bagi masyarakat untuk bersatu dan mencapai kesuksesan bersama. Justru dengan keberagaman tersebut, masyarakat dapat memupuk persatuan yang lebih kokoh.', NULL, 'Pilih jawaban yang menekankan perbedaan bukan penghalang untuk persatuan.', '2026-05-09 20:09:25', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 10);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (10669, 1, NULL, 73, NULL, NULL, NULL, 'Keterbatasan akses internet untuk para siswa belajar dari rumah selama pandemi telah mendorong seluruh lapisan masyarakat membantu ketersediaan jaringan internet. Hal itu bertujuan agar penyediaan jaringan internet memenuhi tujuan pembelajaran. Langkah tepat untuk mencegah penyalahgunaan akses internet adalah...', NULL, 'Melatih guru-guru menggunakan gawai berbasis internet', NULL, 'Meningkatkan fasilitas pembelajaran berbasis internet di semua sekolah', NULL, 'Sosialisasi tentang bahaya dan manfaat penggunaan internet', NULL, 'Membimbing para orang tua siswa mengawasi penggunaan internet', NULL, 'Menguatkan pemahaman literasi digital bagi masyarakat', NULL, 'D', 'Pilihan D adalah yang paling tepat. Dengan melibatkan orang tua dalam pengawasan, siswa akan lebih terkontrol dalam menggunakan internet di rumah. Orang tua yang terlibat dan teredukasi tentang bagaimana memantau penggunaan internet dapat membantu mencegah penyalahgunaan.', NULL, 'Pilih jawaban yang menekankan peran orang tua dalam mengawasi penggunaan internet.', '2026-05-09 20:09:25', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 10);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (10670, 1, NULL, 1, NULL, NULL, NULL, 'Perhatikan perilaku berikut ini! 1. Menyontek pada saat ujian untuk meraih prestasi. 2. Membuat berita bohong di media sosial agar terkenal. 3. Mengunggah ujaran kebencian karena sering mendapat perundungan. 4. Memberikan informasi palsu karena mendapatkan tekanan. 5. Mengajak anak-anak untuk menjadi pekerja paruh waktu. Berdasarkan perilaku di atas, tindakan yang bertentangan dengan nilai harkat dan martabat kemanusiaan dalam Pancasila ditunjukan oleh nomor...', NULL, '1 dan 2', NULL, '2 dan 3', NULL, '3 dan 4', NULL, '2 dan 5', NULL, '4 dan 5', NULL, 'B', 'Pilihan B adalah yang paling tepat. Membuat berita bohong dan mengunggah ujaran kebencian keduanya bertentangan dengan nilai kemanusiaan yang menekankan pada penghormatan terhadap martabat orang lain. Berita bohong dapat menyesatkan publik dan merusak keharmonisan sosial, sementara ujaran kebencian menumbuhkan kebencian dan merendahkan martabat orang yang dituju.', NULL, 'Pilih jawaban yang mencerminkan perilaku bertentangan dengan harkat dan martabat kemanusiaan.', '2026-05-09 20:09:25', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 47);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (10671, 1, NULL, 1, NULL, NULL, NULL, 'Hubungan antara india dan Pakistan sering mengalami gangguan karena persoalan perbatasan di Kashmir. Sejalan dengan politik luar negeri Indonesia, peran apakah yang dapat dilakukan oleh pemerintah Indonesia?', NULL, 'Memihak kepada salah satu pihak yg dianggap pada posisi yang benar', NULL, 'Membiarkan hal itu terjadi karena menyangkut hubungan bilateral kedua negara', NULL, 'Aktif mendorong untuk dapat dicapainya solusi damai di antara kedua negara', NULL, 'Meminta kepada PBB untuk turun tangan menyelesaikan persoalan tersebut', NULL, 'Memberi sanksi kepada kedua negara karena mengganggu stabilitas wilayah', NULL, 'C', 'Pilihan C adalah yang paling tepat. Indonesia, sesuai dengan politik luar negeri bebas aktif, dapat berperan sebagai pendorong untuk mencapai solusi damai antara India dan Pakistan. Indonesia sering menjadi mediator dan mendukung upaya perdamaian di berbagai konflik internasional.', NULL, 'Pilih jawaban yang mencerminkan peran Indonesia dalam politik luar negeri bebas aktif.', '2026-05-09 20:09:25', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 39);
