INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (11386, 3, NULL, 49, NULL, NULL, NULL, 'Karena sebagian besar pegawai pulang kampung dan saya diminta menunda cuti lebaran oleh pimpinan. Saya berjanji pada orang tua untuk mudik di hari lebaran, sikap saya ...', NULL, 'Tetap mengambil cuti', NULL, 'Memberi pengertian kepada orang tua', NULL, 'Memberi pengertian kepada pimpinan agar diperbolehkan pulang kampung', NULL, 'Meminta anggota keluarga lain untuk membujuk orang tua', NULL, 'Meminta teman untuk menggantikan penundaan cuti', NULL, 'B', 'Pilihan jawaban B adalah yang paling tepat karena memberi pengertian kepada orang tua menunjukkan komunikasi yang baik.', NULL, 'Pilih jawaban yang menunjukkan komunikasi yang baik.', '2026-05-09 20:11:51', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 135);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (11403, 1, NULL, 89, NULL, NULL, NULL, 'Perhatikan nilai-nilai Pancasila di bawah ini! 1. Mengembangkan rasa cinta kepada tanah air dan bangsa, 2. Bangsa Indonesia merasa dirinya sebagai bagian dari seluruh umat manusia, 3. Tidak menggunakan hak milik untuk hal-hal yang bersifat pemborosan dan gaya hidup mewah, 4. Tidak menggunakan hak milik untuk yang bertentangan dengan atau merugikan kepentingan umum, 5. Memelihara ketertiban dunia yang berdasarkan kemerdekaan, perdamaian abadi, dan keadilan sosial. Pernyataan di atas yang menunjukan perwujudan sikap nasionalisme adalah nomor...', NULL, '1 dan 3', NULL, '2 dan 4', NULL, '3 dan 5', NULL, '1 dan 5', NULL, '3 dan 4', NULL, 'D', 'Pilihan D adalah yang paling tepat. Pernyataan 1 mengandung unsur cinta kepada tanah air dan bangsa, yang merupakan inti dari nasionalisme. Pernyataan 5 juga relevan dalam konteks nasionalisme karena menunjukkan peran Indonesia dalam memelihara perdamaian dan keadilan di dunia, yang sejalan dengan komitmen negara untuk berperan dalam tatanan global sebagai bagian dari sikap nasionalisme yang luas.', NULL, 'Pilih jawaban yang mencerminkan sikap nasionalisme berdasarkan nilai-nilai Pancasila.', '2026-05-09 20:11:51', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 12);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (11421, 1, NULL, 2, NULL, NULL, NULL, 'Indonesia dianugerahi kekayaan yang tidak hanya terbatas pada alam tetapi juga keragaman budaya, suku, bahkan agama oleh sang pencipta. Dalam kerangka mempertahankan anugerah budaya tersebut, perilaku yang dapat dilakukan oleh warga Negara Indonesia adalah...', NULL, 'Menghormati budaya yang ada di masyarakat dengan segala kelebihan dan kekurangannya', NULL, 'Membuang jauh-jauh tradisi yang sudah tidak relevan dengan perkembangan zaman', NULL, 'Menyukai budaya luar negeri yang baik-baik untuk diterapkan dan dilakukan di Indonesia', NULL, 'Meyakini bahwa budaya sendiri paling benar sehingga tidak perlu budaya orang lain', NULL, 'Fokus terhadap teknologi dan meninggalkan budaya yang tidak mau menerima teknologi', NULL, 'A', 'Pilihan A adalah yang paling tepat. Menghormati budaya menunjukkan sikap menghargai keragaman dan menerima perbedaan. Mengakui kelebihan dan kekurangan budaya yang ada merupakan bentuk toleransi dan keterbukaan. Sikap ini membantu mempertahankan anugerah budaya Indonesia.', NULL, 'Pilih jawaban yang mencerminkan sikap menghormati keragaman budaya Indonesia.', '2026-05-09 20:11:51', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 1);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (11422, 1, NULL, 63, NULL, NULL, NULL, 'Di lingkungan yang multikultural sering terdengar perbincangan yang diwarnai logat khas daerah masing-masing. Pemaknaan atas peristiwa tersebut dalam kerangka bhineka tunggal ika adalah...', NULL, 'Tiap-tiap budaya memiliki kekayaan berbahasa yang diapresiasi', NULL, 'Keragaman logat perbincangan menjadi kekayaan untuk saling memahami', NULL, 'Perlu logat bahasa standar agar Indonesia menjadi satu aksi berbahasa', NULL, 'Perbincangan yang menjadi cerminan multikultural tersebut bisa menjadi aset nasional', NULL, 'Lingkungan multikultural rentan praktik perundungan karena ada yang dianggap orang kampung', NULL, 'B', 'Pilihan B adalah yang paling tepat. Logat khas daerah merupakan bentuk kekayaan budaya yang memungkinkan orang dari latar belakang berbeda untuk saling mengenal dan memahami. Sikap saling memahami ini adalah inti dari Bhinneka Tunggal Ika.', NULL, 'Pilih jawaban yang menekankan keragaman sebagai kekayaan untuk saling memahami.', '2026-05-09 20:11:51', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 8);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (11423, 1, NULL, 1, NULL, NULL, NULL, 'Mendengarkan musik adalah bagian dari HAM. Seorang anak muda memutar musik kesukaannya secara keras hingga mengganggu tetangganya yang sedang istirahat. Pemuda tersebut telah mendapat teguran, tetapi menolak dengan alasan HAM. Tindakan pemuda ini bertentangan dengan pelestarian nilai Pancasila karena...', NULL, 'Pemenuhan HAM tidak boleh menggangu HAM orang lain', NULL, 'Menggangu selera musik orang lain yang berbeda', NULL, 'Hak asasi merupakan kebebasan individu yang mutlak', NULL, 'Memilih musik merupakan bagian dari hak setiap orang', NULL, 'Tidak sesuai dengan selera musik orang lain', NULL, 'A', 'Pilihan A adalah yang paling tepat. HAM seseorang, seperti menikmati musik, tidak boleh dilaksanakan dengan cara yang mengganggu hak orang lain, misalnya hak untuk beristirahat. Pelaksanaan HAM harus mempertimbangkan lingkungan sosialnya dan tidak mengabaikan hak orang lain.', NULL, 'Pilih jawaban yang menekankan bahwa HAM tidak boleh mengganggu HAM orang lain.', '2026-05-09 20:11:51', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 50);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (11424, 1, NULL, 1, NULL, NULL, NULL, 'Salah satu pergerakan untuk mencapai kemerdekaan diwarnai oleh lahirnya Sarekat Dagang Islam yang didirikan oleh Haji Samanhudi di Solo pada 1911. Gerakan ini berusaha membangun kekuatan serta persatuan bangsa melalui penguatan dalam bidang...', NULL, 'Ekonomi melalui perlindungan pengusaha lokal agar mampu bersaing dengan pengusaha non lokal', NULL, 'Kebudayaan melalui pengembangan keseniaan daerah agar mampu mengharumkan nama baik Indonesia', NULL, 'Pendidikan melalui pengajaran serta menjadi pemantik persatuan dan kesatuan bangsa Indonesia', NULL, 'Keagamaan yang memobilitasi gerakan rakyat dengan dasar keyakinan pada nilai-nilai Ketuhanan', NULL, 'Politik melalui pengembangan kebijakan yang berpihak masyarakat lokal dibanding masyarakat non lokal', NULL, 'A', 'Pilihan A adalah yang paling tepat. SDI awalnya didirikan untuk melindungi dan mendukung para pedagang pribumi agar dapat bersaing dengan pengusaha non-pribumi, terutama pedagang Tionghoa yang saat itu menguasai sektor perdagangan. SDI bertujuan untuk meningkatkan kekuatan ekonomi rakyat Indonesia.', NULL, 'Pilih jawaban yang mencerminkan fokus Sarekat Dagang Islam pada bidang ekonomi.', '2026-05-09 20:11:51', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 21);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (11425, 1, NULL, 1, NULL, NULL, NULL, 'Penggunaan berita bohong di masa kampanye pemilu presiden dan wakil presiden tahun 2019 telah membelah kesatuan bangsa yang memiliki keragaman latar belakang. Sebagai seorang warga negara Indonesia yang memiliki literasi teknologi dan informasi tinggi upaya yang tepat untuk menghentikan berita bohong tersebut adalah...', NULL, 'Membuat konten informasi tandingan', NULL, 'Membiarkan berita bohong tersimpan dalam telepon pintar', NULL, 'Mempermalukan penyebaran berita bohong di depan masyarakat', NULL, 'Menghentikan penyebaran berita bohong mulai dari diri sendiri', NULL, 'Mengkritisi pemerintah agar memperketat penggunaan media sosial', NULL, 'D', 'Pilihan D adalah yang paling tepat. Sebagai orang yang memiliki literasi teknologi tinggi, langkah pertama yang bisa dilakukan adalah memastikan diri sendiri tidak menjadi bagian dari penyebaran hoaks. Dengan menghentikan penyebaran dari diri sendiri, seseorang ikut berperan dalam memutus rantai hoaks dan menjaga persatuan bangsa.', NULL, 'Pilih jawaban yang menekankan tanggung jawab pribadi dalam menghentikan penyebaran hoaks.', '2026-05-09 20:11:51', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 49);
