INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (11801, 3, NULL, 49, NULL, NULL, NULL, 'Saya mengikuti rapat RT untuk menentukan konsep acara hari kemerdekaan, namun rapat berlangsung lama karena peserta rapat tidak ada yang mengajukan konsep', NULL, 'Rapat ini benar-benar membuang waktu saja', NULL, 'Saya mengajukan konsep yang saya punya sebagai pancingan saja.', NULL, 'Mereka saja tidak menyiapkan konsep, mengapa harus saya yang bicara.', NULL, 'Saya mengajukan konsep yang saya punya dan meminta saran dari para peserta.', NULL, 'Saya mengusulkan konsep yang sama dengan tahun lalu.', NULL, 'D', 'Sikap yang baik adalah mengajukan konsep dan meminta saran.', NULL, 'Pilih jawaban yang menunjukkan inisiatif dan kerjasama.', '2026-05-09 20:14:39', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 101);
