INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (12048, 1, NULL, 1, NULL, NULL, NULL, 'Integrasi nasional seharusnya dimulai dari pejabat negara sehingga bisa memberikan contoh bagi warga negara. Salah satu tindakan pejabat negara yang tidak mendukung integritas negara adalah praktik korupsi. Komisi Pemberantasan Korupsi (KPK) merupakan lembaga negara yang dibentuk untuk menyelidiki kasus kejahatan luar biasa korupsi, kolusi, dan nepotisme(KKN). Berbagai kasus korupsi mencuat ke permukaan. KPK berhasil mengungkap dan menangkap pelakunya. Akan tetapi, kasus korupsi masih marak terjadi. Upaya paling tepat yang dapat dilakukan masyarakat untuk menghentikan praktik kejahatan luar biasa tersebut adalah ....', NULL, 'Menjatuhkan sanksi berat terhadap terdakwa kasus korupsi', NULL, 'Menegakkan hukum setegak-tegaknya tanpa pandang bulu', NULL, 'Melakukan sosialisasi terkait tindak pidana korupsi dan dampaknya', NULL, 'Mengembangkan sikap sadar hukum dalam kehidupan mulai dari lingkungan terkecil', NULL, 'Membuat peraturan perundang-undangan tanpa memberi celah untuk berkembangnya praktik korupsi.', NULL, 'B', 'Upaya paling tepat yang dapat dilakukan masyarakat untuk menghentikan praktik korupsi adalah menegakkan hukum setegak-tegaknya tanpa pandang bulu.', NULL, 'Pilih jawaban yang menunjukkan penegakan hukum yang tegas.', '2026-05-09 20:14:39', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 25);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (12054, 1, NULL, 65, NULL, NULL, NULL, 'Kebersihan lingkungan adalah tanggung jawab kita bersama. Kita harus memulainya dari bagian terkecil dari kebersihan lingkungan, yaitu diri kita sendiri. Kita dapat memulainya dari hal - hal sederhana, seperti tidak membuang sampah sembarangan, dan senantiasa menjaga kebersihan diri. Setelah berhasil dari diri kita, kita dapat melanjutkan upaya kita kepada lingkungan terdekat, seperti keluarga, dan tetangga. Dengan terciptanya kesadaran bersama, kebersihan lingkungan bukan merupakan tanggung jawab yang berat. Ide pokok dari bacaan di atas adalah ...', NULL, 'Kebersihan diri lebih utama dari kebersihan lingkungan', NULL, 'Kebersihan lingkungan adalah tanggung jawab bersama', NULL, 'Kesadaran bersama penting untuk keberhasilan kebersihan lingkungan', NULL, 'Kebersihan lingkungan bukan tanggung jawab yang berat', NULL, 'Kebersihan lingkungan adalah tanggung jawab pribadi', NULL, 'B', 'Ide pokok dari bacaan di atas adalah kebersihan lingkungan adalah tanggung jawab bersama.', NULL, 'Cari ide pokok dari bacaan.', '2026-05-09 20:14:39', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 9);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (12055, 1, NULL, 65, NULL, NULL, NULL, 'Kebersihan lingkungan adalah tanggung jawab kita bersama. Kita harus memulainya dari bagian terkecil dari kebersihan lingkungan, yaitu diri kita sendiri. Kita dapat memulainya dari hal - hal sederhana, seperti tidak membuang sampah sembarangan, dan senantiasa menjaga kebersihan diri. Setelah berhasil dari diri kita, kita dapat melanjutkan upaya kita kepada lingkungan terdekat, seperti keluarga, dan tetangga. Dengan terciptanya kesadaran bersama, kebersihan lingkungan bukan merupakan tanggung jawab yang berat. Berdasarkan isinya, bacaan di atas termasuk jenis karangan ...', NULL, 'Narasi', NULL, 'Deskripsi', NULL, 'Eksposisi', NULL, 'Persuasi', NULL, 'Analisis', NULL, 'C', 'Berdasarkan isinya, bacaan di atas termasuk jenis karangan Eksposisi karena menjelaskan tentang kebersihan lingkungan.', NULL, 'Pahami jenis-jenis karangan.', '2026-05-09 20:14:39', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 9);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (12116, 3, NULL, 49, NULL, NULL, NULL, 'Pada pertemuan keluarga dalam rangka merayakan hari raya, saya:', NULL, 'Berusaha menjajaki peluang untuk mendapatkan kesempatan pengembangan masa depan saya', NULL, 'Mengarahkan pembicaraan pada hal-hal yang memungkinkan orang lain mengetahui kelebihan saya', NULL, 'Berusaha memuaskan tamu dengan menjamu tamu sebaik-baiknya', NULL, 'Menunggu kesempatan untuk mendapatkan tawaran bagi pengembangan masa depan saya', NULL, 'Menjamu dengan ramah sambil menunjukkan kelemahan saya', NULL, 'A', 'Pilihan jawaban A adalah yang paling tepat karena menunjukkan inisiatif dan orientasi pada pengembangan.', NULL, 'Pilih jawaban yang menunjukkan inisiatif dan orientasi pada pengembangan.', '2026-05-09 20:14:39', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 141);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (12175, 1, NULL, 2, NULL, NULL, NULL, 'Indonesia dianugerahi kekayaan yang tidak hanya terbatas pada alam tetapi juga keragaman budaya, suku, bahkan agama oleh sang pencipta. Dalam kerangka mempertahankan anugerah budaya tersebut, perilaku yang dapat dilakukan oleh warga Negara Indonesia adalah...', NULL, 'Menghormati budaya yang ada di masyarakat dengan segala kelebihan dan kekurangannya', NULL, 'Membuang jauh-jauh tradisi yang sudah tidak relevan dengan perkembangan zaman', NULL, 'Menyukai budaya luar negeri yang baik-baik untuk diterapkan dan dilakukan di Indonesia', NULL, 'Meyakini bahwa budaya sendiri paling benar sehingga tidak perlu budaya orang lain', NULL, 'Fokus terhadap teknologi dan meninggalkan budaya yang tidak mau menerima teknologi', NULL, 'A', 'Pilihan A adalah yang paling tepat. Menghormati budaya menunjukkan sikap menghargai keragaman dan menerima perbedaan. Mengakui kelebihan dan kekurangan budaya yang ada merupakan bentuk toleransi dan keterbukaan. Sikap ini membantu mempertahankan anugerah budaya Indonesia.', NULL, 'Pilih jawaban yang mencerminkan sikap menghormati keragaman budaya Indonesia.', '2026-05-09 20:14:39', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 1);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (12180, 1, NULL, 25, NULL, NULL, NULL, 'Perbedaan pandangan antar golongan agama (Islam) dan nasionalis dalam perumusan pancasila sebagai dasar negara di Sidang BPUPKI menunjukkan bahwa perbedaan pandangan merupakan hal biasa dan wajar terjadi dalam memutuskan sesuatu. Proses yang terjadi pada masa perumusan dan penetapan UUD 1945 di sidang BPUPKI menunjukkan bahwa...', NULL, 'Golongan Islam adalah golongan mayoritas yang pendapatnya harus diakomodasi', NULL, 'Merumuskan dasar Negara bukan hal mudah dalam mendirikan sebuah Negara berdaulat', NULL, 'Perbedaan pandangan seringkali memunculkan pertentangan dan rentan konflik horizontal', NULL, 'Sidang BPUPKI mengakomodasi perbedaan kepentingan dan pandangan anggota sidang', NULL, 'Pancasila merupakan hasil kesepakatan bersama antara dua golongan yang berbeda pandangan', NULL, 'D', 'Pilihan D adalah yang paling tepat. Sidang BPUPKI mengakomodasi berbagai pandangan dari kelompok Islam dan nasionalis, sehingga kesepakatan yang diambil dapat diterima oleh semua pihak. Perumusan dasar negara Pancasila menunjukkan sikap saling menghormati dan kemampuan untuk berkompromi demi kepentingan bersama.', NULL, 'Pilih jawaban yang mencerminkan pengakomodasian perbedaan pandangan dalam proses perumusan dasar negara.', '2026-05-09 20:14:39', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 4);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (12181, 1, NULL, 1, NULL, NULL, NULL, 'UUD NRI 1945 pasal 28J ayat 1 menyebutkan bahwa setiap orang wajib menghormati hak asasi manusia orang lain dalam tertib kehidupan bermasyarakat, berbangsa, dan bernegara. Dari bunyi pasal tersebut, perilaku yang mencerminkan sikap kesadaran nasionalisme adalah...', NULL, 'Menuntut hak terlebih dahulu agar dapat melaksanakan kewajiban secara baik', NULL, 'Melaksanakan kewajiban dengan harapan akan mendapatkan hak yg sesuai', NULL, 'Menyadari bahwa di dalam hak orang ada kewajiban kita yg harus dilaksanakan', NULL, 'Menyadari bahwa setiap orang mempunyai kemampuan memaksakan hak dan kewajiban', NULL, 'Menghafal tentang rumusan hak asasi manusia untuk menambahkan pengetahuan', NULL, 'C', 'Pilihan C adalah yang paling tepat. Pernyataan ini menunjukkan bahwa setiap individu menyadari keterkaitan antara hak orang lain dan kewajiban pribadi. Dengan menghormati hak orang lain, seseorang melaksanakan kewajibannya sebagai warga negara yang baik.', NULL, 'Pilih jawaban yang menekankan kesadaran akan kewajiban dalam konteks hak orang lain.', '2026-05-09 20:14:39', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 30);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (12182, 1, NULL, 1, NULL, NULL, NULL, 'UUD NRI 1945 pasal 22E ayat 1 menyebutkan bahwa pemilu dilaksanakan secara langsung, umum, bebas, rahasia, jujur dan adil setiap lima tahun sekali. Dari pernyataan pasal tersebut, perilaku yang mencerminkan sikap nasionalisme adalah...', NULL, 'Budi menggunakan hak pilihnya dalam pemilukada karena kewajiban sebagai warga negara', NULL, 'Arman menggunakan hak dalam pemilukada karena ada keluarganya yg mencalonkan diri', NULL, 'Dadang memaksa keluarga dan tetanggayua agar memilih pasangan tertentu dalam pemilukada', NULL, 'Tuti menggunakan hak pilihnya dalam pemilu karena mendapat tugas dari sekolahnya', NULL, 'Marlena menggunakan hak pilih atas dasar hati nurani dan program kerja partai politik', NULL, 'E', 'Pilihan E adalah yang paling tepat. Marlena menggunakan hak pilihnya secara bebas dan bertanggung jawab, sesuai dengan hati nuraninya dan berdasarkan evaluasi terhadap program kerja partai politik. Sikap ini mencerminkan prinsip pemilu yang langsung, umum, bebas, rahasia, jujur, dan adil.', NULL, 'Pilih jawaban yang mencerminkan penggunaan hak pilih secara bebas dan bertanggung jawab berdasarkan pertimbangan pribadi.', '2026-05-09 20:14:39', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 30);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (12244, 1, NULL, 26, NULL, NULL, NULL, 'Perbandingan ideologi Pancasila dengan ideologi liberalisme yang benar, yaitu...', NULL, 'Pancasila merupakan hukum untuk menjunjung tinggi keadilan dan keberadaan individu serta masyarakat, sedangkan liberalisme adalah hukum untuk melindungi individu', NULL, 'Pancasila adalah kitab suci sebagai dasar hukum, sedangkan liberalisme adalah demokrasi untuk kolektivitas', NULL, 'Pancasila demi kolektivitas berarti demi negara, sedangkan peran negara dalam liberalisme untuk pemerataan', NULL, 'Pancasila menganggap masyarakat lebih penting daripada individu, sedangkan liberalisme sebaliknya', NULL, 'Menurut Pancasila, individu akan memiliki arti jika hidup di tengah masyarakat, sedangkan liberalisme menganggap individu tidak penting', NULL, 'A', 'Pancasila menyeimbangkan kepentingan individu dan masyarakat, sedangkan liberalisme lebih fokus pada perlindungan individu.', NULL, 'Pahami perbedaan Pancasila dengan ideologi liberalisme.', '2026-05-09 20:18:06', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 4);
