INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (12811, 1, NULL, 65, NULL, NULL, NULL, 'Kebersihan lingkungan adalah tanggung jawab kita bersama. Kita harus memulainya dari bagian terkecil dari kebersihan lingkungan, yaitu diri kita sendiri. Kita dapat memulainya dari hal - hal sederhana, seperti tidak membuang sampah sembarangan, dan senantiasa menjaga kebersihan diri. Setelah berhasil dari diri kita, kita dapat melanjutkan upaya kita kepada lingkungan terdekat, seperti keluarga, dan tetangga. Dengan terciptanya kesadaran bersama, kebersihan lingkungan bukan merupakan tanggung jawab yang berat. Ide pokok dari bacaan di atas adalah ...', NULL, 'Kebersihan diri lebih utama dari kebersihan lingkungan', NULL, 'Kebersihan lingkungan adalah tanggung jawab bersama', NULL, 'Kesadaran bersama penting untuk keberhasilan kebersihan lingkungan', NULL, 'Kebersihan lingkungan bukan tanggung jawab yang berat', NULL, 'Kebersihan lingkungan adalah tanggung jawab pribadi', NULL, 'B', 'Ide pokok dari bacaan di atas adalah kebersihan lingkungan adalah tanggung jawab bersama.', NULL, 'Cari ide pokok dari bacaan.', '2026-05-09 20:18:08', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 9);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (12812, 1, NULL, 65, NULL, NULL, NULL, 'Kebersihan lingkungan adalah tanggung jawab kita bersama. Kita harus memulainya dari bagian terkecil dari kebersihan lingkungan, yaitu diri kita sendiri. Kita dapat memulainya dari hal - hal sederhana, seperti tidak membuang sampah sembarangan, dan senantiasa menjaga kebersihan diri. Setelah berhasil dari diri kita, kita dapat melanjutkan upaya kita kepada lingkungan terdekat, seperti keluarga, dan tetangga. Dengan terciptanya kesadaran bersama, kebersihan lingkungan bukan merupakan tanggung jawab yang berat. Berdasarkan isinya, bacaan di atas termasuk jenis karangan ...', NULL, 'Narasi', NULL, 'Deskripsi', NULL, 'Eksposisi', NULL, 'Persuasi', NULL, 'Analisis', NULL, 'C', 'Berdasarkan isinya, bacaan di atas termasuk jenis karangan Eksposisi karena menjelaskan tentang kebersihan lingkungan.', NULL, 'Pahami jenis-jenis karangan.', '2026-05-09 20:18:08', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 9);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (12835, 2, NULL, 25, NULL, NULL, NULL, 'Semua penyelam adalah perenang. Sementara penyelam adalah pelaut.', NULL, 'Sementara pelaut adalah perenang', NULL, 'Sementara perenang bukan penyelam', NULL, 'Semua pelaut adalah perenang', NULL, 'Sementara penyelam bukan pelaut', NULL, 'Sementara penyelam bukan perenang', NULL, 'D', 'Premis: Semua penyelam adalah perenang. Premis: Sementara penyelam adalah pelaut. Kesimpulan yang logis adalah sementara penyelam bukan pelaut.', NULL, 'Untuk soal logika, ikuti premis yang diberikan.', '2026-05-09 20:18:08', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 4);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (12940, 1, NULL, 1, NULL, NULL, NULL, 'Dalam menjaga nilai-nilai nasionalisme, pendidikan di Indonesia mengajarkan mata pelajaran yang berfokus pada sejarah perjuangan bangsa. Tujuan utama dari pengajaran sejarah perjuangan kemerdekaan adalah...', NULL, 'agar generasi muda mengetahui penderitaan masa lalu tanpa belajar dari pengalaman', NULL, 'untuk membuat generasi muda membenci negara-negara lain', NULL, 'membangun kebanggaan dan rasa cinta tanah air melalui pemahaman terhadap perjuangan para pahlawan', NULL, 'memperkenalkan ide-ide budaya dari bangsa lain', NULL, 'membuat generasi muda melupakan budaya lokal', NULL, 'C', 'Pilihan C adalah yang paling tepat. Mempelajari sejarah perjuangan kemerdekaan memberikan pemahaman tentang pengorbanan para pahlawan dalam memperjuangkan kemerdekaan. Hal ini bertujuan untuk menumbuhkan rasa bangga dan cinta terhadap tanah air pada generasi muda.', NULL, 'Pilih jawaban yang menekankan pembangunan kebanggaan dan rasa cinta tanah air.', '2026-05-09 20:18:08', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 24);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (12941, 1, NULL, 1, NULL, NULL, NULL, 'Salah satu wujud nasionalisme dalam kehidupan ekonomi adalah adanya gerakan untuk mencintai produk dalam negeri. Gerakan ini bertujuan untuk...', NULL, 'meningkatkan ketergantungan pada produk asing', NULL, 'mengurangi ekspor produk-produk dalam negeri', NULL, 'memperkuat perekonomian nasional dan menciptakan lapangan kerja lokal', NULL, 'mendukung perusahaan asing dalam memasarkan produk mereka di Indonesia', NULL, 'memperbesar utang negara dengan mengimpor barang', NULL, 'C', 'Pilihan C adalah yang paling tepat. Dengan mencintai produk dalam negeri, masyarakat turut memperkuat perekonomian lokal dan mengurangi ketergantungan pada barang-barang impor. Ini juga membuka lebih banyak lapangan kerja bagi masyarakat Indonesia.', NULL, 'Pilih jawaban yang mencerminkan penguatan ekonomi nasional dan penciptaan lapangan kerja lokal.', '2026-05-09 20:18:08', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 21);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (12942, 1, NULL, 33, NULL, NULL, NULL, 'Seiring dengan perkembangan teknologi, generasi muda dapat menunjukkan rasa nasionalisme melalui media digital. Salah satu contoh nyata adalah...', NULL, 'menyebarkan konten hoaks tentang pemerintah Indonesia', NULL, 'mempromosikan keindahan wisata Indonesia di media sosial', NULL, 'mengikuti budaya populer asing tanpa seleksi', NULL, 'menggunakan media sosial hanya untuk kepentingan pribadi', NULL, 'mengkritik budaya lokal secara terbuka di forum internasional', NULL, 'B', 'Pilihan B adalah yang paling tepat. Melalui media digital, generasi muda dapat memanfaatkan media sosial untuk memperkenalkan keindahan alam, budaya, dan potensi wisata Indonesia ke dunia. Ini adalah bentuk nyata dari nasionalisme digital yang memperlihatkan kebanggaan terhadap tanah air.', NULL, 'Pilih jawaban yang mencerminkan promosi positif tentang Indonesia di media digital.', '2026-05-09 20:18:08', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 5);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (12943, 1, NULL, 95, NULL, NULL, NULL, 'Nilai nasionalisme di bidang pendidikan dapat ditunjukkan dengan mengutamakan pendidikan karakter dan kebangsaan. Salah satu cara yang dapat dilakukan sekolah untuk menanamkan nilai-nilai ini pada siswa adalah...', NULL, 'mengajarkan pentingnya hanya fokus pada pendidikan akademik', NULL, 'mengenalkan lagu-lagu perjuangan dan Pancasila sejak dini', NULL, 'mempromosikan budaya populer dari negara-negara maju', NULL, 'membatasi akses informasi siswa tentang sejarah Indonesia', NULL, 'mendorong siswa untuk menggunakan bahasa asing dalam semua pelajaran', NULL, 'B', 'Pilihan B adalah yang paling tepat. Dengan mengenalkan lagu-lagu perjuangan, nilai-nilai Pancasila, dan pendidikan karakter, siswa dapat menumbuhkan rasa cinta tanah air dan penghargaan terhadap perjuangan bangsa. Pendidikan ini berperan penting dalam membentuk generasi yang memiliki rasa nasionalisme yang tinggi.', NULL, 'Pilih jawaban yang menekankan pengenalan nilai-nilai perjuangan dan Pancasila sejak dini.', '2026-05-09 20:18:08', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 12);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (12944, 1, NULL, 1, NULL, NULL, NULL, 'Indonesia adalah negara yang sangat beragam dengan berbagai suku, agama, dan budaya. Di tengah keberagaman ini, ada kelompok-kelompok yang berusaha untuk memperjuangkan kepentingan kelompoknya sendiri tanpa memperhatikan kepentingan bersama. Jika Anda adalah seorang pemimpin daerah, tindakan apa yang paling tepat dilakukan untuk mengatasi potensi konflik ini dan tetap menjaga nasionalisme?', NULL, 'Menerapkan aturan yang sama untuk semua kelompok tanpa terkecuali', NULL, 'Meminta pemerintah pusat untuk mengawasi kelompok-kelompok tersebut', NULL, 'Melakukan pendekatan dengan tokoh-tokoh masyarakat setempat dan menyosialisasikan pentingnya persatuan nasional', NULL, 'Melarang kelompok-kelompok tersebut untuk mengadakan kegiatan mereka', NULL, 'Menetapkan peraturan yang memihak salah satu kelompok terbesar di daerah tersebut', NULL, 'C', 'Pilihan C adalah yang paling tepat. Sebagai pemimpin, pendekatan yang lebih efektif adalah dengan menggandeng tokoh-tokoh masyarakat yang memiliki pengaruh dalam komunitas mereka untuk bersama-sama mempromosikan nilai persatuan. Melalui sosialisasi tentang pentingnya persatuan, masyarakat akan lebih memahami pentingnya nasionalisme dan mengurangi potensi konflik.', NULL, 'Pilih jawaban yang mencerminkan pendekatan dialogis dengan tokoh masyarakat untuk mempromosikan persatuan.', '2026-05-09 20:18:08', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 1);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (12964, 2, NULL, 25, NULL, NULL, NULL, '9, 7, 20, 18, 31, 29, 42, ..., 53, 51, ...', NULL, '41, 63', NULL, '55, 49', NULL, '47, 49', NULL, '40, 49', NULL, '40, 64', NULL, 'E', 'Pola: -2, +13, -2, +13, -2, +13. 42-2=40, 40+13=53. Pola berulang: -2, +13.', NULL, 'Untuk deret angka, cari pola berulang seperti penjumlahan/pengurangan yang konsisten.', '2026-05-09 20:20:47', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 4);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (13044, 3, NULL, 49, NULL, NULL, NULL, 'Jika Anda dituntut untuk menyelesaikan pekerjaan lebih cepat dari biasanya, maka tindakan Anda seharusnya...', NULL, 'Mengerjakan dengan penuh tanggung jawab dan seoptimal mungkin', NULL, 'Mengerjakan semampu Anda', NULL, 'Menyuruh orang lain yang dapat mengerjakan tugas tersebut lebih cepat dari Anda', NULL, 'Menolak tuntutan tersebut', NULL, 'Meninggalkan pekerjaan tersebut', NULL, 'A', 'Jawaban A menunjukkan tanggung jawab dan optimalitas dalam bekerja, yang merupakan sikap profesional.', NULL, 'Pilih jawaban yang menunjukkan tanggung jawab dan profesionalisme.', '2026-05-09 20:20:47', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 130);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (13091, 3, NULL, 49, NULL, NULL, NULL, 'Apakah Anda merasa sebagai orang yang senang berbagi rahasia dengan orang lain?', NULL, 'Sangat senang', NULL, 'Senang', NULL, 'Biasa saja', NULL, 'Tidak senang', NULL, 'Anda merasa itu bukan diri Anda', NULL, 'C', 'Biasa saja menunjukkan sikap selektif dalam berbagi rahasia, tidak terlalu terbuka tetapi juga tidak terlalu tertutup.', NULL, 'Pilih jawaban yang menunjukkan sikap selektif dan bijaksana.', '2026-05-09 20:20:47', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 138);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (13139, 1, NULL, 2, NULL, NULL, NULL, 'Pergantian sistem pemerintahan yang berlaku di Indonesia pada tahun 1945 didasarkan pada...', NULL, 'Maklumat Wakil Presiden Nomor IX Tanggal 16 Oktober 1945', NULL, 'Maklumat Wakil Presiden Nomor XI Tanggal 16 Oktober 1945', NULL, 'Maklumat Pemerintah Tanggal 3 November 1945', NULL, 'Maklumat Pemerintah Tanggal 14 November 1945', NULL, 'Konsep dasar', NULL, 'D', 'Pergantian sistem pemerintahan didasarkan pada Maklumat Pemerintah Tanggal 14 November 1945.', NULL, 'Hafalkan maklumat-maklumat pemerintahan setelah proklamasi.', '2026-05-09 20:20:47', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 1);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (13229, 1, NULL, 97, NULL, NULL, NULL, 'Menurut informasi terdapat 228 penangkapan terorisme sepanjang tahun 2020 yang berencana untuk meledakkan lembaga resmi pemerintah maupun tempat-tempat ibadah. Hal ini tentu saja menjadi gambaran yang cukup berbahaya. Bagaimana pendapat anda?', NULL, 'Hal tersebut wajar terjadi karena munculnya ketidakpercayaan masyarakat terhadap pemerintah', NULL, 'Adanya gambaran kasus ini menjadi polemik karena radikalisme telah masuk di tengah masyarakat Indonesia', NULL, 'Kita harus mengantisipasi adanya paham radikalisme dan juga ujaran kebencian mengingat adanya kasus ini menjadi bukti bahwa di tengah masyarakat telah terjadi penyebaran radikalisme', NULL, 'Biasa saja karena kasus tersebut tidak terlalu menimbulkan efek yang', NULL, 'Radikalisme tidak bisa diangkat dari beberapa oknum yang terbukti melakukan terorisme', NULL, 'C', 'Kita harus mengantisipasi radikalisme dan ujaran kebencian sebagai bentuk pertahanan negara.', NULL, 'Pilih jawaban yang menunjukkan sikap antisipatif terhadap radikalisme.', '2026-05-09 20:20:47', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 13);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (13309, 3, NULL, 49, NULL, NULL, NULL, 'Anda sedang mengerjakan tugas mata kuliah di perpustakaan dan meminjam komputer di sana. Saat sedang mengetik, tiba-tiba komputer tersebut mati. Yang akan anda lakukan adalah...', NULL, 'Browsing di internet tentang cara memperbaiki komputer yang tiba-tiba mati lalu mencobanya', NULL, 'Segera melapor kepada petugas perpustakaan tentang kerusakan dan meminta bantuan untuk mendapatkan kembali tugas yang sedang diketik', NULL, 'Menelpon teman anak IT dan meminta bantuannya untuk memperbaiki komputer perpustakaan', NULL, 'Segera pindah ke komputer sebelah yang kosong lalu mengetik semua tugas dari awal', NULL, 'Mengecek apakah ada kabel yang tercabut lalu mencoba me-restart komputer untuk menyelamatkan tugas', NULL, 'E', 'Jawaban E menunjukkan sikap tenang dan mencoba solusi praktis terlebih dahulu.', NULL, 'Pilih jawaban yang menunjukkan sikap tenang dan praktis.', '2026-05-09 20:20:47', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 110);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (13338, 1, NULL, 1, NULL, NULL, NULL, 'Mengembangkan sikap bahwa bangsa Indonesia merupakan bagian dari seluruh umat manusia merupakan perwujudan sila...', NULL, 'Pertama', NULL, 'Kedua', NULL, 'Ketiga', NULL, 'Keempat', NULL, 'Kelima', NULL, 'B', 'Sila kedua Pancasila adalah Kemanusiaan yang adil dan beradab, yang menekankan kemanusiaan universal.', NULL, 'Hafalkan sila-sila Pancasila dan maknanya.', '2026-05-09 20:20:47', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 22);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (13549, 3, NULL, 49, NULL, NULL, NULL, 'Anda adalah seorang kepala seksi di sebuah dinas pelayanan publik yang baru saja diberi tanggung jawab untuk menangani keluhan masyarakat mengenai lambatnya proses perizinan usaha. Setelah mengadakan diskusi dengan pegawai, Anda mendapat bahwa sebagian besar dari mereka merasa kurang termotivasi akibat minimnya sumber daya yang tersedia serta kurangnya apresiasi dari pimpinan atas kinerja mereka. Langkah pertama apa yang sebaiknya Anda ambil untuk mulai mengatasi situasi ini?', NULL, 'Mengajukan permintaan ke pimpinan untuk menambah sumber daya dan menyusun kebijakan yang meningkatkan apresiasi bagi pegawai yang bekerja keras', NULL, 'Mengadakan pertemuan dengan pegawai untuk mendiskusikan masalah mereka dan mencari solusi yang dapat diterapkan segera', NULL, 'Mengidentifikasi kebutuhan tambahan sumber daya dan menyarankan kepada pimpinan agar dilakukan peningkatan fasilitas pelayanan', NULL, 'Melakukan evaluasi kinerja pegawai secara menyeluruh untuk memahami akar permasalahan, lalu merumuskan langkah perubahan sistem', NULL, 'Mendorong pimpinan untuk memberikan insentif kepada pegawai dan memperbaiki sistem kerja agar kinerja lebih efektif dan terorganisir', NULL, 'E', 'Pilihan jawaban E adalah poin dengan skor tertinggi (5) karena melakukan langkah strategis yang menyeluruh, yaitu mendorong pimpinan untuk memberikan insentif kepada pegawai sekaligus memperbaiki sistem kerja. Langkah ini tidak hanya meningkatkan motivasi pegawai, tetapi juga memperbaiki efektivitas layanan secara keseluruhan.', NULL, 'Pilih jawaban yang menunjukkan solusi menyeluruh dan strategis.', '2026-05-09 20:20:48', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 119);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (13573, 1, NULL, 65, NULL, NULL, NULL, 'Kebersihan lingkungan adalah tanggung jawab kita bersama. Kita harus memulainya dari bagian terkecil dari kebersihan lingkungan, yaitu diri kita sendiri. Kita dapat memulainya dari hal - hal sederhana, seperti tidak membuang sampah sembarangan, dan senantiasa menjaga kebersihan diri. Setelah berhasil dari diri kita, kita dapat melanjutkan upaya kita kepada lingkungan terdekat, seperti keluarga, dan tetangga. Dengan terciptanya kesadaran bersama, kebersihan lingkungan bukan merupakan tanggung jawab yang berat. Ide pokok dari bacaan di atas adalah ...', NULL, 'Kebersihan diri lebih utama dari kebersihan lingkungan', NULL, 'Kebersihan lingkungan adalah tanggung jawab bersama', NULL, 'Kesadaran bersama penting untuk keberhasilan kebersihan lingkungan', NULL, 'Kebersihan lingkungan bukan tanggung jawab yang berat', NULL, 'Kebersihan lingkungan adalah tanggung jawab pribadi', NULL, 'B', 'Ide pokok dari bacaan di atas adalah kebersihan lingkungan adalah tanggung jawab bersama.', NULL, 'Cari ide pokok dari bacaan.', '2026-05-09 20:20:48', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 9);
