INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (13707, 1, NULL, 24, NULL, NULL, NULL, 'Pemerintah Indonesia berupaya menjaga kedaulatan di wilayah perbatasan dengan meningkatkan pembangunan infrastruktur dan ekonomi di daerah tersebut. Namun, dalam beberapa kasus, wilayah perbatasan masih menghadapi masalah seperti penyelundupan dan infiltrasi dari negara tetangga. Menurut Anda, apa solusi yang paling efektif untuk memperkuat nasionalisme dan kedaulatan di wilayah perbatasan ini?', NULL, 'Membangun lebih banyak pos penjagaan militer', NULL, 'Meningkatkan kesejahteraan masyarakat di wilayah perbatasan melalui pendidikan dan akses kesehatan', NULL, 'Membatasi akses keluar-masuk wilayah perbatasan bagi masyarakat setempat', NULL, 'Meningkatkan kerjasama militer dengan negara tetangga', NULL, 'Memindahkan masyarakat di perbatasan ke wilayah yang lebih aman', NULL, 'B', 'Pilihan B adalah yang paling tepat. Dengan meningkatkan kesejahteraan dan menyediakan fasilitas pendidikan dan kesehatan yang memadai, masyarakat akan merasa lebih diperhatikan dan memiliki rasa nasionalisme yang kuat. Ketika masyarakat di perbatasan sejahtera, mereka akan menjadi pelindung alami dari infiltrasi dan penyelundupan.', NULL, 'Pilih jawaban yang menekankan peningkatan kesejahteraan masyarakat perbatasan untuk memperkuat nasionalisme.', '2026-05-09 20:20:48', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 3);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (13708, 1, NULL, 1, NULL, NULL, NULL, 'Di era digital, generasi muda sering terpapar dengan budaya populer dari luar negeri melalui media sosial. Sementara budaya asing dapat memberikan dampak positif, banyak juga yang khawatir akan hilangnya identitas nasional di kalangan generasi muda. Sebagai seorang pendidik, langkah apa yang bisa Anda lakukan untuk menyeimbangkan pengaruh budaya asing dengan penanaman nilai-nilai nasionalisme?', NULL, 'Melarang siswa mengakses media sosial untuk menghindari pengaruh budaya asing', NULL, 'Mengintegrasikan nilai-nilai budaya lokal dalam kurikulum sekolah dan mendorong siswa untuk bangga dengan budaya Indonesia', NULL, 'Mengadakan kegiatan belajar mengajar dengan menggunakan bahasa asing sebagai pengantar utama', NULL, 'Mewajibkan siswa untuk menghafal sejarah perjuangan bangsa Indonesia', NULL, 'Mengadakan seminar yang hanya membahas budaya asing dan manfaatnya', NULL, 'B', 'Pilihan B adalah yang paling tepat. Sebagai pendidik, memberikan pemahaman mengenai pentingnya budaya lokal dan mempromosikan kebanggaan terhadap identitas nasional merupakan cara yang efektif untuk menanamkan nilai nasionalisme. Ini memungkinkan siswa untuk mengenal dan mencintai budayanya sambil tetap memahami budaya asing secara kritis.', NULL, 'Pilih jawaban yang mencerminkan integrasi budaya lokal dalam kurikulum untuk membangun kebanggaan nasional.', '2026-05-09 20:20:48', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 23);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (13709, 1, NULL, 33, NULL, NULL, NULL, 'Nasionalisme ekonomi di Indonesia dapat diwujudkan melalui berbagai kebijakan yang mengutamakan produk lokal. Namun, di pasar global, produk asing sering kali lebih diminati karena kualitas dan harganya yang kompetitif. Apa yang sebaiknya dilakukan pemerintah untuk meningkatkan daya saing produk lokal di pasar internasional tanpa mengurangi semangat nasionalisme dalam negeri?', NULL, 'Meningkatkan pajak untuk semua produk impor agar produk lokal lebih murah', NULL, 'Memberikan pelatihan dan inovasi teknologi kepada pelaku usaha lokal untuk meningkatkan kualitas produk', NULL, 'Membatasi perdagangan internasional dengan hanya mengizinkan produk lokal beredar di pasar', NULL, 'Menghimbau masyarakat untuk menggunakan produk lokal walaupun kualitasnya rendah', NULL, 'Mengimpor bahan baku dari negara lain untuk menurunkan biaya produksi', NULL, 'B', 'Pilihan B adalah yang paling tepat. Dengan memberikan pelatihan dan bantuan teknologi, produk lokal dapat bersaing secara lebih kompetitif di pasar internasional. Hal ini membantu meningkatkan kualitas produk nasional tanpa merusak semangat nasionalisme, karena masyarakat akan bangga menggunakan produk dalam negeri yang memiliki standar tinggi.', NULL, 'Pilih jawaban yang menekankan peningkatan kualitas produk lokal melalui pelatihan dan teknologi.', '2026-05-09 20:20:48', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 5);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (13710, 1, NULL, 2, NULL, NULL, NULL, 'Indonesia adalah negara yang kaya akan sumber daya alam, tetapi pemanfaatannya sering kali dihadapkan pada ancaman kerusakan lingkungan. Bagaimana sebaiknya pemerintah dan masyarakat mengelola sumber daya alam dengan bijak untuk menjaga keberlanjutan dan mencerminkan nasionalisme?', NULL, 'Mengeksploitasi sumber daya alam sebanyak mungkin untuk meningkatkan pendapatan negara', NULL, 'Membangun lebih banyak industri berat di kawasan hutan lindung', NULL, 'Menggalakkan program konservasi alam serta menanamkan kesadaran lingkungan di masyarakat', NULL, 'Membiarkan perusahaan asing mengambil alih pengelolaan sumber daya alam', NULL, 'Memusatkan semua pengelolaan sumber daya alam pada pemerintah pusat', NULL, 'C', 'Pilihan C adalah yang paling tepat. Pendekatan konservasi dan peningkatan kesadaran lingkungan merupakan wujud nasionalisme yang bertanggung jawab. Dengan mengelola sumber daya alam secara bijak, masyarakat dapat mempertahankan kekayaan alam untuk generasi mendatang sambil menjaga keseimbangan ekosistem yang merupakan aset bangsa.', NULL, 'Pilih jawaban yang mencerminkan pengelolaan sumber daya alam secara bijak dan berkelanjutan.', '2026-05-09 20:20:48', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 1);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (13711, 1, NULL, 97, NULL, NULL, NULL, 'Pada tahun 1945, Indonesia menyatakan kemerdekaannya melalui Proklamasi yang dibacakan oleh Ir. Soekarno dan didampingi oleh Dr. Mohammad Hatta. Sebelum proklamasi, terdapat berbagai peristiwa yang mempengaruhi jalan menuju kemerdekaan, termasuk kekalahan Jepang pada Perang Dunia II dan tekanan dari para pemuda yang menginginkan kemerdekaan segera diumumkan. Setelah Proklamasi Kemerdekaan, Indonesia masih menghadapi ancaman dari Belanda yang ingin kembali menjajah. Perjuangan untuk mempertahankan kemerdekaan terus berlanjut melalui berbagai bentuk perlawanan, baik diplomasi maupun militer. Berdasarkan konteks tersebut, salah satu bentuk perjuangan nasionalisme yang dilakukan bangsa Indonesia pasca Proklamasi adalah...', NULL, 'menyerah kepada Belanda demi tercapainya perdamaian', NULL, 'mengandalkan bantuan negara-negara Asia Tenggara untuk perlawanan', NULL, 'melakukan perlawanan militer melalui perang fisik dan perjuangan diplomasi', NULL, 'menyerahkan sebagian wilayah Indonesia untuk mendapatkan pengakuan internasional', NULL, 'membentuk pemerintahan sementara yang dipimpin oleh perwakilan Belanda', NULL, 'C', 'Pilihan C adalah yang paling tepat. Pasca Proklamasi Kemerdekaan, bangsa Indonesia menghadapi upaya Belanda untuk kembali menjajah melalui agresi militer. Bangsa Indonesia melakukan berbagai perlawanan, seperti Perang Puputan di Bali dan Pertempuran Surabaya. Selain itu, diplomasi juga dilakukan untuk mendapatkan pengakuan internasional terhadap kemerdekaan Indonesia.', NULL, 'Pilih jawaban yang mencerminkan perlawanan militer dan diplomasi untuk mempertahankan kemerdekaan.', '2026-05-09 20:20:48', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 13);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (13712, 1, NULL, 1, NULL, NULL, NULL, 'Seorang mahasiswa Pendidikan Teknik Elektro baru saja menyelesaikan studinya. Ia ditawarkan untuk melanjutkan studinya di Inggris dengan beasiswa. Meski demikian ia memilih Kembali ke kampungnya. Di kampung ia membuat pembangkit listrik sederhana dengan memanfaatkan aliran air sungai yang deras. Berkat pembangkit listrik tersebut, warga kampung sudah dapat menikmati ketersediaan listrik. Tindakan mahasiswa tersebut menunjukkan sikap...', NULL, 'Bela negara', NULL, 'Cinta tanah air', NULL, 'Patriotisme', NULL, 'Nasionalisme', NULL, 'Integritas', NULL, 'C', 'Patriotisme adalah cinta tanah air yang ditunjukkan dengan tindakan nyata. Mahasiswa tersebut memilih kembali ke kampung dan berkontribusi untuk masyarakatnya, bukan mengejar keuntungan pribadi di luar negeri.', NULL, 'Untuk soal TWK tentang sikap nasionalisme, cari jawaban yang menunjukkan tindakan nyata untuk kemajuan bangsa.', '2026-05-09 23:13:43', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 50);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (13835, 3, NULL, 49, NULL, NULL, NULL, 'Anda adalah seorang kepala instansi yang cukup bergengsi. Suatu hari, ada teman akrab Anda datang dan meminta bantuan agar menerima anaknya bekerja tanpa melalui tes. Rekan karib Anda tersebut menjanjikan jaminan berupa sejumlah uang dan fasilitas. Apa yang akan Anda lakukan?', NULL, 'Menerima tawaran tanpa jaminan karena dia sahabat Anda', NULL, 'Basa-basi dulu, lalu menerimanya karena tidak enak pada teman', NULL, 'Menolaknya mentah-mentah', NULL, 'Menolaknya secara halus dan menganjurkan agar anak rekan Anda mengikuti seleksi seperti lainnya', NULL, 'Menerimanya dan menyuruhnya mengikuti tes seleksi sebagai formalitas', NULL, 'D', 'Menolak secara halus dan menganjurkan mengikuti seleksi menunjukkan integritas dan profesionalisme sebagai kepala instansi.', NULL, 'Pilih jawaban yang menunjukkan integritas dan kepatuhan terhadap prosedur.', '2026-05-09 23:13:43', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 119);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (13980, 3, NULL, 49, NULL, NULL, NULL, 'Ketika berhasil dalam menyelesaikan tugas, Anda akan …', NULL, 'Tidak perlu berusaha lagi', NULL, 'Tetap berusaha sekuat tenaga', NULL, 'Untuk tugas berikutnya, akan mengerjakan dengan lebih baik lagi', NULL, 'Tidak puas dan berusaha lebih baik lagi', NULL, 'Berusaha sekadarnya', NULL, 'C', 'Jawaban C menunjukkan sikap terus belajar dan ingin meningkatkan kualitas kerja.', NULL, 'Pilih jawaban yang menunjukkan sikap terus belajar dan meningkatkan kualitas.', '2026-05-09 23:13:43', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 107);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (14011, 1, NULL, 1, NULL, NULL, NULL, 'Perwakilan diplomatik Indonesia yang berada di Hongkong adalah:', NULL, 'Kedutaan Besar', NULL, 'Atase Pertahanan', NULL, 'Konsulat Jenderal', NULL, 'Atase Perdagangan', NULL, 'Nuncio Apostolik', NULL, 'C', 'Perwakilan Indonesia di Hongkong adalah Konsulat Jenderal.', NULL, 'Pahami jenis perwakilan diplomatik Indonesia.', '2026-05-09 23:13:43', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 1);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (14094, 3, NULL, 49, NULL, NULL, NULL, 'Saya lupa membuat laporan keuangan yang seharusnya diserahkan pada hari ini karena selama seminggu saya mengikuti diklat diluar kota...', NULL, 'Saya meminta waktu kepada atasan untuk menyelesaikan laporan tersebut sesegera mungkin.', NULL, 'Saya meminta beberapa teman untuk membantu saya menyelesaikan laporan itu.', NULL, 'Seharusnya atasan saya memaklumi bahwa saya tidak ada waktu karena sedang mengikuti diklat.', NULL, 'Saya menyadari bahwa saya lupa mengerjakan laporan dan saya yakin dapat menyelesaikannya.', NULL, 'Saya minta maaf kepada atasan dan beralasan bahwa saya tidak sempat membuat laporan tersebut karena sedang mengikuti diklat.', NULL, 'A', 'Sikap yang baik adalah meminta waktu untuk menyelesaikan laporan.', NULL, 'Pilih jawaban yang menunjukkan tanggung jawab.', '2026-05-09 23:13:44', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 101);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (14104, 1, NULL, 26, NULL, NULL, NULL, 'Pancasila sebagai paradigma pembangunan politik harus mampu...', NULL, 'Menjadikan rakyat sebagai subjek politik bukan objek politik', NULL, 'Menjadi sumber dari segala sumber hukum', NULL, 'Pengontrol atas kekuasaan yang absolut', NULL, 'Pedoman hidup berkebangsaan', NULL, 'Memberi perlindungan hak asasi bagi rakyat', NULL, 'A', 'Pancasila sebagai paradigma pembangunan politik harus menjadikan rakyat sebagai subjek politik.', NULL, 'Pahami Pancasila sebagai paradigma pembangunan.', '2026-05-09 23:13:44', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 4);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (14237, 3, NULL, 49, NULL, NULL, NULL, 'Anda mendapatkan tugas mendadak dengan deadline singkat, sementara pekerjaan sebelumnya belum selesai. Sikap Anda adalah...', NULL, 'Menyelesaikan tugas lama terlebih dahulu', NULL, 'Menolak tugas baru', NULL, 'Mengatur prioritas dan menyelesaikan keduanya secara bertahap', NULL, 'Meminta orang lain mengerjakan tugas baru', NULL, 'Mengabaikan salah satu tugas', NULL, 'C', 'Mengatur prioritas menunjukkan kemampuan manajemen waktu dan tanggung jawab.', NULL, 'Pilih jawaban yang menunjukkan kemampuan manajemen waktu.', '2026-05-09 23:13:44', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 114);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (14256, 1, NULL, 25, NULL, NULL, NULL, 'Pedoman Penghayatan dan Pengamalan Pancasila ditetapkan pada tanggal...', NULL, '4 Maret 1978', NULL, '22 Maret 1978', NULL, '12 Maret 1978', NULL, '14 Maret 2978', NULL, '2 Maret 1978', NULL, 'B', 'Pedoman Penghayatan dan Pengamalan Pancasila (P4) ditetapkan pada tanggal 22 Maret 1978.', NULL, 'Hafalkan tanggal penetapan P4.', '2026-05-09 23:13:44', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 4);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (14368, 2, NULL, 33, NULL, NULL, NULL, 'Seperti rusa masuk kampung. Makna peribahasa ini adalah ...', NULL, 'Merasa tidak paham tentang sesuatu', NULL, 'Bingung karena tidak harus berbuat apa', NULL, 'Tercengang dan keheran-heranan melihat sesuatu yang baru', NULL, 'Orang kampung masuk kota besar', NULL, 'Orang yang tidak paham teknologi', NULL, 'C', 'Peribahasa \"Seperti rusa masuk kampung\" berarti tercengang dan keheran-heranan melihat sesuatu yang baru.', NULL, 'Pahami makna peribahasa Indonesia.', '2026-05-09 23:13:44', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 5);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (14438, 1, NULL, 50, NULL, NULL, NULL, 'Peristiwa pada 28 Oktober 1928 merupakan tonggak penting dalam sejarah lahirnya bangsa Indonesia. Para pemuda dari berbagai suku dan daerah berkumpul untuk mengikrarkan sumpah yang dikenal dengan Sumpah Pemuda. Bercermin dari peristiwa sejarah tersebut, yang tidak termasuk ke dalam nilai nasionalisme yang dapat digali dan diamalkan oleh generasi penerus bangsa adalah...', NULL, 'Kepedulian generasi muda terhadap nasib bangsa', NULL, 'Keberanian melawan kolonialisme', NULL, 'Mengorbankan semangat kesukuan dan kedaerahan dalam berjuang', NULL, 'Menunjukan eksistensi generasi muda Indonesia saat itu kepada pihak kolonial', NULL, 'Semangat kebersamaan untuk berjuang', NULL, 'D', 'Pilihan D adalah yang paling tepat. Pilihan ini tidak sejalan dengan nilai nasionalisme seperti yang tercermin dalam Sumpah Pemuda, yang lebih mengutamakan persatuan, pengorbanan, dan kepedulian terhadap nasib bangsa secara kolektif.', NULL, 'Pilih jawaban yang tidak mencerminkan nilai nasionalisme yang sejalan dengan semangat Sumpah Pemuda.', '2026-05-09 23:13:44', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 7);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (14479, 1, NULL, 1, NULL, NULL, NULL, 'Pada masa penjajahan Belanda, muncul berbagai organisasi pergerakan nasional yang bertujuan untuk mencapai kemerdekaan. Salah satu organisasi yang berperan penting dalam menanamkan semangat nasionalisme di kalangan masyarakat Indonesia adalah Budi Utomo. Organisasi ini didirikan pada tahun 1908 oleh Dr. Wahidin Sudirohusodo bersama para mahasiswa STOVIA di Batavia. Budi Utomo berfokus pada pengembangan pendidikan dan kesejahteraan masyarakat Jawa, yang kemudian menginspirasi terbentuknya berbagai organisasi lainnya. Dengan latar belakang tersebut, dapat disimpulkan bahwa kontribusi Budi Utomo terhadap perjuangan nasionalisme di Indonesia adalah...', NULL, 'mendorong penggunaan bahasa Belanda sebagai bahasa pendidikan', NULL, 'memperjuangkan hak-hak perempuan untuk mendapat pendidikan yang sama', NULL, 'menanamkan kesadaran nasional dan memperjuangkan kemajuan pendidikan bagi masyarakat Indonesia', NULL, 'menggalang dukungan dari negara-negara Eropa untuk membantu Indonesia merdeka', NULL, 'membentuk tentara nasional untuk melawan penjajah Belanda', NULL, 'C', 'Pilihan C adalah yang paling tepat. Budi Utomo berfokus pada aspek pendidikan, kesehatan, dan kesejahteraan, yang bertujuan untuk meningkatkan kualitas hidup masyarakat Indonesia, khususnya Jawa. Organisasi ini menjadi awal dari pergerakan nasionalisme di Indonesia, karena menumbuhkan kesadaran akan pentingnya persatuan dan kemajuan untuk mencapai kemerdekaan.', NULL, 'Pilih jawaban yang mencerminkan penanaman kesadaran nasional dan kemajuan pendidikan.', '2026-05-09 23:13:44', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 49);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (14480, 1, NULL, 1, NULL, NULL, NULL, 'Pasal 27 Ayat 3 UUD 1945 berbunyi: \"Setiap warga negara berhak dan wajib ikut serta dalam upaya pembelaan negara.\" Dalam konteks nasionalisme, pasal ini mengandung makna bahwa...', NULL, 'hanya tentara yang diwajibkan untuk membela negara dalam situasi darurat', NULL, 'warga negara diperbolehkan untuk mengabaikan kewajibannya jika tinggal di luar negeri', NULL, 'setiap warga negara memiliki hak dan kewajiban yang sama dalam mempertahankan kedaulatan negara', NULL, 'warga negara diharuskan untuk mengikuti pendidikan militer sejak usia dini', NULL, 'warga negara hanya perlu membela negara dalam situasi perang', NULL, 'C', 'Pilihan C adalah yang paling tepat. Pasal 27 Ayat 3 UUD 1945 menegaskan bahwa upaya pembelaan negara bukan hanya tanggung jawab militer, tetapi seluruh warga negara. Ini mencerminkan semangat nasionalisme, di mana setiap warga negara diharapkan siap berkontribusi dalam menjaga kedaulatan negara.', NULL, 'Pilih jawaban yang menekankan hak dan kewajiban setiap warga negara dalam pembelaan negara.', '2026-05-09 23:13:44', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 30);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (14481, 1, NULL, 33, NULL, NULL, NULL, 'Nasionalisme sering kali disertai dengan cinta terhadap produk dalam negeri sebagai upaya memperkuat ekonomi nasional. Dalam hal ini, gerakan yang mendukung pemakaian produk lokal dan mengurangi ketergantungan terhadap produk impor dapat berkontribusi dalam...', NULL, 'memperkuat pasar produk impor', NULL, 'meningkatkan daya saing produk lokal dan menciptakan lapangan kerja', NULL, 'menurunkan kualitas produk dalam negeri', NULL, 'mempercepat laju inflasi di sektor ekonomi lokal', NULL, 'mendukung monopoli perusahaan multinasional', NULL, 'B', 'Pilihan B adalah yang paling tepat. Dengan mendukung produk dalam negeri, masyarakat membantu memperkuat ekonomi nasional, meningkatkan daya saing produk lokal di pasar global, serta membuka lebih banyak lapangan kerja. Ini merupakan bentuk nyata dari nasionalisme ekonomi yang berdampak langsung pada kesejahteraan masyarakat Indonesia.', NULL, 'Pilih jawaban yang mencerminkan penguatan daya saing produk lokal dan penciptaan lapangan kerja.', '2026-05-09 23:13:44', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 5);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (14482, 1, NULL, 1, NULL, NULL, NULL, 'Pada masa perjuangan kemerdekaan, nasionalisme diwujudkan dalam berbagai tindakan heroik oleh para pahlawan. Salah satu peristiwa yang mencerminkan semangat nasionalisme tinggi adalah Pertempuran Surabaya pada 10 November 1945. Pertempuran ini dikenal sebagai hari pahlawan dan diperingati setiap tahun di Indonesia. Apa makna dari peringatan Hari Pahlawan ini bagi generasi muda Indonesia saat ini?', NULL, 'Mengingatkan generasi muda untuk selalu waspada terhadap bangsa asing', NULL, 'Mendorong generasi muda untuk melanjutkan perjuangan dalam mempertahankan kemerdekaan', NULL, 'Mengharuskan generasi muda untuk mempelajari seluruh strategi militer yang digunakan', NULL, 'Membuat generasi muda fokus pada nostalgia masa lalu tanpa melihat ke depan', NULL, 'Menyuruh generasi muda untuk mengenakan seragam militer setiap 10 November', NULL, 'B', 'Pilihan B adalah yang paling tepat. Peringatan Hari Pahlawan bertujuan untuk mengingat jasa para pahlawan yang telah berkorban demi kemerdekaan bangsa. Makna ini diharapkan menumbuhkan rasa cinta tanah air dan mendorong generasi muda untuk terus mengisi kemerdekaan dengan tindakan positif.', NULL, 'Pilih jawaban yang menekankan kelanjutan perjuangan dalam mengisi kemerdekaan.', '2026-05-09 23:13:44', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 49);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (14483, 1, NULL, 34, NULL, NULL, NULL, 'Gerakan nasionalisme di Indonesia tumbuh karena adanya kesadaran untuk bersatu melawan penjajahan yang menyengsarakan rakyat. Salah satu faktor eksternal yang mempengaruhi perkembangan nasionalisme di Indonesia adalah...', NULL, 'masuknya ideologi liberalisme dan sosialisme dari negara-negara Barat', NULL, 'kehadiran organisasi masyarakat dari negara-negara Eropa di Indonesia', NULL, 'pelatihan militer yang diberikan oleh Belanda kepada pemuda Indonesia', NULL, 'kebijakan Belanda yang mendukung perdagangan bebas di Indonesia', NULL, 'peningkatan peran penjajah dalam bidang kesehatan dan pendidikan', NULL, 'A', 'Pilihan A adalah yang paling tepat. Pemikiran tentang kebebasan, persamaan hak, dan perjuangan untuk keadilan mulai mempengaruhi masyarakat Indonesia, terutama setelah menyaksikan perubahan di negara-negara Barat. Hal ini memicu kesadaran untuk melawan penindasan dan memperjuangkan kemerdekaan.', NULL, 'Pilih jawaban yang mencerminkan pengaruh ideologi dari negara Barat terhadap pergerakan nasionalisme.', '2026-05-09 23:13:44', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 5);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (14620, 3, NULL, 49, NULL, NULL, NULL, 'Anda sedang menyelesaikan pekerjaan ketika kantor hampir tutup, maka Anda akan...', NULL, 'Menunda penyelesaian pekerjaan', NULL, 'Ikut rekan kerja yang mulai mengemasi barang-barang', NULL, 'Tetap berada di kantor hingga pekerjaan selesai jika ada uang lembur', NULL, 'Tetap berada di kantor hingga pekerjaan selesai tanpa uang lembur', NULL, 'Membawa pekerjaan ke rumah saja', NULL, 'D', 'Tetap menyelesaikan pekerjaan tanpa uang lembur menunjukkan tanggung jawab dan profesionalisme.', NULL, 'Pilih jawaban yang menunjukkan tanggung jawab dan profesionalisme.', '2026-05-09 23:15:37', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 110);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (14651, 3, NULL, 49, NULL, NULL, NULL, 'Anda sering mengingatkan bawahan untuk tidak melakukan kesalahan pekerjaan di kantor...', NULL, 'Anda pun tidak boleh melakukan kesalahan itu', NULL, 'Karena Anda atasannya, peraturan tidak berlaku bagi diri-sendiri', NULL, 'Anda sesekali melakukan kesalahan', NULL, 'Peraturan khusus untuk pegawai setingkat', NULL, 'Lebih baik Anda tidak melakukan kesalahan itu', NULL, 'A', 'Anda pun tidak boleh melakukan kesalahan menunjukkan keteladanan sebagai atasan.', NULL, 'Pilih jawaban yang menunjukkan keteladanan.', '2026-05-09 23:15:38', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 106);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (14767, 1, NULL, 1, NULL, NULL, NULL, 'Tindakan bullying saat ini menjadi momok yang menakutkan bagi generasi muda. Bahkan bullying bisa dilakukan dimana saja karena arus perkembangan teknologi informasi dan komunikasi yang begitu cepat. Penyebab utama kasus cyber bullying pada era milennial saat ini ditinjau dari pendekatan pilar kebangsaan disebabkan oleh...', NULL, 'Kurangnya kesadaran terhadap hukum', NULL, 'Lemahnya pendidikan dasar', NULL, 'Minimnya pengawasan yang dilakukan oleh sekolah', NULL, 'Kurangnya bimbingan konseling pada peserta didik', NULL, 'Lunturnya pemahaman terhadap nilai-nilai Pancasila', NULL, 'E', 'Lunturnya pemahaman terhadap nilai-nilai Pancasila menjadi penyebab utama cyber bullying karena Pancasila sebagai dasar moral bangsa.', NULL, 'Pilih jawaban yang berkaitan dengan nilai-nilai Pancasila sebagai pilar kebangsaan.', '2026-05-09 23:15:38', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 47);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (14935, 2, NULL, 25, NULL, NULL, NULL, 'Berbagai solusi penanganan limbah sebenarnya telah dilakukan oleh Rumah Potong Hewan di beberapa kota di Indonesia seperti Bogor, Bandung, Solo, dan Yogyakarta, baik berupa solusi pengelolaan dan penanganan limbah secara mandiri maupun melibatkan pihak luar. Pengelolaan limbah secara mandiri antara lain dengan fermentasi isi rumen sebagai bahan pakan ikan serta penggunaan kotoran ternak sebagai bahan biogas. Sementara itu, pengelolaan limbah dengan melibatkan pihak luar dilakukan dengan menggandeng pabrik pupuk kompos. Dari informasi di atas, maka kota di bawah ini yang telah melaksanakan penanganan limbah Rumah Potong Hewan, kecuali...', NULL, 'Yogyakarta', NULL, 'Bandung', NULL, 'Cilacap', NULL, 'Bogor', NULL, 'Solo', NULL, 'C', 'Cilacap tidak disebutkan dalam teks sebagai kota yang melaksanakan penanganan limbah RPH.', NULL, 'Untuk soal bacaan, perhatikan kota-kota yang disebutkan.', '2026-05-09 23:15:38', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 78);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (14980, 3, NULL, 49, NULL, NULL, NULL, 'Berpindah-pindah pekerjaan adalah hal yang wajar', NULL, 'Saya tidak berpendapat bahwa karyawan harus setia terhadap perusahaannya', NULL, 'Saya meyakini nilai-nilai yang mengatakan bahwa loyalitas terhadap pekerjaan adalah sikap yang terpuji.', NULL, 'Pekerjaan saya saat ini tidak dapat menjamin masa depan saya.', NULL, 'Saya meyakini bahwa loyalitas itu penting, sehingga saya merasakan pentingnya tanggung jawab moral karyawan.', NULL, 'Saya menyukai pekerjaan saya, tetapi jika ada pekerjaan yang lebih baik saya tidak ragu untuk pindah', NULL, 'B', 'Loyalitas adalah sikap terpuji yang harus dijaga.', NULL, 'Pilih jawaban yang menunjukkan loyalitas.', '2026-05-09 23:15:38', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 109);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (15059, 3, NULL, 49, NULL, NULL, NULL, 'Pada saat saya sedang mengerjakan suatu tugas kerja, saya akan ...', NULL, 'Sesekali menyelanya dengan kegiatan lain sebagai hiburan', NULL, 'Melakukan pekerjaan lain secara bersamaan', NULL, 'Menundanya dan melihat apakah ada tugas lain yang harus diselesaikan', NULL, 'Hanya melakukan satu pekerjaan dalam satu waktu', NULL, 'Melakukan pekerjaan lain yang tidak berhubungan dengan pekerjaan', NULL, 'D', 'Hanya melakukan satu pekerjaan dalam satu waktu menunjukkan fokus dan konsentrasi.', NULL, 'Pilih jawaban yang menunjukkan fokus dan konsentrasi.', '2026-05-09 23:15:38', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 118);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (15092, 3, NULL, 49, NULL, NULL, NULL, 'Anda mendapatkan sebuah berita hoaks tentang kebijakan baru mengenai instansi yang Anda pimpin. Informasi hoaks ini beredar luas di media sosial dan membuat kebingungan bawahan Anda. Mengingat situasi tersebut, apa langkah yang akan Anda ambil?', NULL, 'Membantah berita hoaks tersebut secara individual kepada rekan-rekan kerja Anda tanpa melakukan klarifikasi resmi.', NULL, 'Melaporkan berita hoaks tersebut kepada pimpinan tertinggi dan menunggu instruksi selanjutnya.', NULL, 'Setelah melakukan klarifikasi resmi, Anda berinisiatif untuk membuat sistem atau prosedur tetap lainnya yang dapat mempercepat proses klarifikasi berita di masa mendatang dan menyampaikan strategi ini ke pimpinan lembaga.', NULL, 'Anda mengumpulkan informasi valid untuk membantu berita hoaks tersebut dan meneruskannya kepada seluruh anggota instansi.', NULL, 'Segera melakukan klarifikasi resmi melalui saluran komunikasi internal dan menekankan kepada bawahan mengenai pentingnya digital literacy dan cara mendeteksi hoaks.', NULL, 'C', 'Pilihan ini adalah pendekatan yang paling proaktif dan berdampak. Tidak hanya berurusan dengan berita hoaks saat ini, strategi ini juga mencoba mencegah atau setidaknya mempercepat penanganan hoaks di masa mendatang. Dengan sistem ini, instansi Anda akan lebih siap untuk menangani hoaks dan misinformasi.', NULL, 'Pilih jawaban yang menunjukkan pendekatan proaktif dan berdampak.', '2026-05-09 23:15:38', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 115);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (15112, 1, NULL, 65, NULL, NULL, NULL, 'Kebersihan lingkungan adalah tanggung jawab kita bersama. Kita harus memulainya dari bagian terkecil dari kebersihan lingkungan, yaitu diri kita sendiri. Kita dapat memulainya dari hal - hal sederhana, seperti tidak membuang sampah sembarangan, dan senantiasa menjaga kebersihan diri. Setelah berhasil dari diri kita, kita dapat melanjutkan upaya kita kepada lingkungan terdekat, seperti keluarga, dan tetangga. Dengan terciptanya kesadaran bersama, kebersihan lingkungan bukan merupakan tanggung jawab yang berat. Ide pokok dari bacaan di atas adalah ...', NULL, 'Kebersihan diri lebih utama dari kebersihan lingkungan', NULL, 'Kebersihan lingkungan adalah tanggung jawab bersama', NULL, 'Kesadaran bersama penting untuk keberhasilan kebersihan lingkungan', NULL, 'Kebersihan lingkungan bukan tanggung jawab yang berat', NULL, 'Kebersihan lingkungan adalah tanggung jawab pribadi', NULL, 'B', 'Ide pokok dari bacaan di atas adalah kebersihan lingkungan adalah tanggung jawab bersama.', NULL, 'Cari ide pokok dari bacaan.', '2026-05-09 23:15:38', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 9);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (15113, 1, NULL, 65, NULL, NULL, NULL, 'Kebersihan lingkungan adalah tanggung jawab kita bersama. Kita harus memulainya dari bagian terkecil dari kebersihan lingkungan, yaitu diri kita sendiri. Kita dapat memulainya dari hal - hal sederhana, seperti tidak membuang sampah sembarangan, dan senantiasa menjaga kebersihan diri. Setelah berhasil dari diri kita, kita dapat melanjutkan upaya kita kepada lingkungan terdekat, seperti keluarga, dan tetangga. Dengan terciptanya kesadaran bersama, kebersihan lingkungan bukan merupakan tanggung jawab yang berat. Berdasarkan isinya, bacaan di atas termasuk jenis karangan ...', NULL, 'Narasi', NULL, 'Deskripsi', NULL, 'Eksposisi', NULL, 'Persuasi', NULL, 'Analisis', NULL, 'C', 'Berdasarkan isinya, bacaan di atas termasuk jenis karangan Eksposisi karena menjelaskan tentang kebersihan lingkungan.', NULL, 'Pahami jenis-jenis karangan.', '2026-05-09 23:15:38', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 9);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (15256, 1, NULL, 34, NULL, NULL, NULL, 'Nasionalisme pada masa modern tidak hanya diwujudkan dalam bentuk perlawanan fisik, tetapi juga melalui kontribusi dalam berbagai bidang. Salah satu contoh nyata dari nasionalisme di bidang teknologi adalah...', NULL, 'membeli seluruh produk teknologi dari negara maju', NULL, 'menggunakan teknologi untuk mempromosikan produk impor', NULL, 'mengembangkan teknologi lokal untuk kebutuhan nasional dan menciptakan lapangan kerja', NULL, 'menolak menggunakan teknologi untuk mempertahankan budaya lokal', NULL, 'melarang masyarakat untuk menggunakan internet demi keamanan nasional', NULL, 'C', 'Pilihan C adalah yang paling tepat. Dengan mengembangkan teknologi lokal, Indonesia dapat menjadi lebih mandiri secara ekonomi dan mengurangi ketergantungan pada negara asing. Ini juga menciptakan lapangan kerja dan meningkatkan kesejahteraan masyarakat, yang merupakan wujud nyata dari nasionalisme di bidang teknologi.', NULL, 'Pilih jawaban yang mencerminkan pengembangan teknologi lokal untuk kemandirian ekonomi.', '2026-05-09 23:15:39', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 5);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (15257, 1, NULL, 1, NULL, NULL, NULL, 'Di tengah perubahan sosial yang cepat, menjaga bahasa Indonesia sebagai bahasa nasional adalah wujud dari nasionalisme. Mengapa penting bagi generasi muda untuk tetap menggunakan bahasa Indonesia dalam kehidupan sehari-hari?', NULL, 'Agar tidak terlalu bergantung pada bahasa daerah', NULL, 'Karena bahasa Indonesia lebih mudah dipelajari daripada bahasa lain', NULL, 'Untuk memperkuat persatuan bangsa dan menjaga identitas nasional', NULL, 'Supaya bisa diterima di komunitas internasional', NULL, 'Agar budaya asing tidak memiliki pengaruh di Indonesia', NULL, 'C', 'Pilihan C adalah yang paling tepat. Bahasa Indonesia adalah bahasa pemersatu yang memungkinkan komunikasi antardaerah, mengurangi kesalahpahaman, dan mencerminkan jati diri bangsa. Dengan menjaga bahasa Indonesia, generasi muda turut serta dalam mempertahankan persatuan dan identitas Indonesia.', NULL, 'Pilih jawaban yang menekankan peran bahasa Indonesia sebagai pemersatu bangsa.', '2026-05-09 23:15:39', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 24);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (15258, 1, NULL, 1, NULL, NULL, NULL, 'Banyak tokoh perjuangan kemerdekaan yang memiliki semangat nasionalisme tinggi. Salah satunya adalah Ki Hajar Dewantara, yang dikenal sebagai Bapak Pendidikan Nasional. Perjuangan Ki Hajar Dewantara dalam mengembangkan pendidikan bertujuan untuk...', NULL, 'meningkatkan status sosial masyarakat pribumi di mata Belanda', NULL, 'memberikan pendidikan yang hanya fokus pada keterampilan militer', NULL, 'mendidik masyarakat Indonesia agar mampu berpikir kritis dan mandiri', NULL, 'menghilangkan budaya asli dan menggantinya dengan budaya Eropa', NULL, 'menyiapkan masyarakat Indonesia untuk menjadi pekerja bagi perusahaan asing', NULL, 'C', 'Pilihan C adalah yang paling tepat. Ki Hajar Dewantara memperjuangkan pendidikan sebagai alat untuk membebaskan bangsa dari kebodohan dan ketergantungan, sehingga masyarakat Indonesia bisa berpikir kritis dan mandiri dalam mengatur kehidupannya sendiri.', NULL, 'Pilih jawaban yang mencerminkan pendidikan untuk kemandirian dan pemikiran kritis.', '2026-05-09 23:15:39', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 48);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (15259, 1, NULL, 37, NULL, NULL, NULL, 'Sejak era reformasi, nasionalisme di Indonesia berkembang lebih terbuka dan melibatkan partisipasi masyarakat secara luas. Salah satu bentuk nasionalisme yang muncul adalah nasionalisme ekonomi, yaitu...', NULL, 'mendukung perusahaan asing untuk menguasai sektor penting di Indonesia', NULL, 'mengutamakan ekspor barang-barang mentah tanpa olahan', NULL, 'memperkuat produk lokal dan mengurangi ketergantungan pada impor', NULL, 'membebaskan investor asing untuk memiliki tanah di Indonesia', NULL, 'mengekspor bahan pangan strategis meskipun kebutuhan domestik belum terpenuhi', NULL, 'C', 'Pilihan C adalah yang paling tepat. Nasionalisme ekonomi mengedepankan kemandirian ekonomi dengan mendukung produk dalam negeri, yang membantu membangun ekonomi yang kuat, mengurangi ketergantungan pada negara asing, dan menciptakan lapangan kerja bagi rakyat Indonesia.', NULL, 'Pilih jawaban yang mencerminkan penguatan produk lokal dan kemandirian ekonomi.', '2026-05-09 23:15:39', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 5);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (15260, 1, NULL, 1, NULL, NULL, NULL, 'Sebagai bagian dari upaya untuk memperkuat nasionalisme di bidang ekonomi, pemerintah Indonesia meluncurkan kampanye Gerakan Bangga Buatan Indonesia. Namun, masih ada tantangan berupa anggapan bahwa produk luar negeri memiliki kualitas lebih baik. Apa langkah terbaik yang dapat diambil pemerintah untuk merubah pola pikir masyarakat ini?', NULL, 'Membatasi impor produk dari luar negeri secara ketat', NULL, 'Melakukan kampanye yang menonjolkan kualitas dan inovasi produk lokal yang kompetitif', NULL, 'Memaksa masyarakat untuk membeli produk lokal meskipun tidak sesuai dengan kebutuhan', NULL, 'Menghapus pajak untuk produk lokal dan menaikkan pajak untuk produk asing', NULL, 'Menurunkan harga produk lokal meskipun kualitasnya tidak diperbaiki', NULL, 'B', 'Pilihan B adalah yang paling tepat. Dengan mempromosikan kualitas dan inovasi produk lokal, masyarakat akan lebih percaya diri untuk membeli produk dalam negeri. Hal ini bisa dicapai dengan meningkatkan kualitas produk lokal melalui inovasi dan mengedukasi masyarakat tentang manfaat ekonomi dari menggunakan produk dalam negeri.', NULL, 'Pilih jawaban yang mencerminkan promosi kualitas dan inovasi produk lokal.', '2026-05-09 23:15:39', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 44);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (15261, 4, NULL, 65, NULL, NULL, NULL, 'Jika semua A adalah B, dan semua B adalah C, maka...', NULL, 'Semua A adalah C', NULL, 'Semua C adalah A', NULL, 'Sebagian A adalah C', NULL, 'Tidak ada hubungan', NULL, 'Sebagian C adalah A', NULL, 'A', 'Dalam logika silogisme, jika semua A adalah B dan semua B adalah C, maka semua A adalah C. Ini adalah aturan transitivitas.', NULL, 'Gunakan diagram Venn untuk memvisualisasikan hubungan antar himpunan.', '2026-05-09 23:37:42', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 155);
