INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (15323, 1, NULL, 1, NULL, NULL, NULL, 'Pada masa penjajahan Belanda, muncul berbagai organisasi pergerakan nasional yang bertujuan untuk mencapai kemerdekaan. Salah satu organisasi yang berperan penting dalam menanamkan semangat nasionalisme di kalangan masyarakat Indonesia adalah Budi Utomo. Organisasi ini didirikan pada tahun 1908 oleh Dr. Wahidin Sudirohusodo bersama para mahasiswa STOVIA di Batavia. Budi Utomo berfokus pada pengembangan pendidikan dan kesejahteraan masyarakat Jawa, yang kemudian menginspirasi terbentuknya berbagai organisasi lainnya. Dengan latar belakang tersebut, dapat disimpulkan bahwa kontribusi Budi Utomo terhadap perjuangan nasionalisme di Indonesia adalah ...', NULL, 'mendorong penggunaan bahasa Belanda sebagai bahasa pendidikan', NULL, 'memperjuangkan hak-hak perempuan untuk mendapat pendidikan yang sama', NULL, 'menanamkan kesadaran nasional dan memperjuangkan kemajuan pendidikan bagi masyarakat Indonesia', NULL, 'menggalang dukungan dari negara-negara Eropa untuk membantu Indonesia merdeka', NULL, 'membentuk tentara nasional untuk melawan penjajah Belanda', NULL, 'A', '', NULL, '', '2026-05-09 23:48:35', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 49);
