INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (15326, 1, NULL, 34, NULL, NULL, NULL, 'Nasionalisme pada masa modern tidak hanya diwujudkan dalam bentuk perlawanan fisik, tetapi juga melalui kontribusi dalam berbagai bidang. Salah satu contoh nyata dari nasionalisme di bidang teknologi adalah ...', NULL, 'membeli seluruh produk teknologi dari negara maju', NULL, 'menggunakan teknologi untuk mempromosikan produk impor', NULL, 'mengembangkan teknologi lokal untuk kebutuhan nasional dan menciptakan lapangan kerja', NULL, 'menolak menggunakan teknologi untuk mempertahankan budaya lokal', NULL, 'melarang masyarakat untuk menggunakan internet demi keamanan nasional', NULL, 'A', '', NULL, '', '2026-05-09 23:48:48', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 5);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (15327, 1, NULL, 1, NULL, NULL, NULL, 'Banyak tokoh perjuangan kemerdekaan yang memiliki semangat nasionalisme tinggi. Salah satunya adalah Ki Hajar Dewantara, yang dikenal sebagai Bapak Pendidikan Nasional. Perjuangan Ki Hajar Dewantara dalam mengembangkan pendidikan bertujuan untuk ...', NULL, 'meningkatkan status sosial masyarakat pribumi di mata Belanda', NULL, 'memberikan pendidikan yang hanya fokus pada keterampilan militer', NULL, 'mendidik masyarakat Indonesia agar mampu berpikir kritis dan mandiri', NULL, 'menghilangkan budaya asli dan menggantinya dengan budaya Eropa', NULL, 'menyiapkan masyarakat Indonesia untuk menjadi pekerja bagi perusahaan asing', NULL, 'A', '', NULL, '', '2026-05-09 23:48:48', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 48);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (15328, 1, NULL, 37, NULL, NULL, NULL, 'Sejak era reformasi, nasionalisme di Indonesia berkembang lebih terbuka dan melibatkan partisipasi masyarakat secara luas. Salah satu bentuk nasionalisme yang muncul adalah nasionalisme ekonomi, yaitu ...', NULL, 'mendukung perusahaan asing untuk menguasai sektor penting di Indonesia', NULL, 'mengutamakan ekspor barang-barang mentah tanpa olahan', NULL, 'memperkuat produk lokal dan mengurangi ketergantungan pada impor', NULL, 'membebaskan investor asing untuk memiliki tanah di Indonesia', NULL, 'mengekspor bahan pangan strategis meskipun kebutuhan domestik belum terpenuhi', NULL, 'A', '', NULL, '', '2026-05-09 23:48:48', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 5);
