INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (15331, 1, NULL, 1, NULL, NULL, NULL, 'Dalam era globalisasi, banyak produk dari luar negeri yang membanjiri pasar Indonesia. Bagaimana peran nasionalisme ekonomi dalam menghadapi fenomena ini?', NULL, 'Melarang semua produk impor masuk ke Indonesia', NULL, 'Mengedukasi masyarakat tentang pentingnya mendukung produk dalam negeri untuk kesejahteraan bangsa', NULL, 'Mengizinkan dominasi produk impor demi efisiensi harga', NULL, 'Mengurangi produksi dalam negeri untuk memberi ruang bagi produk asing', NULL, 'Menaikkan harga produk lokal agar setara dengan produk asing', NULL, 'A', '', NULL, '', '2026-05-09 23:49:02', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 48);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (15332, 1, NULL, 1, NULL, NULL, NULL, 'Indonesia memiliki semboyan \"Bhinneka Tunggal Ika\" yang berarti \"Berbeda-beda tetapi tetap satu.\" Semboyan ini sangat penting dalam menjaga persatuan bangsa di tengah keberagaman. Jika Anda adalah seorang guru yang ingin menanamkan nilai ini pada siswa, metode pembelajaran apa yang paling efektif?', NULL, 'Mengajarkan mata pelajaran lain yang lebih penting daripada budaya', NULL, 'Membentuk kelompok diskusi di mana siswa dari latar belakang yang berbeda saling berbagi tentang tradisi mereka', NULL, 'Menghindari pembahasan tentang keberagaman untuk mengurangi konflik', NULL, 'Mewajibkan siswa untuk mempelajari budaya lain di luar negeri', NULL, 'Menyuruh siswa hanya untuk fokus pada budaya dari daerah asal mereka', NULL, 'A', '', NULL, '', '2026-05-09 23:49:02', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 1);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (15333, 1, NULL, 1, NULL, NULL, NULL, 'Banyak negara maju mempengaruhi cara hidup masyarakat Indonesia melalui budaya populer yang tersebar lewat internet. Generasi muda sering kali lebih mengenal budaya asing daripada budaya daerah sendiri. Jika Anda adalah seorang aktivis budaya, apa pendekatan terbaik untuk menumbuhkan rasa bangga generasi muda terhadap budaya lokal?', NULL, 'Membatasi akses internet di kalangan generasi muda', NULL, 'Mengadakan festival budaya yang menampilkan seni dan tradisi lokal dengan sentuhan modern', NULL, 'Mewajibkan penggunaan pakaian adat setiap hari di sekolah', NULL, 'Menghapus semua konten budaya asing dari kurikulum sekolah', NULL, 'Mengkritik budaya asing secara terbuka di depan publik', NULL, 'A', '', NULL, '', '2026-05-09 23:49:15', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 48);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (15334, 1, NULL, 1, NULL, NULL, NULL, 'Indonesia dikenal dengan keragaman suku dan budaya, yang berpotensi menjadi kekuatan maupun tantangan dalam menjaga persatuan nasional. Dalam menghadapi situasi yang menimbulkan potensi konflik antar suku atau kelompok, apa langkah yang paling tepat dilakukan untuk menjaga semangat nasionalisme?', NULL, 'Mengedepankan penegakan hukum yang tegas tanpa mempertimbangkan latar belakang budaya', NULL, 'Menyediakan forum dialog antar suku untuk membangun saling pengertian dan menyelesaikan konflik secara damai', NULL, 'Mengabaikan permasalahan antar suku dengan harapan masalahnya hilang sendiri', NULL, 'Membentuk komunitas berdasarkan kesamaan suku untuk menjaga identitas budaya', NULL, 'Melarang suku-suku berbeda untuk tinggal di wilayah yang sama', NULL, 'A', '', NULL, '', '2026-05-09 23:49:16', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 1);
