INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (15347, 1, NULL, 4, NULL, NULL, NULL, 'Selain orang Indonesia asli terdapat juga bangsa Tionghoa, Arab, dan India yang telah turun temurun menetap di wilayah Indonesia. Mereka dapat menjadi warga negara Indonesia sepanjang mereka bersungguh-sungguh ingin menjadi Warga Negara Indonesia (WNI). Kesungguhan mereka untuk menjadi WNI merupakan hal yang penting karena ...', NULL, 'Perbedaan etnis lebih memperkaya bangsa Indonesia', NULL, 'Semakin banyak WNI semakin kuat persatuan bangsa', NULL, 'Indonesia terbuka bagi semua warga yang ingin menjadi WNI', NULL, 'Mendukung persatuan bangsa Indonesia', NULL, 'Kepentingan politik lebih penting dari pada etnis', NULL, 'A', '', NULL, '', '2026-05-09 23:50:01', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 1);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (15348, 1, NULL, 1, NULL, NULL, NULL, 'Pada saat sidang BPUPKI tanggal 29 Mei - 1 Juni 1945 dalam rangka merumuskan dasar negara, setiap tokoh (M. Yamin, Soepomo, dan Soekarno) memiliki prinsip dasar negara yang berbeda-beda. Namun demikian terdapat persamaan di antara ketiganya dalam mengungkapkan prinsip dasar negara yaitu ...', NULL, 'Memuat prinsip ketuhanan', NULL, 'Bercirikan prinsip kekeluargaan', NULL, 'Memiliki prinsip internasionalisme', NULL, 'Adanya prinsip gotong-royong', NULL, 'Memiliki prinsip demokrasi', NULL, 'A', '', NULL, '', '2026-05-09 23:50:01', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 35);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (15349, 1, NULL, 1, NULL, NULL, NULL, 'Pada tanggal 20 Mei 1908, Soetomo mendirikan organisasi \"Budi Utomo\" dan menjadi organisasi modern pertama yang ada di Indonesia. Budi Utomo bertujuan memajukan bangsa Indonesia menjadi bangsa yang bermartabat dan mempertinggi cita-cita kemanusiaan. Perjuangan yang dilakukan Soetomo melalui Budi Utomo dalam kerangka integritas menunjukan makna bahwa ...', NULL, 'Organisasi modern menjadi faktor utama yang paling penting dan efektif untuk melakukan perlawanan terhadap penjajah', NULL, 'Perjuangan mencapai kemerdekaan dan cita-cita bersama lebih mudah dicapai jika terorganisir dengan baik dan terarah', NULL, 'Organisasi Budi Utomo merupakan organisasi modern pertama khusus untuk para bangsawan dan berpendidikan', NULL, 'Perlawanan terhadap pemerintah penjajahan Belanda tidak cukup hanya dengan menjalankan organisasi modern', NULL, 'Budi Utomo merupakan organisasi yang diinisiasi dan menjadi fokus oleh para dokter untuk kepentingan rakyat', NULL, 'A', '', NULL, '', '2026-05-09 23:50:16', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 35);
