INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (15351, 1, NULL, 1, NULL, NULL, NULL, 'Seorang kepala daerah yang juga anggota partai politik melakukan perjanjian dengan partai pendukungnya sebagai wujud loyalitasnya dengan membuat kebijakan yang berpihak dengan partai politiknya. Padalah beliau sudah disumpah dan dilantik jabatan. Menurut anda perilaku yang bertentangan dengan integritas adalah ...', NULL, 'Bersikap loyal pada partai pendukung', NULL, 'Menaati sumpah dan janji sebagai pemimpin', NULL, 'Berjanji menaati peraturan UU yang berlaku', NULL, 'Membuat kesepakatan untuk membuat kebijakan yang berpihak kepada partainya', NULL, 'Berkomitmen untuk bersikap adil tanpa diskriminasi', NULL, 'A', '', NULL, '', '2026-05-09 23:50:16', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 50);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (15352, 1, NULL, 2, NULL, NULL, NULL, 'Indonesia merupakan negara yang memiliki beragam suku, sehingga kalau tidak mampu memahami dengan baik karakter suku-suku lain, konflik antar suku akan mudah terjadi. Pernyataan ini menunjukkan bahwa jika menerapkan prinsip-prinsip Bhineka Tunggal Ika untuk menguatkan integritas bangsa Indonesia maka perilaku yang perlu dikembangkan ...', NULL, 'Menghormati perbedaan dan memiliki kesadaran bahwa setiap suku memiliki karakteristik yang berbeda', NULL, 'Menumbuhkan kesadaran bahwa suku sendiri harus ditonjolkan karena memiliki kelebihan-kelebihan', NULL, 'Menganggap bahwa keberadaan suku-suku yang berbeda di Indonesia merupakan salah satu penghalang persatuan', NULL, 'Membiarkan suku di Indonesia mengembangkan tradisi yang ada meskipun bertentangan dengan hukum', NULL, 'Mendorong pemerintah agar memberikan bantuan untuk pengembangan tradisi yang dimiliki oleh suku tertentu', NULL, 'A', '', NULL, '', '2026-05-09 23:50:16', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 1);
