INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (15360, 1, NULL, 1, NULL, NULL, NULL, 'Upaya untuk menjaga nasionalisme di era digital dapat diwujudkan melalui berbagai kegiatan positif. Salah satu cara yang paling efektif bagi generasi muda adalah ...', NULL, 'menghindari semua konten digital yang berbau internasional', NULL, 'aktif mempromosikan keindahan dan budaya Indonesia melalui media sosial', NULL, 'memfokuskan diri hanya pada budaya populer dari negara lain', NULL, 'mengikuti tren global tanpa mempertimbangkan budaya lokal', NULL, 'menghapus konten lokal dari platform media sosial', NULL, 'A', '', NULL, '', '2026-05-09 23:54:31', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 44);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (15361, 1, NULL, 1, NULL, NULL, NULL, 'Indonesia dikenal sebagai negara dengan keanekaragaman suku dan budaya. Namun, tidak jarang perbedaan ini memicu konflik sosial. Jika Anda adalah seorang pemimpin komunitas, pendekatan apa yang paling efektif untuk menumbuhkan rasa persatuan di tengah keragaman tersebut?', NULL, 'Menghindari kegiatan yang melibatkan lebih dari satu kelompok suku', NULL, 'Mengadakan kegiatan kebudayaan bersama yang melibatkan seluruh kelompok suku untuk mempererat hubungan antar kelompok', NULL, 'Meminta setiap suku untuk mengisolasi diri dari suku lainnya', NULL, 'Menyerahkan penyelesaian konflik kepada pihak luar tanpa melibatkan komunitas setempat', NULL, 'Memusatkan kegiatan hanya pada satu kelompok suku saja', NULL, 'A', '', NULL, '', '2026-05-09 23:54:45', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 1);
