INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (15363, 1, NULL, 1, NULL, NULL, NULL, 'Di tengah perkembangan teknologi yang pesat, generasi muda sering kali lebih akrab dengan budaya digital global daripada budaya lokal. Sebagai seorang pemimpin pemuda, apa pendekatan yang bisa diambil untuk meningkatkan kesadaran nasionalisme digital di kalangan anak muda?', NULL, 'Melarang penggunaan teknologi asing', NULL, 'Mengembangkan platform digital yang mempromosikan budaya dan nilai-nilai lokal dalam format yang sesuai dengan generasi muda', NULL, 'Menyebarkan berita yang merendahkan budaya asing', NULL, 'Menghindari diskusi tentang budaya lokal di media digital', NULL, 'Mewajibkan generasi muda untuk tidak menggunakan media sosial', NULL, 'A', '', NULL, '', '2026-05-09 23:54:45', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 23);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (15364, 1, NULL, 1, NULL, NULL, NULL, 'Salah satu cara menumbuhkan semangat nasionalisme adalah melalui penggunaan bahasa Indonesia secara baik dan benar. Namun, di era globalisasi ini, banyak generasi muda yang lebih sering menggunakan bahasa asing dalam percakapan sehari-hari. Sebagai seorang tokoh masyarakat, apa langkah yang dapat Anda lakukan untuk mengatasi masalah ini?', NULL, 'Melarang penggunaan bahasa asing dalam percakapan sehari-hari', NULL, 'Mengadakan program pelatihan dan penghargaan bagi mereka yang mampu menggunakan bahasa Indonesia dengan baik di media sosial', NULL, 'Mengganti kurikulum pendidikan untuk menghapus semua mata pelajaran bahasa asing', NULL, 'Membatasi akses generasi muda terhadap media asing', NULL, 'Mewajibkan semua orang untuk berbicara dalam bahasa Indonesia dalam segala situasi', NULL, 'A', '', NULL, '', '2026-05-09 23:54:45', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 21);
