INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (15393, 1, NULL, 1, NULL, NULL, NULL, 'Sejak kemerdekaan, Indonesia telah menjalin hubungan diplomatik dengan banyak negara. Prinsip yang mendasari politik luar negeri Indonesia adalah \"Bebas dan Aktif.\" Makna dari prinsip “Bebas” dalam konteks ini adalah ...', NULL, 'mendukung salah satu blok kekuatan dunia', NULL, 'tidak berpihak pada blok manapun dan menjaga independensi', NULL, 'memilih negara yang memiliki keuntungan ekonomi terbesar', NULL, 'mematuhi perintah dari negara-negara adikuasa', NULL, 'tidak menjalin hubungan diplomatik dengan negara manapun', NULL, 'A', '', NULL, '', '2026-05-10 00:01:51', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 37);
