INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (15395, 1, NULL, 1, NULL, NULL, NULL, 'Dalam memperingati Hari Pahlawan, banyak kegiatan yang diadakan di seluruh Indonesia. Peringatan ini bertujuan untuk ...', NULL, 'memperingati jasa para pahlawan yang gugur dalam perang tanpa mengenang nilai perjuangan mereka', NULL, 'menghargai pengorbanan para pahlawan dan menumbuhkan semangat nasionalisme di kalangan generasi muda', NULL, 'menunjukkan kekuatan militer Indonesia kepada negara lain', NULL, 'mengingatkan rakyat agar mengutamakan kepentingan pribadi di atas kepentingan bangsa', NULL, 'melupakan masa lalu demi mencapai masa depan yang lebih baik', NULL, 'A', '', NULL, '', '2026-05-10 00:01:52', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 48);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (15396, 1, NULL, 3, NULL, NULL, NULL, 'Indonesia memiliki banyak daerah dengan budaya yang beragam. Sikap yang sesuai dengan nilai-nilai nasionalisme dalam menghadapi keberagaman ini adalah ...', NULL, 'memaksakan satu budaya untuk diikuti oleh seluruh rakyat', NULL, 'menghargai dan menjaga keberagaman budaya sebagai kekayaan bangsa', NULL, 'hanya mendukung budaya yang mendatangkan keuntungan ekonomi', NULL, 'menganggap budaya lokal sebagai hal yang tidak penting', NULL, 'melarang budaya asing memasuki Indonesia', NULL, 'A', '', NULL, '', '2026-05-10 00:01:52', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 1);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (15397, 1, NULL, 50, NULL, NULL, NULL, 'Sebagai bangsa yang besar, Indonesia memiliki banyak kepentingan yang harus dijaga dalam hubungan internasional. Namun, Indonesia juga berkomitmen untuk tidak memihak blok mana pun. Prinsip ini dikenal sebagai “politik bebas aktif.” Di era globalisasi saat ini, bagaimana Indonesia dapat mempertahankan prinsip tersebut dalam menjaga hubungan internasional?', NULL, 'Menjaga jarak dengan semua negara dan menghindari kerja sama internasional', NULL, 'Membangun aliansi dengan negara-negara yang memiliki pandangan politik sama', NULL, 'Menjalin kerja sama dengan negara lain berdasarkan kepentingan bersama tanpa terikat pada blok kekuatan tertentu', NULL, 'Menghindari hubungan diplomatik dengan negara besar yang memiliki pengaruh global', NULL, 'Mengizinkan negara asing untuk mempengaruhi kebijakan nasional Indonesia', NULL, 'A', '', NULL, '', '2026-05-10 00:02:06', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 7);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (15398, 1, NULL, 37, NULL, NULL, NULL, 'Sebagai bentuk nasionalisme modern, masyarakat Indonesia didorong untuk menggunakan produk-produk lokal. Namun, di pasar lokal, produk asing sering kali lebih menarik bagi konsumen. Apa strategi yang paling efektif bagi produsen lokal untuk meningkatkan daya tarik produk mereka dibandingkan produk impor?', NULL, 'Mengurangi biaya produksi dengan menurunkan kualitas produk', NULL, 'Meningkatkan kualitas produk lokal dan mempromosikan keunggulan produk lokal secara kreatif', NULL, 'Membatasi konsumen untuk membeli produk impor', NULL, 'Menetapkan harga produk lokal setinggi mungkin agar terlihat lebih eksklusif', NULL, 'Mencoba meniru produk impor tanpa inovasi yang berarti', NULL, 'A', '', NULL, '', '2026-05-10 00:02:06', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 5);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (15399, 1, NULL, 13, NULL, NULL, NULL, 'Sebagai negara yang besar dan memiliki banyak pulau, Indonesia memiliki tantangan dalam menyebarkan informasi yang merata ke seluruh wilayah. Hal ini penting agar seluruh masyarakat mendapatkan pemahaman yang sama tentang isu-isu nasional. Apa langkah yang paling efektif yang bisa dilakukan pemerintah untuk memastikan bahwa informasi mengenai nasionalisme dan isu-isu kebangsaan bisa menjangkau seluruh masyarakat, termasuk di daerah terpencil?', NULL, 'Membangun pusat informasi di kota-kota besar saja', NULL, 'Menggunakan teknologi digital seperti radio, televisi, dan internet untuk menjangkau daerah-daerah terpencil', NULL, 'Mengirimkan surat kepada setiap rumah tangga mengenai isu-isu kebangsaan', NULL, 'Mengadakan seminar kebangsaan hanya di kota besar', NULL, 'Menyebarkan informasi hanya melalui media cetak', NULL, 'A', '', NULL, '', '2026-05-10 00:02:06', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 2);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (15400, 1, NULL, 13, NULL, NULL, NULL, 'Sebagai negara maritim, Indonesia memiliki kekayaan laut yang luar biasa. Namun, sering kali laut Indonesia terancam oleh aktivitas ilegal seperti penangkapan ikan oleh kapal asing. Dalam rangka mempertahankan kedaulatan laut, apa tindakan yang paling efektif untuk dilakukan pemerintah?', NULL, 'Mengizinkan kapal asing menangkap ikan di perairan Indonesia dengan syarat tertentu', NULL, 'Meningkatkan patroli di wilayah laut Indonesia dan menindak tegas kapal asing yang menangkap ikan secara ilegal', NULL, 'Membatasi penggunaan laut hanya untuk kepentingan ekonomi negara lain', NULL, 'Menyerahkan pengelolaan laut kepada perusahaan asing', NULL, 'Menaikkan harga ikan untuk mengurangi penangkapan ikan secara keseluruhan', NULL, 'A', '', NULL, '', '2026-05-10 00:02:06', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 2);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (15401, 1, NULL, 1, NULL, NULL, NULL, 'Indonesia menghadapi ancaman disintegrasi jika isu-isu seperti ketidakadilan sosial dan ekonomi tidak ditangani dengan baik. Bagaimana seharusnya pemerintah mengatasi masalah ini untuk memperkuat persatuan dan nasionalisme di tengah masyarakat?', NULL, 'Memusatkan pembangunan hanya di kota-kota besar', NULL, 'Memberikan perhatian dan alokasi anggaran yang lebih besar untuk pembangunan infrastruktur dan peningkatan kesejahteraan di daerah-daerah yang tertinggal', NULL, 'Mengabaikan daerah-daerah yang menuntut pemerataan ekonomi', NULL, 'Membiarkan masyarakat di daerah tertinggal untuk mengelola sendiri tanpa bantuan pemerintah', NULL, 'Menurunkan anggaran daerah agar lebih fokus pada pusat', NULL, 'A', '', NULL, '', '2026-05-10 00:02:23', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 1);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (15402, 1, NULL, 1, NULL, NULL, NULL, 'Di era digital, informasi tentang isu-isu nasional dan kebijakan pemerintah dapat diakses dengan mudah. Namun, tidak semua informasi yang beredar dapat dipercaya. Sebagai seorang warga negara yang bertanggung jawab, bagaimana cara yang paling bijak untuk menangani informasi yang Anda terima tentang isu-isu nasional?', NULL, 'Menyebarkan informasi apa pun yang diperoleh tanpa memeriksa kebenarannya', NULL, 'Mengecek fakta dari sumber resmi sebelum menyebarkan informasi dan berhati-hati terhadap hoaks', NULL, 'Hanya menerima informasi dari satu sumber saja tanpa mempertimbangkan pandangan lain', NULL, 'Mengandalkan informasi dari media sosial tanpa memverifikasi kebenarannya', NULL, 'Menghindari semua jenis berita tentang isu-isu nasional', NULL, 'A', '', NULL, '', '2026-05-10 00:02:23', 'mudah', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 25);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (15403, 1, NULL, 1, NULL, NULL, NULL, 'Dalam menghadapi persaingan global, Indonesia perlu membekali generasi mudanya dengan keterampilan yang relevan. Namun, nasionalisme juga perlu dipertahankan di tengah pengaruh globalisasi. Bagaimana sebaiknya pendidikan nasionalisme dikombinasikan dengan pendidikan keterampilan global bagi generasi muda?', NULL, 'Menekankan pendidikan keterampilan global dan mengabaikan pendidikan nasionalisme', NULL, 'Mewajibkan pendidikan nasionalisme dan keterampilan global untuk membekali generasi muda agar siap bersaing secara internasional dengan tetap mencintai tanah air', NULL, 'Mengajarkan keterampilan global saja karena lebih relevan dalam persaingan dunia', NULL, 'Menghindari pendidikan nasionalisme karena dianggap tidak sesuai dengan era modern', NULL, 'Mengajarkan keterampilan global tetapi membatasi akses terhadap budaya lokal', NULL, 'A', '', NULL, '', '2026-05-10 00:02:23', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 1);
