INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (15427, 1, NULL, 2, NULL, NULL, NULL, 'Indonesia memiliki banyak pulau dengan berbagai macam etnis dan budaya. Untuk menjaga persatuan di tengah keragaman, apa langkah yang paling efektif yang dapat dilakukan pemerintah dalam mengelola keanekaragaman tersebut?', NULL, 'Mewajibkan semua daerah untuk menggunakan bahasa dan budaya yang sama', NULL, 'Meningkatkan pemahaman dan toleransi antar suku dengan mengadakan program budaya lintas daerah yang melibatkan masyarakat dari berbagai wilayah', NULL, 'Memisahkan setiap daerah agar tidak terjadi interaksi antar suku', NULL, 'Menyerahkan kebijakan budaya kepada negara-negara tetangga', NULL, 'Membatasi masyarakat untuk berpindah dari satu daerah ke daerah lain', NULL, 'A', '', NULL, '', '2026-05-10 00:11:11', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 1);
INSERT INTO `soal` (`id`, `kategori_id`, `learning_topic_id`, `materi_id`, `passage_id`, `nomor_urutan_dalam_passage`, `sub_materi`, `pertanyaan`, `gambar_pertanyaan`, `opsi_a`, `gambar_opsi_a`, `opsi_b`, `gambar_opsi_b`, `opsi_c`, `gambar_opsi_c`, `opsi_d`, `gambar_opsi_d`, `opsi_e`, `gambar_opsi_e`, `jawaban_benar`, `pembahasan`, `gambar_pembahasan`, `tips`, `created_at`, `tingkat`, `irt_a`, `irt_b`, `irt_c`, `discrimination_index`, `item_quality`, `generated_by_ai`, `ai_model`, `ai_generated_at`, `quality_score`, `review_status`, `reviewed_by`, `reviewed_at`, `bloom_level`, `cognitive_load`, `avg_time_seconds`, `learning_objective`, `expert_reviewed`, `topic_id`) VALUES (15428, 1, NULL, 1, NULL, NULL, NULL, 'Indonesia menghadapi tantangan ketergantungan pada energi fosil yang tidak terbarukan. Dalam menghadapi situasi ini, apa kebijakan paling efektif yang bisa diambil pemerintah untuk mencerminkan nasionalisme dan menjaga keberlanjutan energi di masa depan?', NULL, 'Meningkatkan eksploitasi energi fosil untuk mendukung pertumbuhan ekonomi', NULL, 'Mengembangkan dan mempercepat investasi pada sumber energi terbarukan seperti tenaga surya, angin, dan biomassa', NULL, 'Melarang masyarakat menggunakan energi alternatif', NULL, 'Membatasi penggunaan energi terbarukan demi mempertahankan industri fosil', NULL, 'Menyerahkan pengelolaan energi sepenuhnya kepada perusahaan asing', NULL, 'A', '', NULL, '', '2026-05-10 00:11:12', 'sulit', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 1);
