INSERT INTO `tips_tricks` (`id`, `kategori_id`, `tipe_tips`, `judul`, `konten`, `contoh`, `prioritas`, `aktif`, `created_at`) VALUES (1, 1, 'umum', 'Tips Menjawab TWK', 'Baca soal dengan teliti dan pahami konteks sejarah dan ideologi bangsa', 'Selalu kaitkan dengan Pancasila dan UUD 1945', 1, 1, '2026-05-12 01:36:34');
INSERT INTO `tips_tricks` (`id`, `kategori_id`, `tipe_tips`, `judul`, `konten`, `contoh`, `prioritas`, `aktif`, `created_at`) VALUES (2, 1, 'strategi', 'Strategi TWK', 'Fokus pada materi sejarah, geografi, dan ideologi negara', 'Pelajari pahlawan nasional dan peristiwa penting', 2, 1, '2026-05-12 01:36:34');
INSERT INTO `tips_tricks` (`id`, `kategori_id`, `tipe_tips`, `judul`, `konten`, `contoh`, `prioritas`, `aktif`, `created_at`) VALUES (3, 2, 'umum', 'Tips Menjawab TIU', 'Gunakan logika matematika dan pola untuk mempercepat penyelesaian', 'Gunakan teknik eliminasi untuk opsi yang jelas salah', 1, 1, '2026-05-12 01:36:34');
INSERT INTO `tips_tricks` (`id`, `kategori_id`, `tipe_tips`, `judul`, `konten`, `contoh`, `prioritas`, `aktif`, `created_at`) VALUES (4, 2, 'shortcut', 'Shortcut TIU', 'Untuk soal deret, cari pola selisih antar angka', 'Contoh: 2,4,6,8 selisihnya 2, angka berikutnya 10', 3, 1, '2026-05-12 01:36:34');
INSERT INTO `tips_tricks` (`id`, `kategori_id`, `tipe_tips`, `judul`, `konten`, `contoh`, `prioritas`, `aktif`, `created_at`) VALUES (5, 3, 'umum', 'Tips Menjawab TKP', 'Jawab sesuai kepribadian dan karakter Anda yang sebenarnya', 'Jangan pura-pura, sistem akan mendeteksi ketidakkonsistenan', 1, 1, '2026-05-12 01:36:34');
