INSERT INTO `tips_tricks` (`id`, `kategori_id`, `tipe_tips`, `judul`, `konten`, `contoh`, `prioritas`, `aktif`, `created_at`) VALUES (1623, 1, 'umum', 'Tips TWK - Wawasan Kebangsaan', 'Pelajari sejarah Indonesia, pancasila, UUD 1945, dan budaya nasional. Banyak membaca berita dan artikel tentang kebangsaan.', NULL, 2, 1, '2026-05-12 02:15:46');
INSERT INTO `tips_tricks` (`id`, `kategori_id`, `tipe_tips`, `judul`, `konten`, `contoh`, `prioritas`, `aktif`, `created_at`) VALUES (1625, 2, 'umum', 'Tips TIU - Tes Intelejensi Umum', 'Latih soal logika, aritmatika, dan deret angka secara rutin. Pahami pola-pola yang sering muncul.', NULL, 2, 1, '2026-05-12 02:15:46');
INSERT INTO `tips_tricks` (`id`, `kategori_id`, `tipe_tips`, `judul`, `konten`, `contoh`, `prioritas`, `aktif`, `created_at`) VALUES (1627, 3, 'umum', 'Tips TKP - Tes Karakteristik Pribadi', 'Jawab dengan jujur sesuai kepribadian asli. TKP tidak ada jawaban salah atau benar, pilih yang paling menggambarkan diri.', NULL, 2, 1, '2026-05-12 02:15:46');
INSERT INTO `tips_tricks` (`id`, `kategori_id`, `tipe_tips`, `judul`, `konten`, `contoh`, `prioritas`, `aktif`, `created_at`) VALUES (1629, 4, 'umum', 'Tips TPA - Tes Potensi Akademik', 'Latih verbal, numerik, dan logika. TPA mengukur potensi akademik, bukan pengetahuan yang sudah dipelajari.', NULL, 2, 1, '2026-05-12 02:15:46');
INSERT INTO `tips_tricks` (`id`, `kategori_id`, `tipe_tips`, `judul`, `konten`, `contoh`, `prioritas`, `aktif`, `created_at`) VALUES (1630, 5, 'umum', 'Tips Psikologis', 'Jawab dengan tenang dan jujur. Tes psikologis mengukur kecocokan kepribadian dengan pekerjaan.', NULL, 2, 1, '2026-05-12 02:15:46');
INSERT INTO `tips_umum` (`id`, `kategori_id`, `judul`, `konten`, `created_at`) VALUES (6, 1, 'Tips TWK - Pahami Konsep', 'Untuk soal TWK, pahami konsep dasar nasionalisme, integritas, dan bela negara. Baca dengan teliti setiap pertanyaan karena seringkali ada jebakan dalam pemilihan kata.', '2026-05-09 18:28:12');
INSERT INTO `tips_umum` (`id`, `kategori_id`, `judul`, `konten`, `created_at`) VALUES (13, 3, 'Tips TKP - Jujur pada Diri Sendiri', 'Soal TKP mengukur kepribadian Anda. Jawablah dengan jujur sesuai dengan karakter Anda. Jangan mencoba menebak jawaban yang dianggap \"benar\" karena sistem penilaian TKP berbeda dengan TWK dan TIU.', '2026-05-09 23:21:38');
INSERT INTO `tips_umum` (`id`, `kategori_id`, `judul`, `konten`, `created_at`) VALUES (14, 4, 'Tips TPA - Latihan Rutin', 'TPA menguji potensi akademik Anda. Latihan soal secara rutin akan membantu meningkatkan kecepatan dan akurasi dalam mengerjakan soal bahasa, numerik, dan logika.', '2026-05-09 23:21:38');
INSERT INTO `tips_umum` (`id`, `kategori_id`, `judul`, `konten`, `created_at`) VALUES (15, 5, 'Tips Psikologis - Tenang dan Waspada', 'Tes psikologis mengukur kepribadian dan motivasi Anda. Tetaplah tenang dan wasapda saat mengerjakan. Jawablah sesuai dengan perasaan dan pemikiran Anda yang sebenarnya.', '2026-05-09 23:21:38');
INSERT INTO `tips_umum` (`id`, `kategori_id`, `judul`, `konten`, `created_at`) VALUES (16, 4, 'Tips TPA - Manajemen Waktu', 'Bagi waktu secara proporsional untuk setiap jenis soal TPA. Jangan terjebak terlalu lama pada satu soal yang sulit. Lewati dan kembali lagi jika ada waktu sisa.', '2026-05-09 23:21:38');
INSERT INTO `tips_umum` (`id`, `kategori_id`, `judul`, `konten`, `created_at`) VALUES (17, 5, 'Tips Psikologis - Konsistensi', 'Jawablah soal psikologis dengan konsisten. Jangan berpindah sikap di tengah tes karena ini dapat mempengaruhi hasil penilaian kepribadian Anda.', '2026-05-09 23:21:38');
INSERT INTO `tips_umum` (`id`, `kategori_id`, `judul`, `konten`, `created_at`) VALUES (29, NULL, 'Tips Deret Angka', 'Trik \"Hitung Detik\" untuk deret angka:\n1. Gunakan metode \"Lompat Pola\" - jangan hitung selisih satu per satu\n2. Jika angka naik-turun drastis, curigai pola lompat 2 atau 3\n3. Perhatikan pola penjumlahan (+), pengurangan (-), perkalian (×), pembagian (÷)\n4. Untuk deret kuadrat: 1, 4, 9, 16 (pola n²)\n5. Untuk deret kubik: 1, 8, 27, 64 (pola n³)\n6. Gunakan eliminasi jika tidak bisa menemukan pola dengan cepat', '2026-05-20 03:01:21');
INSERT INTO `tips_umum` (`id`, `kategori_id`, `judul`, `konten`, `created_at`) VALUES (30, NULL, 'Tips Logika Silogisme', 'Trik menjawab soal silogisme:\n1. Identifikasi premis mayor dan minor\n2. Cari hubungan antar-subjek dalam premis\n3. Gunakan diagram Venn jika perlu untuk visualisasi\n4. Hindari asumsi luar yang tidak ada dalam premis\n5. Perhatikan kata kunci: \"semua\", \"sebagian\", \"tidak ada\"\n6. Konklusi harus mengikuti secara logis dari premis', '2026-05-20 03:01:21');
INSERT INTO `tips_umum` (`id`, `kategori_id`, `judul`, `konten`, `created_at`) VALUES (31, NULL, 'Tips Sinonim Antonim', 'Trik cepat sinonim dan antonim:\n1. Buat flashcards dari kata-kata sulit\n2. Perhatikan prefiks/sufiks untuk mengidentifikasi makna\n3. Gunakan konteks kalimat untuk menebak makna\n4. Sinonim: kata dengan makna sama (gembira = senang)\n5. Antonim: kata dengan makna berlawanan (panjang = pendek)\n6. Eliminasi pilihan yang jelas salah terlebih dahulu', '2026-05-20 03:01:21');
INSERT INTO `tips_umum` (`id`, `kategori_id`, `judul`, `konten`, `created_at`) VALUES (32, NULL, 'Tips Analogi', 'Trik mengerjakan soal analogi:\n1. Buat kalimat penghubung antara dua kata pertama\n2. Contoh: \"Buku : Membaca = Radio : Mendengarkan\"\n3. Terapkan pola kalimat yang sama pada pilihan jawaban\n4. Perhatikan jenis hubungan: fungsi, bagian, sebab-akibat\n5. Gunakan pengetahuan umum untuk memahami hubungan\n6. Eliminasi jawaban yang tidak memiliki pola yang sama', '2026-05-20 03:01:21');
INSERT INTO `tips_umum` (`id`, `kategori_id`, `judul`, `konten`, `created_at`) VALUES (33, NULL, 'Tips Aritmatika', 'Trik hitung cepat aritmatika:\n1. Gunakan estimasi dan pembulatan\n2. Untuk persentase: 10% = ÷10, 20% = ÷5, 25% = ÷4\n3. Untuk perbandingan: gunakan rasio sederhana\n4. Triple Pythagoras untuk geometri jarak\n5. Jangan menghitung detail jika tidak perlu\n6. Gunakan eliminasi untuk pilihan yang tidak masuk akal', '2026-05-20 03:01:21');
INSERT INTO `tips_umum` (`id`, `kategori_id`, `judul`, `konten`, `created_at`) VALUES (34, NULL, 'Tips Nasionalisme', 'Tips menjawab soal nasionalisme TWK:\n1. Pahami 5 sila Pancasila dan contohnya\n2. Ketahui sejarah kemerdekaan Indonesia\n3. Pahami UUD 1945 pasal-pasal penting\n4. Nilai-nilai Bhinneka Tunggal Ika\n5. Bela negara: cinta tanah air dan siap membela\n6. Fokus pada konteks Indonesia dalam pertanyaan', '2026-05-20 03:01:21');
INSERT INTO `tips_umum` (`id`, `kategori_id`, `judul`, `konten`, `created_at`) VALUES (35, NULL, 'Tips Sikap Perilaku', 'Tips menjawab soal sikap dan perilaku TKP:\n1. Pilih jawaban yang menunjukkan sikap positif\n2. Prioritaskan kerjasama tim dan integritas\n3. Hindari jawaban yang menunjukkan sikap negatif\n4. Pilih jawaban yang menunjukkan tanggung jawab\n5. Pertimbangkan etika kerja dan profesionalisme\n6. Pilih jawaban yang mendukung lingkungan kerja baik', '2026-05-20 03:01:21');
INSERT INTO `tips_umum` (`id`, `kategori_id`, `judul`, `konten`, `created_at`) VALUES (36, NULL, 'Tips Sejarah', 'Tips menjawab soal sejarah TWK:\n1. Hafalkan tahun-tahun penting Indonesia\n2. Pahami periode sejarah: penjajahan, kemerdekaan, reformasi\n3. Ketahui tokoh-tokoh penting nasional\n4. Pahami peristiwa penting: Proklamasi, Baperki, dll\n5. Kaitkan sejarah dengan konteks nasionalisme\n6. Gunakan pengetahuan umum sejarah Indonesia', '2026-05-20 03:01:21');
INSERT INTO `tips_umum` (`id`, `kategori_id`, `judul`, `konten`, `created_at`) VALUES (37, NULL, 'Tips Geografi', 'Tips menjawab soal geografi TWK:\n1. Hafalkan provinsi dan ibu kota Indonesia\n2. Pahami posisi strategis Indonesia\n3. Ketahui pulau-pulau besar di Indonesia\n4. Pahami batas wilayah Indonesia\n5. Ketahui sumber daya alam per wilayah\n6. Kaitkan geografi dengan pembangunan nasional', '2026-05-20 03:01:21');
INSERT INTO `tips_umum` (`id`, `kategori_id`, `judul`, `konten`, `created_at`) VALUES (38, NULL, 'Tips Psikotes', 'Tips menjawab soal psikotes:\n1. Jawab dengan jujur dan konsisten\n2. Jangan berusaha menjawab sesuai keinginan penguji\n3. Pilih jawaban yang mencerminkan kepribadian Anda\n4. Hindari jawaban ekstrem (sangat setuju/sangat tidak setuju)\n5. Pilih jawaban moderat jika ragu\n6. Konsistensi jawaban sangat penting', '2026-05-20 03:01:21');
INSERT INTO `tips_umum` (`id`, `kategori_id`, `judul`, `konten`, `created_at`) VALUES (39, NULL, 'Tips Deret Angka', 'Trik \"Hitung Detik\" untuk deret angka:\n1. Gunakan metode \"Lompat Pola\" - jangan hitung selisih satu per satu\n2. Jika angka naik-turun drastis, curigai pola lompat 2 atau 3\n3. Perhatikan pola penjumlahan (+), pengurangan (-), perkalian (×), pembagian (÷)\n4. Untuk deret kuadrat: 1, 4, 9, 16 (pola n²)\n5. Untuk deret kubik: 1, 8, 27, 64 (pola n³)\n6. Gunakan eliminasi jika tidak bisa menemukan pola dengan cepat', '2026-05-20 03:01:38');
INSERT INTO `tips_umum` (`id`, `kategori_id`, `judul`, `konten`, `created_at`) VALUES (40, NULL, 'Tips Logika Silogisme', 'Trik menjawab soal silogisme:\n1. Identifikasi premis mayor dan minor\n2. Cari hubungan antar-subjek dalam premis\n3. Gunakan diagram Venn jika perlu untuk visualisasi\n4. Hindari asumsi luar yang tidak ada dalam premis\n5. Perhatikan kata kunci: \"semua\", \"sebagian\", \"tidak ada\"\n6. Konklusi harus mengikuti secara logis dari premis', '2026-05-20 03:01:38');
INSERT INTO `tips_umum` (`id`, `kategori_id`, `judul`, `konten`, `created_at`) VALUES (41, NULL, 'Tips Sinonim Antonim', 'Trik cepat sinonim dan antonim:\n1. Buat flashcards dari kata-kata sulit\n2. Perhatikan prefiks/sufiks untuk mengidentifikasi makna\n3. Gunakan konteks kalimat untuk menebak makna\n4. Sinonim: kata dengan makna sama (gembira = senang)\n5. Antonim: kata dengan makna berlawanan (panjang = pendek)\n6. Eliminasi pilihan yang jelas salah terlebih dahulu', '2026-05-20 03:01:38');
INSERT INTO `tips_umum` (`id`, `kategori_id`, `judul`, `konten`, `created_at`) VALUES (42, NULL, 'Tips Analogi', 'Trik mengerjakan soal analogi:\n1. Buat kalimat penghubung antara dua kata pertama\n2. Contoh: \"Buku : Membaca = Radio : Mendengarkan\"\n3. Terapkan pola kalimat yang sama pada pilihan jawaban\n4. Perhatikan jenis hubungan: fungsi, bagian, sebab-akibat\n5. Gunakan pengetahuan umum untuk memahami hubungan\n6. Eliminasi jawaban yang tidak memiliki pola yang sama', '2026-05-20 03:01:38');
INSERT INTO `tips_umum` (`id`, `kategori_id`, `judul`, `konten`, `created_at`) VALUES (43, NULL, 'Tips Aritmatika', 'Trik hitung cepat aritmatika:\n1. Gunakan estimasi dan pembulatan\n2. Untuk persentase: 10% = ÷10, 20% = ÷5, 25% = ÷4\n3. Untuk perbandingan: gunakan rasio sederhana\n4. Triple Pythagoras untuk geometri jarak\n5. Jangan menghitung detail jika tidak perlu\n6. Gunakan eliminasi untuk pilihan yang tidak masuk akal', '2026-05-20 03:01:38');
