INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (17493, 80, 'Negara memperoleh kebenaran politik secara organik dari adanya kesamaan bangsa atau ras, menurut semangat romantisme cerita heroik yang terjadi dalam kehidupan sejarah bangsa atau ras yang bersangkutan merupakan pengertian ...', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #80', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_80_1778528440.html', 0, 'C', 'Nasionalisme identitas adalah nasionalisme yang muncul dari kesamaan identitas budaya dan sejarah suatu bangsa.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (40137, 80, 'Negara memperoleh kebenaran politik secara organik dari adanya kesamaan bangsa atau ras, menurut semangat romantisme cerita heroik yang terjadi dalam kehidupan sejarah bangsa atau ras yang bersangkutan merupakan pengertian ...', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #80', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_80_1778530120.html', 0, 'C', 'Nasionalisme identitas adalah nasionalisme yang muncul dari kesamaan identitas budaya dan sejarah suatu bangsa.');
