INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (13785, 130, 'Seorang mahasiswa Pendidikan Teknik Elektro baru saja menyelesaikan studinya. Ia ditawarkan untuk melanjutkan studinya di Inggris dengan beasiswa. Meski demikian ia memilih Kembali ke kampungnya. Di kampung ia membuat pembangkit listrik sederhana dengan memanfaatkan aliran air sungai yang deras. Berkat pembangkit listrik tersebut, warga kampung sudah dapat menikmati ketersediaan listrik. Tindakan mahasiswa tersebut menunjukkan sikap...', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #130', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_130_1778528331.html', 0, 'C', 'Patriotisme adalah cinta tanah air yang ditunjukkan dengan tindakan nyata. Mahasiswa tersebut memilih kembali ke kampung dan berkontribusi untuk masyarakatnya, bukan mengejar keuntungan pribadi di luar negeri.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (28890, 130, 'Seorang mahasiswa Pendidikan Teknik Elektro baru saja menyelesaikan studinya. Ia ditawarkan untuk melanjutkan studinya di Inggris dengan beasiswa. Meski demikian ia memilih Kembali ke kampungnya. Di kampung ia membuat pembangkit listrik sederhana dengan memanfaatkan aliran air sungai yang deras. Berkat pembangkit listrik tersebut, warga kampung sudah dapat menikmati ketersediaan listrik. Tindakan mahasiswa tersebut menunjukkan sikap...', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #130', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_130_1778529820.html', 0, 'C', 'Patriotisme adalah cinta tanah air yang ditunjukkan dengan tindakan nyata. Mahasiswa tersebut memilih kembali ke kampung dan berkontribusi untuk masyarakatnya, bukan mengejar keuntungan pribadi di luar negeri.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (8368, 133, 'Pancasila sebagai ideologi terbuka memiliki batas-batas berikut, kecuali', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #133', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_133_1778528131.html', 0, 'B', 'Pancasila sebagai ideologi terbuka dapat berkembang dan menyerap nilai baru, tetapi tetap harus melalui konsensus nasional. Penciptaan norma baru tanpa konsensus bertentangan dengan prinsip demokrasi.');
