INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (9503, 290, '\"Sesudah tiga hari berturut-turut anggota-anggota Dokuritsu Zyunbi Tyoosakai mengeluarkan pendapat-pendapatnya, maka sekarang saya mendapat kehormatan dari Paduka Tuan Ketua yang mulia untuk mengemukakan pendapat saya...\" Dalam pidatonya di sidang BPUPKI Bung Karno telah menyampaikan prinsip dasar negara yakni...', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #290', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_290_1778528160.html', 0, 'C', 'Pada tanggal 1 Juni 1945, Ir. Soekarno menyampaikan pidato di hadapan sidang BPUPKI dengan lima asas: Nasionalisme, Internasionalisme, Mufakat, Kesejahteraan sosial, dan Ketuhanan yang berkebudayaan.');
