INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (26924, 351, 'Paham integralistik yang terkandung dalam Pancasila meletakkan asas kebersamaan hidup, menginginkan keselarasan dalam hubungan, baik antara individu maupun masyarakat. Jika dirinci, maka paham negara integralistik mempunyai pandangan sebagai berikut, kecuali...', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #351', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_351_1778529767.html', 0, 'B', 'Paham negara integralistik menempatkan kepentingan masyarakat seluruhnya sebagai satu kesatuan, bukan kepentingan individu sebagai pusat.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (28746, 351, 'Paham integralistik yang terkandung dalam Pancasila meletakkan asas kebersamaan hidup, menginginkan keselarasan dalam hubungan, baik antara individu maupun masyarakat. Jika dirinci, maka paham negara integralistik mempunyai pandangan sebagai berikut, kecuali...', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #351', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_351_1778529817.html', 0, 'B', 'Paham negara integralistik menempatkan kepentingan masyarakat seluruhnya sebagai satu kesatuan, bukan kepentingan individu sebagai pusat.');
