INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (38974, 398, 'Tanggal berapa proklamasi kemerdekaan Indonesia diumumkan?', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #398', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_398_1778530095.html', 0, 'A', 'Proklamasi kemerdekaan Indonesia diumumkan pada 17 Agustus 1945 oleh Ir. Soekarno dan Mohammad Hatta.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (17483, 443, 'Paham integralistik yang terkandung dalam Pancasila meletakkan asas kebersamaan hidup, menginginkan keselarasan dalam hubungan, baik antara individu maupun masyarakat. Jika dirinci, maka paham negara integralistik mempunyai pandangan sebagai berikut, kecuali...', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #443', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_443_1778528440.html', 0, 'B', 'Paham negara integralistik menempatkan kepentingan masyarakat seluruhnya sebagai satu kesatuan, bukan kepentingan individu sebagai pusat.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (34765, 443, 'Paham integralistik yang terkandung dalam Pancasila meletakkan asas kebersamaan hidup, menginginkan keselarasan dalam hubungan, baik antara individu maupun masyarakat. Jika dirinci, maka paham negara integralistik mempunyai pandangan sebagai berikut, kecuali...', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #443', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_443_1778529978.html', 0, 'B', 'Paham negara integralistik menempatkan kepentingan masyarakat seluruhnya sebagai satu kesatuan, bukan kepentingan individu sebagai pusat.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (37691, 443, 'Paham integralistik yang terkandung dalam Pancasila meletakkan asas kebersamaan hidup, menginginkan keselarasan dalam hubungan, baik antara individu maupun masyarakat. Jika dirinci, maka paham negara integralistik mempunyai pandangan sebagai berikut, kecuali...', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #443', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_443_1778530066.html', 0, 'B', 'Paham negara integralistik menempatkan kepentingan masyarakat seluruhnya sebagai satu kesatuan, bukan kepentingan individu sebagai pusat.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (15977, 467, '\"Sesudah tiga hari berturut-turut anggota-anggota Dokuritsu Zyunbi Tyoosakai mengeluarkan pendapat-pendapatnya, maka sekarang saya mendapat kehormatan dari Paduka Tuan Ketua yang mulia untuk mengemukakan pendapat saya...\" Dalam pidatonya di sidang BPUPKI Bung Karno telah menyampaikan prinsip dasar negara yakni...', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #467', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_467_1778528395.html', 0, 'C', 'Pada tanggal 1 Juni 1945, Ir. Soekarno menyampaikan pidato di hadapan sidang BPUPKI dengan lima asas: Nasionalisme, Internasionalisme, Mufakat, Kesejahteraan sosial, dan Ketuhanan yang berkebudayaan.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (33321, 467, '\"Sesudah tiga hari berturut-turut anggota-anggota Dokuritsu Zyunbi Tyoosakai mengeluarkan pendapat-pendapatnya, maka sekarang saya mendapat kehormatan dari Paduka Tuan Ketua yang mulia untuk mengemukakan pendapat saya...\" Dalam pidatonya di sidang BPUPKI Bung Karno telah menyampaikan prinsip dasar negara yakni...', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #467', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_467_1778529939.html', 0, 'C', 'Pada tanggal 1 Juni 1945, Ir. Soekarno menyampaikan pidato di hadapan sidang BPUPKI dengan lima asas: Nasionalisme, Internasionalisme, Mufakat, Kesejahteraan sosial, dan Ketuhanan yang berkebudayaan.');
