INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (14902, 476, 'Secara umum, tujuan bela negara adalah untuk mewujudkan sikap dan perilaku yang mendukung sistem pertahanan negara. Salah satu nilai utama dalam bela negara adalah kesadaran berbangsa dan bernegara. Bagaimana kesadaran ini seharusnya diimplementasikan dalam kehidupan sehari-hari?', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #476', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_476_1778528366.html', 0, 'B', 'Kesadaran berbangsa dan bernegara diimplementasikan dengan menghormati perbedaan dan menjaga kerukunan antar suku, agama, ras, dan golongan.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (20098, 476, 'Secara umum, tujuan bela negara adalah untuk mewujudkan sikap dan perilaku yang mendukung sistem pertahanan negara. Salah satu nilai utama dalam bela negara adalah kesadaran berbangsa dan bernegara. Bagaimana kesadaran ini seharusnya diimplementasikan dalam kehidupan sehari-hari?', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #476', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_476_1778529582.html', 0, 'B', 'Kesadaran berbangsa dan bernegara diimplementasikan dengan menghormati perbedaan dan menjaga kerukunan antar suku, agama, ras, dan golongan.');
