INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (15282, 477, 'Dalam konteks penerapan prinsip Bhinneka Tunggal Ika, berikut adalah pernyataan yang paling tepat mengenai masyarakat Indonesia dalam mengelola keberagaman...', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #477', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_477_1778528374.html', 0, 'C', 'Bhinneka Tunggal Ika berarti berbeda-beda tetapi tetap satu jua. Masyarakat harus mengintegrasikan perbedaan dalam satu identitas nasional sambil mempertahankan keberagaman.');
