INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (9864, 478, 'Pancasila sebagai dasar negara Indonesia memainkan peran penting dalam memperkuat persatuan dan kesatuan bangsa. Bagaimana Pancasila sebagai dasar negara Indonesia memperkuat persatuan dan kesatuan bangsa?', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #478', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_478_1778528171.html', 0, 'C', 'Pancasila membentuk identitas nasional yang kuat dan bersatu sebagai dasar persatuan bangsa.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (28100, 478, 'Pancasila sebagai dasar negara Indonesia memainkan peran penting dalam memperkuat persatuan dan kesatuan bangsa. Bagaimana Pancasila sebagai dasar negara Indonesia memperkuat persatuan dan kesatuan bangsa?', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #478', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_478_1778529797.html', 0, 'C', 'Pancasila membentuk identitas nasional yang kuat dan bersatu sebagai dasar persatuan bangsa.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (17625, 479, 'Banyak korban musibah longsor yang terjadi di Indonesia mendorong kita untuk bersatu dan saling menolong. Apa dampak sosial utama jika kita tidak membantu korban bencana tersebut?', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #479', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_479_1778528443.html', 0, 'A', 'Dampak sosial utama adalah menurunnya semangat gotong-royong dalam masyarakat jika kita tidak saling menolong.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (21003, 480, 'Bagaimana hubungan antara Presiden dan DPR dalam mekanisme pemberian amnesti dan abolisi?', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #480', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_480_1778529610.html', 0, 'B', 'Berdasarkan Pasal 14 ayat (2) UUD 1945, Presiden memberikan amnesti dan abolisi dengan pertimbangan DPR.');
