INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (34441, 480, 'Bagaimana hubungan antara Presiden dan DPR dalam mekanisme pemberian amnesti dan abolisi?', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #480', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_480_1778529967.html', 0, 'B', 'Berdasarkan Pasal 14 ayat (2) UUD 1945, Presiden memberikan amnesti dan abolisi dengan pertimbangan DPR.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (23154, 481, 'Pasal 14 ayat (2) UUD 1945 menyatakan bahwa Presiden memberikan amnesti dan abolisi dengan pertimbangan dari suatu lembaga negara. Dalam konteks era sekarang, bagaimana mekanisme ini berperan dalam menjaga keadilan dan hukum di Indonesia?', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #481', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_481_1778529667.html', 0, 'B', 'Pertimbangan DPR memastikan transparansi dan akuntabilitas dalam pemberian amnesti dan abolisi sebagai bentuk check and balance.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (34827, 481, 'Pasal 14 ayat (2) UUD 1945 menyatakan bahwa Presiden memberikan amnesti dan abolisi dengan pertimbangan dari suatu lembaga negara. Dalam konteks era sekarang, bagaimana mekanisme ini berperan dalam menjaga keadilan dan hukum di Indonesia?', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #481', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_481_1778529980.html', 0, 'B', 'Pertimbangan DPR memastikan transparansi dan akuntabilitas dalam pemberian amnesti dan abolisi sebagai bentuk check and balance.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (8471, 507, 'Hampir semua partai politik melakukan proses permohonan gugatan kepada KPU, adapun sengketa yang diajukan antara lain terkait masalah internal dan perselisihan kursi terakhir di DPR RI. Komisi Pemilihan Umum (KPU) RI berusaha mengumpulkan bukti-bukti dari KPU daerah untuk menghadapi gugatan sengketa PHPU Legislatif 2019, yang akan segera disidangkan Komisioner KPU Ilham Saputra mengatakan, bukti-bukti dari KPU Kabupaten/kota dan provinsi itu akan dijadikan bahan untuk memberikan keterangan dalam sidang sengketa Pileg 2019. Jika terjadi kasus tersebut maka yang memiliki kewenangan untuk memberikan putusan adalah...', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #507', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_507_1778528133.html', 0, 'C', 'Sengketa hasil pemilihan umum (PHPU) merupakan kewenangan Mahkamah Konstitusi berdasarkan UUD 1945 Pasal 24C ayat (1).');
