INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (12871, 509, 'Pancasila sebagai ideologi terbuka memiliki batas-batas berikut, kecuali', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #509', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_509_1778528299.html', 0, 'B', 'Pancasila sebagai ideologi terbuka dapat berkembang dan menyerap nilai baru, tetapi tetap harus melalui konsensus nasional. Penciptaan norma baru tanpa konsensus bertentangan dengan prinsip demokrasi.');
