INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (11287, 512, 'Mengembangkan sikap bahwa bangsa Indonesia merupakan bagian dari seluruh umat manusia merupakan perwujudan sila ke...', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #512', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_512_1778528207.html', 0, 'B', 'Sila ke-2 Kemanusiaan yang Adil dan Beradab menekankan bahwa bangsa Indonesia adalah bagian dari masyarakat dunia.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (13369, 512, 'Mengembangkan sikap bahwa bangsa Indonesia merupakan bagian dari seluruh umat manusia merupakan perwujudan sila ke...', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #512', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_512_1778528310.html', 0, 'B', 'Sila ke-2 Kemanusiaan yang Adil dan Beradab menekankan bahwa bangsa Indonesia adalah bagian dari masyarakat dunia.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (36595, 520, 'Tanggal berapa proklamasi kemerdekaan Indonesia diumumkan?', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #520', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_520_1778530041.html', 0, 'A', 'Proklamasi kemerdekaan Indonesia diumumkan pada 17 Agustus 1945 oleh Ir. Soekarno dan Mohammad Hatta.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (30632, 565, 'Paham integralistik yang terkandung dalam Pancasila meletakkan asas kebersamaan hidup, menginginkan keselarasan dalam hubungan, baik antara individu maupun masyarakat. Jika dirinci, maka paham negara integralistik mempunyai pandangan sebagai berikut, kecuali...', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #565', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_565_1778529863.html', 0, 'B', 'Paham negara integralistik menempatkan kepentingan masyarakat seluruhnya sebagai satu kesatuan, bukan kepentingan individu sebagai pusat.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (10342, 568, 'UUD 1945 yang disahkan oleh Panitia Persiapan Kemerdekaan Indonesia (PPKI) pada 18 Agustus 1945 terdiri atas...', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #568', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_568_1778528182.html', 0, 'B', 'UUD 1945 terdiri dari Pembukaan, Batang Tubuh, dan Penjelasan.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (36912, 568, 'UUD 1945 yang disahkan oleh Panitia Persiapan Kemerdekaan Indonesia (PPKI) pada 18 Agustus 1945 terdiri atas...', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #568', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_568_1778530048.html', 0, 'B', 'UUD 1945 terdiri dari Pembukaan, Batang Tubuh, dan Penjelasan.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (14043, 589, '\"Sesudah tiga hari berturut-turut anggota-anggota Dokuritsu Zyunbi Tyoosakai mengeluarkan pendapat-pendapatnya, maka sekarang saya mendapat kehormatan dari Paduka Tuan Ketua yang mulia untuk mengemukakan pendapat saya...\" Dalam pidatonya di sidang BPUPKI Bung Karno telah menyampaikan prinsip dasar negara yakni...', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #589', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_589_1778528337.html', 0, 'C', 'Pada tanggal 1 Juni 1945, Ir. Soekarno menyampaikan pidato di hadapan sidang BPUPKI dengan lima asas: Nasionalisme, Internasionalisme, Mufakat, Kesejahteraan sosial, dan Ketuhanan yang berkebudayaan.');
