INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (21252, 598, 'Secara umum, tujuan bela negara adalah untuk mewujudkan sikap dan perilaku yang mendukung sistem pertahanan negara. Salah satu nilai utama dalam bela negara adalah kesadaran berbangsa dan bernegara. Bagaimana kesadaran ini seharusnya diimplementasikan dalam kehidupan sehari-hari?', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #598', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_598_1778529615.html', 0, 'B', 'Kesadaran berbangsa dan bernegara diimplementasikan dengan menghormati perbedaan dan menjaga kerukunan antar suku, agama, ras, dan golongan.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (24885, 598, 'Secara umum, tujuan bela negara adalah untuk mewujudkan sikap dan perilaku yang mendukung sistem pertahanan negara. Salah satu nilai utama dalam bela negara adalah kesadaran berbangsa dan bernegara. Bagaimana kesadaran ini seharusnya diimplementasikan dalam kehidupan sehari-hari?', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #598', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_598_1778529715.html', 0, 'B', 'Kesadaran berbangsa dan bernegara diimplementasikan dengan menghormati perbedaan dan menjaga kerukunan antar suku, agama, ras, dan golongan.');
