INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (3431, 601, 'Banyak korban musibah longsor yang terjadi di Indonesia mendorong kita untuk bersatu dan saling menolong. Apa dampak sosial utama jika kita tidak membantu korban bencana tersebut?', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #601', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_601_1778527978.html', 0, 'A', 'Dampak sosial utama adalah menurunnya semangat gotong-royong dalam masyarakat jika kita tidak saling menolong.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (14692, 601, 'Banyak korban musibah longsor yang terjadi di Indonesia mendorong kita untuk bersatu dan saling menolong. Apa dampak sosial utama jika kita tidak membantu korban bencana tersebut?', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #601', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_601_1778528351.html', 0, 'A', 'Dampak sosial utama adalah menurunnya semangat gotong-royong dalam masyarakat jika kita tidak saling menolong.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (18650, 602, 'Bagaimana hubungan antara Presiden dan DPR dalam mekanisme pemberian amnesti dan abolisi?', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #602', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_602_1778528483.html', 0, 'B', 'Berdasarkan Pasal 14 ayat (2) UUD 1945, Presiden memberikan amnesti dan abolisi dengan pertimbangan DPR.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (23457, 602, 'Bagaimana hubungan antara Presiden dan DPR dalam mekanisme pemberian amnesti dan abolisi?', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #602', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_602_1778529674.html', 0, 'B', 'Berdasarkan Pasal 14 ayat (2) UUD 1945, Presiden memberikan amnesti dan abolisi dengan pertimbangan DPR.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (12293, 603, 'Pasal 14 ayat (2) UUD 1945 menyatakan bahwa Presiden memberikan amnesti dan abolisi dengan pertimbangan dari suatu lembaga negara. Dalam konteks era sekarang, bagaimana mekanisme ini berperan dalam menjaga keadilan dan hukum di Indonesia?', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #603', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_603_1778528235.html', 0, 'B', 'Pertimbangan DPR memastikan transparansi dan akuntabilitas dalam pemberian amnesti dan abolisi sebagai bentuk check and balance.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (13256, 603, 'Pasal 14 ayat (2) UUD 1945 menyatakan bahwa Presiden memberikan amnesti dan abolisi dengan pertimbangan dari suatu lembaga negara. Dalam konteks era sekarang, bagaimana mekanisme ini berperan dalam menjaga keadilan dan hukum di Indonesia?', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #603', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_603_1778528307.html', 0, 'B', 'Pertimbangan DPR memastikan transparansi dan akuntabilitas dalam pemberian amnesti dan abolisi sebagai bentuk check and balance.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (18740, 679, 'Hampir semua partai politik melakukan proses permohonan gugatan kepada KPU, adapun sengketa yang diajukan antara lain terkait masalah internal dan perselisihan kursi terakhir di DPR RI. Komisi Pemilihan Umum (KPU) RI berusaha mengumpulkan bukti-bukti dari KPU daerah untuk menghadapi gugatan sengketa PHPU Legislatif 2019, yang akan segera disidangkan Komisioner KPU Ilham Saputra mengatakan, bukti-bukti dari KPU Kabupaten/kota dan provinsi itu akan dijadikan bahan untuk memberikan keterangan dalam sidang sengketa Pileg 2019. Jika terjadi kasus tersebut maka yang memiliki kewenangan untuk memberikan putusan adalah...', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #679', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_679_1778528485.html', 0, 'C', 'Sengketa hasil pemilihan umum (PHPU) merupakan kewenangan Mahkamah Konstitusi berdasarkan UUD 1945 Pasal 24C ayat (1).');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (39802, 681, 'Pancasila sebagai ideologi terbuka memiliki batas-batas berikut, kecuali', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #681', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_681_1778530113.html', 0, 'B', 'Pancasila sebagai ideologi terbuka dapat berkembang dan menyerap nilai baru, tetapi tetap harus melalui konsensus nasional. Penciptaan norma baru tanpa konsensus bertentangan dengan prinsip demokrasi.');
