INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (9677, 1313, 'Alberto Gonzales tinggal di Indonesia sudah lebih dari 5 tahun dan menikah dengan seorang wanita Indonesia dan dikaruniai 3 orang anak. Karena ia telah jatuh cinta dengan Indonesia sehingga ingin mengganti kewarganegaraannya menjadi warga negara Indonesia. Landasan hukum yang digunakan Gonzales untuk mengganti kewarganegaraanya tertuang dalam Undang-Undang Hak Asasi Manusia yakni pada pasal...', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #1313', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_1313_1778528164.html', 0, 'A', 'Pasal 26 Ayat 1 dan 2 UUD 1945 menyatakan: (1) Yang menjadi warga negara ialah orang-orang bangsa Indonesia asli dan orang-orang bangsa lain yang disahkan dengan undang-undang sebagai warga negara.');
