INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (11801, 1317, 'Indonesia telah mengalami beberapa kali perubahan konstitusi sejak kemerdekaan. Urutan perubahan konstitusi yang benar adalah...', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #1317', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_1317_1778528224.html', 0, 'B', 'Urutan perubahan konstitusi di Indonesia dimulai dari UUD 1945 (1945–1949), kemudian Konstitusi RIS (1949–1950), dilanjutkan UUDS 1950 (1950–1959), dan kembali ke UUD 1945 yang kemudian mengalami amandemen pada periode 1999–2002.');
