INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (30325, 2175, 'Konflik antara Indonesia dengan Tiongkok kembali terjadi di Perairan Natuna yang berbatasan dengan Laut Cina Selatan. Sejumlah kapal penangkap ikan asal Tiongkok didampingi kapan Coast Guard negaranya, berkegiatan di perairan yang masih masuk dalam teritori ZonaEkonomi Eksklusif (ZEE) milik Indonesia. Hal tersebut juga merupakan sebuah ancaman bagi Indonesia. Ancaman terhadap satu pulau atau daerah pada hakikatnya ancaman seluruh bangsa dan negara. Hal ini ditegaskan dalam wawasan Nusantara dalam bidang...', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #2175', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_2175_1778529856.html', 0, 'E', 'Wawasan Nusantara dalam bidang Hankam menyatakan bahwa ancaman terhadap satu pulau atau daerah adalah ancaman terhadap seluruh bangsa dan negara.');
