INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (38465, 3671, 'Tindakan bullying saat ini menjadi momok yang menakutkan bagi generasi muda. Bahkan bullying bisa dilakukan dimana saja karena arus perkembangan teknologi informasi dan komunikasi yang begitu cepat. Penyebab utama kasus cyber bullying pada era milennial saat ini ditinjau dari pendekatan pilar kebangsaan disebabkan oleh...', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #3671', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_3671_1778530083.html', 0, 'E', 'Lunturnya pemahaman terhadap nilai-nilai Pancasila menjadi penyebab utama cyber bullying karena Pancasila sebagai dasar moral bangsa.');
