INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (25474, 3783, 'Setiap siswa peserta kesenian adalah peserta bela diri atau renang. Tidak ada peserta bela diri atau renang yang bukan peserta melukis. Inda bukan peserta melukis.', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #3783', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_3783_1778529728.html', 0, 'A', 'Inda bukan peserta melukis, maka Inda bukan peserta bela diri maupun kesenian.');
