INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (15820, 6153, 'Kekerasan dalam rumah tangga (disingkat KDRT) adalah tindakan yang dilakukan di dalam rumah tangga baik oleh suami, istri, maupun anak yang berdampak buruk terhadap keutuhan fisik, psikis, dan keharmonisan hubungan sesuai yang termaktub dalam pasal 1 UU Nomor 23 tahun 2004 tentang Penghapusan Kekerasan dalam Rumah Tangga (UU PKDRT). Kekerasan dalam rumah tangga adalah penyimpangan sila ke...', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #6153', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_6153_1778528391.html', 0, 'B', 'Kekerasan dalam rumah tangga adalah penyimpangan sila ke-2 (Kemanusiaan yang Adil dan Beradab).');
