INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (15244, 6154, 'Integrasi nasional seharusnya dimulai dari pejabat negara sehingga bisa memberikan contoh bagi warga negara. Salah satu tindakan pejabat negara yang tidak mendukung integritas negara adalah praktik korupsi. Komisi Pemberantasan Korupsi (KPK) merupakan lembaga negara yang dibentuk untuk menyelidiki kasus kejahatan luar biasa korupsi, kolusi, dan nepotisme(KKN). Berbagai kasus korupsi mencuat ke permukaan. KPK berhasil mengungkap dan menangkap pelakunya. Akan tetapi, kasus korupsi masih marak terjadi. Upaya paling tepat yang dapat dilakukan masyarakat untuk menghentikan praktik kejahatan luar biasa tersebut adalah ....', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #6154', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_6154_1778528374.html', 0, 'B', 'Upaya paling tepat yang dapat dilakukan masyarakat untuk menghentikan praktik korupsi adalah menegakkan hukum setegak-tegaknya tanpa pandang bulu.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (29005, 6154, 'Integrasi nasional seharusnya dimulai dari pejabat negara sehingga bisa memberikan contoh bagi warga negara. Salah satu tindakan pejabat negara yang tidak mendukung integritas negara adalah praktik korupsi. Komisi Pemberantasan Korupsi (KPK) merupakan lembaga negara yang dibentuk untuk menyelidiki kasus kejahatan luar biasa korupsi, kolusi, dan nepotisme(KKN). Berbagai kasus korupsi mencuat ke permukaan. KPK berhasil mengungkap dan menangkap pelakunya. Akan tetapi, kasus korupsi masih marak terjadi. Upaya paling tepat yang dapat dilakukan masyarakat untuk menghentikan praktik kejahatan luar biasa tersebut adalah ....', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #6154', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_6154_1778529823.html', 0, 'B', 'Upaya paling tepat yang dapat dilakukan masyarakat untuk menghentikan praktik korupsi adalah menegakkan hukum setegak-tegaknya tanpa pandang bulu.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (19043, 6155, 'Krisis moneter pernah terjadi di Indonesia pada tahun 1997. Krisis itu memukul perekonomian dan usaha di Indonesia. Diambil dari buku Monetary Policy Strategy (2007) karya Frederic S Mishkin, krisis moneter adalah krisis yang berhubungan dengan keuangan suatu negara. Krisis Moneter yang dialami Indonesia sejak tahun 1997-1998, ditandai dengan melemahnya nilai tukar rupiah yang sangat drastis. Disebabkan oleh?', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #6155', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_6155_1778528545.html', 0, 'C', 'Krisis Moneter yang dialami Indonesia sejak tahun 1997-1998 disebabkan oleh faktor internal dan eksternal.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (37567, 6155, 'Krisis moneter pernah terjadi di Indonesia pada tahun 1997. Krisis itu memukul perekonomian dan usaha di Indonesia. Diambil dari buku Monetary Policy Strategy (2007) karya Frederic S Mishkin, krisis moneter adalah krisis yang berhubungan dengan keuangan suatu negara. Krisis Moneter yang dialami Indonesia sejak tahun 1997-1998, ditandai dengan melemahnya nilai tukar rupiah yang sangat drastis. Disebabkan oleh?', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #6155', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_6155_1778530063.html', 0, 'C', 'Krisis Moneter yang dialami Indonesia sejak tahun 1997-1998 disebabkan oleh faktor internal dan eksternal.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (36112, 6156, 'Peristiwa Bandung Lautan Api adalah peristiwa kebakaran besar yang terjadi di kota Bandung, provinsi Jawa Barat, Indonesia pada 23 Maret 1946. Dalam waktu tujuh jam, sekitar 200.000 penduduk Bandung membakar rumah mereka, meninggalkan kota menuju pegunungan di daerah selatan Bandung. Hal ini dilakukan untuk mencegah tentara Sekutu dan tentara NICA Belanda untuk dapat menggunakan kota Bandung sebagai markas strategis militer dalam Perang Kemerdekaan Indonesia. Peristiwa yang tidak menjadi Latar belakang terjadinya Bandung Lautan Api adalah.....', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #6156', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_6156_1778530031.html', 0, 'E', 'Peristiwa yang tidak menjadi latar belakang terjadinya Bandung Lautan Api adalah terjadinya kesenjangan Ekonomi pada Warga Bandung pada masa itu.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (6174, 6157, 'Mata uang Lira adalah mata uang dari negara ...', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #6157', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_6157_1778528071.html', 0, 'B', 'Mata uang Lira adalah mata uang dari negara Turki.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (27356, 6158, 'Pemenggalan kata yang tidak sesuai dengan Ejaan Yang Disempurnakan terdapat pada kata ...', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #6158', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_6158_1778529776.html', 0, 'C', 'Pemenggalan kata yang tidak sesuai dengan EYD terdapat pada kata Sa - u - da - ra. Yang benar adalah Sau - da - ra.');
