INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (7021, 7704, 'UUD NRI 1945 mengandung ketentuan yang memberikan kebebasan dalam menjalankan ibadah sesuai dengan agama dan kepercayaan masing-masing. Contoh perilaku yang mencerminkannya adalah...', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #7704', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_7704_1778528093.html', 0, 'C', 'Pilihan C adalah yang paling tepat. Menghormati dan memberikan kesempatan kepada orang lain untuk menjalankan ibadahnya menunjukkan sikap toleransi dan penghormatan terhadap kebebasan beragama, sesuai dengan semangat UUD NRI 1945. Sikap ini mendukung terciptanya lingkungan yang harmonis dan damai di tengah masyarakat yang beragam.');
