INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (22795, 7892, 'Pergerakan Boedi Utomo dimaksudkan dalam rangka mewujudkan...', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #7892', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_7892_1778529659.html', 0, 'A', 'Pergerakan Boedi Utomo dimaksudkan untuk mewujudkan cita-cita kebangsaan.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (27730, 8333, 'Kebersihan lingkungan adalah tanggung jawab kita bersama. Kita harus memulainya dari bagian terkecil dari kebersihan lingkungan, yaitu diri kita sendiri. Kita dapat memulainya dari hal - hal sederhana, seperti tidak membuang sampah sembarangan, dan senantiasa menjaga kebersihan diri. Setelah berhasil dari diri kita, kita dapat melanjutkan upaya kita kepada lingkungan terdekat, seperti keluarga, dan tetangga. Dengan terciptanya kesadaran bersama, kebersihan lingkungan bukan merupakan tanggung jawab yang berat. Ide pokok dari bacaan di atas adalah ...', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #8333', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_8333_1778529788.html', 0, 'B', 'Ide pokok dari bacaan di atas adalah kebersihan lingkungan adalah tanggung jawab bersama.');
