INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (31003, 10670, 'Perhatikan perilaku berikut ini! 1. Menyontek pada saat ujian untuk meraih prestasi. 2. Membuat berita bohong di media sosial agar terkenal. 3. Mengunggah ujaran kebencian karena sering mendapat perundungan. 4. Memberikan informasi palsu karena mendapatkan tekanan. 5. Mengajak anak-anak untuk menjadi pekerja paruh waktu. Berdasarkan perilaku di atas, tindakan yang bertentangan dengan nilai harkat dan martabat kemanusiaan dalam Pancasila ditunjukan oleh nomor...', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #10670', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_10670_1778529875.html', 0, 'B', 'Pilihan B adalah yang paling tepat. Membuat berita bohong dan mengunggah ujaran kebencian keduanya bertentangan dengan nilai kemanusiaan yang menekankan pada penghormatan terhadap martabat orang lain. Berita bohong dapat menyesatkan publik dan merusak keharmonisan sosial, sementara ujaran kebencian menumbuhkan kebencian dan merendahkan martabat orang yang dituju.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (35638, 10670, 'Perhatikan perilaku berikut ini! 1. Menyontek pada saat ujian untuk meraih prestasi. 2. Membuat berita bohong di media sosial agar terkenal. 3. Mengunggah ujaran kebencian karena sering mendapat perundungan. 4. Memberikan informasi palsu karena mendapatkan tekanan. 5. Mengajak anak-anak untuk menjadi pekerja paruh waktu. Berdasarkan perilaku di atas, tindakan yang bertentangan dengan nilai harkat dan martabat kemanusiaan dalam Pancasila ditunjukan oleh nomor...', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #10670', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_10670_1778529998.html', 0, 'B', 'Pilihan B adalah yang paling tepat. Membuat berita bohong dan mengunggah ujaran kebencian keduanya bertentangan dengan nilai kemanusiaan yang menekankan pada penghormatan terhadap martabat orang lain. Berita bohong dapat menyesatkan publik dan merusak keharmonisan sosial, sementara ujaran kebencian menumbuhkan kebencian dan merendahkan martabat orang yang dituju.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (14893, 10671, 'Hubungan antara india dan Pakistan sering mengalami gangguan karena persoalan perbatasan di Kashmir. Sejalan dengan politik luar negeri Indonesia, peran apakah yang dapat dilakukan oleh pemerintah Indonesia?', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #10671', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_10671_1778528366.html', 0, 'C', 'Pilihan C adalah yang paling tepat. Indonesia, sesuai dengan politik luar negeri bebas aktif, dapat berperan sebagai pendorong untuk mencapai solusi damai antara India dan Pakistan. Indonesia sering menjadi mediator dan mendukung upaya perdamaian di berbagai konflik internasional.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (18089, 10671, 'Hubungan antara india dan Pakistan sering mengalami gangguan karena persoalan perbatasan di Kashmir. Sejalan dengan politik luar negeri Indonesia, peran apakah yang dapat dilakukan oleh pemerintah Indonesia?', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #10671', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_10671_1778528470.html', 0, 'C', 'Pilihan C adalah yang paling tepat. Indonesia, sesuai dengan politik luar negeri bebas aktif, dapat berperan sebagai pendorong untuk mencapai solusi damai antara India dan Pakistan. Indonesia sering menjadi mediator dan mendukung upaya perdamaian di berbagai konflik internasional.');
