INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (27684, 11425, 'Penggunaan berita bohong di masa kampanye pemilu presiden dan wakil presiden tahun 2019 telah membelah kesatuan bangsa yang memiliki keragaman latar belakang. Sebagai seorang warga negara Indonesia yang memiliki literasi teknologi dan informasi tinggi upaya yang tepat untuk menghentikan berita bohong tersebut adalah...', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #11425', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_11425_1778529784.html', 0, 'D', 'Pilihan D adalah yang paling tepat. Sebagai orang yang memiliki literasi teknologi tinggi, langkah pertama yang bisa dilakukan adalah memastikan diri sendiri tidak menjadi bagian dari penyebaran hoaks. Dengan menghentikan penyebaran dari diri sendiri, seseorang ikut berperan dalam memutus rantai hoaks dan menjaga persatuan bangsa.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (21683, 11432, 'Mengembangkan sikap bahwa bangsa Indonesia merupakan bagian dari seluruh umat manusia merupakan perwujudan sila ke...', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #11432', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_11432_1778529625.html', 0, 'B', 'Sila ke-2 Kemanusiaan yang Adil dan Beradab menekankan bahwa bangsa Indonesia adalah bagian dari masyarakat dunia.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (13257, 11971, 'Janji kemerdekaan yang akan diberikan Jepang setelah kekalahan Jepang pada saat Perang Dunia II diumumkan oleh...', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #11971', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_11971_1778528307.html', 0, 'B', 'Janji kemerdekaan yang akan diberikan Jepang setelah kekalahan Jepang pada saat Perang Dunia II diumumkan oleh Perdana Menteri Kyoto.');
