INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (9891, 12048, 'Integrasi nasional seharusnya dimulai dari pejabat negara sehingga bisa memberikan contoh bagi warga negara. Salah satu tindakan pejabat negara yang tidak mendukung integritas negara adalah praktik korupsi. Komisi Pemberantasan Korupsi (KPK) merupakan lembaga negara yang dibentuk untuk menyelidiki kasus kejahatan luar biasa korupsi, kolusi, dan nepotisme(KKN). Berbagai kasus korupsi mencuat ke permukaan. KPK berhasil mengungkap dan menangkap pelakunya. Akan tetapi, kasus korupsi masih marak terjadi. Upaya paling tepat yang dapat dilakukan masyarakat untuk menghentikan praktik kejahatan luar biasa tersebut adalah ....', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #12048', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_12048_1778528172.html', 0, 'B', 'Upaya paling tepat yang dapat dilakukan masyarakat untuk menghentikan praktik korupsi adalah menegakkan hukum setegak-tegaknya tanpa pandang bulu.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (23071, 12048, 'Integrasi nasional seharusnya dimulai dari pejabat negara sehingga bisa memberikan contoh bagi warga negara. Salah satu tindakan pejabat negara yang tidak mendukung integritas negara adalah praktik korupsi. Komisi Pemberantasan Korupsi (KPK) merupakan lembaga negara yang dibentuk untuk menyelidiki kasus kejahatan luar biasa korupsi, kolusi, dan nepotisme(KKN). Berbagai kasus korupsi mencuat ke permukaan. KPK berhasil mengungkap dan menangkap pelakunya. Akan tetapi, kasus korupsi masih marak terjadi. Upaya paling tepat yang dapat dilakukan masyarakat untuk menghentikan praktik kejahatan luar biasa tersebut adalah ....', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #12048', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_12048_1778529665.html', 0, 'B', 'Upaya paling tepat yang dapat dilakukan masyarakat untuk menghentikan praktik korupsi adalah menegakkan hukum setegak-tegaknya tanpa pandang bulu.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (10056, 12054, 'Kebersihan lingkungan adalah tanggung jawab kita bersama. Kita harus memulainya dari bagian terkecil dari kebersihan lingkungan, yaitu diri kita sendiri. Kita dapat memulainya dari hal - hal sederhana, seperti tidak membuang sampah sembarangan, dan senantiasa menjaga kebersihan diri. Setelah berhasil dari diri kita, kita dapat melanjutkan upaya kita kepada lingkungan terdekat, seperti keluarga, dan tetangga. Dengan terciptanya kesadaran bersama, kebersihan lingkungan bukan merupakan tanggung jawab yang berat. Ide pokok dari bacaan di atas adalah ...', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #12054', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_12054_1778528176.html', 0, 'B', 'Ide pokok dari bacaan di atas adalah kebersihan lingkungan adalah tanggung jawab bersama.');
