INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (24311, 12180, 'Perbedaan pandangan antar golongan agama (Islam) dan nasionalis dalam perumusan pancasila sebagai dasar negara di Sidang BPUPKI menunjukkan bahwa perbedaan pandangan merupakan hal biasa dan wajar terjadi dalam memutuskan sesuatu. Proses yang terjadi pada masa perumusan dan penetapan UUD 1945 di sidang BPUPKI menunjukkan bahwa...', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #12180', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_12180_1778529697.html', 0, 'D', 'Pilihan D adalah yang paling tepat. Sidang BPUPKI mengakomodasi berbagai pandangan dari kelompok Islam dan nasionalis, sehingga kesepakatan yang diambil dapat diterima oleh semua pihak. Perumusan dasar negara Pancasila menunjukkan sikap saling menghormati dan kemampuan untuk berkompromi demi kepentingan bersama.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (4839, 12181, 'UUD NRI 1945 pasal 28J ayat 1 menyebutkan bahwa setiap orang wajib menghormati hak asasi manusia orang lain dalam tertib kehidupan bermasyarakat, berbangsa, dan bernegara. Dari bunyi pasal tersebut, perilaku yang mencerminkan sikap kesadaran nasionalisme adalah...', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #12181', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_12181_1778528035.html', 0, 'C', 'Pilihan C adalah yang paling tepat. Pernyataan ini menunjukkan bahwa setiap individu menyadari keterkaitan antara hak orang lain dan kewajiban pribadi. Dengan menghormati hak orang lain, seseorang melaksanakan kewajibannya sebagai warga negara yang baik.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (29917, 12182, 'UUD NRI 1945 pasal 22E ayat 1 menyebutkan bahwa pemilu dilaksanakan secara langsung, umum, bebas, rahasia, jujur dan adil setiap lima tahun sekali. Dari pernyataan pasal tersebut, perilaku yang mencerminkan sikap nasionalisme adalah...', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #12182', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_12182_1778529847.html', 0, 'E', 'Pilihan E adalah yang paling tepat. Marlena menggunakan hak pilihnya secara bebas dan bertanggung jawab, sesuai dengan hati nuraninya dan berdasarkan evaluasi terhadap program kerja partai politik. Sikap ini mencerminkan prinsip pemilu yang langsung, umum, bebas, rahasia, jujur, dan adil.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (37977, 12182, 'UUD NRI 1945 pasal 22E ayat 1 menyebutkan bahwa pemilu dilaksanakan secara langsung, umum, bebas, rahasia, jujur dan adil setiap lima tahun sekali. Dari pernyataan pasal tersebut, perilaku yang mencerminkan sikap nasionalisme adalah...', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #12182', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_12182_1778530072.html', 0, 'E', 'Pilihan E adalah yang paling tepat. Marlena menggunakan hak pilihnya secara bebas dan bertanggung jawab, sesuai dengan hati nuraninya dan berdasarkan evaluasi terhadap program kerja partai politik. Sikap ini mencerminkan prinsip pemilu yang langsung, umum, bebas, rahasia, jujur, dan adil.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (5009, 12244, 'Perbandingan ideologi Pancasila dengan ideologi liberalisme yang benar, yaitu...', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #12244', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_12244_1778528038.html', 0, 'A', 'Pancasila menyeimbangkan kepentingan individu dan masyarakat, sedangkan liberalisme lebih fokus pada perlindungan individu.');
