INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (7015, 12940, 'Dalam menjaga nilai-nilai nasionalisme, pendidikan di Indonesia mengajarkan mata pelajaran yang berfokus pada sejarah perjuangan bangsa. Tujuan utama dari pengajaran sejarah perjuangan kemerdekaan adalah...', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #12940', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_12940_1778528093.html', 0, 'C', 'Pilihan C adalah yang paling tepat. Mempelajari sejarah perjuangan kemerdekaan memberikan pemahaman tentang pengorbanan para pahlawan dalam memperjuangkan kemerdekaan. Hal ini bertujuan untuk menumbuhkan rasa bangga dan cinta terhadap tanah air pada generasi muda.');
