INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (11431, 12941, 'Salah satu wujud nasionalisme dalam kehidupan ekonomi adalah adanya gerakan untuk mencintai produk dalam negeri. Gerakan ini bertujuan untuk...', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #12941', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_12941_1778528210.html', 0, 'C', 'Pilihan C adalah yang paling tepat. Dengan mencintai produk dalam negeri, masyarakat turut memperkuat perekonomian lokal dan mengurangi ketergantungan pada barang-barang impor. Ini juga membuka lebih banyak lapangan kerja bagi masyarakat Indonesia.');
