INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (40450, 12942, 'Seiring dengan perkembangan teknologi, generasi muda dapat menunjukkan rasa nasionalisme melalui media digital. Salah satu contoh nyata adalah...', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #12942', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_12942_1778530127.html', 0, 'B', 'Pilihan B adalah yang paling tepat. Melalui media digital, generasi muda dapat memanfaatkan media sosial untuk memperkenalkan keindahan alam, budaya, dan potensi wisata Indonesia ke dunia. Ini adalah bentuk nyata dari nasionalisme digital yang memperlihatkan kebanggaan terhadap tanah air.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (26820, 13139, 'Pergantian sistem pemerintahan yang berlaku di Indonesia pada tahun 1945 didasarkan pada...', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #13139', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_13139_1778529764.html', 0, 'D', 'Pergantian sistem pemerintahan didasarkan pada Maklumat Pemerintah Tanggal 14 November 1945.');
