INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (19148, 13229, 'Menurut informasi terdapat 228 penangkapan terorisme sepanjang tahun 2020 yang berencana untuk meledakkan lembaga resmi pemerintah maupun tempat-tempat ibadah. Hal ini tentu saja menjadi gambaran yang cukup berbahaya. Bagaimana pendapat anda?', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #13229', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_13229_1778528547.html', 0, 'C', 'Kita harus mengantisipasi radikalisme dan ujaran kebencian sebagai bentuk pertahanan negara.');
