INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (13111, 14438, 'Peristiwa pada 28 Oktober 1928 merupakan tonggak penting dalam sejarah lahirnya bangsa Indonesia. Para pemuda dari berbagai suku dan daerah berkumpul untuk mengikrarkan sumpah yang dikenal dengan Sumpah Pemuda. Bercermin dari peristiwa sejarah tersebut, yang tidak termasuk ke dalam nilai nasionalisme yang dapat digali dan diamalkan oleh generasi penerus bangsa adalah...', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #14438', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_14438_1778528304.html', 0, 'D', 'Pilihan D adalah yang paling tepat. Pilihan ini tidak sejalan dengan nilai nasionalisme seperti yang tercermin dalam Sumpah Pemuda, yang lebih mengutamakan persatuan, pengorbanan, dan kepedulian terhadap nasib bangsa secara kolektif.');
