INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (7264, 15256, 'Nasionalisme pada masa modern tidak hanya diwujudkan dalam bentuk perlawanan fisik, tetapi juga melalui kontribusi dalam berbagai bidang. Salah satu contoh nyata dari nasionalisme di bidang teknologi adalah...', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #15256', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_15256_1778528099.html', 0, 'C', 'Pilihan C adalah yang paling tepat. Dengan mengembangkan teknologi lokal, Indonesia dapat menjadi lebih mandiri secara ekonomi dan mengurangi ketergantungan pada negara asing. Ini juga menciptakan lapangan kerja dan meningkatkan kesejahteraan masyarakat, yang merupakan wujud nyata dari nasionalisme di bidang teknologi.');
