INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (10695, 15332, 'Indonesia memiliki semboyan \"Bhinneka Tunggal Ika\" yang berarti \"Berbeda-beda tetapi tetap satu.\" Semboyan ini sangat penting dalam menjaga persatuan bangsa di tengah keberagaman. Jika Anda adalah seorang guru yang ingin menanamkan nilai ini pada siswa, metode pembelajaran apa yang paling efektif?', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #15332', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_15332_1778528190.html', 0, 'A', '');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (5693, 15334, 'Indonesia dikenal dengan keragaman suku dan budaya, yang berpotensi menjadi kekuatan maupun tantangan dalam menjaga persatuan nasional. Dalam menghadapi situasi yang menimbulkan potensi konflik antar suku atau kelompok, apa langkah yang paling tepat dilakukan untuk menjaga semangat nasionalisme?', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #15334', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_15334_1778528054.html', 0, 'A', '');
