INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (7255, 15335, 'Dalam upaya mempertahankan kedaulatan negara, Tentara Nasional Indonesia (TNI) memiliki peran yang sangat penting. Namun, di era modern ini, ancaman terhadap kedaulatan tidak hanya berasal dari serangan fisik, tetapi juga dari serangan di dunia maya. Apa yang sebaiknya dilakukan untuk memperkuat pertahanan nasional di dunia maya sebagai wujud nasionalisme?', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #15335', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_15335_1778528099.html', 0, 'A', '');
