INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (22663, 15364, 'Salah satu cara menumbuhkan semangat nasionalisme adalah melalui penggunaan bahasa Indonesia secara baik dan benar. Namun, di era globalisasi ini, banyak generasi muda yang lebih sering menggunakan bahasa asing dalam percakapan sehari-hari. Sebagai seorang tokoh masyarakat, apa langkah yang dapat Anda lakukan untuk mengatasi masalah ini?', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #15364', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_15364_1778529653.html', 0, 'A', '');
