INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (13320, 15400, 'Sebagai negara maritim, Indonesia memiliki kekayaan laut yang luar biasa. Namun, sering kali laut Indonesia terancam oleh aktivitas ilegal seperti penangkapan ikan oleh kapal asing. Dalam rangka mempertahankan kedaulatan laut, apa tindakan yang paling efektif untuk dilakukan pemerintah?', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #15400', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_15400_1778528309.html', 0, 'A', '');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (40855, 15400, 'Sebagai negara maritim, Indonesia memiliki kekayaan laut yang luar biasa. Namun, sering kali laut Indonesia terancam oleh aktivitas ilegal seperti penangkapan ikan oleh kapal asing. Dalam rangka mempertahankan kedaulatan laut, apa tindakan yang paling efektif untuk dilakukan pemerintah?', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #15400', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_15400_1778530136.html', 0, 'A', '');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (28259, 15401, 'Indonesia menghadapi ancaman disintegrasi jika isu-isu seperti ketidakadilan sosial dan ekonomi tidak ditangani dengan baik. Bagaimana seharusnya pemerintah mengatasi masalah ini untuk memperkuat persatuan dan nasionalisme di tengah masyarakat?', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #15401', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_15401_1778529800.html', 0, 'A', '');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (39190, 15401, 'Indonesia menghadapi ancaman disintegrasi jika isu-isu seperti ketidakadilan sosial dan ekonomi tidak ditangani dengan baik. Bagaimana seharusnya pemerintah mengatasi masalah ini untuk memperkuat persatuan dan nasionalisme di tengah masyarakat?', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #15401', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_15401_1778530099.html', 0, 'A', '');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (33287, 15402, 'Di era digital, informasi tentang isu-isu nasional dan kebijakan pemerintah dapat diakses dengan mudah. Namun, tidak semua informasi yang beredar dapat dipercaya. Sebagai seorang warga negara yang bertanggung jawab, bagaimana cara yang paling bijak untuk menangani informasi yang Anda terima tentang isu-isu nasional?', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #15402', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_15402_1778529938.html', 0, 'A', '');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (37815, 15402, 'Di era digital, informasi tentang isu-isu nasional dan kebijakan pemerintah dapat diakses dengan mudah. Namun, tidak semua informasi yang beredar dapat dipercaya. Sebagai seorang warga negara yang bertanggung jawab, bagaimana cara yang paling bijak untuk menangani informasi yang Anda terima tentang isu-isu nasional?', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #15402', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_15402_1778530068.html', 0, 'A', '');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (35812, 15403, 'Dalam menghadapi persaingan global, Indonesia perlu membekali generasi mudanya dengan keterampilan yang relevan. Namun, nasionalisme juga perlu dipertahankan di tengah pengaruh globalisasi. Bagaimana sebaiknya pendidikan nasionalisme dikombinasikan dengan pendidikan keterampilan global bagi generasi muda?', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #15403', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_15403_1778530024.html', 0, 'A', '');
