INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (10140, 15424, 'Seorang pegawai negeri menyadari bahwa rekan kerjanya menyalahgunakan dana publik untuk kepentingan pribadi. Namun, pegawai tersebut merasa khawatir melaporkannya karena takut akan konsekuensi pribadi. Apa tindakan yang paling tepat?', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #15424', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_15424_1778528178.html', 0, 'A', '');
