INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (8642, 15425, 'Di Indonesia, terdapat kebijakan desentralisasi yang memberikan otonomi lebih besar kepada pemerintah daerah untuk mengatur wilayah mereka. Namun, hal ini dapat menimbulkan perbedaan kebijakan antar daerah yang berpotensi mengganggu persatuan nasional. Bagaimana pemerintah pusat dapat mendukung keberhasilan desentralisasi tanpa mengorbankan rasa persatuan?', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #15425', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_15425_1778528137.html', 0, 'A', '');
