INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (4649, 15426, 'Nasionalisme di era globalisasi sering dihadapkan pada pengaruh budaya asing yang kuat. Banyak generasi muda yang mengadopsi gaya hidup dan nilai-nilai dari negara lain tanpa seleksi. Sebagai seorang guru, bagaimana cara terbaik untuk menumbuhkan rasa cinta terhadap budaya lokal di kalangan siswa?', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #15426', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_15426_1778528011.html', 0, 'A', '');
