INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (10171, 15427, 'Indonesia memiliki banyak pulau dengan berbagai macam etnis dan budaya. Untuk menjaga persatuan di tengah keragaman, apa langkah yang paling efektif yang dapat dilakukan pemerintah dalam mengelola keanekaragaman tersebut?', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #15427', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_15427_1778528178.html', 0, 'A', '');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (20712, 15428, 'Indonesia menghadapi tantangan ketergantungan pada energi fosil yang tidak terbarukan. Dalam menghadapi situasi ini, apa kebijakan paling efektif yang bisa diambil pemerintah untuk mencerminkan nasionalisme dan menjaga keberlanjutan energi di masa depan?', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #15428', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_15428_1778529603.html', 0, 'A', '');
