INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (18300, 15429, 'Indonesia memiliki banyak Taman Nasional yang kaya akan keanekaragaman hayati. Namun, Taman Nasional ini sering kali terancam oleh perambahan ilegal dan kerusakan ekosistem. Apa kebijakan yang paling efektif bagi pemerintah untuk menjaga kelestarian Taman Nasional sebagai wujud dari nasionalisme lingkungan?', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #15429', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_15429_1778528475.html', 0, 'A', '');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (12407, 15430, 'Dalam konteks globalisasi, pendidikan nasional sering kali menghadapi tantangan untuk tetap mempertahankan nilai-nilai kebangsaan di tengah pengaruh dari budaya luar. Bagaimana sebaiknya kurikulum pendidikan disusun agar dapat menyeimbangkan pendidikan keterampilan global dengan nasionalisme?', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #15430', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_15430_1778528238.html', 0, 'A', '');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (41214, 15430, 'Dalam konteks globalisasi, pendidikan nasional sering kali menghadapi tantangan untuk tetap mempertahankan nilai-nilai kebangsaan di tengah pengaruh dari budaya luar. Bagaimana sebaiknya kurikulum pendidikan disusun agar dapat menyeimbangkan pendidikan keterampilan global dengan nasionalisme?', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #15430', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_15430_1778530144.html', 0, 'A', '');
