INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (4720, 9, 'Perhatikan pernyataan berikut! Setiap manusia di dunia pernah mengalami gigi rontok. Beberapa manusia di dunia adalah orang yang sangat tampan. Jadi,....', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #9', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_9_1778528013.html', 0, 'B', 'Kesimpulan yang tepat berdasarkan kedua informasi adalah Beberapa manusia yang sangat tampan pernah mengalami rontok gigi. Kesimpulan ini ditarik berdasarkan pernyataan bahwa Setiap manusia di dunia pernah mengalami gigi rontok. Karena Beberapa manusia di dunia adalah orang yang sangat tampan, maka orang tersebut tetap pernah mengalami rontok gigi. Ini adalah silogisme dengan premis universal dan partikular.');
