INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (10724, 50, '2, 5, 10, 17, ..., ...', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #50', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_50_1778528191.html', 0, 'C', 'Pola: +3, +5, +7, +9, +11. 17+9=26, 26+11=37. Selisih bertambah 2.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (22808, 50, '2, 5, 10, 17, ..., ...', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #50', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_50_1778529659.html', 0, 'C', 'Pola: +3, +5, +7, +9, +11. 17+9=26, 26+11=37. Selisih bertambah 2.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (7142, 51, 'Persamaan kuadrat: x^2-2x-15 memotong pada sumbu x di titik...', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #51', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_51_1778528096.html', 0, 'D', 'x^2-2x-15=0, (x-5)(x+3)=0, x=5 atau x=-3. Titik potong: (5,0) dan (-3,0).');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (17965, 52, 'Sebuah bola dengan luas permukaan 314 cm^2, memiliki jari-jari...', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #52', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_52_1778528468.html', 0, 'A', 'Luas permukaan bola = 4πr². 314 = 4 × 3.14 × r². r² = 25, r = 5 cm.');
