INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (6164, 159, 'Adi berangkat ke Surabaya kota pukul 07.15. Jarak rumah Adi ke Surabaya adalah 40 km. Kecepatan mobil yang dikendarai oleh Adi ke Surabaya adalah 80 km/jam. Jam berapa Adi sampai Surabaya kota?', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #159', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_159_1778528071.html', 0, 'A', 'Waktu = jarak/kecepatan = 40/80 = 0.5 jam = 30 menit. 07.15 + 30 menit = 07.45.');
