INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (19447, 284, 'Sari dan Ratih memiliki suatu pekerjaan. Waktu yang dibutuhkan oleh Sari dalam menghasilkan uang adalah 21 menit, sedangkan Ratih membutuhkan waktu 42 menit. Jika Sari dan Ratih bekerja bersama-sama untuk menghasilkan uang, waktu yang dibutuhkan adalah...', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #284', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_284_1778528554.html', 0, 'A', '1/21 + 1/42 = 2/42 + 1/42 = 3/42 = 1/14. Jadi waktu yang dibutuhkan adalah 14 menit.');
