INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (25923, 370, 'Prestasi Intan lebih tinggi dari Dini dan lebih rendah dari Tina. Prestasi Cantik lebih lebih rendah dari Intan, tetapi lebih tinggi dari Dini. Prestasi Dani lebih tinggi dari Dini dan Cantik. Tiga orang berprestasi terbaik adalah...', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #370', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_370_1778529741.html', 0, 'A', 'Urutan prestasi: Tina > Intan > Cantik > Dani > Dini. Tiga terbaik: Tina, Intan, Cantik (salah). Cek ulang: Tina > Intan > Cantik > Dani > Dini. Tiga terbaik: Tina, Intan, Cantik. Tapi opsi A adalah Dani, Intan, Tina. Mari cek: Dani > Dini dan Cantik. Intan > Dini, Intan < Tina. Cantik < Intan, Cantik > Dini. Jadi Tina > Intan > Cantik > Dani > Dini. Tiga terbaik: Tina, Intan, Cantik. Tidak ada opsi yang sesuai. Mungkin ada kesalahan dalam soal.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (28937, 370, 'Prestasi Intan lebih tinggi dari Dini dan lebih rendah dari Tina. Prestasi Cantik lebih lebih rendah dari Intan, tetapi lebih tinggi dari Dini. Prestasi Dani lebih tinggi dari Dini dan Cantik. Tiga orang berprestasi terbaik adalah...', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #370', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_370_1778529821.html', 0, 'A', 'Urutan prestasi: Tina > Intan > Cantik > Dani > Dini. Tiga terbaik: Tina, Intan, Cantik (salah). Cek ulang: Tina > Intan > Cantik > Dani > Dini. Tiga terbaik: Tina, Intan, Cantik. Tapi opsi A adalah Dani, Intan, Tina. Mari cek: Dani > Dini dan Cantik. Intan > Dini, Intan < Tina. Cantik < Intan, Cantik > Dini. Jadi Tina > Intan > Cantik > Dani > Dini. Tiga terbaik: Tina, Intan, Cantik. Tidak ada opsi yang sesuai. Mungkin ada kesalahan dalam soal.');
