INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (7735, 411, 'Semua tanaman di kebun Pak Subur adalah tanaman obat. Sebagian tanaman di kebun Pak Subur adalah tanaman sayur.', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #411', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_411_1778528109.html', 0, 'C', 'Semua tanaman di kebun = obat. Sebagian tanaman di kebun = sayur. Maka sebagian sayur di kebun = obat (karena semua tanaman di kebun obat).');
