INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (9752, 461, 'Sari dan Ratih memiliki suatu pekerjaan. Waktu yang dibutuhkan oleh Sari dalam menghasilkan uang adalah 21 menit, sedangkan Ratih membutuhkan waktu 42 menit. Jika Sari dan Ratih bekerja bersama-sama untuk menghasilkan uang, waktu yang dibutuhkan adalah...', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #461', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_461_1778528166.html', 0, 'A', '1/21 + 1/42 = 2/42 + 1/42 = 3/42 = 1/14. Jadi waktu yang dibutuhkan adalah 14 menit.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (28153, 461, 'Sari dan Ratih memiliki suatu pekerjaan. Waktu yang dibutuhkan oleh Sari dalam menghasilkan uang adalah 21 menit, sedangkan Ratih membutuhkan waktu 42 menit. Jika Sari dan Ratih bekerja bersama-sama untuk menghasilkan uang, waktu yang dibutuhkan adalah...', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #461', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_461_1778529798.html', 0, 'A', '1/21 + 1/42 = 2/42 + 1/42 = 3/42 = 1/14. Jadi waktu yang dibutuhkan adalah 14 menit.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (34566, 461, 'Sari dan Ratih memiliki suatu pekerjaan. Waktu yang dibutuhkan oleh Sari dalam menghasilkan uang adalah 21 menit, sedangkan Ratih membutuhkan waktu 42 menit. Jika Sari dan Ratih bekerja bersama-sama untuk menghasilkan uang, waktu yang dibutuhkan adalah...', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #461', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_461_1778529970.html', 0, 'A', '1/21 + 1/42 = 2/42 + 1/42 = 3/42 = 1/14. Jadi waktu yang dibutuhkan adalah 14 menit.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (10191, 462, 'Prestasi Intan lebih tinggi dari Dini dan lebih rendah dari Tina. Prestasi Cantik lebih lebih rendah dari Intan, tetapi lebih tinggi dari Dini. Prestasi Dani lebih tinggi dari Dini dan Cantik. Tiga orang berprestasi terbaik adalah...', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #462', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_462_1778528179.html', 0, 'A', 'Urutan prestasi: Tina > Intan > Cantik > Dani > Dini. Tiga terbaik: Tina, Intan, Cantik (salah). Cek ulang: Tina > Intan > Cantik > Dani > Dini. Tiga terbaik: Tina, Intan, Cantik. Tapi opsi A adalah Dani, Intan, Tina. Mari cek: Dani > Dini dan Cantik. Intan > Dini, Intan < Tina. Cantik < Intan, Cantik > Dini. Jadi Tina > Intan > Cantik > Dani > Dini. Tiga terbaik: Tina, Intan, Cantik. Tidak ada opsi yang sesuai. Mungkin ada kesalahan dalam soal.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (39905, 462, 'Prestasi Intan lebih tinggi dari Dini dan lebih rendah dari Tina. Prestasi Cantik lebih lebih rendah dari Intan, tetapi lebih tinggi dari Dini. Prestasi Dani lebih tinggi dari Dini dan Cantik. Tiga orang berprestasi terbaik adalah...', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #462', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_462_1778530115.html', 0, 'A', 'Urutan prestasi: Tina > Intan > Cantik > Dani > Dini. Tiga terbaik: Tina, Intan, Cantik (salah). Cek ulang: Tina > Intan > Cantik > Dani > Dini. Tiga terbaik: Tina, Intan, Cantik. Tapi opsi A adalah Dani, Intan, Tina. Mari cek: Dani > Dini dan Cantik. Intan > Dini, Intan < Tina. Cantik < Intan, Cantik > Dini. Jadi Tina > Intan > Cantik > Dani > Dini. Tiga terbaik: Tina, Intan, Cantik. Tidak ada opsi yang sesuai. Mungkin ada kesalahan dalam soal.');
