INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (26163, 1090, 'Dayana memiliki permen sebanyak 3 kali banyaknya permen yang dimiliki Estefania. Permen Estefania lebih sedikit 6 buah dari Catriona. Catriona memiliki 2 permen lebih banyak dari Dayana. Perbandingan banyak permen yang dimiliki ketiganya adalah...', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #1090', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_1090_1778529746.html', 0, 'C', 'Misalkan Permen Dayana = D, Permen Estefania = E, Permen Catriona = C. D = 3E, E = C - 6, C = D + 2. Substitusi: C = 3E + 2, E = (3E + 2) - 6, E = 3E - 4, 2E = 4, E = 2. Maka D = 6, C = 8. Perbandingan C : D : E = 8 : 6 : 2 = 4 : 3 : 1.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (30448, 1090, 'Dayana memiliki permen sebanyak 3 kali banyaknya permen yang dimiliki Estefania. Permen Estefania lebih sedikit 6 buah dari Catriona. Catriona memiliki 2 permen lebih banyak dari Dayana. Perbandingan banyak permen yang dimiliki ketiganya adalah...', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #1090', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_1090_1778529859.html', 0, 'C', 'Misalkan Permen Dayana = D, Permen Estefania = E, Permen Catriona = C. D = 3E, E = C - 6, C = D + 2. Substitusi: C = 3E + 2, E = (3E + 2) - 6, E = 3E - 4, 2E = 4, E = 2. Maka D = 6, C = 8. Perbandingan C : D : E = 8 : 6 : 2 = 4 : 3 : 1.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (40731, 1090, 'Dayana memiliki permen sebanyak 3 kali banyaknya permen yang dimiliki Estefania. Permen Estefania lebih sedikit 6 buah dari Catriona. Catriona memiliki 2 permen lebih banyak dari Dayana. Perbandingan banyak permen yang dimiliki ketiganya adalah...', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #1090', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_1090_1778530134.html', 0, 'C', 'Misalkan Permen Dayana = D, Permen Estefania = E, Permen Catriona = C. D = 3E, E = C - 6, C = D + 2. Substitusi: C = 3E + 2, E = (3E + 2) - 6, E = 3E - 4, 2E = 4, E = 2. Maka D = 6, C = 8. Perbandingan C : D : E = 8 : 6 : 2 = 4 : 3 : 1.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (22325, 1091, 'Pernyataan: \"jika laba tinggi maka karyawan sejahtera\" mempunyai kontraposisi yaitu...', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #1091', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_1091_1778529645.html', 0, 'E', 'Kontraposisi dari p → q adalah ~q → ~p. Jadi kontraposisi \"jika laba tinggi maka karyawan sejahtera\" adalah \"Jika karyawan tidak sejahtera maka laba tidak tinggi\".');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (37459, 1091, 'Pernyataan: \"jika laba tinggi maka karyawan sejahtera\" mempunyai kontraposisi yaitu...', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #1091', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_1091_1778530061.html', 0, 'E', 'Kontraposisi dari p → q adalah ~q → ~p. Jadi kontraposisi \"jika laba tinggi maka karyawan sejahtera\" adalah \"Jika karyawan tidak sejahtera maka laba tidak tinggi\".');
