INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (17164, 1138, '1, 5, 11, 19, 29, ..., 55', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #1138', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_1138_1778528433.html', 0, 'B', 'Pola: +4, +6, +8, +10, +12, +16. 29+12=41, 41+16=57 (bukan 55). Cek ulang: 1+4=5, 5+6=11, 11+8=19, 19+10=29, 29+12=41, 41+14=55. Pola: selisih bertambah 2. 41+14=55.');
