INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (28764, 1324, 'Perhatikan deret angka berikut: 2, 5, 9, 12, 16, 19, ... Angka selanjutnya adalah...', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #1324', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_1324_1778529817.html', 0, 'D', 'Pola deret bergantian, yaitu +3 dan +4. 2 → 5 (+3), 5 → 9 (+4), 9 → 12 (+3), 12 → 16 (+4), 16 → 19 (+3), sehingga berikutnya +4 = 23.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (40555, 1324, 'Perhatikan deret angka berikut: 2, 5, 9, 12, 16, 19, ... Angka selanjutnya adalah...', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #1324', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_1324_1778530130.html', 0, 'D', 'Pola deret bergantian, yaitu +3 dan +4. 2 → 5 (+3), 5 → 9 (+4), 9 → 12 (+3), 12 → 16 (+4), 16 → 19 (+3), sehingga berikutnya +4 = 23.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (28886, 1325, 'Perhatikan deret angka berikut: -1, 1, 3, 8, 13, 15, ... Angka selanjutnya adalah...', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #1325', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_1325_1778529820.html', 0, 'E', 'Deret terbagi dua pola berselang-seling. Deret genap bertambah +7, sedangkan deret ganjil berpola kenaikan sehingga 13 + 4 = 17.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (33415, 1325, 'Perhatikan deret angka berikut: -1, 1, 3, 8, 13, 15, ... Angka selanjutnya adalah...', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #1325', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_1325_1778529941.html', 0, 'E', 'Deret terbagi dua pola berselang-seling. Deret genap bertambah +7, sedangkan deret ganjil berpola kenaikan sehingga 13 + 4 = 17.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (5904, 1326, 'Perhatikan deret angka berikut: 44, 43, 33, 24, 16, 9, ... Angka selanjutnya adalah...', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #1326', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_1326_1778528065.html', 0, 'C', 'Pola deret berkurang dengan selisih menurun: -1, -10, -9, -8, -7. Selanjutnya berkurang -6, sehingga 9 - 6 = 3.');
