INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (5555, 1327, 'Perhatikan pola berikut: 5 [ 36 ] 7 8 [ 30 ] 2 2 7 [ A ] 4. Berapakah nilai A?', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #1327', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_1327_1778528051.html', 0, 'C', 'Pola diperoleh dari perkalian angka kiri dan kanan dengan penyesuaian tertentu. 5 × 7 → 36, 8 × 2 → 30, sehingga 7 × 4 menghasilkan 33.');
