INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (13086, 1579, 'FLUKTUASI = ....', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #1579', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_1579_1778528303.html', 0, 'B', 'Fluktuasi = Gejolak. Bangkrut = Pailit. Skeptis = Ragu-ragu. Mayor = Besar. Pilih-pilih = Elektif.');
