INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (40902, 1579, 'FLUKTUASI = ....', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #1579', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_1579_1778530137.html', 0, 'B', 'Fluktuasi = Gejolak. Bangkrut = Pailit. Skeptis = Ragu-ragu. Mayor = Besar. Pilih-pilih = Elektif.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (25756, 1581, 'Rudi dan Ahmad menjadi peserta asuransi kesehatan dengan besaran premi yang sama. Rudi menerima gaji sebesar Rp 3.000.000 per bulan dan gaji tersebut dipotong 5% untuk premi asuransi. Berapa besar gaji Ahmad per bulan jika gajinya harus dipotong 3% untuk membayar premi?', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #1581', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_1581_1778529737.html', 0, 'B', 'Gaji Rudi = y, Gaji Ahmad = z. Besarnya premi asuransi = 5% x y = 5% x 3.000.000 = 150.000. Besarnya premi asuransi = 3% x z. 150.000 = 3% x z. 150.000 / 3% = z. 150.000 / (3/100) = z. 150.000 x 100 / 3 = z. 5.000.000 = z.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (29522, 1581, 'Rudi dan Ahmad menjadi peserta asuransi kesehatan dengan besaran premi yang sama. Rudi menerima gaji sebesar Rp 3.000.000 per bulan dan gaji tersebut dipotong 5% untuk premi asuransi. Berapa besar gaji Ahmad per bulan jika gajinya harus dipotong 3% untuk membayar premi?', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #1581', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_1581_1778529834.html', 0, 'B', 'Gaji Rudi = y, Gaji Ahmad = z. Besarnya premi asuransi = 5% x y = 5% x 3.000.000 = 150.000. Besarnya premi asuransi = 3% x z. 150.000 = 3% x z. 150.000 / 3% = z. 150.000 / (3/100) = z. 150.000 x 100 / 3 = z. 5.000.000 = z.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (7339, 1582, 'Semua karyawan di perusahaan A mendapat Tunjangan Hari Raya. Sebagian karyawan mendapat bingkisan hari raya. Maka, ....', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #1582', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_1582_1778528101.html', 0, 'C', 'Semua karyawan → Tunjangan Hari Raya. Sebagian karyawan → bingkisan Hari Raya. Jadi, sebagian karyawan mendapat Tunjungan Hari Raya dan bingkisan Hari Raya.');
