INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (4253, 1615, 'Semua tanaman di kebun Pak Subur adalah tanaman obat. Sebagian tanaman di kebun Pak Subur adalah tanaman sayur.', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #1615', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_1615_1778528003.html', 0, 'C', 'Semua tanaman di kebun = obat. Sebagian tanaman di kebun = sayur. Maka sebagian sayur di kebun = obat (karena semua tanaman di kebun obat).');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (19597, 1615, 'Semua tanaman di kebun Pak Subur adalah tanaman obat. Sebagian tanaman di kebun Pak Subur adalah tanaman sayur.', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #1615', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_1615_1778528557.html', 0, 'C', 'Semua tanaman di kebun = obat. Sebagian tanaman di kebun = sayur. Maka sebagian sayur di kebun = obat (karena semua tanaman di kebun obat).');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (29007, 1625, '1, 4, 12, 48, 144, ..., 1728', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #1625', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_1625_1778529823.html', 0, 'D', 'Pola: ×4, ×3, ×4, ×3, ×4. 144×4=576, 576×3=1728. Pola berulang: ×4, ×3.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (40679, 1625, '1, 4, 12, 48, 144, ..., 1728', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #1625', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_1625_1778530132.html', 0, 'D', 'Pola: ×4, ×3, ×4, ×3, ×4. 144×4=576, 576×3=1728. Pola berulang: ×4, ×3.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (19449, 1627, '1, 5, 11, 19, 29, ..., 55', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #1627', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_1627_1778528554.html', 0, 'B', 'Pola: +4, +6, +8, +10, +12, +16. 29+12=41, 41+16=57 (bukan 55). Cek ulang: 1+4=5, 5+6=11, 11+8=19, 19+10=29, 29+12=41, 41+14=55. Pola: selisih bertambah 2. 41+14=55.');
