INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (7581, 1845, 'Sebuah pesawat terbang berangkat dari Kota Kupang menuju Kota Jakarta pukul 07.00 dan perjalanan ke Jakarta selama 4 jam. Transit di Denpasar selama 30 menit. Pukul berapa pesawat tersebut tiba di Jakarta?', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #1845', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_1845_1778528106.html', 0, 'D', '07.00 + 4 jam = 11.00, + 30 menit transit = 11.30.');
