INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (22504, 1845, 'Sebuah pesawat terbang berangkat dari Kota Kupang menuju Kota Jakarta pukul 07.00 dan perjalanan ke Jakarta selama 4 jam. Transit di Denpasar selama 30 menit. Pukul berapa pesawat tersebut tiba di Jakarta?', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #1845', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_1845_1778529649.html', 0, 'D', '07.00 + 4 jam = 11.00, + 30 menit transit = 11.30.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (10148, 1846, 'Andi membeli boneka seharga Rp50.000. Setelah itu, boneka dijual lagi dengan harga Rp80.000. Berapa persen keuntungan Andi?', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #1846', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_1846_1778528178.html', 0, 'D', 'Keuntungan = Rp80.000 - Rp50.000 = Rp30.000. Persentase keuntungan = (30.000 / 50.000) x 100% = 60%.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (32076, 1846, 'Andi membeli boneka seharga Rp50.000. Setelah itu, boneka dijual lagi dengan harga Rp80.000. Berapa persen keuntungan Andi?', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #1846', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_1846_1778529903.html', 0, 'D', 'Keuntungan = Rp80.000 - Rp50.000 = Rp30.000. Persentase keuntungan = (30.000 / 50.000) x 100% = 60%.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (39215, 1846, 'Andi membeli boneka seharga Rp50.000. Setelah itu, boneka dijual lagi dengan harga Rp80.000. Berapa persen keuntungan Andi?', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #1846', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_1846_1778530100.html', 0, 'D', 'Keuntungan = Rp80.000 - Rp50.000 = Rp30.000. Persentase keuntungan = (30.000 / 50.000) x 100% = 60%.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (7079, 1847, 'Berapa tiga suku pertama suatu barisan yang rumus suku ke-n nya Un = 3n² - 2?', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #1847', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_1847_1778528095.html', 0, 'B', 'U1 = 3(1)² - 2 = 1, U2 = 3(2)² - 2 = 10, U3 = 3(3)² - 2 = 25.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (12223, 1848, 'Semua karyawan berdasi. Semua karyawan berjas. Jadi:', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #1848', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_1848_1778528234.html', 0, 'D', 'Karena semua karyawan berdasi dan semua karyawan berjas, maka sebagian karyawan (atau semua) berdasi dan berjas.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (40915, 1848, 'Semua karyawan berdasi. Semua karyawan berjas. Jadi:', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #1848', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_1848_1778530138.html', 0, 'D', 'Karena semua karyawan berdasi dan semua karyawan berjas, maka sebagian karyawan (atau semua) berdasi dan berjas.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (12543, 1849, 'Umur Roni 4 tahun lebih muda dari pada umur Elsa. Bila jumlah umur keduanya 34 tahun, maka umur Elsa saat ini adalah...', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #1849', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_1849_1778528241.html', 0, 'E', 'Misal umur Elsa = x, maka umur Roni = x - 4. x + (x - 4) = 34. 2x = 38, x = 19.');
