INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (25799, 2161, 'Dalam pembagian tugas kuliah ada lima orang yang berdiskusi dengan memakai kostum yang berbeda-beda. Dodi memakai kemeja, Aldi dan Bintang memakai kaos lengan pendek, sisanya memakai kaos lengan Panjang. Pipit dan Hari memakai sepatu, Aldi memakai sepatu sendal, sisanya memakai sendal. Dodi dan Aldi tidak berkacamata sedangkan yang lain memakai kacamata. Siapakah mahasiswa yang berkacamata, memakai kaos lengan pendek dan bersendal?', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #2161', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_2161_1778529738.html', 0, 'B', 'Bintang memakai kaos lengan pendek (bersama Aldi), bersendal (selain Pipit dan Hari), dan berkacamata (selain Dodi dan Aldi).');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (27929, 2161, 'Dalam pembagian tugas kuliah ada lima orang yang berdiskusi dengan memakai kostum yang berbeda-beda. Dodi memakai kemeja, Aldi dan Bintang memakai kaos lengan pendek, sisanya memakai kaos lengan Panjang. Pipit dan Hari memakai sepatu, Aldi memakai sepatu sendal, sisanya memakai sendal. Dodi dan Aldi tidak berkacamata sedangkan yang lain memakai kacamata. Siapakah mahasiswa yang berkacamata, memakai kaos lengan pendek dan bersendal?', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #2161', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_2161_1778529793.html', 0, 'B', 'Bintang memakai kaos lengan pendek (bersama Aldi), bersendal (selain Pipit dan Hari), dan berkacamata (selain Dodi dan Aldi).');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (3685, 2162, 'Andi membuat sebuah gapura memerlukan waktu 12 hari sedangkan Eko membuat gapura yang sama memerlukan waktu 6 hari. Disamping itu Eca dapat membuat gapura yang sama dalam waktu 4 hari. X: Waktu yang dibutuhkan ketika Andi, Eko dan Eca membuat gapura bersama-sama. Y: Waktu yang dibutuhkan ketika Andi dan Eko membuat gapura bersama-sama dimana Andi meningkatkan kecepatannya sebesar 100 persen.', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #2162', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_2162_1778527984.html', 0, 'D', 'Kecepatan Andi = 1/12, Eko = 1/6, Eca = 1/4. X = 1/(1/12+1/6+1/4) = 1/2 hari. Andi kecepatan baru = 2/12 = 1/6. Y = 1/(1/6+1/6) = 3 hari. Y = 1.5 X.');
