INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (14772, 2827, 'Jika Naruto bukan tokoh kartun maka Doraemon adalah kucing sungguhan. Ingkaran dari pernyataan di atas adalah:', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #2827', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_2827_1778528363.html', 0, 'C', 'Ingkaran dari \"Jika P maka Q\" adalah \"P dan tidak Q\". Ingkaran dari \"Jika Naruto bukan tokoh kartun maka Doraemon adalah kucing sungguhan\" adalah \"Naruto bukan tokoh kartun dan Doraemon bukan kucing sungguhan\". Namun berdasarkan aturan ingkaran, jawaban yang benar adalah C.');
