INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (16744, 2830, 'Sebuah proyek pembangunan terdiri atas beberapa jenis proyek kecil, yakni proyek P, Q, R, S, T, dan U. Proyek kecil ini berkaitan satu dengan yang lain sehingga tiap-tiap jenis pekerjaan diatur sebagai berikut: Proyek Q tidak boleh dikerjakan bersamaan dengan proyek S. Proyek P boleh dikerjakan bersama dengan proyek T. Proyek Q hanya boleh dikerjakan bersama dengan proyek R. Proyek T dikerjakan jika proyek U dikerjakan. Jika pekerja sudah mengerjakan proyek T, maka ....', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #2830', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_2830_1778528412.html', 0, 'D', 'Jika T dikerjakan, maka U harus dikerjakan (karena T dikerjakan jika U dikerjakan).');
