INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (22893, 2834, 'Jika M = T maka M tidak sama dengan C. Bila B = M, maka?', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #2834', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_2834_1778529661.html', 0, 'B', 'Jika M = T dan M ≠ C, maka T ≠ C. Jika B = M, maka B = T dan B ≠ C. Jadi jika B = C, maka B tidak sama dengan T.');
