INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (12922, 2842, 'PRIBADI : KELOMPOK : MASYARAKAT :...', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #2842', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_2842_1778528300.html', 0, 'A', 'Pribadi, Kelompok, Masyarakat adalah tingkatan sosial dari individu ke kolektif. Saya, Kita, Mereka adalah tingkatan pronomina dari individu ke kolektif.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (12088, 2843, 'Jika saya pekerja maka saya mendapat gaji. Kalimat berikut yang ekuivalen dengan pernyataan diatas adalah?', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #2843', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_2843_1778528231.html', 0, 'A', 'P → Q ekuivalen dengan ¬P ∨ Q. \"Jika saya pekerja maka saya mendapat gaji\" ekuivalen dengan \"Saya bukan pekerja atau saya mendapat gaji\".');
