INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (24197, 3339, 'Jika 20 ekor kambing mampu menghabiskan rumput sebanyak 4 lapangan selama 8 hari, maka 16 ekor kambing mampu menghabiskan rumput sebanyak 8 lapangan selama hari.', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #3339', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_3339_1778529694.html', 0, 'E', '20 kambing, 4 lapangan, 8 hari. 16 kambing, 8 lapangan, x hari. (20/16) × (8/4) × 8 = 20 hari.');
