INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (13469, 3351, 'Prestasi Intan lebih tinggi dari Dini dan lebih rendah dari Tina. Prestasi Cantik lebih lebih rendah dari Intan, tetapi lebih tinggi dari Dini. Prestasi Dani lebih tinggi dari Dini dan Cantik. Tiga orang berprestasi terbaik adalah ....', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #3351', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_3351_1778528312.html', 0, 'A', 'Tina > Intan > Cantik > Dani > Dini. Tiga terbaik: Tina, Intan, Cantik. Wait, Dani lebih tinggi dari Cantik. Urutan: Tina > Intan > Dani > Cantik > Dini. Tiga terbaik: Tina, Intan, Dani. But answer A says Dani, Intan, Tina which is wrong order. Let me re-read: Dani lebih tinggi dari Dini dan Cantik. Tina > Intan > Cantik. Intan > Dini. Jadi Tina > Intan > Dani > Cantik > Dini. Tiga terbaik: Tina, Intan, Dani.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (22065, 3352, 'FIKTIF : FAKTA', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #3352', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_3352_1778529639.html', 0, 'D', 'Fiktif berlawanan dengan Fakta, Dongeng berlawanan dengan Peristiwa nyata.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (29434, 3353, '7,5 : 2,5 - (2/4 x 3/4) = ...', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #3353', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_3353_1778529832.html', 0, 'D', '7,5 : 2,5 = 3. 2/4 × 3/4 = 6/16 = 0,375. 3 - 0,375 = 2,625.');
