INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (3515, 3354, 'Jika a=5 dan b=2 maka nilai dari a^3 - 3a^2b + 3ab^2 - b^3 = ...', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #3354', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_3354_1778527980.html', 0, 'C', '(a-b)^3 = (5-2)^3 = 3^3 = 27.');
