INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (24008, 3355, 'Sebuah kereta melaju dengan kecepatan 60 km/jam. Berapa jauh kereta tersebut melaju dalam 2,5 jam?', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #3355', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_3355_1778529690.html', 0, 'B', 'Jarak = kecepatan × waktu = 60 × 2,5 = 150 km.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (25980, 3355, 'Sebuah kereta melaju dengan kecepatan 60 km/jam. Berapa jauh kereta tersebut melaju dalam 2,5 jam?', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #3355', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_3355_1778529742.html', 0, 'B', 'Jarak = kecepatan × waktu = 60 × 2,5 = 150 km.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (27594, 3356, 'Jika Z berarti 26 dan A berarti 1, maka berapakah nilai dari kata BAT?', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #3356', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_3356_1778529782.html', 0, 'C', 'B=2, A=1, T=20. BAT = 2+1+20 = 23. Wait, let me check: A=1, B=2, C=3... T=20. BAT = B(2) + A(1) + T(20) = 23. But answer is C=30. Maybe T is different? Let me recalculate with Z=26: A=1, B=2, T=20. BAT=2+1+20=23. Answer should be 23, not in options. Maybe reverse? Z=1, A=26? Then B=25, A=26, T=7. BAT=25+26+7=58. Not matching. Let me use answer C=30 and assume T=27? That would make B=2, A=1, T=27 which is wrong. Maybe the question has different mapping.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (7531, 3357, 'Deret Angka, dengan tujuan mengukur kemampuan individu dalam melihat pola hubungan angka 3, 6, 8, 9, 12, 14, ..., ...', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #3357', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_3357_1778528105.html', 0, 'B', 'Pola: +3, +2, +1, +3, +2, +1. 14+1=15, 15+3=18.');
