INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (27008, 3713, 'Sebuah proyek pembangunan terdiri atas beberapa jenis proyek kecil, yakni proyek P, Q, R, S, T, dan U. Proyek kecil ini berkaitan satu dengan yang lain sehingga tiap-tiap jenis pekerjaan diatur sebagai berikut: Proyek Q tidak boleh dikerjakan bersamaan dengan proyek S. Proyek P boleh dikerjakan bersama dengan proyek T. Proyek Q hanya boleh dikerjakan bersama dengan proyek R. Proyek T dikerjakan jika proyek U dikerjakan. Jika pekerja sudah mengerjakan proyek T, maka ....', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #3713', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_3713_1778529769.html', 0, 'D', 'Jika T dikerjakan, maka U harus dikerjakan (karena T dikerjakan jika U dikerjakan).');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (29152, 3713, 'Sebuah proyek pembangunan terdiri atas beberapa jenis proyek kecil, yakni proyek P, Q, R, S, T, dan U. Proyek kecil ini berkaitan satu dengan yang lain sehingga tiap-tiap jenis pekerjaan diatur sebagai berikut: Proyek Q tidak boleh dikerjakan bersamaan dengan proyek S. Proyek P boleh dikerjakan bersama dengan proyek T. Proyek Q hanya boleh dikerjakan bersama dengan proyek R. Proyek T dikerjakan jika proyek U dikerjakan. Jika pekerja sudah mengerjakan proyek T, maka ....', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #3713', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_3713_1778529826.html', 0, 'D', 'Jika T dikerjakan, maka U harus dikerjakan (karena T dikerjakan jika U dikerjakan).');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (10489, 3726, 'Jika saya pekerja maka saya mendapat gaji. Kalimat berikut yang ekuivalen dengan pernyataan diatas adalah?', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #3726', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_3726_1778528185.html', 0, 'A', 'P → Q ekuivalen dengan ¬P ∨ Q. \"Jika saya pekerja maka saya mendapat gaji\" ekuivalen dengan \"Saya bukan pekerja atau saya mendapat gaji\".');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (15623, 3746, 'Andi membuat sebuah gapura memerlukan waktu 12 hari sedangkan Eko membuat gapura yang sama memerlukan waktu 6 hari. Disamping itu Eca dapat membuat gapura yang sama dalam waktu 4 hari. X: Waktu yang dibutuhkan ketika Andi, Eko dan Eca membuat gapura bersama-sama. Y: Waktu yang dibutuhkan ketika Andi dan Eko membuat gapura bersama-sama dimana Andi meningkatkan kecepatannya sebesar 100 persen.', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #3746', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_3746_1778528382.html', 0, 'D', 'Kecepatan Andi = 1/12, Eko = 1/6, Eca = 1/4. X = 1/(1/12+1/6+1/4) = 1/2 hari. Andi kecepatan baru = 2/12 = 1/6. Y = 1/(1/6+1/6) = 3 hari. Y = 1.5 X.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (31763, 3746, 'Andi membuat sebuah gapura memerlukan waktu 12 hari sedangkan Eko membuat gapura yang sama memerlukan waktu 6 hari. Disamping itu Eca dapat membuat gapura yang sama dalam waktu 4 hari. X: Waktu yang dibutuhkan ketika Andi, Eko dan Eca membuat gapura bersama-sama. Y: Waktu yang dibutuhkan ketika Andi dan Eko membuat gapura bersama-sama dimana Andi meningkatkan kecepatannya sebesar 100 persen.', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #3746', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_3746_1778529896.html', 0, 'D', 'Kecepatan Andi = 1/12, Eko = 1/6, Eca = 1/4. X = 1/(1/12+1/6+1/4) = 1/2 hari. Andi kecepatan baru = 2/12 = 1/6. Y = 1/(1/6+1/6) = 3 hari. Y = 1.5 X.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (4302, 3835, 'Jika 20 ekor kambing mampu menghabiskan rumput sebanyak 4 lapangan selama 8 hari, maka 16 ekor kambing mampu menghabiskan rumput sebanyak 8 lapangan selama hari.', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #3835', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_3835_1778528004.html', 0, 'E', '20 kambing, 4 lapangan, 8 hari. 16 kambing, 8 lapangan, x hari. (20/16) × (8/4) × 8 = 20 hari.');
