INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (10092, 4401, 'Perhatikan pola berikut:\\n4 × 5 [36]8 × 2 [80]3 × B [27]\\nNilai B adalah...', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #4401', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_4401_1778528177.html', 0, 'C', 'Nilai dalam kurung mengikuti pola tertentu dari hasil perkalian. Untuk menghasilkan 27, maka 3 × B = 18, sehingga B = 6.');
