INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (18742, 4620, 'Pernyataan: \"jika laba tinggi maka karyawan sejahtera\" mempunyai kontraposisi yaitu...', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #4620', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_4620_1778528485.html', 0, 'E', 'Kontraposisi dari p → q adalah ~q → ~p. Jadi kontraposisi \"jika laba tinggi maka karyawan sejahtera\" adalah \"Jika karyawan tidak sejahtera maka laba tidak tinggi\".');
