INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (31358, 5267, '.... Aku menanti berita darinya seperti orang gila. Aku merasa gelisah, lebih dari saat pertama kali naik ke atas penggung atau saat Leskar diwawancarai media untuk pertama kalinya. Mengapa ia membiarkan aku menunggu begitu lama? Yang harus ia lakukan hanyalah menghubungiku. SMS. Telepon. E-mail. Apapun itu, aku tidak peduli. Aku hanya ingin mendengar suaranya. Tujuan paragraf di atas adalah:', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #5267', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_5267_1778529883.html', 0, 'B', 'Paragraf tersebut menggambarkan perasaan penulis yang gelisah menunggu berita.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (41278, 5267, '.... Aku menanti berita darinya seperti orang gila. Aku merasa gelisah, lebih dari saat pertama kali naik ke atas penggung atau saat Leskar diwawancarai media untuk pertama kalinya. Mengapa ia membiarkan aku menunggu begitu lama? Yang harus ia lakukan hanyalah menghubungiku. SMS. Telepon. E-mail. Apapun itu, aku tidak peduli. Aku hanya ingin mendengar suaranya. Tujuan paragraf di atas adalah:', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #5267', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_5267_1778530146.html', 0, 'B', 'Paragraf tersebut menggambarkan perasaan penulis yang gelisah menunggu berita.');
