INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (12009, 5272, 'PENYAKIT : PATOLOGI :...: CUACA', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #5272', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_5272_1778528229.html', 0, 'D', 'Patologi adalah ilmu tentang penyakit, sama seperti Meteorologi adalah ilmu tentang cuaca.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (9047, 5273, 'Sebuah proyek pembangunan terdiri atas beberapa jenis proyek kecil, yakni proyek P, Q, R, S, T, dan U. Proyek kecil ini berkaitan satu dengan yang lain sehingga tiap-tiap jenis pekerjaan diatur sebagai berikut: Proyek Q tidak boleh dikerjakan bersamaan dengan proyek S. Proyek P boleh dikerjakan bersama dengan proyek T. Proyek Q hanya boleh dikerjakan bersama dengan proyek R. Proyek T dikerjakan jika proyek U dikerjakan. Jika pekerja sudah mengerjakan proyek T, maka ....', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #5273', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_5273_1778528149.html', 0, 'D', 'Jika T dikerjakan, maka U harus dikerjakan (karena T dikerjakan jika U dikerjakan).');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (15988, 5273, 'Sebuah proyek pembangunan terdiri atas beberapa jenis proyek kecil, yakni proyek P, Q, R, S, T, dan U. Proyek kecil ini berkaitan satu dengan yang lain sehingga tiap-tiap jenis pekerjaan diatur sebagai berikut: Proyek Q tidak boleh dikerjakan bersamaan dengan proyek S. Proyek P boleh dikerjakan bersama dengan proyek T. Proyek Q hanya boleh dikerjakan bersama dengan proyek R. Proyek T dikerjakan jika proyek U dikerjakan. Jika pekerja sudah mengerjakan proyek T, maka ....', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #5273', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_5273_1778528395.html', 0, 'D', 'Jika T dikerjakan, maka U harus dikerjakan (karena T dikerjakan jika U dikerjakan).');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (11192, 5277, 'Jika M = T maka M tidak sama dengan C. Bila B = M, maka?', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #5277', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_5277_1778528205.html', 0, 'B', 'Jika M = T dan M ≠ C, maka T ≠ C. Jika B = M, maka B = T dan B ≠ C. Jadi jika B = C, maka B tidak sama dengan T.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (18975, 5277, 'Jika M = T maka M tidak sama dengan C. Bila B = M, maka?', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #5277', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_5277_1778528543.html', 0, 'B', 'Jika M = T dan M ≠ C, maka T ≠ C. Jika B = M, maka B = T dan B ≠ C. Jadi jika B = C, maka B tidak sama dengan T.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (27542, 5281, 'Jelajahi Mars dengan Simulator Baru Keluaran NASA. Meskipun masih diperlukan bertahun-tahun lamanya hingga manusia dapat menginjakkan kaki di planet Mars, bukan berarti tidak mungkin bagi manusia sekarang ini untuk menjalankan tur keliling Mars. NASA telah mengeluarkan simulator 3D baru yang dapat memungkinkan para penggunanya menjelajahi Mars. Simulator ini memberikan pengalaman tur virtual bagi orang-orang yang berkeinginan untuk melakukan perjalanan mengelilingi Mars. Dikutip dari situs Quartz, fitur terbaru ciptaan NASA ini mengizinkan para penggunanya untuk mengatur gerak navigasi kendaraan Mars Curiosity yang dimiliki agen luar angkasa Amerika Serikat ini ke seluruh penjuru Mars. Dengan mengatur gerak Mars Curiosity, para pengguna fitur terbaru NASA dapat mengeksplorasi planet merah sesuai yang mereka inginkan melalui komputer pribadi mereka. Kata \"fitur\" pada bacaan di atas adalah....', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #5281', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_5281_1778529781.html', 0, 'A', 'Fitur berarti kemampuan atau ciri khusus pada suatu gawai atau aplikasi.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (11529, 5286, 'Jika saya pekerja maka saya mendapat gaji. Kalimat berikut yang ekuivalen dengan pernyataan diatas adalah?', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #5286', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_5286_1778528212.html', 0, 'A', 'P → Q ekuivalen dengan ¬P ∨ Q. \"Jika saya pekerja maka saya mendapat gaji\" ekuivalen dengan \"Saya bukan pekerja atau saya mendapat gaji\".');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (21735, 5286, 'Jika saya pekerja maka saya mendapat gaji. Kalimat berikut yang ekuivalen dengan pernyataan diatas adalah?', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #5286', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_5286_1778529631.html', 0, 'A', 'P → Q ekuivalen dengan ¬P ∨ Q. \"Jika saya pekerja maka saya mendapat gaji\" ekuivalen dengan \"Saya bukan pekerja atau saya mendapat gaji\".');
