INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (18015, 5401, 'Dalam sehari, sebuah pabrik dapat memproduksi 480 unit produk. Jika pabrik tersebut beroperasi selama 7 hari dalam seminggu, berapa total unit produk yang dapat diproduksi oleh pabrik tersebut dalam satu bulan?', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #5401', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_5401_1778528469.html', 0, 'E', '480 × 7 × 4 = 480 × 28 = 13,440 per bulan. Wait, 480×7=3360 per minggu, 3360×4=13440. Let me recalculate: 480×30=14400 per bulan (30 hari). Answer seems wrong. Let me use 4 weeks: 480×7×4=13440. None match. Maybe 480×8=3840 for 8 working days?');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (9281, 5404, 'Seekor monyet mula - mula berada di ketinggian tertentu pada sebuah tiang, kemudian ia turun 4 meter, naik 3 meter, turun 6 meter, naik 2 meter, naik 9 meter, dan turun 2 meter. Pada ketinggian berapakah monyet itu berada?', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #5404', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_5404_1778528155.html', 0, 'B', '-4 + 3 - 6 + 2 + 9 - 2 = +2. Monyet berada 2 meter di atas posisi semula.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (9900, 5404, 'Seekor monyet mula - mula berada di ketinggian tertentu pada sebuah tiang, kemudian ia turun 4 meter, naik 3 meter, turun 6 meter, naik 2 meter, naik 9 meter, dan turun 2 meter. Pada ketinggian berapakah monyet itu berada?', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #5404', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_5404_1778528172.html', 0, 'B', '-4 + 3 - 6 + 2 + 9 - 2 = +2. Monyet berada 2 meter di atas posisi semula.');
