INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (28972, 5510, '100, 95, 85, 70, 50,...', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #5510', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_5510_1778529822.html', 0, 'A', 'Semakin ke kiri angka akan dikurangi kelipatan 5 yakni 5, 10, 15, 20, dan yang terakhir berarti dikurang 25 (50 - 25 = 25).');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (39612, 5511, 'Manakah yang bernilai paling kecil?', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #5511', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_5511_1778530109.html', 0, 'E', '8/10 = 0.8, 3/4 = 0.75, 11/5 = 2.2, 5/7 ≈ 0.714, 17/24 ≈ 0.708. Yang paling kecil adalah 17/24.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (32831, 5512, 'Di antara bilangan-bilangan berikut, yang habis dibagi oleh 6 dan 7 adalah...', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #5512', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_5512_1778529928.html', 0, 'A', 'KPK dari 6 dan 7 adalah 42. 252 ÷ 42 = 6. Jadi 252 habis dibagi oleh 6 dan 7.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (19366, 5513, 'Pintu air di suatu daerah mempunyai 927 cabang saluran yang disalurkan ke rumah-rumah tangga. Dalam satu minggu digunakan 88.065 liter air. Berapa literkah rata-rata air yang digunakan masing-masing rumah tangga dalam satu minggu?', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #5513', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_5513_1778528552.html', 0, 'B', 'Rata-rata penggunaan air = volume air / banyak cabang = 88.065 / 927 = 95.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (40823, 5513, 'Pintu air di suatu daerah mempunyai 927 cabang saluran yang disalurkan ke rumah-rumah tangga. Dalam satu minggu digunakan 88.065 liter air. Berapa literkah rata-rata air yang digunakan masing-masing rumah tangga dalam satu minggu?', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #5513', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_5513_1778530136.html', 0, 'B', 'Rata-rata penggunaan air = volume air / banyak cabang = 88.065 / 927 = 95.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (41284, 5514, 'Jika sudut suatu segitiga adalah x, 2x, dan 3x derajat, dan y = 30 derajat. Maka.....', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #5514', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_5514_1778530146.html', 0, 'C', 'Jumlah sudut dalam segitiga adalah 180 derajat. x + 2x + 3x = 180, 6x = 180, x = 30. Maka x = y = 30.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (8592, 5515, 'Jika a + 2 < x + p < b + 2 dan b < y + p < c dengan a < b < c, maka....', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #5515', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_5515_1778528136.html', 0, 'E', 'Terdapat empat variabel bebas yaitu a, b, p, dan c yang dapat merubah batas x dan y, sehingga hubungan x dan y tidak dapat ditentukan.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (35617, 5515, 'Jika a + 2 < x + p < b + 2 dan b < y + p < c dengan a < b < c, maka....', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #5515', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_5515_1778529997.html', 0, 'E', 'Terdapat empat variabel bebas yaitu a, b, p, dan c yang dapat merubah batas x dan y, sehingga hubungan x dan y tidak dapat ditentukan.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (18334, 5516, 'Setiap kota yang memiliki pusat hiburan mempunyai ciri rawan kejahatan. Ini karena pusat hiburan menyebabkan adanya keramaian yang menarik para penjahat, sementara semua penjahat adalah pelaku kriminal. Kesimpulan yang salah adalah....', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #5516', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_5516_1778528476.html', 0, 'C', 'Kesimpulan yang salah adalah semua kota banyak penjahat, karena tidak semua kota memiliki pusat hiburan.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (26355, 5518, 'Rahman berbadan tegap. Semua prajurit berbadan tegap.', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #5518', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_5518_1778529751.html', 0, 'D', 'Rahman berbadan tegap dan semua prajurit berbadan tegap, tetapi tidak berarti semua yang berbadan tegap adalah prajurit. Rahman belum tentu seorang prajurit.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (31106, 5518, 'Rahman berbadan tegap. Semua prajurit berbadan tegap.', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #5518', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_5518_1778529878.html', 0, 'D', 'Rahman berbadan tegap dan semua prajurit berbadan tegap, tetapi tidak berarti semua yang berbadan tegap adalah prajurit. Rahman belum tentu seorang prajurit.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (29297, 5554, 'Sebuah bola dengan luas permukaan 314 cm^2, memiliki jari-jari...', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #5554', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_5554_1778529829.html', 0, 'A', 'Luas permukaan bola = 4πr². 314 = 4 × 3.14 × r². r² = 25, r = 5 cm.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (18474, 5570, '19, 20, 39, 21, 22, 43, 23, 24, ...', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #5570', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_5570_1778528479.html', 0, 'B', 'Pola: +1, +19, +1, +19, +1, +19. 24+19=43, 43+1=44, 44+19=63 (salah). Cek ulang: 19+1=20, 20+19=39, 39+1=40, 40+19=59. Pola: +1, +19 berulang. 23+1=24, 24+19=43, 43+1=44, 44+19=63. Jawaban mungkin 47 (24+23).');
