INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (5859, 5610, 'Prestasi Intan lebih tinggi dari Dini dan lebih rendah dari Tina. Prestasi Cantik lebih lebih rendah dari Intan, tetapi lebih tinggi dari Dini. Prestasi Dani lebih tinggi dari Dini dan Cantik. Tiga orang berprestasi terbaik adalah...', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #5610', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_5610_1778528064.html', 0, 'A', 'Tina > Intan > Cantik > Dani > Dini. Tiga terbaik: Tina, Intan, Cantik. Wait, Dani lebih tinggi dari Cantik. Urutan: Tina > Intan > Dani > Cantik > Dini. Tiga terbaik: Tina, Intan, Dani.');
