INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (12993, 5779, '2 2 5 6 8 18 .... ....', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #5779', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_5779_1778528301.html', 0, 'D', 'Bilangan pertama berpola ditambah tiga (+3) dengan bilangan ke tiga, lima, tujuh, dst. Bilangan kedua berpola dikalikan tiga (x3) dengan bilangan ke empat, enam, delapan, dst. 8 + 3 = 11, 18 x 3 = 54.');
