INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (4384, 6125, 'Hubungan yang terdapat pada kalimat ikan adalah ekor sama seperti hubungan pada kalimat …', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #6125', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_6125_1778528005.html', 0, 'C', 'Hubungan yang terdapat dalam kalimat ikan adalah ekor yang paling mungkin adalah ikan menggunakan penggolongan ekor dalam perhitungannya. Kalimat yang memiliki hubungan yang sama yaitu Daun adalah helai karena daun menggunakan penggolongan helai dalam perhitungannya.');
