INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (23415, 6180, 'Rumah Durga berjarak 1,5 km dari sekolahnya. Jika kecepatan ia berjalan rata-rata 4,5 km/jam. Berapa jam yang diperlukan untuk berjalan pulang-pergi selama 6 hari?', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #6180', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_6180_1778529673.html', 0, 'A', 'Jarak pulang-pergi = 1,5 km x 2 = 3 km. Waktu per hari = 3 km / 4,5 km/jam = 2/3 jam. Waktu 6 hari = 2/3 jam x 6 = 4 jam.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (32406, 6180, 'Rumah Durga berjarak 1,5 km dari sekolahnya. Jika kecepatan ia berjalan rata-rata 4,5 km/jam. Berapa jam yang diperlukan untuk berjalan pulang-pergi selama 6 hari?', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #6180', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_6180_1778529910.html', 0, 'A', 'Jarak pulang-pergi = 1,5 km x 2 = 3 km. Waktu per hari = 3 km / 4,5 km/jam = 2/3 jam. Waktu 6 hari = 2/3 jam x 6 = 4 jam.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (20674, 6181, 'Sebuah mobil bergerak dengan kecepatan 160 km/jam. Berapakah jauh perpindahan mobil dalam 15 menit?', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #6181', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_6181_1778529595.html', 0, 'C', '15 menit = 0,25 jam. Jarak = 160 km/jam x 0,25 jam = 40 km.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (26902, 6181, 'Sebuah mobil bergerak dengan kecepatan 160 km/jam. Berapakah jauh perpindahan mobil dalam 15 menit?', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #6181', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_6181_1778529766.html', 0, 'C', '15 menit = 0,25 jam. Jarak = 160 km/jam x 0,25 jam = 40 km.');
