INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (30577, 6182, 'Seorang penjual mengantar pesanan sebanyak 9 mangkuk sayur ke sebuah toko. Si penjual hanya bisa membawa 2 mangkuk setiap kali pengiriman. Berapa kali si penjual harus mengantarkan seluruh pesanannya?', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #6182', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_6182_1778529862.html', 0, 'C', '9 mangkuk / 2 mangkuk per kali = 4,5 kali. Karena tidak bisa setengah kali, maka dibulatkan menjadi 5 kali.');
