INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (10311, 6193, 'Invers dari pernyataan: \"Jika harga minyak naik maka harga nasi padang naik\" adalah ...', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #6193', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_6193_1778528181.html', 0, 'C', 'Invers dari \"Jika P maka Q\" adalah \"Jika tidak P maka tidak Q\". Jadi invers dari \"Jika harga minyak naik maka harga nasi padang naik\" adalah \"Jika harga minyak tidak naik maka harga nasi padang tidak naik\".');
