INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (10893, 6194, 'Hubungan nilai a dan b yang tepat adalah: 2a + 5 - 2b = 3 3b - 12 = 12', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #6194', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_6194_1778528198.html', 0, 'D', 'Dari 3b - 12 = 12, maka 3b = 24, b = 8. Substitusi ke 2a + 5 - 2(8) = 3, maka 2a + 5 - 16 = 3, 2a - 11 = 3, 2a = 14, a = 7. Jadi a = b - 1 (7 = 8 - 1).');
