INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (25257, 6199, 'Sri membeli tas di sebuah toko dengan harga Rp200.000. Jika tas yang hendak dibeli Sri mendapatkan diskon sebesar 20% serta mendapat lagi potongan 5% karena menggunakan kartu anggota. Berapa harga tas yang harus Sri bayar?', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #6199', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_6199_1778529723.html', 0, 'C', 'Harga awal = Rp200.000. Diskon 20% = Rp40.000. Harga setelah diskon 1 = Rp160.000. Diskon 5% = Rp8.000. Harga akhir = Rp160.000 - Rp8.000 = Rp152.000.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (38880, 6199, 'Sri membeli tas di sebuah toko dengan harga Rp200.000. Jika tas yang hendak dibeli Sri mendapatkan diskon sebesar 20% serta mendapat lagi potongan 5% karena menggunakan kartu anggota. Berapa harga tas yang harus Sri bayar?', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #6199', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_6199_1778530092.html', 0, 'C', 'Harga awal = Rp200.000. Diskon 20% = Rp40.000. Harga setelah diskon 1 = Rp160.000. Diskon 5% = Rp8.000. Harga akhir = Rp160.000 - Rp8.000 = Rp152.000.');
