INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (16671, 6273, 'Elusif = ...', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #6273', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_6273_1778528411.html', 0, 'A', 'Elusif berarti sulit dipahami atau sulit dijelaskan.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (32052, 6495, 'Rudi dan Ahmad menjadi peserta asuransi kesehatan dengan besaran premi yang sama. Rudi menerima gaji sebesar Rp 3.000.000 per bulan dan gaji tersebut dipotong 5% untuk premi asuransi. Berapa besar gaji Ahmad per bulan jika gajinya harus dipotong 3% untuk membayar premi?', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #6495', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_6495_1778529902.html', 0, 'B', 'Gaji Rudi = y, Gaji Ahmad = z. Besarnya premi asuransi = 5% x y = 5% x 3.000.000 = 150.000. Besarnya premi asuransi = 3% x z. 150.000 = 3% x z. 150.000 / 3% = z. 150.000 / (3/100) = z. 150.000 x 100 / 3 = z. 5.000.000 = z.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (32182, 6819, 'Semua lawak membuat tawa. Sebagian tontonan adalah lawak.', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #6819', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_6819_1778529905.html', 0, 'C', 'Karena semua lawak membuat tawa dan sebagian tontonan adalah lawak, maka sebagian tontonan membuat tawa.');
