INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (22192, 9512, 'Jelajahi Mars dengan Simulator Baru Keluaran NASA. Meskipun masih diperlukan bertahun-tahun lamanya hingga manusia dapat menginjakkan kaki di planet Mars, bukan berarti tidak mungkin bagi manusia sekarang ini untuk menjalankan tur keliling Mars. NASA telah mengeluarkan simulator 3D baru yang dapat memungkinkan para penggunanya menjelajahi Mars. Simulator ini memberikan pengalaman tur virtual bagi orang-orang yang berkeinginan untuk melakukan perjalanan mengelilingi Mars. Dikutip dari situs Quartz, fitur terbaru ciptaan NASA ini mengizinkan para penggunanya untuk mengatur gerak navigasi kendaraan Mars Curiosity yang dimiliki agen luar angkasa Amerika Serikat ini ke seluruh penjuru Mars. Dengan mengatur gerak Mars Curiosity, para pengguna fitur terbaru NASA dapat mengeksplorasi planet merah sesuai yang mereka inginkan melalui komputer pribadi mereka. Kata \"fitur\" pada bacaan di atas adalah....', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #9512', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_9512_1778529642.html', 0, 'A', 'Fitur berarti kemampuan atau ciri khusus pada suatu gawai atau aplikasi.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (27943, 9512, 'Jelajahi Mars dengan Simulator Baru Keluaran NASA. Meskipun masih diperlukan bertahun-tahun lamanya hingga manusia dapat menginjakkan kaki di planet Mars, bukan berarti tidak mungkin bagi manusia sekarang ini untuk menjalankan tur keliling Mars. NASA telah mengeluarkan simulator 3D baru yang dapat memungkinkan para penggunanya menjelajahi Mars. Simulator ini memberikan pengalaman tur virtual bagi orang-orang yang berkeinginan untuk melakukan perjalanan mengelilingi Mars. Dikutip dari situs Quartz, fitur terbaru ciptaan NASA ini mengizinkan para penggunanya untuk mengatur gerak navigasi kendaraan Mars Curiosity yang dimiliki agen luar angkasa Amerika Serikat ini ke seluruh penjuru Mars. Dengan mengatur gerak Mars Curiosity, para pengguna fitur terbaru NASA dapat mengeksplorasi planet merah sesuai yang mereka inginkan melalui komputer pribadi mereka. Kata \"fitur\" pada bacaan di atas adalah....', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #9512', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_9512_1778529793.html', 0, 'A', 'Fitur berarti kemampuan atau ciri khusus pada suatu gawai atau aplikasi.');
