INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (3635, 465, 'Edi baru saja diterima bekerja di salah satu pabrik pengolahan kayu. Sebagai pegawai baru, tentu Edi belum terlalu mengenal jenis-jenis pekerjaan dan cara menyelesaikannya. Suatu malam, tiba-tiba Edi ditugaskan manajernya untuk menyelesaikan tugas seorang rekannya yang tiba-tiba memutuskan untuk keluar dan berhenti bekerja. Edi jelas kaget dan kesulitan dengan penugasan itu, tapi ia tidak punya pilihan lain selain menjalankan perintah atasan. Apalagi manajer tadi memang memberikan tugas tersebut karena kagum melihat track record Edi sebagai mahasiswa lulusan terbaik. Menurut Anda, apa yang harus dilakukan Edi?', 3, 'TKP', 'Materi Pembelajaran: TKP - Soal #465', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_465_1778527983.html', 0, 'D', 'Jawaban D menunjukkan profesionalisme dan semangat berprestasi. Melaksanakan tupoksi sebaik mungkin secara maksimal.');
