INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (6493, 882, 'Anda adalah seorang ketua RT di suatu perumahan padat penduduk. Suatu hari, kompleks perumahan Anda kedatangan sekelompok pemuda yang menyewa salah satu rumah warga di wilayah Anda. Setelah beberapa minggu, beberapa warga mengadukan kecurigaan mereka terhadap para pemuda tersebut karena jarang keluar rumah dan enggan bertegur sapa dengan warga yang lain. Penghuni rumah cenderung beraktivitas saat malam hari. Warga yang lain juga melihat terkadang ada kelompok pemuda lain yang keluar masuk rumah tersebut saat malam hari. Anda berusaha mengakrabkan diri dengan para pemuda tersebut dan mengajak mereka ikut serta dalam kegiatan sosial namun mereka selalu menolak dan bersikap pasif. Sikap Anda...', 3, 'TKP', 'Materi Pembelajaran: TKP - Soal #882', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_882_1778528078.html', 0, 'B', 'Jawaban B memiliki skor tertinggi (5) yang menunjukkan kehati-hatian dan tanggung jawab.');
