INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (7534, 1572, 'Seorang pegawai memiliki rekan kerja dari berbagai usia, latar belakang, dan jabatan. Sikap yang mencerminkan rasa hormat terhadap rekan kerja adalah...', 3, 'TKP', 'Materi Pembelajaran: TKP - Soal #1572', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_1572_1778528105.html', 0, 'C', 'Memberikan dukungan dan bantuan kepada rekan kerja mencerminkan sikap saling menghormati dan menghargai perbedaan di lingkungan kerja.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (17311, 1573, 'Anda dan rekan kerja rutin mengadakan arisan. Salah satu rekan menyampaikan kesulitan dalam mendidik anak. Tindakan yang paling tepat adalah...', 3, 'TKP', 'Materi Pembelajaran: TKP - Soal #1573', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_1573_1778528436.html', 0, 'D', 'Mengundang narasumber ahli memberikan solusi yang lebih tepat dan bermanfaat bagi seluruh anggota, tidak hanya satu individu.');
