INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (9627, 1574, 'Anda bekerja dalam sebuah tim proyek yang memiliki deadline ketat. Salah satu anggota tim mengalami kesulitan menyelesaikan tugasnya. Sikap Anda adalah...', 3, 'TKP', 'Materi Pembelajaran: TKP - Soal #1574', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_1574_1778528163.html', 0, 'C', 'Sikap kerja sama tim dan saling membantu sesuai kemampuan penting untuk memastikan tujuan bersama tercapai.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (11094, 1574, 'Anda bekerja dalam sebuah tim proyek yang memiliki deadline ketat. Salah satu anggota tim mengalami kesulitan menyelesaikan tugasnya. Sikap Anda adalah...', 3, 'TKP', 'Materi Pembelajaran: TKP - Soal #1574', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_1574_1778528202.html', 0, 'C', 'Sikap kerja sama tim dan saling membantu sesuai kemampuan penting untuk memastikan tujuan bersama tercapai.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (7419, 1575, 'Anda bekerja pada perusahaan penerbangan yang cukup besar. Perusahaan Anda berencana untuk membentuk anak perusahaan sehingga melakukan rekrutmen calon pegawai yang akan mengurus anak perusahaan tersebut. Kebetulan hari ini adalah proses penentuan calon karyawan yang akan diterima, namun dewan pimpinan berhalangan hadir sehingga beliau mengamanahkan Anda menjadi salah satu dewan yang menentukan siapa saja karyawan yang akan diterima. Hal apa yang akan Anda lakukan?', 3, 'TKP', 'Materi Pembelajaran: TKP - Soal #1575', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_1575_1778528102.html', 0, 'D', 'Jawaban D memiliki skor tertinggi (5) yang menunjukkan kemampuan bekerja secara mandiri dan tuntas dengan indikator tanggung jawab dan inisiatif.');
