INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (11640, 2163, 'Anda seorang mahasiswa yang mendapatkan tugas materi dalam kelompok dan dijadwalkan untuk presentasi besok dan anda ditunjuk sebagai ketua kelompok. Dalam kelompok anda terdiri dari 4 (empat) orang termasuk anda. Ketika dalam proses penyusunan materi, anda sudah mengetahui kemampuan akademis rekan-rekan satu tim anda sehingga anda tahu mana orang yang mampu membantu menyusun materi dengan baik dan yang tidak, bahkan anda mengetahui mana yang pasif (hanya mengandalkan rekannya yang lain) dan mana yang tidak. Bagaimana sikap anda?', 3, 'TKP', 'Materi Pembelajaran: TKP - Soal #2163', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_2163_1778528215.html', 0, 'A', 'Jawaban A menunjukkan kepemimpinan yang adil dengan membagi tugas sesuai kemampuan.');
