INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (17604, 2166, 'Bulan ini anda menerima berbagai macam keluhan dari pelanggan anda terkait pelayanan dari perusahaan terhadap mereka. Sebagai perusahaan yang memberikan layanan anda sudah sepatutnya mengerti akan kebutuhan pelanggan agar mereka tetap menggunakan jasa perusahaan anda, ketika ada seorang pelanggan yang datang menyampaikan keluhannya, yang anda lakukan?', 3, 'TKP', 'Materi Pembelajaran: TKP - Soal #2166', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_2166_1778528443.html', 0, 'B', 'Jawaban B menunjukkan sikap responsif dan solutif terhadap keluhan pelanggan.');
