INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (8683, 2169, 'Saya merupakan salah satu junior di sebuah perusahaan terkemuka. Pada era sekarang ini, perusahaan mengharuskan merubah sistem kerja menggunakan IT mulai dari pengiriman surat, komunikasi dengan pihak lain untuk bekerjasama dan aktivitas lainnya yang dapat dijalankan dengan IT. Saya mendapati bahwa senior di tempat saya masih tetap menggunakan non IT, padahal perusahaan telah memberikan instruksi untuk penggunaan IT dalam aktivitas perusahaan, Apa yang akan anda lakukan...', 3, 'TKP', 'Materi Pembelajaran: TKP - Soal #2169', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_2169_1778528138.html', 0, 'C', 'Jawaban C menunjukkan sikap membantu dan adaptif terhadap perubahan teknologi.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (27849, 2169, 'Saya merupakan salah satu junior di sebuah perusahaan terkemuka. Pada era sekarang ini, perusahaan mengharuskan merubah sistem kerja menggunakan IT mulai dari pengiriman surat, komunikasi dengan pihak lain untuk bekerjasama dan aktivitas lainnya yang dapat dijalankan dengan IT. Saya mendapati bahwa senior di tempat saya masih tetap menggunakan non IT, padahal perusahaan telah memberikan instruksi untuk penggunaan IT dalam aktivitas perusahaan, Apa yang akan anda lakukan...', 3, 'TKP', 'Materi Pembelajaran: TKP - Soal #2169', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_2169_1778529791.html', 0, 'C', 'Jawaban C menunjukkan sikap membantu dan adaptif terhadap perubahan teknologi.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (15740, 2170, 'Anda menemukan data evaluasi pelanggan yang menyarankan agar kantor Anda memiliki akun media sosial sehingga mudah berkomunikasi dengan pelanggan. Pada sisi lain, beberapa staf menolak saran tersebut karena akan menambah pekerjaan mereka. Bagaimana tindakan Anda?', 3, 'TKP', 'Materi Pembelajaran: TKP - Soal #2170', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_2170_1778528385.html', 0, 'E', 'Jawaban E menunjukkan sikap inovatif dan berorientasi pada pelayanan pelanggan.');
