INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (19798, 4651, 'Anda bekerja pada perusahaan penerbangan yang cukup besar. Perusahaan Anda berencana untuk membentuk anak perusahaan sehingga melakukan rekrutmen calon pegawai yang akan mengurus anak perusahaan tersebut. Kebetulan hari ini adalah proses penentuan calon karyawan yang akan diterima, namun dewan pimpinan berhalangan hadir sehingga beliau mengamanahkan Anda menjadi salah satu dewan yang menentukan siapa saja karyawan yang akan diterima. Hal apa yang akan Anda lakukan?', 3, 'TKP', 'Materi Pembelajaran: TKP - Soal #4651', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_4651_1778529576.html', 0, 'D', 'Jawaban D memiliki skor tertinggi (5) yang menunjukkan kemampuan bekerja secara mandiri dan tuntas dengan indikator tanggung jawab dan inisiatif.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (39491, 4651, 'Anda bekerja pada perusahaan penerbangan yang cukup besar. Perusahaan Anda berencana untuk membentuk anak perusahaan sehingga melakukan rekrutmen calon pegawai yang akan mengurus anak perusahaan tersebut. Kebetulan hari ini adalah proses penentuan calon karyawan yang akan diterima, namun dewan pimpinan berhalangan hadir sehingga beliau mengamanahkan Anda menjadi salah satu dewan yang menentukan siapa saja karyawan yang akan diterima. Hal apa yang akan Anda lakukan?', 3, 'TKP', 'Materi Pembelajaran: TKP - Soal #4651', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_4651_1778530106.html', 0, 'D', 'Jawaban D memiliki skor tertinggi (5) yang menunjukkan kemampuan bekerja secara mandiri dan tuntas dengan indikator tanggung jawab dan inisiatif.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (21049, 4654, 'Anda bekerja di instansi pelayanan publik dan seringkali dihadapkan pada situasi di mana Anda harus menangani keluhan atau kekecewaan dari masyarakat. Bagaimana sikap Anda dalam menghadapi situasi tersebut?', 3, 'TKP', 'Materi Pembelajaran: TKP - Soal #4654', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_4654_1778529611.html', 0, 'C', 'Jawaban C memiliki skor tertinggi (5) yang menunjukkan kemampuan dalam mengelola konflik, kepedulian terhadap kebutuhan masyarakat, dan komunikasi yang baik.');
