INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (6689, 6141, 'Anda adalah seorang android developer dan bekerja sebagai ASN di departemen teknologi informasi suatu instansi pemerintah. Aplikasi instansi yang baru dirilis mendapatkan banyak feedback negatif dan rating rendah di Google Play Store. Mengingat situasi di atas, apa langkah terbaik yang akan Anda lakukan?', 3, 'TKP', 'Materi Pembelajaran: TKP - Soal #6141', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_6141_1778528083.html', 0, 'D', 'Opsi ini adalah pendekatan yang paling efektif. Menganalisis feedback, berkoordinasi dengan tim, dan melakukan tindakan konkret adalah pendekatan yang sangat baik dalam menyelesaikan masalah dan meningkatkan aplikasi.');
INSERT INTO `v_bahan_pelajaran_lengkap` (`id`, `soal_id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `judul`, `konten`, `tipe`, `url`, `file_path`, `urutan`, `jawaban_benar`, `pembahasan`) VALUES (14860, 6141, 'Anda adalah seorang android developer dan bekerja sebagai ASN di departemen teknologi informasi suatu instansi pemerintah. Aplikasi instansi yang baru dirilis mendapatkan banyak feedback negatif dan rating rendah di Google Play Store. Mengingat situasi di atas, apa langkah terbaik yang akan Anda lakukan?', 3, 'TKP', 'Materi Pembelajaran: TKP - Soal #6141', NULL, 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_6141_1778528365.html', 0, 'D', 'Opsi ini adalah pendekatan yang paling efektif. Menganalisis feedback, berkoordinasi dengan tim, dan melakukan tindakan konkret adalah pendekatan yang sangat baik dalam menyelesaikan masalah dan meningkatkan aplikasi.');
