INSERT INTO `v_soal_statistics` (`id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `muncul_count`, `benar_count`, `salah_count`, `persen_benar`, `persen_salah`) VALUES (1, 'Negara X adalah sebuah negara yang baru saja merdeka dan sedang berusaha membangun rasa nasionalisme di kalangan warganya. Proses ini dilakukan melalui implementasi berbagai program pemerintah dan penyebaran nilai-nilai patriotisme dalam pendidikan. Namun, beberapa tantangan tampaknya menjadi penghambat dalam upaya tersebut. Antara lain: Banyak warga Negara X yang memilih untuk bekerja di negara lain dan mengadopsi gaya hidup serta budaya negara tersebut. Sebagian masyarakat Negara X lebih tertarik pada barang-barang impor dibandingkan produk lokal. Penyiaran dan media di Negara X banyak didominasi oleh konten dari luar negeri. Konflik internal antara berbagai kelompok etnis dan agama yang berbeda. Pengetahuan dan apresiasi terhadap sejarah dan budaya lokal cukup tinggi di kalangan masyarakat berusia. Berdasarkan kasus di atas, mana faktor yang paling mungkin menjadi penghambat utama dalam membangun semangat nasionalisme di Negara X?', 1, 'TWK', 0, 0, 0, 0.00, 0.00);
INSERT INTO `v_soal_statistics` (`id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `muncul_count`, `benar_count`, `salah_count`, `persen_benar`, `persen_salah`) VALUES (2, 'Pada masa penjajahan, beberapa pemuda Indonesia seperti Ernest Douwes Dekker, Soewardi Soerjaningrat dan Tjipto Mangunkusumo mendirikan organisasi yang bernama Indische Party. Organisasi ini dikenal sebagai organisasi pertama yang mencetuskan konsep merdeka, yaitu bebas dari penjajahan Belanda dan menjadi fondasi penting dalam paham nasionalisme Indonesia. Peran Indische Party dan konsep merdeka memiliki pengaruh yang signifikan dalam sejarah kemerdekaan Indonesia. Bagaimanakah dampak konsep merdeka dan paham nasionalisme yang ditetapkan oleh Indische Party dalam perjuangan bangsa Indonesia hingga hari ini?', 1, 'TWK', 2, 0, 1, 0.00, 50.00);
