INSERT INTO `v_soal_statistics` (`id`, `pertanyaan`, `kategori_id`, `nama_kategori`, `muncul_count`, `benar_count`, `salah_count`, `persen_benar`, `persen_salah`) VALUES (13709, 'Nasionalisme ekonomi di Indonesia dapat diwujudkan melalui berbagai kebijakan yang mengutamakan produk lokal. Namun, di pasar global, produk asing sering kali lebih diminati karena kualitas dan harganya yang kompetitif. Apa yang sebaiknya dilakukan pemerintah untuk meningkatkan daya saing produk lokal di pasar internasional tanpa mengurangi semangat nasionalisme dalam negeri?', 1, 'TWK', 0, 0, 0, 0.00, 0.00);
